                                        }} />
                                     </div>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => {
                                     const p = state.people.find(x => x.id === e.target.value);
                                     const nl = {...activeMatch.lineup};
                                     nl.starters[idx] = { playerId: p?.id || '', name: p?.name || '', number: p?.number?.toString() || '', minutesPlayed: '90' };
                                     setActiveMatch({...activeMatch, lineup: nl});
                                  }}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>)}
                                  </select>
                               </div>
                            ))}
