      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
      syncManager.current.isInitialLoad = false;
    }
  }, [state.currentUser]);

  const pushData = async (updatedState: AppState) => {
    if (!updatedState.currentUser) return;

    syncManager.current.isPushing = true;
    syncManager.current.lastPushTime = Date.now();
    setSyncStatus('syncing');

    try {
      const tasks = [];
      if (updatedState.people.length > 0) tasks.push(supabase.from('people').upsert(sanitize(updatedState.people)));
      if (updatedState.sessions.length > 0) tasks.push(supabase.from('sessions').upsert(sanitize(updatedState.sessions)));
      if (updatedState.matches.length > 0) tasks.push(supabase.from('matches').upsert(sanitize(updatedState.matches)));
      if (updatedState.attendance.length > 0) tasks.push(supabase.from('attendance').upsert(sanitize(updatedState.attendance)));
      if (updatedState.technicalReports.length > 0) tasks.push(supabase.from('technical_reports').upsert(sanitize(updatedState.technicalReports)));
      if (updatedState.users.length > 0) tasks.push(supabase.from('app_users').upsert(sanitize(updatedState.users)));
      if (updatedState.warehouse.length > 0) tasks.push(supabase.from('warehouse').upsert(sanitize(updatedState.warehouse)));

      await Promise.all(tasks);
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
      addLog('خطأ مزامنة سحابية', error.message, 'error');
    } finally {
      setTimeout(() => { syncManager.current.isPushing = false; }, 3000);
    }
  };

  const updateStateAndSync = (updater: (prev: AppState) => AppState) => {
    setState(prev => {
      const next = updater(prev);
      pushData(next);
      return next;
    });
  };

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();

    const channel = supabase.channel('cloud-v6-sync')
      .on('postgres_changes', { event: '*', schema: 'public' }, () => {
