      alert('فشل الحذف من السحاب: ' + err.message);
    } finally {
      syncManager.current.lastPushTime = Date.now();
      setTimeout(() => { syncManager.current.isPushing = false; }, 3000);
    }
  };

  const deleteSession = async (id: string) => {
    if (!confirm('هل تريد حذف التمرين نهائياً؟')) return;
    setSyncStatus('syncing');
    syncManager.current.isPushing = true;
    try {
      const { error } = await supabase.from('sessions').delete().eq('id', id);
      if (error) throw error;
      setState(prev => ({ ...prev, sessions: prev.sessions.filter(s => s.id !== id) }));
      addLog('حذف تمرين', 'تم الحذف بنجاح من السحاب والمحلي', 'success');
    } catch (err: any) {
      alert('خطأ في الاتصال بالسحاب: ' + err.message);
    } finally {
      syncManager.current.lastPushTime = Date.now();
      setTimeout(() => { syncManager.current.isPushing = false; }, 3000);
    }
  };

  // تفعيل المزامنة الفورية بين الحسابات المختلفة (Real-time Multi-Account Sync)
  useEffect(() => {
    if (!state.currentUser) return;

    // جلب أولي للبيانات
    fetchData();

    // إنشاء قناة مزامنة شاملة لكافة الجداول
    const channel = supabase.channel('global-club-sync')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, () => fetchData(true))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'sessions' }, () => fetchData(true))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'people' }, () => fetchData(true))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'attendance' }, () => fetchData(true))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'technical_reports' }, () => fetchData(true))
      .on('postgres_changes', { event: '*', schema: 'public', table: 'warehouse' }, () => fetchData(true))
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [state.currentUser, fetchData]);

