  // --- Disciplinary Logic (Suspension System) ---
  const getPlayerSuspensionStatus = useCallback((personId: string, category: string) => {
    // جلب كافة المباريات المكتملة لهذه الفئة مرتبة زمنياً
    const categoryMatches = state.matches
      .filter(m => m.category === category && m.isCompleted)
      .sort((a, b) => a.date.localeCompare(b.date));

    let yellowCount = 0;
    let isSuspended = false;
    let cardsBeforeSuspension = { yellows: 0, hasRed: false };

    for (const match of categoryMatches) {
      if (isSuspended) {
        // إذا كان اللاعب موقوفاً، نتحقق إذا كانت هذه المباراة هي مباراة "قضاء العقوبة"
        const inLineup = [...match.lineup.starters, ...match.lineup.subs].some(p => p.playerId === personId);
        if (!inLineup) {
          // لم يشارك في المباراة المكتملة التالية -> تم قضاء العقوبة
          isSuspended = false;
          yellowCount = 0;
        }
        // ملاحظة: إذا شارك بالخطأ وهو موقوف، تبقى العقوبة قائمة في النظام
      } else {
        // احتساب البطاقات في المباراة الحالية
        const matchYellows = match.events.filter(e => e.type === 'yellow' && e.player === personId).length;
        const matchReds = match.events.filter(e => e.type === 'red' && e.player === personId).length;

        yellowCount += matchYellows;
        if (matchReds > 0 || yellowCount >= 3) {
          isSuspended = true;
          cardsBeforeSuspension = { yellows: yellowCount, hasRed: matchReds > 0 };
        }
      }
    }

    // احتساب البطاقات في المباريات غير المكتملة (الحالية) لتنبيه المدرب
    const activeMatch = state.matches.find(m => m.category === category && !m.isCompleted);
    let activeYellows = 0;
    let activeReds = false;
    if (activeMatch) {
       activeYellows = activeMatch.events.filter(e => e.type === 'yellow' && e.player === personId).length;
       activeReds = activeMatch.events.filter(e => e.type === 'red' && e.player === personId).length > 0;
    }

    return { 
      isSuspended, 
      currentYellows: yellowCount + activeYellows, 
      hasActiveRed: activeReds,
      pendingYellows: yellowCount 
    };
  }, [state.matches]);

