      const trimmedPass = passwordInput.trim();
      if ((trimmedUser.toUpperCase() === 'IZZAT' || trimmedUser === 'عزت') && trimmedPass === '123') {
        const rootUser: AppUser = { id: 'root-izzat', username: 'عزت عامر الشيخة', role: 'مدير' };
        setState(prev => ({ ...prev, currentUser: rootUser }));
        return rootUser;
      }
      const { data, error } = await supabase.from('app_users').select('*').ilike('username', trimmedUser).maybeSingle(); 
      if (error || !data) throw new Error("المستخدم غير موجود");
      if (data.password === trimmedPass) {
        const loggedUser: AppUser = { id: data.id, username: data.username, role: data.role as any, restrictedCategory: data.restrictedCategory };
        setState(prev => ({ ...prev, currentUser: loggedUser }));
        return loggedUser;
      } else { throw new Error("كلمة المرور غير صحيحة"); }
    } catch (err: any) { throw err; }
  };

  if (!state.currentUser) return <Login onLoginAttempt={handleCloudLogin} />;

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'tech_reports', label: 'التقارير الفنية', icon: FilePieChart },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'stats', label: 'الإحصائيات', icon: BarChart3 },
    { id: 'archive', label: 'الأرشيف', icon: Archive },
    { id: 'ai', label: 'الذكاء الفني', icon: Sparkles },
    { id: 'logistics', label: 'اللوجستيك', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  return (
    <div className="min-h-screen bg-[#000F21] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 transition-all duration-500 lg:translate-x-0 lg:static lg:p-4 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print`}>
        <div className="h-full bg-[#001F3F] rounded-[2rem] flex flex-col border-2 border-[#FF6B00]">
          <div className="p-8 flex items-center justify-between border-b border-white/5">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-2xl"><ClubLogo size={45} /></div>
              <div className="flex flex-col text-white">
                <span className="font-black text-lg leading-tight">نادي الكرامة</span>
                <span className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-tighter">مكتب كرة القدم</span>
              </div>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 text-white hover:text-[#FF6B00]"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-2 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 group ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg scale-[1.02]' : 'text-white/60 hover:text-white hover:bg-white/5'}`}>
                <item.icon size={22} className={`${activeTab === item.id ? 'text-white' : 'group-hover:text-[#FF6B00]'} transition-colors`} />
                <span className="font-bold text-sm">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-6 border-t border-white/5">
            <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-red-400 hover:bg-red-500/10 font-bold transition-all">
              <LogOut size={22} /> <span className="text-sm">تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-[#001F3F] z-40 px-6 lg:px-12 py-5 flex items-center justify-between no-print border-b border-[#FF6B00]">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-3 bg-white/5 rounded-2xl text-white shadow-lg"><Menu size={24} /></button>
            <div>
               <h1 className="text-2xl font-black text-white tracking-tight">{navItems.find(i => i.id === activeTab)?.label}</h1>
               <p className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-widest mt-0.5">Football Intelligence OS v9.0 Stable</p>
            </div>
          </div>
          <div className="flex items-center gap-4 lg:gap-8">
            <div className="flex items-center gap-4 bg-black/20 border border-white/10 px-5 py-2 rounded-2xl">
                 <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-white/60 hover:text-[#FF6B00] relative">
                    <Bell size={24} />
                    {state.notifications.filter(n => !n.isRead).length > 0 && (
                      <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-[#FF6B00] rounded-full border-2 border-[#001F3F]"></span>
                    )}
                 </button>
                 <div className="flex items-center gap-4 border-r pr-5 border-white/10">
                    <div className="hidden sm:flex flex-col text-left">
                       <span className="text-xs font-black text-white leading-none">{state.currentUser?.username}</span>
                       <span className="text-[10px] font-black text-[#FF6B00] uppercase mt-1">{state.currentUser?.role}</span>
                    </div>
                    <div className="w-10 h-10 bg-[#FF6B00] text-white border border-white/20 rounded-2xl flex items-center justify-center font-black text-lg">
                       {state.currentUser?.username.charAt(0)}
                    </div>
                 </div>
              </div>
            <div className="flex items-center gap-3">
              <div className={`hidden md:flex items-center gap-3 px-5 py-3 rounded-2xl border transition-all ${syncStatus === 'synced' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-orange-500/10 border-[#FF6B00]/30 text-[#FF6B00]'}`}>
                 {syncStatus === 'synced' ? <CloudCheck size={18} /> : <Cloud size={18} />}
                 <span className="text-[10px] font-black uppercase tracking-tighter">{syncStatus === 'synced' ? 'مؤمن سحابياً' : 'جاري المزامنة...'}</span>
              </div>
              <button onClick={() => fetchData()} disabled={isSyncing} className="p-3.5 rounded-2xl bg-white/5 border border-white/10 text-white/60 hover:text-white hover:bg-[#FF6B00] transition-all">
                <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
              </button>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-6 lg:p-12 custom-scrollbar bg-[#000F21]">
          <div className="max-w-[1400px] mx-auto pb-24">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'tech_reports' && <TechnicalReports state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'archive' && <ArchiveView state={state} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'stats' && <StatsView state={state} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <nav className="lg:hidden fixed bottom-0 inset-x-0 bg-[#001F3F] border-t border-[#FF6B00]/30 p-3 flex justify-around items-center z-[100] rounded-t-[2rem]">
           {navItems.slice(0, 5).map(item => (
             <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/40'}`}>
                <item.icon size={24} />
             </button>
           ))}
        </nav>
        <ChatBot state={state} />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock, Ban
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '90' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const updateActiveMatchLineup = (index: number, playerId: string, isStarter: boolean) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // فحص الإيقاف قبل الإضافة
    const suspension = getSuspension(playerId, activeMatch.category);
    if (suspension.isSuspended) {
      const player = state.people.find(p => p.id === playerId);
      alert(`تنبيه نظام الانضباط: اللاعب [${player?.name}] موقوف حالياً بسبب السجل الانضباطي (تراكم بطاقات أو طرد). لا يمكن إدراجه في التشكيلة.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (isStarter) {
      if (!person) newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '90' };
      else newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: '90' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // فحص الإيقاف للبدلاء
    const suspension = getSuspension(playerId, activeMatch.category);
    if (suspension.isSuspended) {
      const player = state.people.find(p => p.id === playerId);
      alert(`تنبيه انضباطي: [${player?.name}] موقوف رسمياً. يمنع تواجده حتى على مقاعد البدلاء.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    if (!person) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const addMatchEvent = (type: MatchEvent['type']) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvent: MatchEvent = { id: generateUUID(), type, player: '', minute: '', note: '' };
    setActiveMatch({ ...activeMatch, events: [...(activeMatch.events || []), newEvent] });
  };

  const updateMatchEvent = (id: string, field: keyof MatchEvent, value: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvents = activeMatch.events.map(e => e.id === id ? { ...e, [field]: value } : e);
    setActiveMatch({ ...activeMatch, events: newEvents });
  };

  const removeMatchEvent = (id: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvents = activeMatch.events.filter(e => e.id !== id);
    setActiveMatch({ ...activeMatch, events: newEvents });
  };

  const saveMatchDetails = (lockStatus: boolean = false) => {
    if (!activeMatch || isViewer) return;
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: lockStatus } : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const inputStyle = "w-full bg-slate-50 border border-[#001F3F] rounded-xl py-2 px-3 font-bold text-[#001F3F] text-xs shadow-inner";
  const labelStyle = "text-[10px] font-black text-[#001F3F] mr-1 uppercase block mb-1";

  return (
    <div className="space-y-4 md:space-y-6 pb-20 px-1 font-['Tajawal']" dir="rtl">
      <div className="bg-white p-4 rounded-2xl border-2 border-slate-900 flex justify-between items-center no-print shadow-md">
        <h2 className="text-sm md:text-xl font-black text-[#001F3F] flex items-center gap-2 uppercase tracking-tighter">
          <Trophy size={20} className="text-orange-600" /> إدارة المباريات
        </h2>
        {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-lg border-b-4 border-black">جدولة مواجهة</button>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 no-print text-right">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-5 rounded-2xl border-2 border-slate-900 relative shadow-sm border-b-8 transition-all ${m.isCompleted ? 'border-red-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-4">
                <span className="bg-orange-600 text-white text-[8px] font-black px-2 py-0.5 rounded uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-500 tabular-nums">{m.date}</span>
             </div>
             <div className="text-center mb-6">
                <p className="text-2xl font-black text-[#001F3F] tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-bold text-sm text-slate-800 mt-2">{m.opponent}</p>
             </div>
             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-[10px] uppercase shadow-lg">
                  {m.isCompleted ? 'عرض التقرير' : 'التشكيل والأحداث'}
                </button>
                {!isViewer && !m.isCompleted && (
                  <button onClick={async () => { if(confirm('حذف المباراة؟')) { await supabase.from('matches').delete().eq('id', m.id); setState(p => ({...p, matches: p.matches.filter(x => x.id !== m.id)})); } }} className="bg-red-50 text-red-600 p-3 rounded-xl border border-red-200"><Trash2 size={16}/></button>
                )}
             </div>
          </div>
        ))}
      </div>

      {isAddOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4 no-print">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg shadow-2xl border-[6px] border-slate-900 overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center text-right">
                 <h3 className="font-black text-slate-900 uppercase">جدولة مواجهة جديدة</h3>
                 <button onClick={() => setIsAddOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateMatch} className="p-8 space-y-5 text-right">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1 text-right">
                       <label className={labelStyle}>الفئة</label>
                       <select required disabled={!!restrictedCat} className={inputStyle} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1 text-right">
                       <label className={labelStyle}>نوع المباراة</label>
                       <select className={inputStyle} value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as any})}>
                          <option value="دوري">دوري</option>
                          <option value="كأس">كأس</option>
                          <option value="ودية">ودية</option>
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1 text-right">
                    <label className={labelStyle}>اسم الفريق المنافس</label>
                    <input required type="text" className={inputStyle} value={formData.opponent} onChange={e => setFormData({...formData, opponent: e.target.value})} placeholder="أدخل اسم الخصم..." />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1 text-right">
                       <label className={labelStyle}>التاريخ</label>
                       <input required type="date" className={inputStyle} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1 text-right">
                       <label className={labelStyle}>التوقيت</label>
                       <input required type="time" className={inputStyle} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all mt-4 uppercase">حفظ وتثبيت المواجهة</button>
              </form>
           </div>
        </div>
      )}

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-xl z-[400] overflow-y-auto no-print">
           <div className="max-w-4xl mx-auto p-2 md:p-8 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[2rem] border-[4px] border-slate-900 p-4 md:p-8 shadow-2xl relative text-right">
                <header className="flex flex-col md:flex-row justify-between items-center mb-8 border-b-4 border-slate-900 pb-6 gap-4">
                   <div className="text-center md:text-right">
                      <h2 className="text-xl md:text-2xl font-black text-[#001F3F] tracking-tighter uppercase">{activeMatch.opponent} × الكرامة</h2>
                      <div className="flex gap-2 mt-2 justify-center md:justify-start">
                         <span className="bg-slate-100 text-[#001F3F] text-[9px] font-black px-2 py-1 rounded-full border border-slate-900">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-red-50 text-red-600 text-[9px] font-black px-2 py-1 rounded-full border border-red-200 flex items-center gap-1"><Lock size={10}/> مقفل</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-2 justify-center">
                      {isManager && (
                        <button onClick={() => saveMatchDetails(!activeMatch.isCompleted)} className={`${activeMatch.isCompleted ? 'bg-red-600' : 'bg-emerald-600'} text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-md flex items-center gap-2 transition-all`}>
                          {activeMatch.isCompleted ? <Unlock size={16}/> : <Lock size={16}/>} {activeMatch.isCompleted ? 'فتح التعديل' : 'اعتماد وقفل'}
                        </button>
                      )}
                      {!activeMatch.isCompleted && <button onClick={() => saveMatchDetails(false)} className="bg-blue-600 text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-md flex items-center gap-2"><Save size={16}/> حفظ</button>}
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-2 rounded-xl border-2 border-slate-300 hover:bg-red-50 hover:text-red-600 transition-all"><X size={20}/></button>
                   </div>
                </header>

                <div className={`grid grid-cols-1 lg:grid-cols-12 gap-8 ${activeMatch.isCompleted ? 'opacity-80 pointer-events-none' : ''}`}>
                   <div className="lg:col-span-8 space-y-8">
                      <section className="text-right">
                         <h3 className="text-sm font-black text-[#001F3F] mb-4 border-r-4 border-orange-600 pr-2 uppercase">التشكيلة الأساسية (Starting XI)</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-4 rounded-xl border-2 border-slate-200 shadow-sm flex flex-col gap-2">
                                  <div className="flex justify-between items-center">
                                     <span className="w-8 h-8 bg-[#001F3F] text-white rounded-lg flex items-center justify-center font-black text-xs">#{s.number || (idx+1)}</span>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => {
                                        const suspension = getSuspension(p.id, activeMatch.category);
                                        return (
                                          <option key={p.id} value={p.id} disabled={suspension.isSuspended} className={suspension.isSuspended ? 'text-red-400' : ''}>
                                            {p.name} (#{p.number}) {suspension.isSuspended ? '[موقوف ⛔]' : ''} 
                                            {suspension.currentYellows > 0 ? ` (🟨 ${suspension.currentYellows})` : ''}
                                          </option>
                                        );
                                     })}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section className="bg-white p-5 rounded-2xl border-2 border-[#001F3F] shadow-sm space-y-4 text-right">
                         <div className="flex justify-between items-center">
                            <h3 className="text-sm font-black text-[#001F3F] uppercase flex items-center gap-2">أحداث المواجهة (أهداف وبطاقات)</h3>
                            <div className="flex gap-1">
                               <button onClick={() => addMatchEvent('goal')} className="bg-emerald-600 text-white p-1.5 rounded-lg text-[8px] font-black uppercase flex items-center gap-1"><Plus size={10}/> هدف</button>
                               <button onClick={() => addMatchEvent('yellow')} className="bg-yellow-500 text-white p-1.5 rounded-lg text-[8px] font-black uppercase flex items-center gap-1"><AlertTriangle size={10}/> إنذار</button>
                               <button onClick={() => addMatchEvent('red')} className="bg-red-600 text-white p-1.5 rounded-lg text-[8px] font-black uppercase flex items-center gap-1"><X size={10}/> طرد</button>
                            </div>
                         </div>
                         <div className="space-y-3">
                            {activeMatch.events && activeMatch.events.map((ev, idx) => (
                               <div key={ev.id} className={`p-3 rounded-xl border-2 flex flex-col md:flex-row gap-3 items-center ${ev.type === 'goal' ? 'bg-emerald-50 border-emerald-100' : ev.type === 'yellow' ? 'bg-yellow-50 border-yellow-100' : ev.type === 'red' ? 'bg-red-50 border-red-100' : 'bg-slate-50 border-slate-100'}`}>
                                  <div className="flex items-center gap-2">
                                     {ev.type === 'yellow' && <div className="w-3 h-5 bg-yellow-400 rounded-sm"></div>}
                                     {ev.type === 'red' && <div className="w-3 h-5 bg-red-600 rounded-sm"></div>}
                                     <span className="text-[10px] font-black text-slate-900 uppercase">{ev.type}</span>
                                  </div>
                                  <div className="flex-1 w-full">
                                     <select className={inputStyle} value={ev.player} onChange={e => updateMatchEvent(ev.id, 'player', e.target.value)}>
                                        <option value="">-- اللاعب --</option>
                                        {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name} (#{p.number})</option>)}
                                     </select>
                                  </div>
                                  <div className="w-16">
                                     <input type="number" className={inputStyle + " text-center"} placeholder="دقيقة" value={ev.minute} onChange={e => updateMatchEvent(ev.id, 'minute', e.target.value)} />
                                  </div>
                                  <button onClick={() => removeMatchEvent(ev.id)} className="p-2 text-red-600 hover:bg-red-100 rounded-lg"><Trash2 size={14}/></button>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section className="bg-slate-50 p-4 rounded-2xl border-2 border-dashed border-[#001F3F] text-right">
                         <div className="flex justify-between items-center mb-6">
                            <h3 className="text-sm font-black text-[#001F3F] uppercase flex items-center gap-2">البدلاء والتبديلات</h3>
                            <button onClick={() => { if (!activeMatch.isCompleted) setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0' }] } }); }} className="bg-[#001F3F] text-white px-3 py-1.5 rounded-lg font-black text-[9px] flex items-center gap-1"><Plus size={12}/> إضافة بديل</button>
                         </div>
                         <div className="space-y-3">
                            {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="bg-white p-3 rounded-xl border border-slate-200 flex flex-col md:flex-row gap-2 items-end md:items-center shadow-sm">
                                  <div className="flex-1 w-full">
                                     <select className={inputStyle} value={s.playerId} onChange={e => updateSub(idx, e.target.value)}>
                                        <option value="">-- دخول لاعب --</option>
                                        {getAvailablePlayers(s.playerId).map(p => {
                                           const suspension = getSuspension(p.id, activeMatch.category);
                                           return (
                                              <option key={p.id} value={p.id} disabled={suspension.isSuspended}>
                                                {p.name} (#{p.number}) {suspension.isSuspended ? '[موقوف ⛔]' : ''}
                                              </option>
                                           );
                                        })}
                                     </select>
                                  </div>
                                  <button onClick={() => { const newSubs = activeMatch.lineup.subs.filter((_, i) => i !== idx); setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } }); }} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/></button>
                               </div>
                            ))}
                         </div>
                      </section>
                   </div>

                   <div className="lg:col-span-4 space-y-6 text-right">
                      <section className="bg-slate-900 text-white p-6 rounded-2xl border-4 border-orange-600 text-center shadow-xl">
                         <h3 className="text-[10px] font-black text-orange-400 mb-6 uppercase tracking-widest">النتيجة النهائية</h3>
                         <div className="flex justify-center items-center gap-4">
                            <input type="number" className="w-14 h-14 bg-white text-slate-900 rounded-xl text-center font-black text-xl outline-none" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                            <span className="text-3xl font-black text-orange-600">:</span>
                            <input type="number" className="w-14 h-14 bg-white text-slate-900 rounded-xl text-center font-black text-xl outline-none" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                         </div>
                      </section>

                      <section className="bg-white p-5 rounded-2xl border-2 border-slate-900 shadow-sm space-y-4 text-right">
                         <h3 className="font-black text-xs text-[#001F3F] flex items-center gap-2"><FileText size={16}/> التقرير الفني</h3>
                         <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold text-[10px] text-slate-800 outline-none h-40 resize-none text-right" value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})} placeholder="اكتب تحليل المباراة..."></textarea>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useEffect } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  MapPin, Hash, UserCheck, ChevronLeft, FolderPlus, Filter, Settings2, BookOpen, Globe, CreditCard, Map,
  Briefcase, Printer, FileSpreadsheet, Eye, FileText, Users, ChevronRight, HeartPulse, Gavel, StickyNote,
  Edit2, Ban
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';
import ClubLogo from './ClubLogo';
import { generateUUID, supabase } from '../App';

interface SquadManagementProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog, getSuspension }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');
  const [activeSubTab, setActiveSubTab] = useState<'players' | 'staff'>('players');
  const [showFullReportView, setShowFullReportView] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: restrictedCat || state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return null;
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    if (isViewer) return;
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: generateUUID(),
        name: formData.name || '',
        fatherName: formData.fatherName || '',
        motherName: formData.motherName || '',
        birthDate: formData.birthDate || '',
        birthPlace: formData.birthPlace || '',
        khana: formData.khana || '',
        nationalId: formData.nationalId || '',
        federalNumber: formData.federalNumber || '',
        internationalId: formData.internationalId || '',
        address: formData.address || '',
        category: formData.category || restrictedCat || state.categories[0],
        role: formData.role || 'لاعب',
        number: formData.number || 0,
        phone: formData.phone || '',
        joinDate: formData.joinDate || new Date().toISOString().split('T')[0],
        monthlyReports: {}
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const baseFiltered = state.people.filter(p => {
    const matchCat = restrictedCat ? p.category === restrictedCat : (localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter);
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  const displayList = activeSubTab === 'players' ? baseFiltered.filter(p => p.role === 'لاعب') : baseFiltered.filter(p => p.role !== 'لاعب');

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2.5 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 no-print space-y-6">
        <div className="flex flex-col lg:flex-row gap-4 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
            <input type="text" placeholder="البحث بالاسم أو رقم القميص..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className={`${fieldClass} pr-12 h-12 text-lg`} />
          </div>
          <div className="flex items-center gap-3 w-full lg:w-auto">
            {!restrictedCat && (
              <select value={localCategoryFilter} onChange={e => setLocalCategoryFilter(e.target.value)} className="bg-slate-100 border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-sm h-12 appearance-none cursor-pointer">
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            )}
            {!isViewer && (
              <button onClick={() => { setEditingId(null); setFormData({ role: 'لاعب', category: restrictedCat || (localCategoryFilter !== 'الكل' ? localCategoryFilter : state.categories[0]), joinDate: new Date().toISOString().split('T')[0] }); setIsModalOpen(true); }} className="bg-[#001F3F] text-white px-8 h-12 rounded-xl font-black text-sm flex items-center gap-3 shadow-lg border-b-4 border-black">
                <UserPlus size={20} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        <div className="flex p-1.5 bg-slate-100 border-2 border-slate-900 rounded-2xl w-fit">
          <button onClick={() => setActiveSubTab('players')} className={`flex items-center gap-2 px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'players' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>اللاعبين</button>
          <button onClick={() => setActiveSubTab('staff')} className={`flex items-center gap-2 px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'staff' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>الكوادر</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 no-print">
        {displayList.map(person => {
          const suspension = getSuspension(person.id, person.category);
          return (
            <div key={person.id} className={`bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 relative transition-all border-b-[8px] ${suspension.isSuspended ? 'border-red-600 bg-red-50/30' : 'hover:border-orange-600'}`}>
               <div className="flex justify-between items-start mb-4">
                 <div className="w-12 h-12 bg-slate-100 border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-slate-900 text-lg">
                   {person.name.charAt(0)}
                 </div>
                 <div className="flex flex-col items-end gap-1">
                    <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase ${person.role === 'لاعب' ? 'bg-orange-600 text-white' : 'bg-[#001F3F] text-white'}`}>{person.role}</span>
                    <div className="flex gap-1">
                       {suspension.isSuspended && <Ban size={16} className="text-red-600 animate-pulse" title="موقوف رسمياً" />}
                       {suspension.hasActiveRed && <div className="w-3 h-4 bg-red-600 rounded-sm" title="بطاقة حمراء مباشرة"></div>}
                       {suspension.currentYellows > 0 && Array(suspension.currentYellows).fill(0).map((_, i) => (
                         <div key={i} className="w-2.5 h-3.5 bg-yellow-400 rounded-sm border border-yellow-600" title="بطاقة صفراء"></div>
                       ))}
                    </div>
                 </div>
               </div>

               <div className="space-y-2">
                 <h4 className="font-black text-xl text-slate-900">{person.name}</h4>
                 <div className="flex gap-3 pt-1 text-[11px] font-black text-slate-600">
                    <span className="flex items-center gap-1.5"><MapPin size={12} className="text-orange-600" /> {person.birthPlace}</span>
                    <span className="flex items-center gap-1.5"><Calendar size={12} className="text-[#001F3F]" /> {calculateAge(person.birthDate)} سنة</span>
                 </div>
               </div>

               <div className="mt-6 pt-4 border-t-2 border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-3">
                     <div className="bg-[#001F3F] text-white w-9 h-9 rounded-xl flex items-center justify-center font-black text-lg border-2 border-black">#{person.number || '0'}</div>
                     <button onClick={() => onOpenReport?.(person)} className="text-slate-900 text-xs font-black hover:text-orange-600 underline">الملف الفني الشامل</button>
                  </div>
                  {!isViewer && (
                    <div className="flex gap-2">
                      <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-2.5 bg-slate-100 border-2 border-slate-900 rounded-xl hover:bg-[#001F3F] hover:text-white transition-all"><Edit2 size={16}/></button>
                      <button onClick={async () => { if(confirm(`حذف ${person.name}؟`)) { await supabase.from('people').delete().eq('id', person.id); setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); } }} className="p-2.5 bg-red-50 text-red-600 border-2 border-red-900 rounded-xl hover:bg-red-600 hover:text-white transition-all"><Trash2 size={16}/></button>
                    </div>
                  )}
               </div>
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[250] p-4 no-print">
          <div className="bg-white rounded-[2.5rem] w-full max-w-4xl shadow-2xl overflow-hidden border-[6px] border-slate-900 flex flex-col h-[90vh]">
            <div className="p-5 border-b-2 bg-slate-50 flex justify-between items-center shrink-0">
              <h3 className="text-md font-black text-slate-900 uppercase">تسجيل / تحديث بيانات العضو</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2.5 rounded-xl hover:rotate-90 transition-all"><X size={22} /></button>
            </div>
            <form onSubmit={handleSave} className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10 text-right">
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="space-y-1 col-span-2">
                    <label className={labelClass}>الاسم الكامل</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>تاريخ الميلاد</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>رقم القميص</label>
                    <input type="number" value={formData.number || ''} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>الصفة</label>
                    <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as Role})} className={fieldClass}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>الفئة</label>
                    <select disabled={!!restrictedCat} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className={fieldClass}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                </div>
                <div className="flex gap-4 pt-10 border-t-2 border-slate-200 pb-10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-slate-200 text-slate-900 font-black py-4 rounded-xl text-xs uppercase">إلغاء</button>
                <button type="submit" className="flex-[2] bg-[#001F3F] text-white font-black py-4 rounded-xl shadow-2xl hover:bg-black transition-all text-xs uppercase">حفظ البيانات</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface TechnicalReport {
  id: string;
  targetId: string; 
  type: 'match_evaluation' | 'staff_review' | 'player_radar';
  category: Category;
  rating: number; 
  content: string;
  author: string;
  date: string;
  radarData?: {
    technical: number;
    physical: number;
    tactical: number;
    mental: number;
    discipline: number;
  };
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
  monthlyReports?: { [key: string]: string };
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
  isLocked?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury' | 'substitution';
  player: string; 
  minute: string;
  playerInId?: string; // للاعب الداخل في التبديل
  playerOutId?: string; // للاعب الخارج في التبديل
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
