    let yellowCount = 0;
    let isSuspended = false;

    for (const match of categoryMatches) {
      if (isSuspended) {
        const inLineup = [...match.lineup.starters, ...match.lineup.subs].some(p => p.playerId === personId);
        if (!inLineup) {
