        const matchReds = match.events.filter(e => e.type === 'red' && e.player === personId).length;
        yellowCount += matchYellows;
        if (matchReds > 0 || yellowCount >= 3) {
          isSuspended = true;
        }
      }
    }

    const activeMatch = state.matches.find(m => m.category === category && !m.isCompleted);
    let activeYellows = 0;
    let activeReds = false;
    if (activeMatch) {
