                   <div className="lg:col-span-8 space-y-8">
                      <section>
                         <h3 className="text-sm font-black text-[#001F3F] mb-4 border-r-4 border-orange-600 pr-2 uppercase">التشكيلة الأساسية</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-4 rounded-xl border-2 border-slate-200 shadow-sm flex flex-col gap-2">
                                  <div className="flex justify-between items-center">
                                     <span className="w-8 h-8 bg-[#001F3F] text-white rounded-lg flex items-center justify-center font-black text-xs">#{s.number || (idx+1)}</span>
                                     <div className="flex items-center gap-1 text-[10px] font-black text-emerald-600">
                                        <Timer size={12}/> {s.minutesPlayed || '0'} د
                                     </div>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value, true)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {getAvailablePlayers(s.playerId).map(p => (
                                        <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                     ))}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section className="bg-white p-5 rounded-2xl border-2 border-[#001F3F] shadow-sm space-y-4 text-right">
                         <div className="flex justify-between items-center">
                            <h3 className="text-sm font-black text-[#001F3F] uppercase flex items-center gap-2">الأحداث والتبديلات</h3>
                            <div className="flex gap-1">
                               <button onClick={() => addMatchEvent('goal')} className="bg-emerald-600 text-white p-1.5 rounded-lg text-[8px] font-black uppercase flex items-center gap-1"><Plus size={10}/> هدف</button>
                               <button onClick={() => addMatchEvent('yellow')} className="bg-yellow-500 text-white p-1.5 rounded-lg text-[8px] font-black uppercase flex items-center gap-1">🟨 إنذار</button>
                               <button onClick={() => addMatchEvent('substitution')} className="bg-blue-600 text-white p-1.5 rounded-lg text-[8px] font-black uppercase flex items-center gap-1">🔄 تبديل</button>
                            </div>
                         </div>
                         <div className="space-y-3">
                            {activeMatch.events && activeMatch.events.map((ev, idx) => (
                               <div key={ev.id} className={`p-3 rounded-xl border-2 flex flex-col md:flex-row gap-3 items-center ${ev.type === 'substitution' ? 'bg-blue-50 border-blue-200' : 'bg-slate-50 border-slate-100'}`}>
                                  <div className="flex items-center gap-2 min-w-[80px]">
                                     <span className="text-[10px] font-black uppercase">{ev.type === 'substitution' ? '🔄 تبديل' : ev.type}</span>
                                  </div>

                                  {ev.type === 'substitution' ? (
                                    <div className="flex-1 grid grid-cols-2 gap-2 w-full">
                                       <select className={inputStyle} value={ev.playerOutId} onChange={e => updateMatchEvent(ev.id, 'playerOutId', e.target.value)}>
                                          <option value="">-- الخارج --</option>
                                          {activeMatch.lineup.starters.filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                       </select>
                                       <select className={inputStyle} value={ev.playerInId} onChange={e => updateMatchEvent(ev.id, 'playerInId', e.target.value)}>
                                          <option value="">-- الداخل --</option>
                                          {activeMatch.lineup.subs.filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                       </select>
                                    </div>
                                  ) : (
                                    <div className="flex-1 w-full">
                                       <select className={inputStyle} value={ev.player} onChange={e => updateMatchEvent(ev.id, 'player', e.target.value)}>
                                          <option value="">-- اللاعب --</option>
                                          {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                       </select>
                                    </div>
                                  )}

                                  <div className="w-16">
                                     <input type="number" className={inputStyle + " text-center"} placeholder="دقيقة" value={ev.minute} onChange={e => updateMatchEvent(ev.id, 'minute', e.target.value)} />
                                  </div>
                                  <button onClick={() => removeMatchEvent(ev.id)} className="p-2 text-red-600 hover:bg-red-100 rounded-lg"><Trash2 size={14}/></button>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section className="bg-slate-50 p-4 rounded-2xl border-2 border-dashed border-[#001F3F] text-right">
                         <div className="flex justify-between items-center mb-6">
                            <h3 className="text-sm font-black text-[#001F3F] uppercase flex items-center gap-2">البدلاء</h3>
                            <button onClick={() => setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0' }] } })} className="bg-[#001F3F] text-white px-3 py-1.5 rounded-lg font-black text-[9px] flex items-center gap-1"><Plus size={12}/> إضافة بديل</button>
                         </div>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="bg-white p-3 rounded-xl border border-slate-200 flex items-center gap-2 shadow-sm">
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateSub(idx, e.target.value)}>
                                     <option value="">-- لاعب بديل --</option>
                                     {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                  </select>
                                  <div className="text-[10px] font-black text-emerald-600 min-w-[40px]">{s.minutesPlayed} د</div>
                                  <button onClick={() => setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: activeMatch.lineup.subs.filter((_, i) => i !== idx) } })} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/></button>
                               </div>
                            ))}
                         </div>
                      </section>
                   </div>

                   <div className="lg:col-span-4 space-y-6 text-right">
                      <section className="bg-slate-900 text-white p-6 rounded-2xl border-4 border-orange-600 text-center shadow-xl">
                         <h3 className="text-[10px] font-black text-orange-400 mb-6 uppercase tracking-widest">النتيجة النهائية والوقت الضائع</h3>
                         <div className="flex justify-center items-center gap-4 mb-8">
                            <input type="number" className="w-14 h-14 bg-white text-slate-900 rounded-xl text-center font-black text-xl outline-none" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                            <span className="text-3xl font-black text-orange-600">:</span>
                            <input type="number" className="w-14 h-14 bg-white text-slate-900 rounded-xl text-center font-black text-xl outline-none" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                         </div>
                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                               <label className="text-[8px] font-black text-slate-400 uppercase">ضائع (1)</label>
                               <input type="number" className="w-full bg-white/10 border border-white/20 rounded-xl p-2 text-center text-white font-black" value={activeMatch.stoppageTime1} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                            </div>
                            <div className="space-y-1">
                               <label className="text-[8px] font-black text-slate-400 uppercase">ضائع (2)</label>
                               <input type="number" className="w-full bg-white/10 border border-white/20 rounded-xl p-2 text-center text-white font-black" value={activeMatch.stoppageTime2} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                            </div>
                         </div>
                      </section>

                      <section className="bg-white p-5 rounded-2xl border-2 border-slate-900 shadow-sm space-y-4 text-right">
                         <h3 className="font-black text-xs text-[#001F3F] flex items-center gap-2"><FileText size={16}/> التحليل والتقرير الفني</h3>
                         <textarea className="w-full bg-slate-50 border border-slate-200 rounded-xl p-3 font-bold text-[10px] text-slate-800 outline-none h-40 resize-none" value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})} placeholder="سجل أهم الملاحظات الفنية للمباراة..."></textarea>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

