  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');

  const isInternalUpdate = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_football_pro_v11');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      warehouse: [],
      technicalReports: [],
      attendance: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // --- Disciplinary Engine: Check for Red/3-Yellows ---
  const getPlayerSuspensionStatus = useCallback((personId: string, category: string) => {
    const completedMatches = state.matches
      .filter(m => m.category === category && m.isCompleted)
      .sort((a, b) => b.date.localeCompare(a.date));

    let yellowCount = 0;
    let hasRecentRed = false;
    let isSuspended = false;

    // Red Card in the absolute last match check
    if (completedMatches.length > 0) {
      const lastMatch = completedMatches[0];
      hasRecentRed = lastMatch.events.some(e => e.type === 'red' && e.player === personId);
    }

    // Cumulative Yellows check (all completed matches)
    state.matches
      .filter(m => m.category === category && m.isCompleted)
      .forEach(m => {
        yellowCount += m.events.filter(e => e.type === 'yellow' && e.player === personId).length;
      });

    if (hasRecentRed || yellowCount >= 3) {
      isSuspended = true;
    }

    return { 
      isSuspended, 
      currentYellows: yellowCount, 
      hasActiveRed: hasRecentRed 
    };
  }, [state.matches]);

  useEffect(() => {
    localStorage.setItem('alkarama_football_pro_v11', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;
    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const pplQuery = supabase.from('people').select('*');
      const sessQuery = supabase.from('sessions').select('*');
      const mtchQuery = supabase.from('matches').select('*');
      const techQuery = supabase.from('technical_reports').select('*');
      const wrhsQuery = supabase.from('warehouse').select('*');
      const attnQuery = supabase.from('attendance').select('*');
      const catQuery = supabase.from('categories').select('name');

      if (state.currentUser.restrictedCategory) {
        pplQuery.eq('category', state.currentUser.restrictedCategory);
        sessQuery.eq('category', state.currentUser.restrictedCategory);
        mtchQuery.eq('category', state.currentUser.restrictedCategory);
        wrhsQuery.or(`category.eq.${state.currentUser.restrictedCategory},category.eq.المخزن العام`);
      }

      const [cats, ppl, sess, mtch, attn, wrhs, tech] = await Promise.all([
        catQuery, pplQuery, sessQuery, mtchQuery, attnQuery, wrhsQuery, techQuery
      ]);

      setState(prev => ({
        ...prev,
        categories: (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories,
        people: ppl.data || prev.people,
        sessions: sess.data || prev.sessions,
        matches: mtch.data || prev.matches,
        technicalReports: tech.data || prev.technicalReports,
        warehouse: wrhs.data || prev.warehouse,
        attendance: attn.data || prev.attendance
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  const updateStateAndSync = useCallback(async (updater: (prev: AppState) => AppState) => {
    if (!state.currentUser) return;
    const nextState = updater(state);
    const filterByAccess = (items: any[]) => {
        if (!state.currentUser?.restrictedCategory) return items;
        return items.filter(i => i.category === state.currentUser?.restrictedCategory || i.category === 'المخزن العام');
    };

    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    try {
      const tasks = [
        supabase.from('people').upsert(sanitize(filterByAccess(nextState.people))),
        supabase.from('sessions').upsert(sanitize(filterByAccess(nextState.sessions))),
        supabase.from('matches').upsert(sanitize(filterByAccess(nextState.matches))),
        supabase.from('attendance').upsert(sanitize(filterByAccess(nextState.attendance))),
        supabase.from('technical_reports').upsert(sanitize(filterByAccess(nextState.technicalReports))),
        supabase.from('warehouse').upsert(sanitize(filterByAccess(nextState.warehouse)))
      ];

      const results = await Promise.all(tasks);
      const error = results.find(r => r.error);
      if (error) throw new Error(error.error.message);
      await fetchData();
      setSyncStatus('synced');
    } catch (err: any) {
      setSyncStatus('error');
      addLog('خطأ في المزامنة السحابية', err.message, 'error');
      setState(nextState);
    } finally {
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state, fetchData, addLog]);

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();
    const handleRealtimeChange = () => {
        if (isInternalUpdate.current) return;
        fetchData();
    };
    const channels = [
        supabase.channel('matches-db').on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, handleRealtimeChange).subscribe(),
        supabase.channel('sessions-db').on('postgres_changes', { event: '*', schema: 'public', table: 'sessions' }, handleRealtimeChange).subscribe(),
        supabase.channel('people-db').on('postgres_changes', { event: '*', schema: 'public', table: 'people' }, handleRealtimeChange).subscribe(),
        supabase.channel('attendance-db').on('postgres_changes', { event: '*', schema: 'public', table: 'attendance' }, handleRealtimeChange).subscribe(),
        supabase.channel('tech-db').on('postgres_changes', { event: '*', schema: 'public', table: 'technical_reports' }, handleRealtimeChange).subscribe()
    ];
    return () => { channels.forEach(ch => supabase.removeChannel(ch)); };
  }, [state.currentUser, fetchData]);

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('alkarama_football_pro_v11');
  };

  const handleCloudLogin = async (usernameInput: string, passwordInput: string): Promise<AppUser | null> => {
    try {
      const trimmedUser = usernameInput.trim();
      const trimmedPass = passwordInput.trim();
      if ((trimmedUser.toUpperCase() === 'IZZAT' || trimmedUser === 'عزت') && trimmedPass === '123') {
        const rootUser: AppUser = { id: 'root-izzat', username: 'عزت عامر الشيخة', role: 'مدير' };
        setState(prev => ({ ...prev, currentUser: rootUser }));
        return rootUser;
      }
      const { data, error } = await supabase.from('app_users').select('*').ilike('username', trimmedUser).maybeSingle(); 
      if (error || !data) throw new Error("المستخدم غير موجود");
      if (data.password === trimmedPass) {
        const loggedUser: AppUser = { id: data.id, username: data.username, role: data.role as any, restrictedCategory: data.restrictedCategory };
        setState(prev => ({ ...prev, currentUser: loggedUser }));
        return loggedUser;
      } else { throw new Error("كلمة المرور غير صحيحة"); }
    } catch (err: any) { throw err; }
  };

  if (!state.currentUser) return <Login onLoginAttempt={handleCloudLogin} />;

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'tech_reports', label: 'التقارير الفنية', icon: FilePieChart },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'stats', label: 'الإحصائيات', icon: BarChart3 },
    { id: 'archive', label: 'الأرشيف', icon: Archive },
    { id: 'ai', label: 'الذكاء الفني', icon: Sparkles },
    { id: 'logistics', label: 'اللوجستيك', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  return (
    <div className="min-h-screen bg-[#000F21] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 transition-all duration-500 lg:translate-x-0 lg:static lg:p-4 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print`}>
        <div className="h-full bg-[#001F3F] rounded-[2rem] flex flex-col border-2 border-[#FF6B00]">
          <div className="p-8 flex items-center justify-between border-b border-white/5">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-2xl"><ClubLogo size={45} /></div>
              <div className="flex flex-col text-white">
                <span className="font-black text-lg leading-tight">نادي الكرامة</span>
                <span className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-tighter">مكتب كرة القدم</span>
              </div>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 text-white hover:text-[#FF6B00]"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-2 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 group ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg scale-[1.02]' : 'text-white/60 hover:text-white hover:bg-white/5'}`}>
                <item.icon size={22} className={`${activeTab === item.id ? 'text-white' : 'group-hover:text-[#FF6B00]'} transition-colors`} />
                <span className="font-bold text-sm">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-6 border-t border-white/5">
            <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-red-400 hover:bg-red-500/10 font-bold transition-all">
              <LogOut size={22} /> <span className="text-sm">تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-[#001F3F] z-40 px-6 lg:px-12 py-5 flex items-center justify-between no-print border-b border-[#FF6B00]">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-3 bg-white/5 rounded-2xl text-white shadow-lg"><Menu size={24} /></button>
            <div>
               <h1 className="text-2xl font-black text-white tracking-tight">{navItems.find(i => i.id === activeTab)?.label}</h1>
               <p className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-widest mt-0.5">Football Intelligence OS v11.0 Stable</p>
            </div>
          </div>
          <div className="flex items-center gap-4 lg:gap-8">
            <div className="flex items-center gap-4 bg-black/20 border border-white/10 px-5 py-2 rounded-2xl">
                 <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-white/60 hover:text-[#FF6B00] relative">
                    <Bell size={24} />
                    {state.notifications.filter(n => !n.isRead).length > 0 && (
                      <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-[#FF6B00] rounded-full border-2 border-[#001F3F]"></span>
                    )}
                 </button>
                 <div className="flex items-center gap-4 border-r pr-5 border-white/10">
                    <div className="hidden sm:flex flex-col text-left">
                       <span className="text-xs font-black text-white leading-none">{state.currentUser?.username}</span>
                       <span className="text-[10px] font-black text-[#FF6B00] uppercase mt-1">{state.currentUser?.role}</span>
                    </div>
                    <div className="w-10 h-10 bg-[#FF6B00] text-white border border-white/20 rounded-2xl flex items-center justify-center font-black text-lg">
                       {state.currentUser?.username.charAt(0)}
                    </div>
                 </div>
              </div>
            <div className="flex items-center gap-3">
              <div className={`hidden md:flex items-center gap-3 px-5 py-3 rounded-2xl border transition-all ${syncStatus === 'synced' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-orange-500/10 border-[#FF6B00]/30 text-[#FF6B00]'}`}>
                 {syncStatus === 'synced' ? <CloudCheck size={18} /> : <Cloud size={18} />}
                 <span className="text-[10px] font-black uppercase tracking-tighter">{syncStatus === 'synced' ? 'مؤمن سحابياً' : 'جاري المزامنة...'}</span>
              </div>
              <button onClick={() => fetchData()} disabled={isSyncing} className="p-3.5 rounded-2xl bg-white/5 border border-white/10 text-white/60 hover:text-white hover:bg-[#FF6B00] transition-all">
                <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
              </button>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-6 lg:p-12 custom-scrollbar bg-[#000F21]">
          <div className="max-w-[1400px] mx-auto pb-24">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'tech_reports' && <TechnicalReports state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'archive' && <ArchiveView state={state} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'stats' && <StatsView state={state} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <nav className="lg:hidden fixed bottom-0 inset-x-0 bg-[#001F3F] border-t border-[#FF6B00]/30 p-3 flex justify-around items-center z-[100] rounded-t-[2rem]">
           {navItems.slice(0, 5).map(item => (
             <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/40'}`}>
                <item.icon size={24} />
             </button>
           ))}
        </nav>
        <ChatBot state={state} />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock, Ban, RefreshCw
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const calculateMinutes = (match: Match): Match => {
    const totalMatchTime = 90 + parseInt(match.stoppageTime1 || '0') + parseInt(match.stoppageTime2 || '0');

    // Reset all starters to full match, subs to 0
    const newStarters = match.lineup.starters.map(s => ({ ...s, minutesPlayed: s.playerId ? totalMatchTime.toString() : '0' }));
    const newSubs = match.lineup.subs.map(s => ({ ...s, minutesPlayed: '0' }));

    // Apply substitution events
    const subEvents = (match.events || []).filter(e => e.type === 'substitution').sort((a,b) => parseInt(a.minute) - parseInt(b.minute));

    subEvents.forEach(event => {
      const min = parseInt(event.minute) || 0;

      // Starter going OUT
      const starterIdx = newStarters.findIndex(s => s.playerId === event.playerOutId);
      if (starterIdx > -1) {
        newStarters[starterIdx].minutesPlayed = min.toString();
      }

      // Sub coming IN
      const subInIdx = newSubs.findIndex(s => s.playerId === event.playerInId);
      if (subInIdx > -1) {
        newSubs[subInIdx].minutesPlayed = (totalMatchTime - min).toString();
      }
    });

    return {
      ...match,
      lineup: {
        ...match.lineup,
        starters: newStarters,
        subs: newSubs
      }
    };
  };

  const updateActiveMatchLineup = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // Check Suspension
    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      const player = state.people.find(p => p.id === playerId);
      alert(`⚠️ تحذير نظام الانضباط الصارم:\nاللاعب [${player?.name}] موقوف حالياً.\nالسبب: ${susp.hasActiveRed ? "بطاقة حمراء مباشرة" : "تراكم 3 بطاقات صفراء"}.\nلا يمكن إدراجه في التشكيلة.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (!person) newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    else newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: '0' };
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSubInLineup = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      alert(`⚠️ تنبيه: اللاعب موقوف انضباطياً ولا يمكنه التواجد على الدكة.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    if (!person) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: '0' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const addMatchEvent = (type: MatchEvent['type']) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvent: MatchEvent = { id: generateUUID(), type, player: '', minute: '', playerInId: '', playerOutId: '' };
    setActiveMatch({ ...activeMatch, events: [...(activeMatch.events || []), newEvent] });
  };

  const updateMatchEvent = (id: string, field: keyof MatchEvent, value: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvents = activeMatch.events.map(e => e.id === id ? { ...e, [field]: value } : e);
    setActiveMatch({ ...activeMatch, events: newEvents });
  };

  const removeMatchEvent = (id: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const saveMatchDetails = (lockStatus: boolean = false) => {
    if (!activeMatch || isViewer) return;
    let matchToSave = { ...activeMatch };
    if (lockStatus) {
      matchToSave = calculateMinutes(matchToSave);
      matchToSave.isCompleted = true;
    }
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === matchToSave.id ? matchToSave : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const inputStyle = "w-full bg-slate-50 border border-[#001F3F] rounded-xl py-2 px-3 font-bold text-[#001F3F] text-xs shadow-inner";
  const labelStyle = "text-[10px] font-black text-[#001F3F] mr-1 uppercase block mb-1";

  return (
    <div className="space-y-4 md:space-y-6 pb-20 px-1 font-['Tajawal']" dir="rtl">
      <div className="bg-white p-4 rounded-2xl border-2 border-slate-900 flex justify-between items-center no-print shadow-md">
        <h2 className="text-sm md:text-xl font-black text-[#001F3F] flex items-center gap-2 uppercase tracking-tighter">
          <Trophy size={20} className="text-orange-600" /> إدارة المباريات والتشكيلة
        </h2>
        {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-lg border-b-4 border-black">جدولة مواجهة</button>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 no-print text-right">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-5 rounded-2xl border-2 border-slate-900 relative shadow-sm border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-4">
                <span className="bg-orange-600 text-white text-[8px] font-black px-2 py-0.5 rounded uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-500 tabular-nums">{m.date}</span>
             </div>
             <div className="text-center mb-6">
                <p className="text-2xl font-black text-[#001F3F] tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-bold text-sm text-slate-800 mt-2">{m.opponent}</p>
             </div>
             <div className="flex gap-2">
