import React, { useMemo, useState, useEffect } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase, Sparkles, Loader2, X, BrainCircuit,
  HeartPulse, ShieldAlert, Gavel, Smartphone, CalendarDays, Wallet, Zap, ShieldCheck,
  Medal, Swords, Star, UserPlus, Info, Phone, Fingerprint, Save, Edit3, ChevronDown
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord, MatchEvent } from '../types';
import ClubLogo from './ClubLogo';
import { supabase } from '../App';

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  const [isSavingReport, setIsSavingReport] = useState(false);
  const [monthlyNotes, setMonthlyNotes] = useState<{ [key: string]: string }>(player?.monthlyReports || {});

  const months = ["كانون الثاني", "شباط", "آذار", "نيسان", "أيار", "حزيران", "تموز", "آب", "أيلول", "تشرين الأول", "تشرين الثاني", "كانون الأول"];
  const currentMonthIndex = new Date().getMonth();
  const [selectedMonth, setSelectedMonth] = useState(months[currentMonthIndex]);

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';
  const isViewer = state.currentUser.role === 'مشاهد';

  const matchStats = useMemo(() => {
    if (isStaff) return { totalMins: 0, goals: 0, assists: 0, yellows: 0, reds: 0, list: [] };

    let totalMins = 0;
    let totalGoals = 0;
    let totalAssists = 0;
    let totalYellows = 0;
    let totalReds = 0;

    const statsList = state.matches
      .filter(m => m.isCompleted)
      .sort((a, b) => b.date.localeCompare(a.date))
      .map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);

        let mins = parseInt(starter?.minutesPlayed || sub?.minutesPlayed || '0') || 0;
        totalMins += mins;

        const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length;
        const assists = m.events.filter(e => e.type === 'assist' && (e.player === player.id || e.player === player.name)).length;
        const yellows = m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length;
        const reds = m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length;

        totalGoals += goals;
        totalAssists += assists;
        totalYellows += yellows;
        totalReds += reds;

        return { 
          opponent: m.opponent, 
          date: m.date, 
          type: m.matchType,
          mins, 
          goals, 
          assists,
          yellows,
          reds,
          played: !!(starter || sub) 
        };
      })
      .filter(s => s.played);

    return {
      totalMins,
      goals: totalGoals,
      assists: totalAssists,
      yellows: totalYellows,
      reds: totalReds,
      list: statsList
    };
  }, [state.matches, player, isStaff]);

  const attendanceData = useMemo(() => {
    const sessions = state.sessions.filter(s => s.category === player.category);
    const sessionIds = sessions.map(s => s.id);
    const allRecords = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));
    const present = allRecords.filter(r => r.status === 'حاضر').length;
    const late = allRecords.filter(r => r.status === 'متأخر').length;
    const rate = sessions.length > 0 ? Math.min(100, Math.round(((present + late * 0.7) / sessions.length) * 100)) : 0;
    return { rate, total: sessions.length, present, late };
  }, [state.attendance, state.sessions, player]);

  const handleSaveMonthlyReport = async () => {
    if (isViewer) return;
    setIsSavingReport(true);
    try {
      const { error } = await supabase.from('people').update({ monthlyReports: monthlyNotes }).eq('id', player.id);
      if (error) throw error;
      alert(`تم تحديث التقرير بنجاح.`);
    } catch (err: any) { alert(err.message); } finally { setIsSavingReport(false); }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-24 text-right" dir="rtl">

      <div className="flex justify-between items-center no-print">
        <button onClick={onBack} className="flex items-center gap-2 text-[#001F3F] font-black bg-white border-2 border-[#001F3F] px-6 py-3 rounded-2xl text-sm shadow-md">
          <ChevronRight size={20} /> العودة للمديرية
        </button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 shadow-xl">
          <Printer size={20} /> طباعة السجل الكامل
        </button>
      </div>

      <div className="solid-panel overflow-hidden border-4 border-[#001F3F]">
        <div className="bg-[#001F3F] h-32 relative">
          <div className="absolute -bottom-14 right-10 flex items-end gap-6">
            <div className="w-32 h-32 bg-white rounded-3xl border-8 border-white flex items-center justify-center font-black text-5xl text-[#001F3F] shadow-2xl relative">
               {player.name.charAt(0)}
               <div className="absolute -top-4 -left-4 bg-orange-600 text-white w-10 h-10 rounded-full flex items-center justify-center text-lg border-4 border-white shadow-lg">
                  #{player.number || '0'}
               </div>
            </div>
            <div className="mb-4">
              <h1 className="text-3xl font-black text-white">{player.name}</h1>
              <div className="flex gap-2 mt-2">
                 <span className="bg-orange-600 text-white text-[10px] font-black px-4 py-1 rounded-xl">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[10px] font-black px-4 py-1 rounded-xl">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-16"></div>

        <div className="px-10 pb-10 grid grid-cols-2 md:grid-cols-6 gap-4">
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center">
             <Timer className="text-[#001F3F] mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900">دقائق اللعب</span>
             <p className="text-xl font-black text-[#001F3F] tabular-nums">{matchStats.totalMins}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center">
             <Trophy className="text-emerald-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900">الأهداف</span>
             <p className="text-xl font-black text-emerald-700">{matchStats.goals}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center">
             <Zap className="text-blue-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900">أسيست</span>
             <p className="text-xl font-black text-blue-700">{matchStats.assists}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center">
             <div className="w-3 h-5 bg-yellow-400 rounded-sm mb-1 border border-yellow-600"></div>
             <span className="text-[8px] font-black text-slate-900">إنذارات</span>
             <p className="text-xl font-black text-yellow-600">{matchStats.yellows}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center">
             <div className="w-3 h-5 bg-red-600 rounded-sm mb-1 border border-red-800"></div>
             <span className="text-[8px] font-black text-slate-900">طرد</span>
             <p className="text-xl font-black text-red-600">{matchStats.reds}</p>
           </div>
           <div className="bg-emerald-50 p-4 rounded-2xl border-2 border-emerald-600 flex flex-col items-center">
             <TrendingUp className="text-emerald-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-emerald-900">الالتزام</span>
             <p className="text-xl font-black text-emerald-700">%{attendanceData.rate}</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-8 rounded-[2.5rem] border-2 border-[#001F3F] shadow-md">
             <h3 className="text-xl font-black text-[#001F3F] mb-6 flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                <ClipboardList className="text-blue-700" size={24}/> سجل المشاركة الفني الفعلي (Active Minutes)
             </h3>
             <div className="overflow-x-auto">
               <table className="w-full text-right border-collapse">
                 <thead>
                    <tr className="bg-slate-100 border-y-2 border-[#001F3F] text-[10px] font-black uppercase text-slate-900">
                       <th className="p-4 border-l">المنافس</th>
                       <th className="p-4 border-l text-center">الوقت</th>
                       <th className="p-4 border-l text-center">مساهمات</th>
                       <th className="p-4 border-l text-center">كروت</th>
                       <th className="p-4 text-center">التاريخ</th>
                    </tr>
                 </thead>
                 <tbody>
                    {matchStats.list.length > 0 ? matchStats.list.map((m, i) => (
                      <tr key={i} className="border-b border-slate-200 text-sm font-black hover:bg-slate-50">
                         <td className="p-4 border-l">{m.opponent}</td>
                         <td className="p-4 border-l text-center font-black text-emerald-600">{m.mins} د</td>
                         <td className="p-4 border-l text-center">⚽{m.goals} / 👟{m.assists}</td>
                         <td className="p-4 border-l text-center">
                            {m.yellows > 0 && <span className="bg-yellow-400 w-2 h-3 inline-block rounded-sm mr-1"></span>}
                            {m.reds > 0 && <span className="bg-red-600 w-2 h-3 inline-block rounded-sm mr-1"></span>}
                         </td>
                         <td className="p-4 text-center text-slate-400 text-[10px]">{m.date}</td>
                      </tr>
                    )) : (
                      <tr><td colSpan={5} className="p-16 text-center text-slate-300 font-black italic">لا توجد مشاركات رسمية معتمدة.</td></tr>
                    )}
                 </tbody>
               </table>
             </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border-2 border-blue-900 shadow-sm">
