              </button>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-6 lg:p-12 custom-scrollbar bg-[#000F21]">
          <div className="max-w-[1400px] mx-auto pb-24">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'tech_reports' && <TechnicalReports state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'archive' && <ArchiveView state={state} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'stats' && <StatsView state={state} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <nav className="lg:hidden fixed bottom-0 inset-x-0 bg-[#001F3F] border-t border-[#FF6B00]/30 p-3 flex justify-around items-center z-[100] rounded-t-[2rem]">
           {navItems.slice(0, 5).map(item => (
             <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/40'}`}>
                <item.icon size={24} />
             </button>
           ))}
        </nav>
        <ChatBot state={state} />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock, Ban, RefreshCw
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const calculateMinutes = (match: Match): Match => {
    const totalMatchTime = 90 + parseInt(match.stoppageTime1 || '0') + parseInt(match.stoppageTime2 || '0');

    // Reset calculations
    const newStarters = match.lineup.starters.map(s => ({ 
      ...s, 
      minutesPlayed: s.playerId ? totalMatchTime.toString() : '0' 
    }));
    const newSubs = match.lineup.subs.map(s => ({ ...s, minutesPlayed: '0' }));

    // Apply substitution events
    const subEvents = (match.events || []).filter(e => e.type === 'substitution').sort((a,b) => parseInt(a.minute) - parseInt(b.minute));

    subEvents.forEach(event => {
      const min = parseInt(event.minute) || 0;

      // Starter going OUT
      const starterIdx = newStarters.findIndex(s => s.playerId === event.playerOutId);
      if (starterIdx > -1) {
        newStarters[starterIdx].minutesPlayed = min.toString();
      }

      // Sub coming IN
      const subInIdx = newSubs.findIndex(s => s.playerId === event.playerInId);
      if (subInIdx > -1) {
        // Player entered at min, played until totalTime
        newSubs[subInIdx].minutesPlayed = (totalMatchTime - min).toString();
      }
    });

    return {
      ...match,
      lineup: {
        ...match.lineup,
        starters: newStarters,
        subs: newSubs
      }
    };
  };

  const updateActiveMatchLineup = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // STRICT DISCIPLINARY CHECK
    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      const player = state.people.find(p => p.id === playerId);
      alert(`⚠️ تنبيه نظام الانضباط بنادي الكرامة:\nلا يمكن إدراج اللاعب [${player?.name}] في التشكيلة.\nالسبب: ${susp.hasActiveRed ? "بطاقة حمراء مباشرة" : "تراكم 3 إنذارات صفراء"}.\nيرجى مراجعة المكتب الفني.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (!person) newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    else newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: '0' };
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addSubToLineup = (playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      alert(`⚠️ تنبيه: اللاعب موقوف انضباطياً ولا يمكنه التواجد حتى على مقاعد البدلاء.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    if (!person) return;

    const newSubs = [...activeMatch.lineup.subs, { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: '0' }];
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const addMatchEvent = (type: MatchEvent['type']) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvent: MatchEvent = { id: generateUUID(), type, player: '', minute: '', playerInId: '', playerOutId: '' };
    setActiveMatch({ ...activeMatch, events: [...(activeMatch.events || []), newEvent] });
  };

  const updateMatchEvent = (id: string, field: keyof MatchEvent, value: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvents = activeMatch.events.map(e => e.id === id ? { ...e, [field]: value } : e);
    setActiveMatch({ ...activeMatch, events: newEvents });
  };

  const removeMatchEvent = (id: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const saveMatchDetails = (lockStatus: boolean = false) => {
    if (!activeMatch || isViewer) return;
    let matchToSave = { ...activeMatch };
    if (lockStatus) {
      matchToSave = calculateMinutes(matchToSave);
      matchToSave.isCompleted = true;
    }
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === matchToSave.id ? matchToSave : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const inputStyle = "w-full bg-slate-50 border border-[#001F3F] rounded-xl py-2 px-3 font-bold text-[#001F3F] text-xs shadow-inner";

  return (
    <div className="space-y-4 md:space-y-6 pb-20 px-1 font-['Tajawal'] text-right" dir="rtl">
      <div className="bg-white p-4 rounded-2xl border-2 border-slate-900 flex justify-between items-center no-print shadow-md">
        <h2 className="text-sm md:text-xl font-black text-[#001F3F] flex items-center gap-2 uppercase tracking-tighter">
          <Trophy size={20} className="text-orange-600" /> إدارة مباريات الكرامة والبيانات الفنية
        </h2>
        {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-lg border-b-4 border-black">جدولة مواجهة</button>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-5 rounded-2xl border-2 border-slate-900 relative shadow-sm border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-4">
                <span className="bg-orange-600 text-white text-[8px] font-black px-2 py-0.5 rounded uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-500 tabular-nums">{m.date}</span>
             </div>
             <div className="text-center mb-6">
                <p className="text-2xl font-black text-[#001F3F] tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-bold text-sm text-slate-800 mt-2">{m.opponent}</p>
             </div>
             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-[10px] uppercase shadow-lg">
                  {m.isCompleted ? 'تقرير المباراة والدقائق' : 'التشكيل والأحداث'}
                </button>
             </div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-xl z-[400] overflow-y-auto no-print">
           <div className="max-w-5xl mx-auto p-2 md:p-8 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[2.5rem] border-[6px] border-slate-900 p-4 md:p-10 shadow-2xl relative">
                <header className="flex flex-col md:flex-row justify-between items-center mb-10 border-b-4 border-slate-900 pb-8 gap-4">
                   <div className="text-center md:text-right">
                      <h2 className="text-xl md:text-3xl font-black text-[#001F3F] tracking-tighter uppercase">{activeMatch.opponent} × الكرامة</h2>
                      <div className="flex gap-2 mt-3 justify-center md:justify-start">
                         <span className="bg-slate-100 text-[#001F3F] text-[10px] font-black px-3 py-1.5 rounded-full border border-slate-900">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-emerald-50 text-emerald-600 text-[10px] font-black px-3 py-1.5 rounded-full border border-emerald-200 flex items-center gap-1"><CheckCircle size={14}/> تقرير معتمد</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-3 justify-center">
                      {isManager && (
                        <button onClick={() => saveMatchDetails(!activeMatch.isCompleted)} className={`${activeMatch.isCompleted ? 'bg-red-600' : 'bg-emerald-600'} text-white px-6 py-3 rounded-2xl font-black text-[11px] shadow-xl flex items-center gap-2 transition-all`}>
                          {activeMatch.isCompleted ? <Unlock size={18}/> : <CheckCircle size={18}/>} {activeMatch.isCompleted ? 'فتح التعديل' : 'اعتماد واحتساب الدقائق'}
                        </button>
                      )}
                      {!activeMatch.isCompleted && <button onClick={() => saveMatchDetails(false)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[11px] shadow-xl flex items-center gap-2 hover:bg-black"><Save size={18}/> حفظ مسودة</button>}
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-3 rounded-2xl border-2 border-slate-300 hover:bg-red-50 hover:text-red-600 transition-all"><X size={24}/></button>
                   </div>
                </header>

                <div className={`grid grid-cols-1 lg:grid-cols-12 gap-10 ${activeMatch.isCompleted ? 'opacity-90 pointer-events-none' : ''}`}>
                   <div className="lg:col-span-8 space-y-10">
                      <section>
                         <h3 className="text-md font-black text-[#001F3F] mb-6 border-r-4 border-orange-600 pr-3 uppercase flex items-center gap-2"><Users size={20}/> التشكيلة الأساسية</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-200 shadow-sm flex flex-col gap-3">
                                  <div className="flex justify-between items-center">
                                     <span className="w-9 h-9 bg-[#001F3F] text-white rounded-xl flex items-center justify-center font-black text-sm shadow-md">#{s.number || (idx+1)}</span>
                                     <div className="flex items-center gap-1 text-[10px] font-black text-emerald-600">
                                        <Timer size={12}/> {s.minutesPlayed || '0'} د
                                     </div>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب متاح --</option>
                                     {getAvailablePlayers(s.playerId).map(p => (
                                        <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                     ))}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section className="bg-white p-6 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm space-y-6 text-right">
                         <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                            <h3 className="text-md font-black text-[#001F3F] uppercase flex items-center gap-2"><Sparkles size={20} className="text-orange-500"/> أحداث المباراة والتبديلات اللانهائية</h3>
                            <div className="flex flex-wrap gap-2">
                               <button onClick={() => addMatchEvent('goal')} className="bg-emerald-600 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all"><Plus size={12}/> هدف</button>
                               <button onClick={() => addMatchEvent('assist')} className="bg-blue-500 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all"><Zap size={12}/> أسيست</button>
                               <button onClick={() => addMatchEvent('yellow')} className="bg-yellow-500 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all">🟨 إنذار</button>
                               <button onClick={() => addMatchEvent('red')} className="bg-red-600 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all">🟥 طرد</button>
                               <button onClick={() => addMatchEvent('substitution')} className="bg-indigo-600 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all"><RefreshCw size={12}/> تبديل</button>
                            </div>
                         </div>
                         <div className="space-y-3">
                            {activeMatch.events && activeMatch.events.map((ev) => (
                               <div key={ev.id} className={`p-4 rounded-2xl border-2 flex flex-col md:flex-row gap-4 items-center transition-all ${ev.type === 'substitution' ? 'bg-indigo-50 border-indigo-200' : 'bg-slate-50 border-slate-100 hover:bg-white'}`}>
                                  <div className="flex items-center gap-2 min-w-[100px]">
                                     <span className="text-[10px] font-black uppercase p-2 bg-white rounded-xl shadow-sm border border-slate-200">
                                        {ev.type === 'substitution' ? '🔄 تبديل' : 
                                         ev.type === 'goal' ? '⚽ هدف' : 
                                         ev.type === 'assist' ? '👟 أسيست' : 
                                         ev.type === 'yellow' ? '🟨 إنذار' : '🟥 طرد'}
                                     </span>
                                  </div>

                                  {ev.type === 'substitution' ? (
                                    <div className="flex-1 grid grid-cols-2 gap-3 w-full">
                                       <select className={inputStyle} value={ev.playerOutId} onChange={e => updateMatchEvent(ev.id, 'playerOutId', e.target.value)}>
                                          <option value="">-- اللاعب الخارج --</option>
                                          {activeMatch.lineup.starters.filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                       </select>
                                       <select className={inputStyle} value={ev.playerInId} onChange={e => updateMatchEvent(ev.id, 'playerInId', e.target.value)}>
                                          <option value="">-- اللاعب الداخل --</option>
                                          {activeMatch.lineup.subs.filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                       </select>
                                    </div>
                                  ) : (
                                    <div className="flex-1 w-full">
                                       <select className={inputStyle} value={ev.player} onChange={e => updateMatchEvent(ev.id, 'player', e.target.value)}>
                                          <option value="">-- اختر اللاعب --</option>
                                          {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                       </select>
                                    </div>
                                  )}

                                  <div className="w-20">
                                     <input type="number" className={inputStyle + " text-center h-10 text-lg"} placeholder="د" value={ev.minute} onChange={e => updateMatchEvent(ev.id, 'minute', e.target.value)} />
                                  </div>
                                  <button onClick={() => removeMatchEvent(ev.id)} className="p-3 text-red-600 bg-red-50 hover:bg-red-600 hover:text-white rounded-xl transition-all shadow-sm"><Trash2 size={16}/></button>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section className="bg-slate-50 p-6 rounded-[2.5rem] border-2 border-dashed border-[#001F3F]">
                         <div className="flex justify-between items-center mb-6">
                            <h3 className="text-md font-black text-[#001F3F] uppercase flex items-center gap-2"><Users size={20}/> مقاعد الاحتياط</h3>
                            <button onClick={() => setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0' }] } })} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] flex items-center gap-2 shadow-lg hover:bg-black transition-all">
                               <Plus size={16}/> إضافة بديل
                            </button>
                         </div>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="bg-white p-4 rounded-2xl border-2 border-slate-200 flex items-center justify-between gap-3 shadow-sm hover:border-orange-600 transition-all">
                                  <div className="flex items-center gap-3 w-full">
                                     <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs">#{s.number}</span>
                                     <select className={inputStyle} value={s.playerId} onChange={e => {
                                        const susp = getSuspension(e.target.value, activeMatch.category);
                                        if (susp.isSuspended) { alert("⚠️ اللاعب موقوف!"); return; }
                                        const person = state.people.find(p => p.id === e.target.value);
                                        if (!person) return;
                                        const newSubs = [...activeMatch.lineup.subs];
                                        newSubs[idx] = { ...newSubs[idx], playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: '0' };
                                        setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
                                     }}>
                                        <option value="">-- لاعب بديل --</option>
                                        {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                     </select>
                                  </div>
                                  <div className="text-[10px] font-black text-emerald-600 min-w-[50px]">{s.minutesPlayed} د</div>
                                  <button onClick={() => setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: activeMatch.lineup.subs.filter((_, i) => i !== idx) } })} className="p-2 text-red-600 hover:bg-red-50 rounded-xl"><Trash2 size={16}/></button>
                               </div>
                            ))}
                         </div>
                      </section>
