interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  const [isSavingReport, setIsSavingReport] = useState(false);
  const [monthlyNotes, setMonthlyNotes] = useState<{ [key: string]: string }>(player?.monthlyReports || {});

  const months = ["كانون الثاني", "شباط", "آذار", "نيسان", "أيار", "حزيران", "تموز", "آب", "أيلول", "تشرين الأول", "تشرين الثاني", "كانون الأول"];
  const currentMonthIndex = new Date().getMonth();
  const [selectedMonth, setSelectedMonth] = useState(months[currentMonthIndex]);

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';
  const isViewer = state.currentUser.role === 'مشاهد';

  const matchStats = useMemo(() => {
    if (isStaff) return { totalMins: 0, avgMins: 0, goals: 0, assists: 0, yellows: 0, reds: 0, list: [] };

    let totalMins = 0;
    let totalGoals = 0;
    let totalAssists = 0;
    let totalYellows = 0;
    let totalReds = 0;

    const statsList = state.matches
      .filter(m => m.isCompleted)
      .sort((a, b) => b.date.localeCompare(a.date))
      .map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);

        let mins = parseInt(starter?.minutesPlayed || sub?.minutesPlayed || '0') || 0;
        totalMins += mins;

        const goals = m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length;
        const assists = m.events.filter(e => e.type === 'assist' && (e.player === player.id || e.player === player.name)).length;
        const yellows = m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length;
        const reds = m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length;

        totalGoals += goals;
        totalAssists += assists;
        totalYellows += yellows;
        totalReds += reds;

        return { 
          opponent: m.opponent, 
          date: m.date, 
          type: m.matchType,
          mins, 
          goals, 
          assists,
          yellows,
          reds,
          wasStarter: !!starter,
          played: !!(starter || sub) 
        };
      })
      .filter(s => s.played);

    return {
      totalMins,
      avgMins: statsList.length > 0 ? Math.round(totalMins / statsList.length) : 0,
      goals: totalGoals,
      assists: totalAssists,
      yellows: totalYellows,
      reds: totalReds,
      list: statsList
    };
  }, [state.matches, player, isStaff]);

  const attendanceData = useMemo(() => {
    const sessions = state.sessions.filter(s => s.category === player.category);
    const sessionIds = sessions.map(s => s.id);
    const allRecords = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));
    const present = allRecords.filter(r => r.status === 'حاضر').length;
    const late = allRecords.filter(r => r.status === 'متأخر').length;
    const rate = sessions.length > 0 ? Math.min(100, Math.round(((present + late * 0.7) / sessions.length) * 100)) : 0;
    return { rate, total: sessions.length, present, late };
  }, [state.attendance, state.sessions, player]);

  const handleSaveMonthlyReport = async () => {
    if (isViewer) return;
    setIsSavingReport(true);
    try {
      const { error } = await supabase.from('people').update({ monthlyReports: monthlyNotes }).eq('id', player.id);
      if (error) throw error;
      alert(`تم تحديث التقرير بنجاح.`);
    } catch (err: any) { alert(err.message); } finally { setIsSavingReport(false); }
  };

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-500 pb-24 px-2 md:px-0 text-right font-['Tajawal']" dir="rtl">

      <div className="flex flex-row justify-between items-center no-print gap-3">
        <button onClick={onBack} className="flex items-center gap-2 text-[#001F3F] font-black bg-white border-2 border-[#001F3F] px-6 py-3 rounded-2xl text-sm shadow-md active:scale-95 transition-all">
          <ChevronRight size={20} /> العودة لقائمة الفريق
        </button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 shadow-xl border-b-4 border-black hover:bg-black transition-all">
          <Printer size={20} /> طباعة الملف الفني الكامل
        </button>
      </div>

      {/* الهوية البصرية العلوية */}
      <div className="solid-panel overflow-hidden relative !shadow-none border-4 border-[#001F3F]">
        <div className="bg-[#001F3F] h-28 md:h-40 relative">
          <div className="absolute -bottom-14 right-8 md:right-16 flex items-end gap-6 md:gap-10">
            <div className="w-28 h-28 md:w-48 md:h-48 bg-white rounded-3xl md:rounded-[3rem] border-[6px] md:border-[10px] border-white flex items-center justify-center font-black text-5xl md:text-8xl text-[#001F3F] uppercase shadow-2xl relative z-10">
               {player.name.charAt(0)}
               <div className="absolute -top-4 -left-4 bg-orange-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl border-4 border-white shadow-lg">
                  #{player.number || '0'}
               </div>
            </div>
            <div className="mb-4">
              <h1 className="text-2xl md:text-5xl font-black text-white drop-shadow-lg tracking-tight leading-tight">{player.name}</h1>
              <div className="flex gap-3 mt-2">
                 <span className="bg-orange-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-16 md:h-24"></div>

        {/* إحصائيات سريعة */}
        <div className="px-6 md:px-16 pb-10 grid grid-cols-2 md:grid-cols-7 gap-3 md:gap-4">
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Timer className="text-[#001F3F] mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900 uppercase">إجمالي الدقائق</span>
             <p className="text-xl font-black text-[#001F3F] tabular-nums">{matchStats.totalMins}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Activity className="text-blue-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900 uppercase">متوسط المشاركة</span>
             <p className="text-xl font-black text-blue-800 tabular-nums">{matchStats.avgMins} د</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Trophy className="text-emerald-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900 uppercase">الأهداف</span>
             <p className="text-xl font-black text-emerald-700 tabular-nums">{matchStats.goals}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Zap className="text-blue-600 mb-1" size={24}/>
