             <p className="text-xl font-black text-blue-700 tabular-nums">{matchStats.assists}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <div className="w-3 h-5 bg-yellow-400 rounded-sm mb-1 shadow-sm border border-yellow-600"></div>
             <span className="text-[8px] font-black text-slate-900 uppercase">إنذارات</span>
             <p className="text-xl font-black text-yellow-600 tabular-nums">{matchStats.yellows}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <div className="w-3 h-5 bg-red-600 rounded-sm mb-1 shadow-sm border border-red-800"></div>
             <span className="text-[8px] font-black text-slate-900 uppercase">طرد</span>
             <p className="text-xl font-black text-red-600 tabular-nums">{matchStats.reds}</p>
           </div>
           <div className="bg-emerald-50 p-4 rounded-2xl border-2 border-emerald-600 flex flex-col items-center shadow-sm col-span-2 md:col-span-1">
             <TrendingUp className="text-emerald-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-emerald-900 uppercase">الالتزام</span>
             <p className="text-xl font-black text-emerald-700">%{attendanceData.rate}</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-10">
        <div className="lg:col-span-2 space-y-8">

          {/* سجل المشاركة الفني الفعلي */}
          <div className="bg-white p-8 rounded-[2.5rem] border-2 border-[#001F3F] shadow-md">
             <h3 className="text-lg md:text-2xl font-black text-[#001F3F] mb-8 flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                <ClipboardList className="text-blue-700" size={28}/> سجل المشاركة الفنية (دقائق اللعب النشطة)
             </h3>
             <div className="overflow-x-auto -mx-6 md:mx-0">
               <table className="w-full text-right border-collapse min-w-[600px]">
                 <thead>
                    <tr className="bg-slate-100 border-y-2 border-[#001F3F] text-[11px] font-black uppercase text-slate-900">
                       <th className="p-4 border-l">المنافس</th>
                       <th className="p-4 border-l text-center">الوضعية</th>
                       <th className="p-4 border-l text-center">الدقائق</th>
                       <th className="p-4 border-l text-center">مساهمات</th>
                       <th className="p-4 border-l text-center">كروت</th>
                       <th className="p-4 text-center">التاريخ</th>
                    </tr>
                 </thead>
                 <tbody>
                    {matchStats.list.length > 0 ? matchStats.list.map((m, i) => (
                      <tr key={i} className="border-b border-slate-200 text-sm font-black hover:bg-slate-50 transition-colors">
                         <td className="p-4 border-l">
