                                  <button onClick={() => { const nl = activeMatch.lineup.subs.filter((_, i) => i !== idx); setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: nl}}); }} className="p-3 text-red-600 hover:bg-red-50 rounded-xl"><Trash2 size={18}/></button>
