export default PlayerReport;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const addSub = () => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' }]
      }
    });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // فحص الإيقاف الصارم عند اختيار البديل
    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      alert(`🚨 تنبيه نظام الانضباط بنادي الكرامة:\nاللاعب موقوف ولا يمكنه المشاركة.\nالسبب: ${susp.hasActiveRed ? 'بطاقة حمراء مباشرة' : 'تراكم 3 إنذارات صفراء'}.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    if (!person) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;

    // حساب الوقت الإجمالي الفعلي للمباراة شاملاً الوقت بدل الضائع للشوطين
    const stop1 = parseInt(activeMatch.stoppageTime1 || '0');
    const stop2 = parseInt(activeMatch.stoppageTime2 || '0');
    const fullMatchTime = 90 + stop1 + stop2;

    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) {
      // اللاعب الخارج يحتسب له فقط حتى لحظة خروجه
      newLineup.starters[starterIdx].minutesPlayed = minute.toString();
    }

    // اللاعب البديل يحتسب له: (الوقت الكلي للمباراة - دقيقة الدخول)
    // هذا يضمن دخول الوقت بدل الضائع ضمن دقائق لعب البديل
    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;
    const playedMins = fullMatchTime - minute;
    newLineup.subs[subIndex].minutesPlayed = playedMins > 0 ? playedMins.toString() : '0';

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addMatchEvent = (type: MatchEvent['type']) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvent: MatchEvent = { id: generateUUID(), type, player: '', minute: '', note: '' };
    setActiveMatch({ ...activeMatch, events: [...(activeMatch.events || []), newEvent] });
  };

  const updateMatchEvent = (id: string, field: keyof MatchEvent, value: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.map(e => e.id === id ? { ...e, [field]: value } : e) });
  };

  const removeMatchEvent = (id: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const updateActiveMatchLineup = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // فحص الإيقاف الصارم (رادار الانضباط)
    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      const p = state.people.find(x => x.id === playerId);
      alert(`⛔ حظر إشراك لاعب معاقب:\nاللاعب [${p?.name}] موقوف حالياً.\nالسبب: ${susp.hasActiveRed ? 'طرد مباشر' : 'تراكم 3 بطاقات صفراء'}.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };

    // عند تعيين لاعب أساسي، القيمة الافتراضية هي وقت المباراة الكامل (سيتم تحديثه في حال التبديل)
    const totalStoppage = (parseInt(activeMatch.stoppageTime1 || '0')) + (parseInt(activeMatch.stoppageTime2 || '0'));
    const fullTime = 90 + totalStoppage;

    if (!person) newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    else newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: fullTime.toString() };

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatchDetails = (lockStatus: boolean = false) => {
    if (!activeMatch || isViewer) return;
    const finalLockStatus = isManager ? lockStatus : activeMatch.isCompleted;

    const stop1 = parseInt(activeMatch.stoppageTime1 || '0');
    const stop2 = parseInt(activeMatch.stoppageTime2 || '0');
    const fullTime = 90 + stop1 + stop2;

    const updatedLineup = { ...activeMatch.lineup };
    updatedLineup.starters = updatedLineup.starters.map(s => {
        // التأكد من أن اللاعبين الأساسيين الذين لم يستبدلوا حصلوا على كامل الوقت شاملاً الوقت الضائع
        const isSubbedOut = updatedLineup.subs.some(sub => sub.replacedPlayerId === s.playerId);
        if (!isSubbedOut && s.playerId) return { ...s, minutesPlayed: fullTime.toString() };
        return s;
    });

    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, lineup: updatedLineup, isCompleted: finalLockStatus } : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const inputStyle = "w-full bg-slate-50 border border-[#001F3F] rounded-xl py-2 px-3 font-black text-[#001F3F] text-xs shadow-inner focus:border-orange-600 outline-none";
  const labelStyle = "text-[10px] font-black text-[#001F3F] mr-1 uppercase block mb-1 tracking-tighter";

  return (
    <div className="space-y-4 md:space-y-6 pb-20 px-1 font-['Tajawal'] text-right" dir="rtl">
      <div className="bg-white p-4 rounded-2xl border-2 border-slate-900 flex justify-between items-center no-print shadow-md">
        <h2 className="text-sm md:text-xl font-black text-[#001F3F] flex items-center gap-2 uppercase tracking-tighter">
          <Trophy size={20} className="text-orange-600" /> إدارة مباريات الكرامة والبيانات الفنية
        </h2>
        {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-lg border-b-4 border-black active:translate-y-1 active:border-b-0 transition-all">جدولة مواجهة</button>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 no-print text-right">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-5 rounded-2xl border-2 border-slate-900 relative shadow-sm border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-4">
                <span className="bg-orange-600 text-white text-[8px] font-black px-2 py-0.5 rounded uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-500 tabular-nums">{m.date}</span>
             </div>
             <div className="text-center mb-6">
                <p className="text-2xl font-black text-[#001F3F] tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-bold text-sm text-slate-800 mt-2">الكرامة × {m.opponent}</p>
             </div>
             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-[10px] uppercase shadow-lg hover:bg-black transition-all">
                  {m.isCompleted ? 'تقرير المباراة والدقائق' : 'ضبط التشكيل والأحداث'}
                </button>
             </div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-xl z-[400] overflow-y-auto no-print">
           <div className="max-w-5xl mx-auto p-2 md:p-8 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[2.5rem] border-[6px] border-slate-900 p-4 md:p-10 shadow-2xl relative text-right">
                <header className="flex flex-col md:flex-row justify-between items-center mb-10 border-b-4 border-slate-900 pb-8 gap-4">
                   <div className="text-center md:text-right">
                      <h2 className="text-xl md:text-3xl font-black text-[#001F3F] tracking-tighter uppercase">{activeMatch.opponent} × الكرامة</h2>
                      <div className="flex gap-2 mt-3 justify-center md:justify-start">
                         <span className="bg-slate-100 text-[#001F3F] text-[10px] font-black px-3 py-1.5 rounded-full border border-slate-900">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-emerald-50 text-emerald-600 text-[10px] font-black px-3 py-1.5 rounded-full border border-emerald-200 flex items-center gap-1"><CheckCircle size={14}/> تقرير معتمد نهائياً</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-3 justify-center">
                      {isManager && (
                        <button onClick={() => saveMatchDetails(!activeMatch.isCompleted)} className={`${activeMatch.isCompleted ? 'bg-red-600' : 'bg-emerald-600'} text-white px-6 py-3 rounded-2xl font-black text-[11px] shadow-xl flex items-center gap-2 transition-all`}>
                          {activeMatch.isCompleted ? <Unlock size={18}/> : <CheckCircle size={18}/>} {activeMatch.isCompleted ? 'فتح التعديل' : 'اعتماد وحفظ الدقائق'}
                        </button>
                      )}
                      {!activeMatch.isCompleted && <button onClick={() => saveMatchDetails(false)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[11px] shadow-xl flex items-center gap-2 hover:bg-black transition-all"><Save size={18}/> حفظ مسودة</button>}
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-3 rounded-2xl border-2 border-slate-300 hover:bg-red-50 hover:text-red-600 transition-all"><X size={24}/></button>
                   </div>
                </header>

                <div className={`grid grid-cols-1 lg:grid-cols-12 gap-10 ${activeMatch.isCompleted ? 'opacity-90 pointer-events-none' : ''}`}>
                   <div className="lg:col-span-8 space-y-10">
                      {/* التشكيلة الأساسية */}
                      <section>
                         <h3 className="text-md font-black text-[#001F3F] mb-6 border-r-4 border-orange-600 pr-3 uppercase flex items-center gap-2"><Users size={20}/> التشكيلة الأساسية</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-200 shadow-sm flex flex-col gap-3">
                                  <div className="flex justify-between items-center">
                                     <span className="w-9 h-9 bg-[#001F3F] text-white rounded-xl flex items-center justify-center font-black text-sm shadow-md">#{s.number || (idx+1)}</span>
                                     <div className="flex items-center gap-1 text-[10px] font-black text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg border border-emerald-100">
                                        <Timer size={12}/> {s.minutesPlayed || '0'} د
                                     </div>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب متاح --</option>
                                     {getAvailablePlayers(s.playerId).map(p => (
                                       <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                     ))}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      {/* أحداث المباراة */}
                      <section className="bg-white p-6 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm space-y-6 text-right">
                         <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                            <h3 className="text-md font-black text-[#001F3F] uppercase flex items-center gap-2"><Sparkles size={20} className="text-orange-500"/> أحداث المباراة (أهداف، أسيست، بطاقات)</h3>
                            <div className="flex flex-wrap gap-2">
                               <button onClick={() => addMatchEvent('goal')} className="bg-emerald-600 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all"><Plus size={12}/> هدف</button>
                               <button onClick={() => addMatchEvent('assist')} className="bg-blue-500 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all"><Zap size={12}/> أسيست</button>
                               <button onClick={() => addMatchEvent('yellow')} className="bg-yellow-500 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all">🟨 إنذار</button>
                               <button onClick={() => addMatchEvent('red')} className="bg-red-600 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all">🟥 طرد</button>
                            </div>
                         </div>
                         <div className="space-y-3">
                            {activeMatch.events && activeMatch.events.map((ev) => (
                               <div key={ev.id} className={`p-4 rounded-2xl border-2 flex flex-col md:flex-row gap-4 items-center transition-all ${ev.type === 'goal' ? 'bg-emerald-50 border-emerald-200' : ev.type === 'assist' ? 'bg-blue-50 border-blue-200' : ev.type === 'yellow' ? 'bg-yellow-50 border-yellow-200' : ev.type === 'red' ? 'bg-red-50 border-red-200' : 'bg-slate-50 border-slate-100'}`}>
                                  <div className="flex items-center gap-2 min-w-[100px]">
                                     <span className="text-[10px] font-black uppercase p-2 bg-white rounded-xl shadow-sm border border-slate-200">
                                        {ev.type === 'goal' ? '⚽ هدف' : ev.type === 'assist' ? '👟 أسيست' : ev.type === 'yellow' ? '🟨 إنذار' : '🟥 طرد'}
                                     </span>
                                  </div>
                                  <div className="flex-1 w-full text-right">
                                     <select className={inputStyle} value={ev.player} onChange={e => updateMatchEvent(ev.id, 'player', e.target.value)}>
                                        <option value="">-- اختر اللاعب --</option>
                                        {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                     </select>
                                  </div>
                                  <div className="w-20">
                                     <input type="number" className={inputStyle + " text-center h-10 text-lg"} placeholder="د" value={ev.minute} onChange={e => updateMatchEvent(ev.id, 'minute', e.target.value)} />
                                  </div>
                                  <button onClick={() => removeMatchEvent(ev.id)} className="p-3 text-red-600 bg-red-50 hover:bg-red-600 hover:text-white rounded-xl transition-all shadow-sm"><Trash2 size={16}/></button>
                               </div>
                            ))}
