                      </section>

                      {/* التبديلات */}
                      <section className="bg-slate-50 p-6 rounded-[2.5rem] border-2 border-dashed border-[#001F3F]">
                         <div className="flex justify-between items-center mb-6">
                            <h3 className="text-md font-black text-[#001F3F] uppercase flex items-center gap-2"><Users size={20}/> مقاعد الاحتياط والتبديلات</h3>
                            <button onClick={addSub} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] flex items-center gap-2 shadow-lg hover:bg-black transition-all">
                               <Plus size={16}/> إضافة تبديل
                            </button>
                         </div>
                         <div className="space-y-4">
                            {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="bg-white p-5 rounded-2xl border-2 border-slate-200 flex flex-col md:flex-row gap-4 items-end md:items-center shadow-sm hover:border-blue-900 transition-all">
                                  <div className="flex-1 w-full space-y-1">
                                     <label className={labelStyle}>اللاعب البديل (الداخل)</label>
                                     <select className={inputStyle} value={s.playerId} onChange={e => updateSub(idx, e.target.value)}>
                                        <option value="">-- دخول لاعب --</option>
                                        {getAvailablePlayers(s.playerId).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                     </select>
                                  </div>
                                  <div className="flex-1 w-full space-y-1">
                                     <label className={labelStyle}>بدلاً من (الخارج)</label>
                                     <select className={inputStyle} value={s.replacedPlayerId || ''} onChange={e => handleSubstitutionCalculation(idx, e.target.value, s.substitutionMinute || '0')}>
                                        <option value="">-- خروج لاعب --</option>
                                        {activeMatch.lineup.starters.filter(st => st.playerId).map(st => <option key={st.playerId} value={st.playerId}>{st.name}</option>)}
                                     </select>
                                  </div>
                                  <div className="w-20 space-y-1">
                                     <label className={labelStyle}>دقيقة</label>
                                     <input type="number" className={inputStyle + " text-center"} value={s.substitutionMinute || ''} placeholder="0" onChange={e => handleSubstitutionCalculation(idx, s.replacedPlayerId || '', e.target.value)} />
                                  </div>
                                  <div className="w-24 text-center">
                                     <p className="text-[8px] font-black text-emerald-600 uppercase">دقائق اللعب</p>
                                     <p className="text-xl font-black text-[#001F3F] tabular-nums">{s.minutesPlayed || '0'}</p>
                                  </div>
                                  <button onClick={() => { const nl = activeMatch.lineup.subs.filter((_, i) => i !== idx); setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: nl}}); }} className="p-3 text-red-600 hover:bg-red-50 rounded-xl"><Trash2 size={18}/></button>
                               </div>
                            ))}
                         </div>
                      </section>
                   </div>

                   <div className="lg:col-span-4 space-y-8">
                      {/* النتيجة والوقت الضائع */}
                      <section className="bg-slate-900 text-white p-8 rounded-[3rem] border-4 border-orange-600 text-center shadow-2xl relative overflow-hidden">
                         <div className="absolute top-0 right-0 w-24 h-24 bg-orange-600/10 rounded-full -mr-12 -mt-12"></div>
                         <h3 className="text-[12px] font-black text-orange-400 mb-8 uppercase tracking-[0.3em]">النتيجة والوقت المضاف</h3>
                         <div className="flex justify-center items-center gap-6 mb-10">
                            <div className="space-y-2">
                               <p className="text-[10px] font-black opacity-50">الكرامة</p>
                               <input type="number" className="w-20 h-20 bg-white/10 border-2 border-white/20 text-white rounded-[1.5rem] text-center font-black text-4xl outline-none focus:border-orange-600" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                            </div>
                            <span className="text-5xl font-black text-orange-600">:</span>
                            <div className="space-y-2">
                               <p className="text-[10px] font-black opacity-50">الخصم</p>
                               <input type="number" className="w-20 h-20 bg-white/10 border-2 border-white/20 text-white rounded-[1.5rem] text-center font-black text-4xl outline-none focus:border-white" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                            </div>
                         </div>
                         <div className="grid grid-cols-2 gap-4 border-t-2 border-white/5 pt-8">
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">ضائع (ش 1)</label>
                               <input type="number" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-center text-white font-black text-lg" value={activeMatch.stoppageTime1} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                            </div>
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">ضائع (ش 2)</label>
                               <input type="number" className="w-full bg-white/5 border border-white/10 rounded-xl p-3 text-center text-white font-black text-lg" value={activeMatch.stoppageTime2} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                            </div>
                         </div>
                      </section>

                      <section className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 shadow-sm space-y-4">
                         <h3 className="font-black text-sm text-[#001F3F] flex items-center gap-2 border-b pb-3"><FileText size={20} className="text-blue-600"/> التقرير الفني والملاحظات</h3>
                         <textarea className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 font-bold text-xs text-slate-800 outline-none h-48 resize-none focus:border-orange-600 transition-all shadow-inner" 
                                   value={activeMatch.notes || ''} onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})} placeholder="اكتب الملاحظات الفنية للمباراة، التبديلات المؤثرة، وحالة اللاعبين..."></textarea>
                      </section>

                      <div className="bg-orange-50 p-6 rounded-[2rem] border-2 border-orange-200">
                         <h4 className="font-black text-xs text-orange-800 mb-3 flex items-center gap-2"><Info size={16}/> تنبيه المحرك الذكي</h4>
                         <p className="text-[10px] font-black text-orange-600 leading-relaxed italic">يتم احتساب دقائق البديل بالمعادلة: (90+الوقت الضائع لشوطين) - دقيقة الدخول. أي أن الوقت بدل الضائع يضاف تلقائياً لرصيد البديل.</p>
                      </div>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

