import React, { useMemo, useState, useEffect } from 'react';
import { 
  ChevronRight, Printer, Target, AlertTriangle, Clock, Calendar, 
  TrendingUp, Users, Shield, MapPin, Activity, Globe, Trophy, 
  CheckCircle, Award, GraduationCap, Home, StickyNote, CreditCard, BarChart3, PieChart,
  Hash, ClipboardList, User, Timer, FileText, Briefcase, Sparkles, Loader2, X, BrainCircuit,
  HeartPulse, ShieldAlert, Gavel, Smartphone, CalendarDays, Wallet, Zap, ShieldCheck,
  Medal, Swords, Star, UserPlus, Info, Phone, Fingerprint, Save, Edit3, ChevronDown
} from 'lucide-react';
import { AppState, Person, Match, AttendanceRecord, MatchEvent } from '../types';
import ClubLogo from './ClubLogo';
import { GoogleGenAI } from "@google/genai";
import { supabase } from '../App';

interface PlayerReportProps {
  state: AppState;
  player: Person | null;
  onBack: () => void;
}

const PlayerReport: React.FC<PlayerReportProps> = ({ state, player, onBack }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isSavingReport, setIsSavingReport] = useState(false);
  const [monthlyNotes, setMonthlyNotes] = useState<{ [key: string]: string }>(player?.monthlyReports || {});

  const months = ["كانون الثاني", "شباط", "آذار", "نيسان", "أيار", "حزيران", "تموز", "آب", "أيلول", "تشرين الأول", "تشرين الثاني", "كانون الأول"];
  const currentMonthIndex = new Date().getMonth();
  const [selectedMonth, setSelectedMonth] = useState(months[currentMonthIndex]);

  if (!player || !state.currentUser) return null;

  const isStaff = player.role !== 'لاعب';
  const isViewer = state.currentUser.role === 'مشاهد';

  // --- ربط وحساب إحصائيات المشاركة شاملة الأسيست والدقائق المحسوبة بدقة ---
  const matchStats = useMemo(() => {
    if (isStaff) return { totalMins: 0, officialMins: 0, goals: 0, assists: 0, yellows: 0, reds: 0, list: [] };

    let totalMins = 0;
    let totalGoals = 0;
    let totalAssists = 0;
    let totalYellows = 0;
    let totalReds = 0;

    const statsList = state.matches
      .filter(m => m.isCompleted)
      .sort((a, b) => b.date.localeCompare(a.date))
      .map(m => {
        const starter = m.lineup.starters.find(s => s.playerId === player.id);
        const sub = m.lineup.subs.find(s => s.playerId === player.id);

        let mins = parseInt(starter?.minutesPlayed || sub?.minutesPlayed || '0') || 0;
        totalMins += mins;

        // حساب الأحداث بناءً على اسم أو معرف اللاعب
        const goals = m.events ? m.events.filter(e => e.type === 'goal' && (e.player === player.id || e.player === player.name)).length : 0;
        const assists = m.events ? m.events.filter(e => e.type === 'assist' && (e.player === player.id || e.player === player.name)).length : 0;
        const matchYellows = m.events ? m.events.filter(e => e.type === 'yellow' && (e.player === player.id || e.player === player.name)).length : 0;
        const matchReds = m.events ? m.events.filter(e => e.type === 'red' && (e.player === player.id || e.player === player.name)).length : 0;

        totalGoals += goals;
        totalAssists += assists;
        totalYellows += matchYellows;
        totalReds += matchReds;

        return { 
          opponent: m.opponent, 
          date: m.date, 
          type: m.matchType,
          mins, 
          goals, 
          assists,
          yellows: matchYellows,
          reds: matchReds,
          wasStarter: !!starter,
          played: !!(starter || sub) 
        };
      })
      .filter(s => s.played);

    return {
      totalMins,
      goals: totalGoals,
      assists: totalAssists,
      yellows: totalYellows,
      reds: totalReds,
      list: statsList
    };
  }, [state.matches, player, isStaff]);

  const attendanceData = useMemo(() => {
    const sessions = state.sessions.filter(s => s.category === player.category);
    const sessionIds = sessions.map(s => s.id);
    const allRecords = state.attendance.filter(a => a.personId === player.id && sessionIds.includes(a.sessionId));
    const uniqueRecords = Array.from(new Map(allRecords.map(r => [r.sessionId, r])).values()) as AttendanceRecord[];
    const present = uniqueRecords.filter(r => r.status === 'حاضر').length;
    const late = uniqueRecords.filter(r => r.status === 'متأخر').length;
    const rate = sessions.length > 0 ? Math.min(100, Math.round(((present + late * 0.7) / sessions.length) * 100)) : 0;
    return { rate, total: sessions.length };
  }, [state.attendance, state.sessions, player]);

  const handleSaveMonthlyReport = async (monthKey: string) => {
    if (isViewer) return;
    setIsSavingReport(true);
    try {
      const { error } = await supabase.from('people').update({ monthlyReports: monthlyNotes }).eq('id', player.id);
      if (error) throw error;
      alert(`تم تحديث التقرير بنجاح.`);
    } catch (err: any) { alert(err.message); } finally { setIsSavingReport(false); }
  };

  const handleGenerateAiAnalysis = async () => {
    setLoadingAi(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `حلل بيانات اللاعب ${player.name}: دقائق(${matchStats.totalMins}), أهداف(${matchStats.goals}), أسيست(${matchStats.assists}), بطاقات(${matchStats.yellows} صفراء, ${matchStats.reds} حمراء). قدم تقريراً فنياً محترفاً لنادي الكرامة السوري.`;
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      setAiAnalysis(response.text || "فشل التحليل.");
    } catch (e) { setAiAnalysis("خطأ في الاتصال بالذكاء الاصطناعي."); } finally { setLoadingAi(false); }
  };

  return (
    <div className="space-y-6 md:space-y-10 animate-in fade-in duration-700 pb-24 px-2 md:px-0 text-right font-['Tajawal']" dir="rtl">

      <div className="flex flex-row justify-between items-center no-print gap-3">
        <button onClick={onBack} className="flex items-center gap-2 text-[#001F3F] font-black bg-white border-2 border-[#001F3F] px-6 py-3 rounded-2xl text-sm shadow-md active:scale-95 transition-all">
          <ChevronRight size={20} /> العودة لقائمة الفريق
        </button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 shadow-xl border-b-4 border-black hover:bg-black transition-all">
          <Printer size={20} /> طباعة السجل الكامل
        </button>
      </div>

      <div className="solid-panel overflow-hidden relative !shadow-none border-4 border-[#001F3F]">
        <div className="bg-[#001F3F] h-28 md:h-40 relative">
          <div className="absolute -bottom-14 right-8 md:right-16 flex items-end gap-6 md:gap-10">
            <div className="w-28 h-28 md:w-48 md:h-48 bg-white rounded-3xl md:rounded-[3rem] border-[6px] md:border-[10px] border-white flex items-center justify-center font-black text-5xl md:text-8xl text-[#001F3F] shadow-2xl relative z-10">
               {player.name.charAt(0)}
               <div className="absolute -top-4 -left-4 bg-orange-600 text-white w-12 h-12 rounded-full flex items-center justify-center text-xl border-4 border-white shadow-lg">
                  #{player.number || '0'}
               </div>
            </div>
            <div className="mb-4">
              <h1 className="text-2xl md:text-5xl font-black text-white drop-shadow-lg tracking-tight leading-tight">{player.name}</h1>
              <div className="flex gap-3 mt-2">
                 <span className="bg-orange-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.role}</span>
                 <span className="bg-blue-600 text-white text-[10px] md:text-[12px] font-black px-4 md:px-6 py-1.5 rounded-xl border-2 border-white uppercase shadow-lg">{player.category}</span>
              </div>
            </div>
          </div>
        </div>
        <div className="h-16 md:h-24"></div>

        {/* إحصائيات سريعة */}
        <div className="px-6 md:px-16 pb-10 grid grid-cols-2 md:grid-cols-7 gap-3 md:gap-4 text-right">
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Timer className="text-[#001F3F] mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900 uppercase">إجمالي الدقائق</span>
             <p className="text-xl font-black text-[#001F3F] tabular-nums">{matchStats.totalMins}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Trophy className="text-emerald-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900 uppercase">الأهداف</span>
             <p className="text-xl font-black text-emerald-700 tabular-nums">{matchStats.goals}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <Zap className="text-blue-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-slate-900 uppercase">أسيست</span>
             <p className="text-xl font-black text-blue-700 tabular-nums">{matchStats.assists}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <div className="w-3 h-5 bg-yellow-400 rounded-sm mb-1 shadow-sm border border-yellow-600"></div>
             <span className="text-[8px] font-black text-slate-900 uppercase">إنذارات</span>
             <p className="text-xl font-black text-yellow-600 tabular-nums">{matchStats.yellows}</p>
           </div>
           <div className="bg-slate-50 p-4 rounded-2xl border-2 border-[#001F3F] flex flex-col items-center shadow-sm">
             <div className="w-3 h-5 bg-red-600 rounded-sm mb-1 shadow-sm border border-red-800"></div>
             <span className="text-[8px] font-black text-slate-900 uppercase">طرد</span>
             <p className="text-xl font-black text-red-600 tabular-nums">{matchStats.reds}</p>
           </div>
           <div className="bg-emerald-50 p-4 rounded-2xl border-2 border-emerald-600 flex flex-col items-center shadow-sm col-span-2 md:col-span-1">
             <TrendingUp className="text-emerald-600 mb-1" size={24}/>
             <span className="text-[8px] font-black text-emerald-900 uppercase">الالتزام</span>
             <p className="text-xl font-black text-emerald-700">%{attendanceData.rate}</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-10">
        <div className="lg:col-span-2 space-y-8 md:space-y-10">

          {/* سجل المشاركة الفني الفعلي */}
          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-2 border-[#001F3F] shadow-md">
             <h3 className="text-lg md:text-2xl font-black text-[#001F3F] mb-8 flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                <ClipboardList className="text-blue-700" size={28}/> سجل المشاركة الفنية (دقائق اللعب النشطة)
             </h3>
             <div className="overflow-x-auto -mx-6 md:mx-0">
               <table className="w-full text-right border-collapse min-w-[600px]">
                 <thead>
                    <tr className="bg-slate-100 border-y-2 border-[#001F3F] text-[11px] font-black uppercase text-slate-900">
                       <th className="p-4 border-l">المنافس</th>
                       <th className="p-4 border-l text-center">الوضعية</th>
                       <th className="p-4 border-l text-center">الدقائق</th>
                       <th className="p-4 border-l text-center">أهداف</th>
                       <th className="p-4 border-l text-center">أسيست</th>
                       <th className="p-4 border-l text-center">كروت</th>
                       <th className="p-4 text-center">التاريخ</th>
                    </tr>
                 </thead>
                 <tbody>
                    {matchStats.list.length > 0 ? matchStats.list.map((m, i) => (
                      <tr key={i} className="border-b border-slate-200 text-sm font-black hover:bg-slate-50 transition-colors">
                         <td className="p-4 border-l">
                            <span className="text-[#001F3F] font-bold">الكرامة × {m.opponent}</span>
                         </td>
                         <td className="p-4 border-l text-center">
                            <span className={`text-[9px] px-2 py-1 rounded-lg ${m.wasStarter ? 'bg-orange-100 text-orange-700' : 'bg-blue-100 text-blue-700'}`}>
                               {m.wasStarter ? 'أساسي' : 'بديل'}
                            </span>
                         </td>
                         <td className="p-4 border-l text-center font-black text-emerald-600 tabular-nums">{m.mins} د</td>
                         <td className="p-4 border-l text-center text-emerald-700 font-bold">{m.goals || '-'}</td>
                         <td className="p-4 border-l text-center text-blue-700 font-bold">{m.assists || '-'}</td>
                         <td className="p-4 border-l text-center flex justify-center gap-1">
                            {m.yellows > 0 && Array(m.yellows).fill(0).map((_, j) => <div key={j} className="w-2.5 h-4 bg-yellow-400 rounded-sm"></div>)}
                            {m.reds > 0 && <div className="w-2.5 h-4 bg-red-600 rounded-sm"></div>}
                         </td>
                         <td className="p-4 text-center text-slate-400 text-[10px] tabular-nums">{m.date}</td>
                      </tr>
                    )) : (
                      <tr><td colSpan={7} className="p-16 text-center text-slate-300 font-black italic">لا يوجد سجل مشاركات معتمد حالياً.</td></tr>
                    )}
                 </tbody>
               </table>
             </div>
          </div>

          {/* التقييم الشهري */}
          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-2 border-blue-900 shadow-sm">
             <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4 border-r-4 border-blue-600 pr-4">
                <h3 className="text-lg md:text-2xl font-black text-[#001F3F] flex items-center gap-3">
                   <CalendarDays className="text-blue-700" size={28}/> التقييم الفني والبدني المستمر
                </h3>
                <div className="flex items-center gap-3 w-full md:w-auto">
                   <select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="flex-1 bg-slate-100 border-2 border-blue-900 rounded-xl py-2 px-4 font-black text-sm outline-none">
                     {months.map(m => <option key={m} value={m}>{m}</option>)}
                   </select>
                   {!isViewer && (
                      <button onClick={() => handleSaveMonthlyReport(selectedMonth)} className="bg-emerald-600 text-white px-4 py-2.5 rounded-xl font-black text-[10px] flex items-center gap-2 hover:bg-black transition-all">
                         <Save size={14}/> حفظ التقرير
                      </button>
                   )}
                </div>
             </div>
             <textarea 
                className="w-full bg-slate-50 border-2 border-slate-200 rounded-2xl p-6 text-xs font-bold text-slate-800 h-48 resize-none outline-none focus:border-blue-600 transition-all shadow-inner"
                placeholder={`سجل التقييم الفني والبدني لشهر ${selectedMonth}...`}
                value={monthlyNotes[selectedMonth] || ''}
                onChange={(e) => setMonthlyNotes({ ...monthlyNotes, [selectedMonth]: e.target.value })}
                readOnly={isViewer}
             ></textarea>
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-[#001F3F] p-8 md:p-10 rounded-[3rem] border-4 border-black text-white shadow-2xl relative overflow-hidden">
             <div className="flex items-center gap-3 mb-8 border-b border-white/10 pb-4">
                <ShieldCheck className="text-orange-500" size={24}/>
                <h3 className="text-sm md:text-lg font-black uppercase tracking-tighter">الوضعية الثبوتية والتعاقدية</h3>
             </div>
             <div className="space-y-4 text-sm font-medium">
                <div className="flex justify-between border-b border-white/5 pb-2">
                   <span className="text-slate-400">الرقم الوطني:</span>
                   <span className="font-bold tabular-nums">{player.nationalId}</span>
                </div>
                <div className="flex justify-between border-b border-white/5 pb-2">
                   <span className="text-slate-400">الرقم الاتحادي:</span>
                   <span className="font-bold tabular-nums">{player.federalNumber || '---'}</span>
                </div>
                <div className="mt-8 pt-4 bg-white/5 p-4 rounded-2xl border border-white/10">
                   <p className="text-orange-500 font-black text-[10px] uppercase mb-4 flex items-center gap-2"><CreditCard size={14}/> تفاصيل العقد</p>
                   <div className="flex justify-between text-xs">
                      <span className="text-slate-400">القيمة السنوية:</span>
                      <span className="font-black text-emerald-400">{player.contractValue || '0.00 SP'}</span>
                   </div>
                </div>
             </div>
          </div>

          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border-2 border-red-900 shadow-md">
             <h4 className="text-sm md:text-lg font-black text-red-700 mb-6 flex items-center gap-3">
                <Gavel size={24}/> سجل العقوبات الإدارية والجزائية
             </h4>
             <p className="text-[12px] font-black text-slate-900 leading-relaxed italic p-5 bg-red-50 rounded-2xl border-r-4 border-red-700">
                {player.penalties || "السجل نظيف إدارياً."}
             </p>
             <div className="mt-4 flex gap-2">
                {matchStats.reds > 0 && <span className="bg-red-600 text-white text-[9px] font-black px-3 py-1 rounded-full">طرد سابق</span>}
                {matchStats.yellows >= 3 && <span className="bg-yellow-500 text-white text-[9px] font-black px-3 py-1 rounded-full">تراكم إنذارات</span>}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PlayerReport;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
  };

  const addSub = () => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({
      ...activeMatch,
      lineup: {
        ...activeMatch.lineup,
        subs: [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' }]
      }
    });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // فحص الإيقاف الصارم عند اختيار البديل
    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      alert(`🚨 تنبيه نظام الانضباط بنادي الكرامة:\nاللاعب موقوف ولا يمكنه المشاركة.\nالسبب: ${susp.hasActiveRed ? 'بطاقة حمراء مباشرة' : 'تراكم 3 إنذارات صفراء'}.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    if (!person) return;
    const newSubs = [...activeMatch.lineup.subs];
    newSubs[index] = { ...newSubs[index], playerId: person.id, name: person.name, number: person.number?.toString() || '' };
    setActiveMatch({ ...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs } });
  };

  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;

    // حساب الوقت الإجمالي الفعلي للمباراة شاملاً الوقت بدل الضائع للشوطين
    const stop1 = parseInt(activeMatch.stoppageTime1 || '0');
    const stop2 = parseInt(activeMatch.stoppageTime2 || '0');
    const fullMatchTime = 90 + stop1 + stop2;

    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) {
      // اللاعب الخارج يحتسب له فقط حتى لحظة خروجه
      newLineup.starters[starterIdx].minutesPlayed = minute.toString();
    }

    // اللاعب البديل يحتسب له: (الوقت الكلي للمباراة - دقيقة الدخول)
    // هذا يضمن دخول الوقت بدل الضائع ضمن دقائق لعب البديل
    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;
    const playedMins = fullMatchTime - minute;
    newLineup.subs[subIndex].minutesPlayed = playedMins > 0 ? playedMins.toString() : '0';

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addMatchEvent = (type: MatchEvent['type']) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newEvent: MatchEvent = { id: generateUUID(), type, player: '', minute: '', note: '' };
    setActiveMatch({ ...activeMatch, events: [...(activeMatch.events || []), newEvent] });
  };

  const updateMatchEvent = (id: string, field: keyof MatchEvent, value: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.map(e => e.id === id ? { ...e, [field]: value } : e) });
  };

  const removeMatchEvent = (id: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const updateActiveMatchLineup = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;

    // فحص الإيقاف الصارم (رادار الانضباط)
    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      const p = state.people.find(x => x.id === playerId);
      alert(`⛔ حظر إشراك لاعب معاقب:\nاللاعب [${p?.name}] موقوف حالياً.\nالسبب: ${susp.hasActiveRed ? 'طرد مباشر' : 'تراكم 3 بطاقات صفراء'}.`);
      return;
    }

    const person = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };

    // عند تعيين لاعب أساسي، القيمة الافتراضية هي وقت المباراة الكامل (سيتم تحديثه في حال التبديل)
    const totalStoppage = (parseInt(activeMatch.stoppageTime1 || '0')) + (parseInt(activeMatch.stoppageTime2 || '0'));
    const fullTime = 90 + totalStoppage;

    if (!person) newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    else newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: fullTime.toString() };

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatchDetails = (lockStatus: boolean = false) => {
    if (!activeMatch || isViewer) return;
    const finalLockStatus = isManager ? lockStatus : activeMatch.isCompleted;

    const stop1 = parseInt(activeMatch.stoppageTime1 || '0');
    const stop2 = parseInt(activeMatch.stoppageTime2 || '0');
    const fullTime = 90 + stop1 + stop2;

    const updatedLineup = { ...activeMatch.lineup };
    updatedLineup.starters = updatedLineup.starters.map(s => {
        // التأكد من أن اللاعبين الأساسيين الذين لم يستبدلوا حصلوا على كامل الوقت شاملاً الوقت الضائع
        const isSubbedOut = updatedLineup.subs.some(sub => sub.replacedPlayerId === s.playerId);
        if (!isSubbedOut && s.playerId) return { ...s, minutesPlayed: fullTime.toString() };
        return s;
    });

    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, lineup: updatedLineup, isCompleted: finalLockStatus } : m)
    }));
    setActiveMatch(null);
  };

  const getAvailablePlayers = (currentId: string) => {
    const selectedIds = [
      ...activeMatch!.lineup.starters.map(s => s.playerId),
      ...activeMatch!.lineup.subs.map(s => s.playerId)
    ].filter(id => id && id !== currentId);
    return state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch?.category && !selectedIds.includes(p.id));
  };

  const inputStyle = "w-full bg-slate-50 border border-[#001F3F] rounded-xl py-2 px-3 font-black text-[#001F3F] text-xs shadow-inner focus:border-orange-600 outline-none";
  const labelStyle = "text-[10px] font-black text-[#001F3F] mr-1 uppercase block mb-1 tracking-tighter";

  return (
    <div className="space-y-4 md:space-y-6 pb-20 px-1 font-['Tajawal'] text-right" dir="rtl">
      <div className="bg-white p-4 rounded-2xl border-2 border-slate-900 flex justify-between items-center no-print shadow-md">
        <h2 className="text-sm md:text-xl font-black text-[#001F3F] flex items-center gap-2 uppercase tracking-tighter">
          <Trophy size={20} className="text-orange-600" /> إدارة مباريات الكرامة والبيانات الفنية
        </h2>
        {!isViewer && <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-4 py-2 rounded-xl font-black text-[10px] shadow-lg border-b-4 border-black active:translate-y-1 active:border-b-0 transition-all">جدولة مواجهة</button>}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 no-print text-right">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-5 rounded-2xl border-2 border-slate-900 relative shadow-sm border-b-8 transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-4">
                <span className="bg-orange-600 text-white text-[8px] font-black px-2 py-0.5 rounded uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-500 tabular-nums">{m.date}</span>
             </div>
             <div className="text-center mb-6">
                <p className="text-2xl font-black text-[#001F3F] tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-bold text-sm text-slate-800 mt-2">الكرامة × {m.opponent}</p>
             </div>
             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-[10px] uppercase shadow-lg hover:bg-black transition-all">
                  {m.isCompleted ? 'تقرير المباراة والدقائق' : 'ضبط التشكيل والأحداث'}
                </button>
             </div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-xl z-[400] overflow-y-auto no-print">
           <div className="max-w-5xl mx-auto p-2 md:p-8 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[2.5rem] border-[6px] border-slate-900 p-4 md:p-10 shadow-2xl relative text-right">
                <header className="flex flex-col md:flex-row justify-between items-center mb-10 border-b-4 border-slate-900 pb-8 gap-4">
                   <div className="text-center md:text-right">
                      <h2 className="text-xl md:text-3xl font-black text-[#001F3F] tracking-tighter uppercase">{activeMatch.opponent} × الكرامة</h2>
                      <div className="flex gap-2 mt-3 justify-center md:justify-start">
                         <span className="bg-slate-100 text-[#001F3F] text-[10px] font-black px-3 py-1.5 rounded-full border border-slate-900">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-emerald-50 text-emerald-600 text-[10px] font-black px-3 py-1.5 rounded-full border border-emerald-200 flex items-center gap-1"><CheckCircle size={14}/> تقرير معتمد نهائياً</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-3 justify-center">
                      {isManager && (
                        <button onClick={() => saveMatchDetails(!activeMatch.isCompleted)} className={`${activeMatch.isCompleted ? 'bg-red-600' : 'bg-emerald-600'} text-white px-6 py-3 rounded-2xl font-black text-[11px] shadow-xl flex items-center gap-2 transition-all`}>
                          {activeMatch.isCompleted ? <Unlock size={18}/> : <CheckCircle size={18}/>} {activeMatch.isCompleted ? 'فتح التعديل' : 'اعتماد وحفظ الدقائق'}
                        </button>
                      )}
                      {!activeMatch.isCompleted && <button onClick={() => saveMatchDetails(false)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[11px] shadow-xl flex items-center gap-2 hover:bg-black transition-all"><Save size={18}/> حفظ مسودة</button>}
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-3 rounded-2xl border-2 border-slate-300 hover:bg-red-50 hover:text-red-600 transition-all"><X size={24}/></button>
                   </div>
                </header>

                <div className={`grid grid-cols-1 lg:grid-cols-12 gap-10 ${activeMatch.isCompleted ? 'opacity-90 pointer-events-none' : ''}`}>
                   <div className="lg:col-span-8 space-y-10">
                      {/* التشكيلة الأساسية */}
                      <section>
                         <h3 className="text-md font-black text-[#001F3F] mb-6 border-r-4 border-orange-600 pr-3 uppercase flex items-center gap-2"><Users size={20}/> التشكيلة الأساسية</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-200 shadow-sm flex flex-col gap-3">
                                  <div className="flex justify-between items-center">
                                     <span className="w-9 h-9 bg-[#001F3F] text-white rounded-xl flex items-center justify-center font-black text-sm shadow-md">#{s.number || (idx+1)}</span>
                                     <div className="flex items-center gap-1 text-[10px] font-black text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg border border-emerald-100">
                                        <Timer size={12}/> {s.minutesPlayed || '0'} د
                                     </div>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateActiveMatchLineup(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب متاح --</option>
                                     {getAvailablePlayers(s.playerId).map(p => (
                                       <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                     ))}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      {/* أحداث المباراة */}
                      <section className="bg-white p-6 rounded-[2.5rem] border-2 border-[#001F3F] shadow-sm space-y-6 text-right">
                         <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                            <h3 className="text-md font-black text-[#001F3F] uppercase flex items-center gap-2"><Sparkles size={20} className="text-orange-500"/> أحداث المباراة (أهداف، أسيست، بطاقات)</h3>
                            <div className="flex flex-wrap gap-2">
                               <button onClick={() => addMatchEvent('goal')} className="bg-emerald-600 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all"><Plus size={12}/> هدف</button>
                               <button onClick={() => addMatchEvent('assist')} className="bg-blue-500 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all"><Zap size={12}/> أسيست</button>
                               <button onClick={() => addMatchEvent('yellow')} className="bg-yellow-500 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all">🟨 إنذار</button>
                               <button onClick={() => addMatchEvent('red')} className="bg-red-600 text-white px-3 py-1.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-1 hover:scale-105 transition-all">🟥 طرد</button>
                            </div>
                         </div>
                         <div className="space-y-3">
                            {activeMatch.events && activeMatch.events.map((ev) => (
                               <div key={ev.id} className={`p-4 rounded-2xl border-2 flex flex-col md:flex-row gap-4 items-center transition-all ${ev.type === 'goal' ? 'bg-emerald-50 border-emerald-200' : ev.type === 'assist' ? 'bg-blue-50 border-blue-200' : ev.type === 'yellow' ? 'bg-yellow-50 border-yellow-200' : ev.type === 'red' ? 'bg-red-50 border-red-200' : 'bg-slate-50 border-slate-100'}`}>
                                  <div className="flex items-center gap-2 min-w-[100px]">
                                     <span className="text-[10px] font-black uppercase p-2 bg-white rounded-xl shadow-sm border border-slate-200">
                                        {ev.type === 'goal' ? '⚽ هدف' : ev.type === 'assist' ? '👟 أسيست' : ev.type === 'yellow' ? '🟨 إنذار' : '🟥 طرد'}
                                     </span>
                                  </div>
                                  <div className="flex-1 w-full text-right">
                                     <select className={inputStyle} value={ev.player} onChange={e => updateMatchEvent(ev.id, 'player', e.target.value)}>
                                        <option value="">-- اختر اللاعب --</option>
                                        {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(l => l.playerId).map(p => <option key={p.playerId} value={p.playerId}>{p.name}</option>)}
                                     </select>
                                  </div>
                                  <div className="w-20">
                                     <input type="number" className={inputStyle + " text-center h-10 text-lg"} placeholder="د" value={ev.minute} onChange={e => updateMatchEvent(ev.id, 'minute', e.target.value)} />
                                  </div>
                                  <button onClick={() => removeMatchEvent(ev.id)} className="p-3 text-red-600 bg-red-50 hover:bg-red-600 hover:text-white rounded-xl transition-all shadow-sm"><Trash2 size={16}/></button>
                               </div>
                            ))}
                         </div>
                      </section>

                      {/* التبديلات */}
                      <section className="bg-slate-50 p-6 rounded-[2.5rem] border-2 border-dashed border-[#001F3F]">
