          <ChevronRight size={20} /> العودة لقائمة الفريق
        </button>
        <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-10 py-3 rounded-2xl font-black text-sm flex items-center gap-2 shadow-[4px_4px_0px_0px_rgba(255,107,0,1)] border-b-4 border-black hover:bg-black transition-all">
          <Printer size={20} /> طباعة السجل الكامل
        </button>
      </div>

      <div className="bg-white rounded-[3rem] overflow-hidden relative border-4 border-[#001F3F] shadow-[12px_12px_0px_0px_rgba(0,31,63,1)]">
        <div className="bg-[#001F3F] h-32 md:h-48 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10"></div>
          <div className="absolute -bottom-16 right-8 md:right-20 flex items-end gap-6 md:gap-12">
            <div className="w-32 h-32 md:w-56 md:h-56 bg-white rounded-[2.5rem] md:rounded-[4rem] border-[8px] md:border-[12px] border-white flex items-center justify-center font-black text-6xl md:text-9xl text-[#001F3F] shadow-2xl relative z-10">
               {player.name.charAt(0)}
               <div className="absolute -top-6 -left-6 bg-orange-600 text-white w-14 h-14 md:w-20 md:h-20 rounded-full flex items-center justify-center text-2xl md:text-4xl border-[6px] border-white shadow-2xl font-black">
                  #{player.number || '0'}
               </div>
            </div>
            <div className="mb-8">
              <h1 className="text-3xl md:text-6xl font-black text-white drop-shadow-[0_4px_4px_rgba(0,0,0,0.5)] tracking-tight leading-none uppercase">{player.name}</h1>
              <div className="flex gap-4 mt-4">
                 <span className="bg-orange-600 text-white text-xs md:text-sm font-black px-6 py-2 rounded-2xl border-2 border-white uppercase shadow-xl">{player.role}</span>
                 <span className="bg-blue-600 text-white text-xs md:text-sm font-black px-6 py-2 rounded-2xl border-2 border-white uppercase shadow-xl">{player.category}</span>
              </div>
            </div>
          </div>
