                <div className="flex justify-between items-center mb-8">
                   <h4 className="text-sm font-black flex items-center gap-3 uppercase tracking-widest text-orange-500">
                      <BrainCircuit size={28} className="drop-shadow-sm"/> تحليل الأداء الرقمي الذكي
                   </h4>
                   <button onClick={handleGenerateAiAnalysis} disabled={loadingAi} className="bg-orange-600 text-white p-3 rounded-2xl hover:scale-110 active:scale-95 transition-all disabled:opacity-30 shadow-xl border-b-4 border-black">
                     {loadingAi ? <Loader2 size={24} className="animate-spin"/> : <Sparkles size={24}/>}
                   </button>
                </div>
                <div className="flex-1 bg-black/30 p-6 rounded-[2rem] border-2 border-white/5">
                   {aiAnalysis ? (
                      <div className="text-[13px] leading-relaxed font-black text-white overflow-y-auto max-h-[300px] custom-scrollbar pr-3 drop-shadow-sm">
                         {aiAnalysis}
                      </div>
                   ) : (
                      <div className="h-full flex flex-col items-center justify-center text-center p-8 space-y-6 opacity-40">
                         <Sparkles size={64} className="text-orange-500 animate-pulse"/>
                         <p className="text-xs font-black uppercase tracking-tighter">اضغط على الأيقونة لتوليد تحليل فني ومعمق للأداء</p>
                      </div>
                   )}
                </div>
             </div>
          </div>

          {/* العقوبات والملاحظات الإدارية بالكامل */}
          <div className="bg-red-50 p-10 rounded-[4rem] border-4 border-red-900 shadow-[12px_12px_0px_0px_rgba(127,29,29,1)]">
             <h4 className="text-lg font-black text-red-900 mb-8 flex items-center gap-3 border-r-8 border-red-700 pr-4 uppercase">
                <Gavel size={28} className="drop-shadow-sm"/> السجل الانضباطي والعقوبات الإدارية
             </h4>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div className="space-y-3">
                  <p className="text-[11px] font-black text-red-600 uppercase flex items-center gap-2"><ShieldAlert size={16}/> العقوبات الرسمية والجزائية</p>
                  <p className="text-[13px] font-black text-slate-900 leading-relaxed p-6 bg-white border-r-8 border-red-700 rounded-3xl shadow-md drop-shadow-sm min-h-[120px]">
                    {player.penalties || "لا يوجد أي عقوبات إدارية أو مسلكية مسجلة."}
                  </p>
               </div>
               <div className="space-y-3">
                  <p className="text-[11px] font-black text-[#001F3F] uppercase flex items-center gap-2"><StickyNote size={16}/> ملاحظات الإدارة والمكتب</p>
                  <p className="text-[13px] font-black text-slate-900 leading-relaxed p-6 bg-white/60 border-r-8 border-[#001F3F] rounded-3xl shadow-md drop-shadow-sm min-h-[120px]">
                    {player.notes || "لا توجد ملاحظات إدارية إضافية حالياً."}
                  </p>
               </div>
             </div>
             <div className="mt-8 flex flex-wrap gap-3">
                {matchStats.reds > 0 && <span className="bg-red-600 text-white text-[10px] font-black px-5 py-2 rounded-full border-2 border-red-900 shadow-lg">سجل طرد نشط</span>}
                {matchStats.yellows >= 3 && <span className="bg-yellow-500 text-white text-[10px] font-black px-5 py-2 rounded-full border-2 border-yellow-700 shadow-lg">تراكم بطاقات صفراء (عقوبة قادمة)</span>}
             </div>
          </div>

          {/* التقييم الشهري المستمر */}
          <div className="bg-white p-10 md:p-12 rounded-[4rem] border-4 border-blue-900 shadow-[12px_12px_0px_0px_rgba(30,58,138,1)]">
             <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6 border-r-8 border-blue-600 pr-6">
                <h3 className="text-xl md:text-3xl font-black text-[#001F3F] flex items-center gap-4">
                   <CalendarDays className="text-blue-700 drop-shadow-sm" size={32}/> السجل التقييمي الشهري الفني
                </h3>
                <div className="flex items-center gap-4 w-full md:w-auto">
                   <select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="flex-1 bg-slate-100 border-4 border-blue-900 rounded-2xl py-3 px-6 font-black text-sm md:text-lg outline-none shadow-lg">
                     {months.map(m => <option key={m} value={m}>{m}</option>)}
                   </select>
                   {!isViewer && (
                      <button onClick={() => handleSaveMonthlyReport(selectedMonth)} className="bg-emerald-600 text-white px-8 py-3.5 rounded-2xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-xl border-b-4 border-black">
                         {isSavingReport ? <Loader2 size={20} className="animate-spin"/> : <Save size={20}/>} حفظ
                      </button>
                   )}
                </div>
             </div>
             <textarea 
                className="w-full bg-slate-50 border-4 border-slate-200 rounded-[3rem] p-10 text-sm md:text-lg font-black text-slate-900 h-64 md:h-80 resize-none outline-none focus:border-blue-600 transition-all shadow-inner drop-shadow-sm"
                placeholder={`اكتب التقييم الفني والبدني المفصل لهذا العضو لشهر ${selectedMonth}...`}
                value={monthlyNotes[selectedMonth] || ''}
                onChange={(e) => setMonthlyNotes({ ...monthlyNotes, [selectedMonth]: e.target.value })}
                readOnly={isViewer}
             ></textarea>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PlayerReport;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
    setFormData({ ...formData, opponent: '' });
  };

  const deleteMatch = (id: string) => {
    if (!isManager) return;
    if (confirm('🚨 هل أنت متأكد من حذف هذه المباراة نهائياً؟ سيتم حذف كافة الإحصائيات والدقائق المرتبطة بها.')) {
      setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      addLog?.('حذف مباراة', 'تمت إزالة سجل المباراة بالكامل من النظام', 'error');
    }
  };

  const updateActiveMatchLineup = (index: number, playerId: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const susp = getSuspension(playerId, activeMatch.category);
    if (susp.isSuspended) {
      const p = state.people.find(x => x.id === playerId);
      alert(`⛔ حظر إشراك لاعب معاقب:\nاللاعب [${p?.name}] موقوف حالياً.\nالسبب: ${susp.hasActiveRed ? 'طرد مباشر' : 'تراكم 3 بطاقات صفراء'}.`);
      return;
    }
    const person = state.people.find(p => p.id === playerId);
    const totalStoppage = (parseInt(activeMatch.stoppageTime1 || '0')) + (parseInt(activeMatch.stoppageTime2 || '0'));
    const fullTime = 90 + totalStoppage;
    const newLineup = { ...activeMatch.lineup };
    if (!person) newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    else newLineup.starters[index] = { playerId: person.id, name: person.name, number: person.number?.toString() || '', minutesPlayed: fullTime.toString() };
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const handleSubstitutionCalculation = (subIndex: number, replacedPlayerId: string, subMinute: string) => {
    if (!activeMatch || isViewer || activeMatch.isCompleted) return;
    const newLineup = { ...activeMatch.lineup };
    const minute = parseInt(subMinute) || 0;
    const stop1 = parseInt(activeMatch.stoppageTime1 || '0');
    const stop2 = parseInt(activeMatch.stoppageTime2 || '0');
    const fullMatchTime = 90 + stop1 + stop2;
    const starterIdx = newLineup.starters.findIndex(s => s.playerId === replacedPlayerId);
    if (starterIdx !== -1) newLineup.starters[starterIdx].minutesPlayed = minute.toString();
    newLineup.subs[subIndex].replacedPlayerId = replacedPlayerId;
    newLineup.subs[subIndex].substitutionMinute = subMinute;
    const playedMins = fullMatchTime - minute;
    newLineup.subs[subIndex].minutesPlayed = playedMins > 0 ? playedMins.toString() : '0';
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatchDetails = (lockStatus: boolean = false) => {
    if (!activeMatch || isViewer) return;
    const finalLockStatus = isManager ? lockStatus : activeMatch.isCompleted;
    const stop1 = parseInt(activeMatch.stoppageTime1 || '0');
    const stop2 = parseInt(activeMatch.stoppageTime2 || '0');
    const fullTime = 90 + stop1 + stop2;
    const updatedLineup = { ...activeMatch.lineup };
    updatedLineup.starters = updatedLineup.starters.map(s => {
        const isSubbedOut = updatedLineup.subs.some(sub => sub.replacedPlayerId === s.playerId);
        if (!isSubbedOut && s.playerId) return { ...s, minutesPlayed: fullTime.toString() };
        return s;
    });
    setState(p => ({
      ...p,
      matches: p.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, lineup: updatedLineup, isCompleted: finalLockStatus } : m)
    }));
    setActiveMatch(null);
  };

  const inputStyle = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 text-sm shadow-inner focus:border-orange-600 outline-none";
  const labelStyle = "text-[11px] font-black text-slate-900 mr-1 uppercase block mb-1.5 tracking-tighter drop-shadow-sm";

  return (
    <div className="space-y-4 md:space-y-6 pb-20 px-1 font-['Tajawal'] text-right" dir="rtl">
      <div className="bg-white p-6 rounded-[2rem] border-4 border-slate-900 flex justify-between items-center no-print shadow-[8px_8px_0px_0px_rgba(0,31,63,1)]">
        <h2 className="text-sm md:text-2xl font-black text-[#001F3F] flex items-center gap-3 uppercase tracking-tighter drop-shadow-sm">
          <Trophy size={24} className="text-orange-600" /> إدارة مباريات الكرامة والبيانات الفنية
        </h2>
        {!isViewer && (
          <button 
            onClick={() => setIsAddOpen(true)} 
            className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm shadow-xl border-b-4 border-black active:translate-y-1 active:shadow-none transition-all flex items-center gap-2"
          >
            <Plus size={20}/> جدولة مواجهة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print text-right">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-4 border-slate-900 relative shadow-md border-b-[12px] transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600'}`}>
             <div className="flex justify-between items-start mb-6">
                <span className="bg-orange-600 text-white text-[10px] font-black px-4 py-1 rounded-xl border-2 border-white shadow-md uppercase">{m.matchType}</span>
                <span className="text-xs font-black text-slate-900 tabular-nums drop-shadow-sm">{m.date}</span>
                {isManager && (
                  <button onClick={() => deleteMatch(m.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-xl transition-all">
                    <Trash2 size={20}/>
                  </button>
                )}
             </div>
             <div className="text-center mb-8">
                <p className="text-5xl font-black text-slate-900 tabular-nums drop-shadow-[0_2px_2px_rgba(0,0,0,0.2)]">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-slate-900 mt-4 uppercase drop-shadow-sm">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-black text-orange-600 mt-1 uppercase tracking-widest">{m.category} | {m.pitch}</p>
             </div>
             <div className="flex gap-3">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-4 rounded-2xl font-black text-sm uppercase shadow-xl hover:bg-black transition-all border-b-4 border-black">
                  {m.isCompleted ? 'تقرير المباراة والدقائق' : 'ضبط التشكيل والأحداث'}
                </button>
             </div>
          </div>
        ))}
      </div>

      {/* نافذة إضافة مباراة جديدة (The Modal) */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-slate-900/90 backdrop-blur-xl z-[600] flex items-center justify-center p-4">
           <div className="bg-white rounded-[3rem] w-full max-w-lg border-[8px] border-slate-900 shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="p-8 bg-slate-100 border-b-4 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black text-slate-900 text-xl uppercase tracking-tighter drop-shadow-sm">جدولة نشاط مواجهة رسمية</h3>
                 <button onClick={() => setIsAddOpen(false)} className="bg-white p-3 rounded-2xl border-2 border-slate-900 hover:rotate-90 transition-all"><X size={24}/></button>
              </div>
              <form onSubmit={handleCreateMatch} className="p-10 space-y-6">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelStyle}>فئة الفريق</label>
                       <select required className={inputStyle} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className={labelStyle}>نوع المباراة</label>
                       <select className={inputStyle} value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as any})}>
                          <option value="دوري">دوري</option>
                          <option value="كأس">كأس</option>
                          <option value="ودية">ودية</option>
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className={labelStyle}>اسم الفريق الخصم</label>
                    <input required type="text" className={inputStyle} value={formData.opponent} onChange={e => setFormData({...formData, opponent: e.target.value})} placeholder="مثال: نادي أهلي حلب..." />
                 </div>
                 <div className="space-y-1">
                    <label className={labelStyle}>موقع المباراة (الملعب)</label>
                    <input type="text" className={inputStyle} value={formData.pitch} onChange={e => setFormData({...formData, pitch: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelStyle}>تاريخ المباراة</label>
                       <input required type="date" className={inputStyle} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelStyle}>ساعة البداية</label>
                       <input type="time" className={inputStyle} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl hover:bg-black border-b-8 border-black transition-all uppercase">تثبيت الجدولة بالنظام</button>
              </form>
           </div>
        </div>
      )}

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-xl z-[400] overflow-y-auto no-print">
           <div className="max-w-6xl mx-auto p-2 md:p-8 min-h-screen text-right" dir="rtl">
              <div className="bg-white rounded-[3rem] border-[10px] border-slate-900 p-6 md:p-12 shadow-2xl relative text-right">
                <header className="flex flex-col md:flex-row justify-between items-center mb-12 border-b-8 border-slate-900 pb-10 gap-6">
                   <div className="text-center md:text-right">
                      <h2 className="text-2xl md:text-5xl font-black text-slate-900 tracking-tighter uppercase drop-shadow-sm">{activeMatch.opponent} × الكرامة</h2>
                      <div className="flex gap-3 mt-5 justify-center md:justify-start">
                         <span className="bg-slate-900 text-white text-xs font-black px-5 py-2 rounded-2xl border-4 border-slate-900 shadow-lg">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-emerald-600 text-white text-xs font-black px-5 py-2 rounded-2xl border-4 border-emerald-900 flex items-center gap-2 shadow-lg"><CheckCircle size={18}/> تقرير معتمد</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-4 justify-center">
                      {isManager && (
                        <button onClick={() => saveMatchDetails(!activeMatch.isCompleted)} className={`${activeMatch.isCompleted ? 'bg-red-600' : 'bg-emerald-600'} text-white px-8 py-4 rounded-3xl font-black text-sm shadow-2xl flex items-center gap-2 border-b-4 border-black transition-all`}>
                          {activeMatch.isCompleted ? <Unlock size={20}/> : <CheckCircle size={20}/>} {activeMatch.isCompleted ? 'فتح التعديل' : 'اعتماد وحفظ التقرير'}
                        </button>
                      )}
