        catQuery, pplQuery, sessQuery, mtchQuery, attnQuery, wrhsQuery, techQuery, usrQuery
      ]);

      setState(prev => ({
        ...prev,
        categories: (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories,
        people: ppl.data || prev.people,
        sessions: sess.data || prev.sessions,
        matches: mtch.data || prev.matches,
        technicalReports: tech.data || prev.technicalReports,
        warehouse: wrhs.data || prev.warehouse,
        attendance: attn.data || prev.attendance,
        users: usrs.data || prev.users
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  const updateStateAndSync = useCallback(async (updater: (prev: AppState) => AppState) => {
    if (!state.currentUser) return;
    const nextState = updater(state);

    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    try {
      const syncTasks = [
        supabase.from('people').upsert(sanitize(nextState.people)),
        supabase.from('sessions').upsert(sanitize(nextState.sessions)),
        supabase.from('matches').upsert(sanitize(nextState.matches)),
        supabase.from('attendance').upsert(sanitize(nextState.attendance)),
        supabase.from('technical_reports').upsert(sanitize(nextState.technicalReports)),
        supabase.from('warehouse').upsert(sanitize(nextState.warehouse)),
        supabase.from('categories').upsert(nextState.categories.map(c => ({ name: c }))) // مزامنة الفئات
      ];

      if (state.currentUser.role === 'مدير') {
        syncTasks.push(supabase.from('app_users').upsert(sanitize(nextState.users)));
      }

      const results = await Promise.all(syncTasks);
      const error = results.find(r => r.error);
      if (error) throw new Error(error.error.message);

      await fetchData();
      setSyncStatus('synced');
    } catch (err: any) {
      setSyncStatus('error');
      addLog('خطأ في المزامنة السحابية', err.message, 'error');
      setState(nextState);
    } finally {
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state, fetchData, addLog]);

  useEffect(() => {
    if (!state.currentUser) return;
