        users: usrs.data || prev.users
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  const updateStateAndSync = useCallback(async (updater: (prev: AppState) => AppState) => {
    if (!state.currentUser) return;
    const nextState = updater(state);

    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    try {
      // 1. مزامنة البيانات الأساسية
      const syncTasks = [
        supabase.from('people').upsert(sanitize(nextState.people)),
        supabase.from('sessions').upsert(sanitize(nextState.sessions)),
        supabase.from('matches').upsert(sanitize(nextState.matches)),
        supabase.from('attendance').upsert(sanitize(nextState.attendance)),
        supabase.from('technical_reports').upsert(sanitize(nextState.technicalReports)),
        supabase.from('warehouse').upsert(sanitize(nextState.warehouse)),
        // تحديد name كـ OnConflict للفئات لضمان عدم الفشل
        supabase.from('categories').upsert(nextState.categories.map(c => ({ name: c })), { onConflict: 'name' })
      ];

      // 2. مزامنة المستخدمين للمدير فقط
      if (state.currentUser.role === 'مدير') {
        syncTasks.push(supabase.from('app_users').upsert(sanitize(nextState.users)));
      }

      const results = await Promise.all(syncTasks);
      const error = results.find(r => r.error);
      if (error) throw new Error(error.error.message);

      await fetchData();
      setSyncStatus('synced');
    } catch (err: any) {
      console.error("Sync Error:", err);
      setSyncStatus('error');
      addLog('خطأ في المزامنة', err.message, 'error');
      setState(nextState);
    } finally {
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state, fetchData, addLog]);

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();
    const handleRealtimeChange = () => {
        if (isInternalUpdate.current) return;
        fetchData();
    };
    const channels = [
        supabase.channel('matches-db').on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, handleRealtimeChange).subscribe(),
        supabase.channel('users-db').on('postgres_changes', { event: '*', schema: 'public', table: 'app_users' }, handleRealtimeChange).subscribe(),
        supabase.channel('people-db').on('postgres_changes', { event: '*', schema: 'public', table: 'people' }, handleRealtimeChange).subscribe(),
        supabase.channel('categories-db').on('postgres_changes', { event: '*', schema: 'public', table: 'categories' }, handleRealtimeChange).subscribe()
    ];
    return () => { channels.forEach(ch => supabase.removeChannel(ch)); };
  }, [state.currentUser, fetchData]);

