        const root = { id: 'root', username: 'عزت عامر الشيخة', role: 'مدير' as const };
        setState(prev => ({ ...prev, currentUser: root }));
        return root;
    }
    throw new Error("بيانات الدخول خاطئة");
  }} />;

  return (
    <div className="min-h-screen bg-[#000F21] flex text-right font-['Tajawal']" dir="rtl">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/60 z-[100] lg:hidden" onClick={() => setSidebarOpen(false)}></div>}

      <aside className={`fixed inset-y-0 right-0 z-[110] w-64 bg-[#001F3F] border-l-2 border-[#FF6B00] transition-transform duration-300 lg:translate-x-0 lg:static ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center justify-between mb-8">
             <div className="flex items-center gap-3">
               <ClubLogo size={40} />
               <span className="text-white font-black text-sm">نادي الكرامة</span>
             </div>
             <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-white"><X size={24}/></button>
          </div>
          <nav className="flex-1 space-y-2 overflow-y-auto custom-scrollbar">
            {navItems.map(item => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 p-4 rounded-xl font-bold text-sm transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/60 hover:bg-white/5'}`}>
                <item.icon size={18} /> {item.label}
              </button>
            ))}
          </nav>
          <button onClick={handleLogout} className="mt-4 flex items-center gap-4 p-4 text-red-400 font-bold text-sm border-t border-white/10"><LogOut size={18}/> خروج</button>
