  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: restrictedCat || state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return null;
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    if (isViewer) return;
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
    } else {
      const newPerson: Person = {
        id: generateUUID(),
        name: formData.name || '',
        fatherName: formData.fatherName || '',
        motherName: formData.motherName || '',
        birthDate: formData.birthDate || '',
        birthPlace: formData.birthPlace || '',
        khana: formData.khana || '',
        nationalId: formData.nationalId || '',
        federalNumber: formData.federalNumber || '',
        internationalId: formData.internationalId || '',
        address: formData.address || '',
        category: formData.category || restrictedCat || state.categories[0],
        role: formData.role || 'لاعب',
        number: formData.number || 0,
        phone: formData.phone || '',
        joinDate: formData.joinDate || new Date().toISOString().split('T')[0],
        monthlyReports: {}
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const baseFiltered = state.people.filter(p => {
    const matchCat = restrictedCat ? p.category === restrictedCat : (localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter);
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  const filteredPlayers = baseFiltered.filter(p => p.role === 'لاعب');
  const filteredStaff = baseFiltered.filter(p => p.role !== 'لاعب');
  const displayList = activeSubTab === 'players' ? filteredPlayers : filteredStaff;

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2.5 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 no-print space-y-6">
        <div className="flex flex-col lg:flex-row gap-4 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
            <input 
              type="text" 
              placeholder="البحث بالاسم أو الرقم..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-12 h-12 text-lg`} 
            />
          </div>

          <div className="flex items-center gap-3 w-full lg:w-auto">
            {!restrictedCat && (
              <select 
                value={localCategoryFilter}
                onChange={e => setLocalCategoryFilter(e.target.value)}
                className="bg-slate-100 border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-sm h-12 outline-none"
              >
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            )}

            {!isViewer && (
              <button 
                onClick={() => { setEditingId(null); setIsModalOpen(true); }} 
                className="bg-[#001F3F] text-white px-8 h-12 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg border-b-4 border-black"
              >
                <Plus size={20} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        <div className="flex p-1.5 bg-slate-100 border-2 border-slate-900 rounded-2xl w-fit">
          <button onClick={() => setActiveSubTab('players')} className={`px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'players' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>اللاعبين</button>
          <button onClick={() => setActiveSubTab('staff')} className={`px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'staff' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>الكوادر</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {displayList.map(person => {
          const susp = getSuspension ? getSuspension(person.id, person.category) : { isSuspended: false, currentYellows: 0, hasActiveRed: false };

          return (
            <div key={person.id} className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 relative transition-all border-b-[8px] hover:border-orange-600">
               <div className="flex justify-between items-start mb-4">
                 <div className="w-12 h-12 bg-slate-100 border-2 border-slate-900 rounded-xl flex items-center justify-center font-black text-slate-900 text-lg">
                   {person.name.charAt(0)}
                 </div>
                 <div className="flex flex-col items-end">
                    <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase ${person.role === 'لاعب' ? 'bg-orange-600 text-white' : 'bg-[#001F3F] text-white'}`}>
                      {person.role}
                    </span>
                    <span className="text-[10px] font-black text-slate-400 mt-2">{person.category}</span>
                 </div>
               </div>

               <div className="space-y-2">
                 <h4 className="font-black text-lg text-slate-900 flex items-center gap-2">
                    {person.name}
                    {/* أيقونات البطاقات والعقوبات */}
                    <div className="flex gap-1">
                      {susp.hasActiveRed && (
                        <div className="w-3 h-5 bg-red-600 rounded-sm border border-red-900 animate-pulse shadow-sm" title="موقوف (طرد مباشر)"></div>
                      )}
                      {susp.isSuspended && !susp.hasActiveRed && (
                        <div className="w-3 h-5 bg-red-600 rounded-sm border border-red-900 shadow-sm" title="موقوف (تراكم إنذارات)"></div>
                      )}
                      {susp.currentYellows % 3 === 2 && !susp.isSuspended && (
                        <div className="w-3 h-5 bg-yellow-400 rounded-sm border border-yellow-600 shadow-sm" title="تنبيه: إنذارين"></div>
                      )}
                    </div>
                 </h4>
                 <div className="flex gap-3 text-[10px] font-black text-slate-500">
                   <span className="flex items-center gap-1"><MapPin size={12}/> {person.birthPlace}</span>
                   <span className="flex items-center gap-1"><Calendar size={12}/> {calculateAge(person.birthDate)} سنة</span>
                 </div>
               </div>

               <div className="mt-6 pt-4 border-t-2 border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-3">
                     <div className="bg-[#001F3F] text-white w-9 h-9 rounded-xl flex items-center justify-center font-black text-lg border-2 border-black">
                       #{person.number || '0'}
                     </div>
                     <button onClick={() => onOpenReport?.(person)} className="text-slate-900 text-xs font-black underline hover:text-orange-600 transition-all">الملف الفني</button>
                  </div>
                  {!isViewer && (
                    <div className="flex gap-2">
                      <button onClick={() => { setEditingId(person.id); setFormData(person); setIsModalOpen(true); }} className="p-2.5 bg-slate-100 text-slate-900 rounded-xl border-2 border-slate-900 transition-all"><Edit2 size={16}/></button>
                      <button onClick={async () => { if(confirm(`حذف ${person.name}؟`)) { await supabase.from('people').delete().eq('id', person.id); setState(p => ({...p, people: p.people.filter(x => x.id !== person.id)})); } }} className="p-2.5 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 transition-all"><Trash2 size={16}/></button>
                    </div>
                  )}
               </div>
            </div>
          );
        })}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[250] p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-2xl shadow-2xl overflow-hidden border-[6px] border-slate-900 flex flex-col h-[90vh]">
            <div className="p-5 border-b-2 bg-slate-50 flex justify-between items-center">
              <h3 className="text-md font-black text-slate-900">بيانات العضو</h3>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-200 p-2 rounded-xl"><X size={20} /></button>
            </div>
            <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-8 space-y-6 text-right">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className={labelClass}>الاسم الكامل</label>
                    <input required type="text" value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>تاريخ الميلاد</label>
                    <input type="date" value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} className={fieldClass} />
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>الدور</label>
                    <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as Role})} className={fieldClass}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>الفئة</label>
                    <select disabled={!!restrictedCat} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className={fieldClass}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className={labelClass}>رقم القميص</label>
                    <input type="number" value={formData.number || ''} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} className={fieldClass} />
                  </div>
                </div>
                <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-4 rounded-xl shadow-2xl text-xl mt-6 border-b-4 border-black">حفظ البيانات</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;

import React, { useState, useMemo } from 'react';
import { Trophy, Clock, Plus, X, Trash2, Edit, Save, CheckCircle, Unlock, Users, ArrowRightLeft, Activity, FileText, Loader2, MapPin, Timer } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';

interface MatchPlannerProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  defaultSelectedId?: string | null;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const restrictedCat = currentUser?.restrictedCategory;

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const deleteMatch = async (id: string, opponent: string) => {
    if (!isManager && !isCatAdmin) return;
    if (confirm(`هل أنت متأكد من حذف مباراة ${opponent} نهائياً؟`)) {
      setIsDeleting(id);
      try {
        const { error } = await supabase.from('matches').delete().eq('id', id);
        if (error) throw error;
        setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      } finally {
        setIsDeleting(null);
      }
    }
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };

    if (player) {
      // التحقق من الإيقاف قبل الإضافة للتشكيلة
      const susp = getSuspension?.(player.id, activeMatch.category);
      if (susp?.isSuspended) {
        alert(`🚨 تنبيه إداري: اللاعب ${player.name} موقوف لهذه المباراة بسبب (تراكم بطاقات أو طرد).`);
        return;
      }
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '0', minutesPlayed: '90' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSub = (index: number, field: string, value: string) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    if (field === 'playerId') {
      const player = state.people.find(p => p.id === value);
      if (player) {
        const susp = getSuspension?.(player.id, activeMatch.category);
        if (susp?.isSuspended) {
          alert(`🚨 تنبيه إداري: اللاعب ${player.name} موقوف لهذه المباراة ولا يمكن إدراجه كبديل.`);
          return;
        }
        newLineup.subs[index] = { ...newLineup.subs[index], playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
      } else {
        newLineup.subs[index] = { ...newLineup.subs[index], playerId: '', name: '', number: '' };
      }
    } else {
      // @ts-ignore
      newLineup.subs[index][field] = value;
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || state.categories[0],
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'خصم مجهول',
      pitch: formData.pitch || 'ملعب النادي',
      date: formData.date || '',
      time: formData.time || '',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({playerId: '', name: '', number: ''}), subs: [], staff: [], captain: '' },
      advancePayment: '0'
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    setIsAddOpen(false);
  };

  const saveMatch = (complete: boolean = false) => {
    if (!activeMatch) return;
    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: complete } : m)
    }));
    setActiveMatch(null);
  };

  const inputStyle = "w-full bg-slate-100 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all";

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-5 md:p-8 rounded-2xl border-2 border-slate-900 flex justify-between items-center shadow-md">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F]">إدارة المباريات</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase">Match Command Center</p>
        </div>
        {!currentUser?.role.includes('مشاهد') && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 border-b-4 border-black active:translate-y-1">
            <Plus size={20}/> جدولة مباراة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-5 rounded-3xl border-2 border-slate-900 relative shadow-sm ${isDeleting === m.id ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date}</span>
             </div>
             <div className="text-center py-4">
                <p className="text-4xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-[#001F3F] mt-2">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-bold text-orange-600 mt-1 uppercase">{m.category}</p>
             </div>
             <div className="flex gap-2 mt-4 pt-4 border-t border-slate-50">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs uppercase shadow-md border-b-4 border-black">
                  {m.isCompleted ? 'عرض التقرير' : 'إدارة المباراة'}
                </button>
                {(isManager || (isCatAdmin && m.category === restrictedCat)) && (
                  <button onClick={() => deleteMatch(m.id, m.opponent)} className="p-3 bg-red-50 text-red-600 border-2 border-red-900 rounded-xl hover:bg-red-600 hover:text-white transition-all">
                    {isDeleting === m.id ? <Loader2 className="animate-spin" size={18}/> : <Trash2 size={18}/>}
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-white z-[300] overflow-y-auto p-4 md:p-10 text-right" dir="rtl">
           <div className="max-w-4xl mx-auto bg-white border-4 border-slate-900 rounded-[2rem] p-6 md:p-10 shadow-2xl mb-20">
              <div className="flex justify-between items-center mb-8 border-b-2 pb-4">
                 <h2 className="text-xl md:text-3xl font-black text-slate-900">الكرامة × {activeMatch.opponent}</h2>
                 <button onClick={() => setActiveMatch(null)} className="p-3 bg-slate-100 rounded-xl"><X/></button>
              </div>

              <div className="space-y-10">
                 {/* قسم التشكيلة الأساسية */}
                 <div className="space-y-4">
                    <h3 className="font-black text-lg flex items-center gap-2 border-r-4 border-orange-600 pr-3">
                       <Users size={24}/> التشكيلة الأساسية (11 لاعب)
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       {activeMatch.lineup.starters.map((s, idx) => (
                         <div key={idx} className="flex gap-3 items-center">
                            <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-xs">#{idx+1}</span>
                            <select className={inputStyle} value={s.playerId} onChange={e => updateStarter(idx, e.target.value)}>
                               <option value="">-- اختر لاعب --</option>
                               {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => (
                                 <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                               ))}
                            </select>
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* زر إضافة بديل */}
                 <div className="pt-6 border-t-2">
                    <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: [...activeMatch.lineup.subs, {playerId: '', name: '', number: '', minutesPlayed: '0'}]}})} className="bg-blue-600 text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 border-b-4 border-black">
                       <Plus size={18}/> إضافة لاعب بديل للقائمة
                    </button>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                       {activeMatch.lineup.subs.map((s, idx) => (
                         <div key={idx} className="flex gap-3 items-center">
                            <select className={inputStyle} value={s.playerId} onChange={e => updateSub(idx, 'playerId', e.target.value)}>
                               <option value="">-- البديل --</option>
                               {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => (
                                 <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                               ))}
                            </select>
                            <button onClick={() => setActiveMatch({...activeMatch, lineup: {...activeMatch.lineup, subs: activeMatch.lineup.subs.filter((_, i) => i !== idx)}})} className="text-red-600"><Trash2 size={18}/></button>
                         </div>
                       ))}
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-3 pt-10">
                    <button onClick={() => saveMatch(true)} className="bg-emerald-600 text-white py-4 rounded-2xl font-black shadow-lg border-b-4 border-black">اعتماد المباراة</button>
                    <button onClick={() => saveMatch(false)} className="bg-blue-600 text-white py-4 rounded-2xl font-black shadow-lg border-b-4 border-black">حفظ مؤقت</button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* نافذة إضافة مباراة جديدة */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-black/80 z-[200] flex items-center justify-center p-4 text-right" dir="rtl">
          <div className="bg-white rounded-3xl w-full max-w-md border-4 border-slate-900 p-6 shadow-2xl">
             <div className="flex justify-between items-center mb-6 border-b-2 pb-4">
                <h3 className="font-black text-lg">جدولة مباراة جديدة</h3>
                <button onClick={() => setIsAddOpen(false)}><X/></button>
             </div>
             <form onSubmit={handleCreate} className="space-y-4">
                <div className="space-y-1">
                   <label className="text-[10px] font-black mr-2">الفئة</label>
                   <select className={inputStyle} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                      {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                   </select>
                </div>
                <div className="space-y-1">
                   <label className="text-[10px] font-black mr-2">المنافس</label>
                   <input type="text" required className={inputStyle} onChange={e => setFormData({...formData, opponent: e.target.value})} placeholder="اسم النادي الخصم" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black mr-2">التاريخ</label>
                      <input type="date" required className={inputStyle} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black mr-2">ساعة الركلة</label>
                      <input type="time" className={inputStyle} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                   </div>
                </div>
                <button type="submit" className="w-full bg-[#001F3F] text-white py-4 rounded-2xl font-black shadow-lg border-b-4 border-black mt-4">تثبيت المباراة</button>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, Globe, ExternalLink, BarChart, TrendingUp, HeartPulse, AlertCircle, Trophy, Info, Search } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string, links?: any[] }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [aiMode, setAiMode] = useState<'fast' | 'deep' | 'global'>('fast');
  const [selectedCategory, setSelectedCategory] = useState<string>(state.currentUser?.restrictedCategory || state.globalCategoryFilter || 'الكل');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const clubAnalysis = useMemo(() => {
    const players = state.people.filter(p => p.role === 'لاعب' && (selectedCategory === 'الكل' ? true : p.category === selectedCategory));
    const matches = state.matches.filter(m => m.isCompleted && (selectedCategory === 'الكل' ? true : m.category === selectedCategory));
    const sessions = state.sessions.filter(s => (selectedCategory === 'الكل' ? true : s.category === selectedCategory));

    const stats = players.map(p => {
      const records = state.attendance.filter(a => a.personId === p.id);
      let goals = 0;
      matches.forEach(m => {
        goals += m.events.filter(e => e.type === 'goal' && (e.player === p.id || e.player === p.name)).length;
      });
      return `- ${p.name}: أهداف(${goals}), التزام(${records.length > 0 ? 'نشط' : 'ضعيف'})`;
    }).join('\n');

    return { stats, recent: matches.slice(-3).map(m => `${m.opponent} (${m.ourScore}-${m.opponentScore})`).join(', ') };
  }, [state, selectedCategory]);

  const handleAsk = async (customPrompt?: string) => {
    const userQuery = customPrompt || input;
    if (!userQuery.trim() || loading) return;

    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const { stats, recent } = clubAnalysis;

      let config: any = {};
      let modelName = 'gemini-3-flash-preview';

      if (aiMode === 'deep') {
        modelName = 'gemini-3-pro-preview';
        config.thinkingConfig = { thinkingBudget: 32768 };
      } else if (aiMode === 'global') {
        modelName = 'gemini-3-flash-preview';
        config.tools = [{ googleSearch: {} }];
      }

      const systemInstruction = `أنت المحلل الفني لنادي الكرامة. فئة: ${selectedCategory}. بياناتك الحالية: ${stats}. نتائج أخيرة: ${recent}. كن دقيقاً وتكتيكياً.`;

      const response = await ai.models.generateContent({
        model: modelName,
        contents: userQuery,
        config: { ...config, systemInstruction }
      });

      const links = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => chunk.web).filter(Boolean);

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "لا يمكنني التحليل الآن.", links }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "خطأ: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-160px)] space-y-4 font-['Tajawal']" dir="rtl">
      <div className="bg-white p-4 md:p-6 rounded-[2rem] border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center gap-4 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="bg-[#001F3F] p-3 rounded-xl shadow-lg">
            <BrainCircuit className="text-orange-400" size={24} />
          </div>
          <div>
            <h2 className="text-lg font-black text-slate-900">المحلل التكتيكي الذكي Pro</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">مدعوم بنماذج Gemini 3 المتطورة</p>
          </div>
        </div>

        <div className="flex gap-1 bg-slate-100 p-1 rounded-xl border border-slate-200">
           <button onClick={() => setAiMode('fast')} className={`px-4 py-2 rounded-lg text-[9px] font-black transition-all ${aiMode === 'fast' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>سرعة (Flash)</button>
           <button onClick={() => setAiMode('deep')} className={`px-4 py-2 rounded-lg text-[9px] font-black transition-all ${aiMode === 'deep' ? 'bg-orange-600 text-white shadow-md' : 'text-slate-500'}`}>تفكير (Pro)</button>
           <button onClick={() => setAiMode('global')} className={`px-4 py-2 rounded-lg text-[9px] font-black transition-all ${aiMode === 'global' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-500'}`}>بحث (Web)</button>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[2.5rem] border-2 border-slate-900 flex flex-col overflow-hidden shadow-inner">
        <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4 custom-scrollbar">
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[90%] p-4 rounded-2xl text-xs font-medium leading-relaxed shadow-sm ${msg.role === 'user' ? 'bg-slate-100 border-2 border-slate-200 rounded-tr-none' : 'bg-[#001F3F] text-white border-b-4 border-orange-600 rounded-tl-none'}`}>
                <div className="flex items-center gap-2 mb-2 opacity-50 text-[8px] font-black uppercase">
                   {msg.role === 'user' ? <User size={10}/> : <Bot size={10}/>} {msg.role === 'user' ? 'المدرب' : 'المحلل الفني'}
                </div>
                <div>{msg.text}</div>
                {msg.links && msg.links.length > 0 && (
                  <div className="mt-4 pt-3 border-t border-white/10 space-y-1">
                    <p className="text-[8px] font-black text-orange-400">المصادر المعتمدة:</p>
                    {msg.links.map((link: any, idx) => (
                      <a key={idx} href={link.uri} target="_blank" className="flex items-center gap-1 text-[9px] text-blue-300 underline hover:text-white transition-all truncate">
                        <Globe size={10}/> {link.title}
                      </a>
                    ))}
                  </div>
                )}
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end animate-pulse">
              <div className="bg-[#001F3F] text-white p-4 rounded-2xl flex items-center gap-3">
                <Loader2 className="animate-spin text-orange-400" size={16} />
                <span className="text-[9px] font-black">{aiMode === 'deep' ? 'الذكاء يقوم بعملية تفكير عميق...' : 'جاري تحليل البيانات...'}</span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 bg-white border-t-2 border-slate-900 flex gap-2">
          <input 
            type="text" value={input} onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            placeholder={aiMode === 'global' ? "ابحث عن أخبار الخصوم أو قوانين اللعبة..." : "اسأل المحلل عن فريقك..."}
            className="flex-1 bg-slate-50 border-2 border-slate-200 rounded-xl px-4 py-3 font-bold text-xs outline-none focus:border-[#001F3F]"
          />
          <button onClick={() => handleAsk()} disabled={loading || !input.trim()} className="bg-[#001F3F] text-white p-3 rounded-xl shadow-lg hover:bg-black transition-all">
            <Send size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MapPin, Search, Navigation, Hospital, Utensils, Trophy, ExternalLink, Loader2, Info, Map as MapIcon } from 'lucide-react';

const LocationAssistant: React.FC = () => {
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [response, setResponse] = useState<{ text: string, links: any[] } | null>(null);

  const searchLocations = async (type: string) => {
    setLoading(true);
    setResponse(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let latLng = { latitude: 34.7324, longitude: 36.7137 }; // حمص

      try {
        const pos = await new Promise<GeolocationPosition>((res, rej) => 
          navigator.geolocation.getCurrentPosition(res, rej, { timeout: 5000 })
        );
        latLng = { latitude: pos.coords.latitude, longitude: pos.coords.longitude };
      } catch (e) { console.warn("Geolocation fallback to Homs center."); }

      const prompt = `بصفتي مسؤول لوجستي لنادي الكرامة السوري، ابحث عن ${type === 'custom' ? query : type} في المنطقة الحالية، مع ذكر المسافة التقريبية والجودة للرياضيين.`;

      const result = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: { retrievalConfig: { latLng } }
        },
      });

      const text = result.text || "لا توجد نتائج خرائط قريبة.";
      const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
      const links = chunks.filter((chunk: any) => chunk.maps).map((chunk: any) => ({
        title: chunk.maps.title,
        uri: chunk.maps.uri
      }));

      setResponse({ text, links });
    } catch (error: any) {
      alert("خطأ في الخرائط: " + error.message);
    } finally {
      setLoading(false);
    }
  };

  const quickButtons = [
    { id: 'stadiums', label: 'ملاعب تدريب', icon: Trophy, prompt: 'ملاعب كرة قدم تدريبية قريبة' },
    { id: 'medical', label: 'طب رياضي', icon: Hospital, prompt: 'مراكز علاج فيزيائي وطوارئ رياضية' },
    { id: 'food', label: 'مطاعم صحية', icon: Utensils, prompt: 'مطاعم تقدم وجبات دايت بروتينية' },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500 font-['Tajawal']" dir="rtl">
      <div className="bg-white p-6 md:p-8 rounded-[2.5rem] border-2 border-slate-900 shadow-md">
        <div className="flex flex-col md:flex-row justify-between items-center gap-6">
          <div>
            <h2 className="text-xl font-black text-slate-900 flex items-center gap-3">
              <Navigation size={28} className="text-[#001F3F] animate-pulse" /> البوصلة اللوجستية الذكية (Maps)
            </h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">تحديد المرافق والخدمات الميدانية بدقة</p>
          </div>
          <div className="flex gap-2">
            {quickButtons.map(btn => (
              <button key={btn.id} onClick={() => searchLocations(btn.prompt)}
                className="bg-slate-50 border-2 border-slate-900 p-3 md:px-5 md:py-3 rounded-xl hover:bg-[#001F3F] hover:text-white transition-all flex flex-col items-center gap-1 group">
                <btn.icon size={18} />
                <span className="text-[9px] font-black">{btn.label}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="mt-8 flex gap-2">
          <input type="text" value={query} onChange={(e) => setQuery(e.target.value)}
            placeholder="مثال: فندق إقامة مريح في مدينة اللاذقية..."
            className="flex-1 bg-slate-100 border-2 border-slate-900 rounded-xl px-4 py-3 font-bold text-xs outline-none"
          />
          <button onClick={() => searchLocations('custom')} disabled={loading || !query}
            className="bg-[#001F3F] text-white px-6 rounded-xl font-black text-xs hover:bg-black disabled:opacity-50 transition-all">
            {loading ? <Loader2 className="animate-spin" size={18}/> : 'بحث'}
          </button>
        </div>
      </div>

      {response && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white p-6 rounded-[2.5rem] border-2 border-slate-900">
            <h3 className="font-black text-sm mb-4 flex items-center gap-2 text-blue-900 border-r-4 border-orange-600 pr-3">التوصية اللوجستية</h3>
            <div className="text-xs font-medium leading-relaxed whitespace-pre-wrap">{response.text}</div>
          </div>
          <div className="space-y-3">
            <h3 className="font-black text-[10px] uppercase text-slate-400 mr-2">المواقع المقترحة على الخريطة</h3>
            {response.links.map((link, i) => (
              <a key={i} href={link.uri} target="_blank" rel="noopener noreferrer"
                className="block bg-white p-4 rounded-xl border-2 border-slate-200 hover:border-orange-600 transition-all group shadow-sm">
                <div className="flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <MapPin size={18} className="text-orange-600"/>
                    <span className="font-black text-[11px]">{link.title}</span>
                  </div>
                  <ExternalLink size={14} className="text-slate-300 group-hover:text-orange-600" />
                </div>
              </a>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default LocationAssistant;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI } from "@google/genai";
import { MessageSquare, X, Send, Bot, User, Loader2, Minimize2, BrainCircuit, Zap } from 'lucide-react';
import { AppState } from '../types';

interface ChatBotProps {
  state: AppState;
}

const ChatBot: React.FC<ChatBotProps> = ({ state }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([
    { role: 'ai', text: 'أهلاً بك! أنا مساعدك السريع في مكتب الكرامة. كيف يمكنني خدمتك إدارياً الآن؟' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen) chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isOpen]);

  const contextStr = useMemo(() => {
    const players = state.people.filter(p => p.role === 'لاعب').length;
    const matches = state.matches.filter(m => !m.isCompleted).length;
    return `النادي به ${players} لاعب، و${matches} مباراة قادمة. المستخدم هو ${state.currentUser?.username}.`;
  }, [state]);

  const handleSendMessage = async () => {
    if (!input.trim() || loading) return;
    const query = input;
    setMessages(prev => [...prev, { role: 'user', text: query }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const systemInstruction = `أنت مساعد إداري سريع لنادي الكرامة السوري. السياق الحالي: ${contextStr}. أجب باختصار وسرعة.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-lite-latest',
        contents: query,
        config: { systemInstruction }
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "عذراً، انقطع الاتصال." }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "خطأ فني: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 left-6 z-[999] no-print" dir="rtl">
      {!isOpen ? (
        <button onClick={() => setIsOpen(true)} className="bg-[#001F3F] text-white p-4 rounded-full shadow-2xl border-4 border-white hover:scale-110 transition-all flex items-center gap-2 group">
          <Zap size={20} className="text-orange-400 group-hover:animate-pulse" />
          <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-500 font-black text-xs whitespace-nowrap px-0 group-hover:px-2">مساعد سريع</span>
          <MessageSquare size={24} />
        </button>
      ) : (
        <div className="bg-white w-[340px] h-[480px] rounded-[2rem] shadow-2xl border-4 border-slate-900 flex flex-col overflow-hidden animate-in slide-in-from-bottom-5 duration-300">
          <div className="bg-[#001F3F] p-4 flex justify-between items-center border-b-4 border-orange-600">
            <div className="flex items-center gap-2">
              <Bot size={18} className="text-orange-400" />
              <span className="text-white font-black text-[10px] uppercase">Al-Karamah AI Lite</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-white hover:text-orange-400"><Minimize2 size={18} /></button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50 custom-scrollbar">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
                <div className={`max-w-[85%] p-3 rounded-xl text-[10px] font-bold leading-relaxed shadow-sm ${msg.role === 'user' ? 'bg-white border border-slate-200 text-slate-900 rounded-tr-none' : 'bg-slate-900 text-white rounded-tl-none'}`}>
                  {msg.text}
                </div>
              </div>
            ))}
            {loading && <div className="text-center text-[8px] font-black text-slate-400 animate-pulse">جاري الاستجابة السريعة...</div>}
            <div ref={chatEndRef} />
          </div>
          <div className="p-3 bg-white border-t flex gap-2">
            <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
              placeholder="اطلب شيئاً سريعاً..." className="flex-1 bg-slate-100 rounded-xl px-3 py-2 text-[10px] font-black outline-none border border-transparent focus:border-orange-600" />
            <button onClick={handleSendMessage} disabled={loading || !input.trim()} className="bg-[#001F3F] text-white p-2 rounded-xl"><Send size={16} /></button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatBot;

