const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');

  const isInternalUpdate = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_secure_v12');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      warehouse: [],
      technicalReports: [],
      attendance: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // حساب حالة الإيقاف بناءً على تاريخ مباريات اللاعب
  const getPlayerSuspensionStatus = useCallback((personId: string, category: string) => {
    const completedMatches = state.matches
      .filter(m => m.category === category && m.isCompleted)
      .sort((a, b) => b.date.localeCompare(a.date));

    if (completedMatches.length === 0) return { isSuspended: false, currentYellows: 0, hasActiveRed: false };

    // البحث عن آخر مباراة شارك فيها اللاعب
    const lastAppearanceIndex = completedMatches.findIndex(m => 
      m.lineup.starters.some(s => s.playerId === personId) || 
      m.lineup.subs.some(s => s.playerId === personId)
    );

    if (lastAppearanceIndex === -1) {
      let yellowCount = 0;
      completedMatches.forEach(m => {
        yellowCount += m.events.filter(e => e.type === 'yellow' && e.player === personId).length;
      });
      return { isSuspended: yellowCount >= 3, currentYellows: yellowCount, hasActiveRed: false };
    }

    const lastMatch = completedMatches[lastAppearanceIndex];
    const gotRedInLast = lastMatch.events.some(e => e.type === 'red' && e.player === personId);

    let yellowCount = 0;
    completedMatches.slice(lastAppearanceIndex).forEach(m => {
      yellowCount += m.events.filter(e => e.type === 'yellow' && e.player === personId).length;
    });

    const reachedThreshold = yellowCount >= 3;
    const hasServedBan = lastAppearanceIndex > 0; // إذا كانت هناك مباراة بعد ظهوره الأخير لم يشارك فيها

    const isCurrentlySuspended = (gotRedInLast || reachedThreshold) && !hasServedBan;

    return { 
      isSuspended: isCurrentlySuspended, 
      currentYellows: yellowCount % 3, 
      hasActiveRed: gotRedInLast && !hasServedBan 
    };
  }, [state.matches]);

  useEffect(() => {
    localStorage.setItem('alkarama_secure_v12', JSON.stringify(state));
  }, [state]);

  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;
    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const [ppl, sess, mtch, attn, wrhs, tech, cats, usrs] = await Promise.all([
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('warehouse').select('*'),
        supabase.from('technical_reports').select('*'),
        supabase.from('categories').select('*'),
        supabase.from('app_users').select('*')
      ]);

      setState(prev => ({
        ...prev,
        categories: (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories,
        people: ppl.data || prev.people,
        sessions: sess.data || prev.sessions,
        matches: mtch.data || prev.matches,
        technicalReports: tech.data || prev.technicalReports,
        warehouse: wrhs.data || prev.warehouse,
        attendance: attn.data || prev.attendance,
        users: usrs.data || prev.users
      }));
      setSyncStatus('synced');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  const updateStateAndSync = useCallback(async (updater: (prev: AppState) => AppState) => {
    if (!state.currentUser) return;
    const nextState = updater(state);
    setState(nextState);

    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    try {
      await Promise.all([
        supabase.from('people').upsert(nextState.people),
        supabase.from('sessions').upsert(nextState.sessions),
        supabase.from('matches').upsert(nextState.matches),
        supabase.from('attendance').upsert(nextState.attendance),
        supabase.from('technical_reports').upsert(nextState.technicalReports),
        supabase.from('warehouse').upsert(nextState.warehouse),
        supabase.from('categories').upsert(nextState.categories.map(c => ({ name: c })), { onConflict: 'name' })
      ]);

      if (state.currentUser.role === 'مدير') {
        await supabase.from('app_users').upsert(nextState.users);
      }

      setSyncStatus('synced');
    } catch (err: any) {
      setSyncStatus('error');
    } finally {
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state]);

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();
    const channel = supabase.channel('global-changes').on('postgres_changes', { event: '*', schema: 'public' }, () => {
      if (!isInternalUpdate.current) fetchData();
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [state.currentUser, fetchData]);

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('alkarama_secure_v12');
  };

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'tech_reports', label: 'التقارير', icon: FilePieChart },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  if (!state.currentUser) return <Login onLoginAttempt={async (u, p) => {
    const { data } = await supabase.from('app_users').select('*').ilike('username', u.trim()).maybeSingle();
    if (data && data.password === p) {
      const user = { id: data.id, username: data.username, role: data.role as any, restrictedCategory: data.restrictedCategory };
      setState(prev => ({ ...prev, currentUser: user }));
      return user;
    }
    if ((u === 'IZZAT' || u === 'عزت') && p === '123') {
        const root = { id: 'root', username: 'عزت عامر الشيخة', role: 'مدير' as const };
        setState(prev => ({ ...prev, currentUser: root }));
        return root;
    }
    throw new Error("بيانات الدخول خاطئة");
  }} />;

  return (
    <div className="min-h-screen bg-[#000F21] flex text-right font-['Tajawal']" dir="rtl">
      {isSidebarOpen && <div className="fixed inset-0 bg-black/60 z-[100] lg:hidden" onClick={() => setSidebarOpen(false)}></div>}
      <aside className={`fixed inset-y-0 right-0 z-[110] w-64 bg-[#001F3F] border-l-2 border-[#FF6B00] transition-transform duration-300 lg:translate-x-0 lg:static ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center justify-between mb-8">
             <div className="flex items-center gap-3">
               <ClubLogo size={40} />
               <span className="text-white font-black text-sm">نادي الكرامة</span>
             </div>
             <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-white"><X size={24}/></button>
          </div>
          <nav className="flex-1 space-y-2 overflow-y-auto custom-scrollbar">
            {navItems.map(item => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 p-4 rounded-xl font-bold text-sm transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/60 hover:bg-white/5'}`}>
                <item.icon size={18} /> {item.label}
              </button>
            ))}
          </nav>
          <button onClick={handleLogout} className="mt-4 flex items-center gap-4 p-4 text-red-400 font-bold text-sm border-t border-white/10"><LogOut size={18}/> خروج</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-[#001F3F] border-b-2 border-[#FF6B00] px-4 md:px-8 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-3">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 bg-white/5 rounded-lg text-white"><Menu size={20}/></button>
            <h1 className="text-lg md:text-xl font-black text-white">{navItems.find(i => i.id === activeTab)?.label}</h1>
          </div>
          <div className="flex items-center gap-3">
            <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-[10px] font-black ${syncStatus === 'synced' ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30' : 'bg-orange-500/10 text-orange-400 border-orange-500/30'}`}>
              {syncStatus === 'synced' ? <CloudCheck size={14}/> : <Cloud size={14}/>}
              <span className="hidden md:inline">{syncStatus === 'synced' ? 'متصل' : 'جاري...'}</span>
            </div>
            <button onClick={fetchData} className="p-2 bg-white/5 rounded-lg text-white"><RefreshCw size={18} className={isSyncing ? 'animate-spin' : ''}/></button>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-3 md:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto pb-20">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'tech_reports' && <TechnicalReports state={state} setState={updateStateAndSync as any} />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync as any} />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
          </div>
        </section>

        <nav className="lg:hidden fixed bottom-0 inset-x-0 bg-[#001F3F] border-t-2 border-[#FF6B00]/30 p-2 flex justify-around items-center z-[90]">
           {navItems.slice(0, 5).map(item => (
             <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-3 rounded-xl transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/40'}`}>
                <item.icon size={20} />
             </button>
           ))}
        </nav>
      </main>
      <ChatBot state={state} />
    </div>
  );
};

