import React, { useState, useMemo } from 'react';
import { Trophy, Clock, Plus, X, Trash2, Edit, Save, CheckCircle, Unlock, Users, ArrowRightLeft, Activity, FileText, Loader2, MapPin } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';

interface MatchPlannerProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  defaultSelectedId?: string | null;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const restrictedCat = currentUser?.restrictedCategory;

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const deleteMatch = async (id: string, opponent: string) => {
    if (!isManager && !isCatAdmin) return;
    if (confirm(`هل أنت متأكد من حذف مباراة ${opponent} نهائياً؟`)) {
      setIsDeleting(id);
      try {
        const { error } = await supabase.from('matches').delete().eq('id', id);
        if (error) throw error;
        setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      } finally {
        setIsDeleting(null);
      }
    }
  };

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || state.categories[0],
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'خصم مجهول',
      pitch: formData.pitch || 'ملعب النادي',
      date: formData.date || '',
      time: formData.time || '',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({playerId: '', name: '', number: ''}), subs: [], staff: [], captain: '' },
      advancePayment: '0'
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    setIsAddOpen(false);
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);

    if (player && getSuspension) {
      const susp = getSuspension(player.id, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 تنبيه: اللاعب ${player.name} موقوف إدارياً لهذه المباراة ولا يمكن إدراجه في التشكيلة.`);
        return;
      }
    }

    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-5 md:p-8 rounded-2xl border-2 border-slate-900 flex justify-between items-center shadow-md">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F]">إدارة المباريات</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase">Match Center</p>
        </div>
        {!currentUser?.role.includes('مشاهد') && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white p-3 md:px-6 md:py-3 rounded-xl font-black text-xs flex items-center gap-2">
            <Plus size={20}/> <span className="hidden md:inline">جدولة مباراة</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-5 rounded-3xl border-2 border-slate-900 relative shadow-sm ${isDeleting === m.id ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date}</span>
             </div>
             <div className="text-center py-4">
                <p className="text-4xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-[#001F3F] mt-2">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-bold text-orange-600 mt-1 uppercase">{m.category}</p>
             </div>
             <div className="flex gap-2 mt-4 pt-4 border-t border-slate-50">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs uppercase">
                  {m.isCompleted ? 'التقرير الفني' : 'إدارة المباراة'}
                </button>
                {(isManager || (isCatAdmin && m.category === restrictedCat)) && (
                  <button onClick={() => deleteMatch(m.id, m.opponent)} className="p-3 bg-red-50 text-red-600 border-2 border-red-100 rounded-xl hover:bg-red-600 transition-all">
                    {isDeleting === m.id ? <Loader2 className="animate-spin" size={18}/> : <Trash2 size={18}/>}
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-white z-[300] overflow-y-auto p-4 md:p-10 text-right" dir="rtl">
           <div className="max-w-4xl mx-auto bg-white border-4 border-slate-900 rounded-[2rem] p-6 md:p-10 shadow-2xl mb-20">
              <div className="flex justify-between items-center mb-8 border-b-2 pb-4">
                 <h2 className="text-xl md:text-3xl font-black text-slate-900">الكرامة × {activeMatch.opponent}</h2>
                 <button onClick={() => setActiveMatch(null)} className="p-3 bg-slate-100 rounded-xl"><X/></button>
              </div>

              <div className="space-y-8">
                 <h3 className="font-black border-r-4 border-orange-600 pr-3">التشكيلة الأساسية</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {activeMatch.lineup.starters.map((s, idx) => (
                      <div key={idx} className="flex gap-3 items-center">
                         <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black">#{idx+1}</span>
                         <select className="flex-1 bg-slate-50 border-2 border-slate-900 p-3 rounded-xl font-bold text-xs" value={s.playerId} onChange={e => updateStarter(idx, e.target.value)}>
                            <option value="">-- اختر لاعب --</option>
                            {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                              <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                            ))}
                         </select>
                      </div>
                    ))}
                 </div>

                 <div className="pt-8 border-t-2">
                    <button onClick={() => {
                       setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? {...activeMatch, isCompleted: true} : m)}));
                       setActiveMatch(null);
                    }} className="w-full bg-emerald-600 text-white py-4 rounded-2xl font-black shadow-lg">حفظ واعتماد المباراة</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Layers, Plus, Calendar,
  MapPin, Edit2, FileText, ChevronRight
} from 'lucide-react';
import { AppState, Person, Role } from '../types';
import ClubLogo from './ClubLogo';
import { generateUUID, supabase } from '../App';

interface SquadManagementProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenReport?: (player: Person) => void;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, getSuspension }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');
  const [activeSubTab, setActiveSubTab] = useState<'players' | 'staff'>('players');

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: restrictedCat || state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0]
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return null;
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    if (isViewer) return;
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
    } else {
      const newPerson: Person = {
        id: generateUUID(),
        name: formData.name || '',
        fatherName: formData.fatherName || '',
        motherName: formData.motherName || '',
        birthDate: formData.birthDate || '',
        birthPlace: formData.birthPlace || '',
        khana: formData.khana || '',
        nationalId: formData.nationalId || '',
        federalNumber: formData.federalNumber || '',
        internationalId: formData.internationalId || '',
        address: formData.address || '',
        category: formData.category || restrictedCat || state.categories[0],
        role: formData.role || 'لاعب',
        number: formData.number || 0,
        phone: formData.phone || '',
        joinDate: formData.joinDate || new Date().toISOString().split('T')[0],
        monthlyReports: {}
      };
      setState(p => ({ ...p, people: [...p.people, newPerson] }));
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const baseFiltered = state.people.filter(p => {
    const matchCat = restrictedCat ? p.category === restrictedCat : (localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter);
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  const filteredPlayers = baseFiltered.filter(p => p.role === 'لاعب');
  const filteredStaff = baseFiltered.filter(p => p.role !== 'لاعب');
  const displayList = activeSubTab === 'players' ? filteredPlayers : filteredStaff;

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2.5 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 no-print space-y-6">
        <div className="flex flex-col lg:flex-row gap-4 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
            <input 
              type="text" 
              placeholder="البحث بالاسم أو الرقم..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-12 h-12 text-lg`} 
            />
          </div>
          <div className="flex items-center gap-3 w-full lg:w-auto">
            {!restrictedCat && (
              <select value={localCategoryFilter} onChange={e => setLocalCategoryFilter(e.target.value)} className="bg-slate-100 border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-sm h-12 outline-none">
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            )}
            {!isViewer && (
              <button onClick={() => { setEditingId(null); setIsModalOpen(true); }} className="bg-[#001F3F] text-white px-8 h-12 rounded-xl font-black text-sm flex items-center gap-2 shadow-lg border-b-4 border-black">
                <Plus size={20} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        <div className="flex p-1.5 bg-slate-100 border-2 border-slate-900 rounded-2xl w-fit">
          <button onClick={() => setActiveSubTab('players')} className={`px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'players' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>اللاعبين</button>
          <button onClick={() => setActiveSubTab('staff')} className={`px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'staff' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}>الكوادر</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
        {displayList.map(person => {
          const susp = getSuspension ? getSuspension(person.id, person.category) : { isSuspended: false, currentYellows: 0, hasActiveRed: false };
          return (
