import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, X, Globe, ExternalLink, BarChart, TrendingUp, ShieldAlert, HeartPulse, History, Gavel, Filter, Trophy, Star, AlertCircle } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [aiMode, setAiMode] = useState<'fast' | 'deep' | 'tactical'>('fast');
  const [selectedCategory, setSelectedCategory] = useState<string>(state.currentUser?.restrictedCategory || state.globalCategoryFilter || 'الكل');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const restrictedCat = currentUser?.restrictedCategory;

  useEffect(() => {
    if (restrictedCat) {
      setSelectedCategory(restrictedCat);
    }
  }, [restrictedCat]);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const clubAnalysis = useMemo(() => {
    const categoryPlayers = state.people.filter(p => 
      p.role === 'لاعب' && (selectedCategory === 'الكل' ? true : p.category === selectedCategory)
    );

    const categoryMatches = state.matches.filter(m => 
      m.isCompleted && (selectedCategory === 'الكل' ? true : m.category === selectedCategory)
    );

    const categorySessions = state.sessions.filter(s => 
      (selectedCategory === 'الكل' ? true : s.category === selectedCategory)
    );

    const medicalHistory = categoryPlayers
      .filter(p => p.injuries || p.medicalHistory)
      .map(p => `- ${p.name}: إصابات (${p.injuries || 'لا يوجد'}), ملاحظات (${p.medicalHistory || 'سليم'})`)
      .join('\n');

    const performanceAndDiscipline = categoryPlayers.map(p => {
      const records = state.attendance.filter(a => a.personId === p.id);
      const lates = records.filter(r => r.status === 'متأخر').length;

      let goals = 0;
      let assists = 0;
      let yellows = 0;
      let reds = 0;

      categoryMatches.forEach(m => {
        goals += m.events.filter(e => e.type === 'goal' && (e.player === p.id || e.player === p.name)).length;
        assists += m.events.filter(e => e.type === 'assist' && (e.player === p.id || e.player === p.name)).length;
        yellows += m.events.filter(e => e.type === 'yellow' && (e.player === p.id || e.player === p.name)).length;
        reds += m.events.filter(e => e.type === 'red' && (e.player === p.id || e.player === p.name)).length;
      });

      const attRate = categorySessions.length > 0 ? Math.round(((records.filter(r => r.status === 'حاضر').length + lates * 0.7) / categorySessions.length) * 100) : 0;

      return `- ${p.name}: أهداف(${goals}), أسيست(${assists}), كروت(🟨:${yellows}, 🟥:${reds}), التزام(${attRate}%)`;
    }).join('\n');

    const recentMatches = categoryMatches
      .slice(-5)
      .map(m => `- ضد ${m.opponent}: (${m.ourScore}-${m.opponentScore}), نوع:${m.matchType}`)
      .join('\n');

    return { medicalHistory, performanceAndDiscipline, recentMatches };
  }, [state, selectedCategory]);

  const handleAsk = async (customPrompt?: string) => {
    const userQuery = customPrompt || input;
    if (!userQuery.trim() || loading) return;

    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const { medicalHistory, performanceAndDiscipline, recentMatches } = clubAnalysis;

      const systemInstruction = `
        أنت المحلل التكتيكي الرقمي لنادي الكرامة الرياضي. 
        تحلل فئة: ${selectedCategory}.

        بيانات قاعدة البيانات المتاحة:
        [إصابات]: ${medicalHistory}
        [أداء وانضباط]: ${performanceAndDiscipline}
        [نتائج أخيرة]: ${recentMatches}

        مهمتك: تقديم توصيات تكتيكية، تحليل مخاطر، واقتراحات استراتيجية مبنية على البيانات العميقة.
      `;

      // استخدام وضع التفكير العميق عند اختيار aiMode === 'deep'
      const response = await ai.models.generateContent({
        model: aiMode === 'deep' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview',
        contents: userQuery,
        config: { 
          systemInstruction,
          // إذا كان الوضع "تفكير عميق"، نخصص الميزانية القصوى
          thinkingConfig: aiMode === 'deep' ? { thinkingBudget: 32768 } : undefined 
        }
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "لم أستطع تحليل البيانات حالياً." }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "حدث خطأ: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  const quickActions = [
    { label: 'أفضل تشكيلة حالية', prompt: 'بناءً على التزام اللاعبين وأدائهم التهديفي، ما هي التشكيلة الأساسية المثالية المقترحة للمباراة القادمة؟ استخدم التفكير العميق للربط بين الأرقام والنتائج.', icon: Trophy, color: 'text-emerald-600' },
    { label: 'تحليل مخاطر الإصابات', prompt: 'حلل السجل الطبي والالتزام البدني وحذرني من اللاعبين المعرضين للإصابة قريباً.', icon: HeartPulse, color: 'text-red-600' },
    { label: 'استراتيجية الموسم القادم', prompt: 'بناءً على مستويات الفئة حالياً، ما هي النواقص التي يجب معالجتها تكتيكياً في سوق الانتقالات القادم؟', icon: TrendingUp, color: 'text-blue-600' }
  ];

  return (
    <div className="flex flex-col h-[calc(100vh-180px)] space-y-4 font-['Tajawal']" dir="rtl">
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center shadow-sm gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-[#001F3F] p-3 rounded-2xl">
            <BrainCircuit className="text-orange-400" size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black text-slate-900 uppercase">المحلل التكتيكي العبقري</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">تفكير عميق مدعوم بـ Gemini 3 Pro</p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="flex gap-1 bg-slate-100 p-1 rounded-2xl border border-slate-200">
             <button onClick={() => setAiMode('fast')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${aiMode === 'fast' ? 'bg-[#001F3F] text-white shadow-md' : 'text-slate-500'}`}>الوضع السريع</button>
             <button onClick={() => setAiMode('deep')} className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${aiMode === 'deep' ? 'bg-orange-600 text-white shadow-md animate-pulse' : 'text-slate-500'}`}>تفكير عميق (Pro)</button>
          </div>
        </div>
      </div>

      <div className="flex-1 bg-white rounded-[3rem] border-2 border-slate-900 flex flex-col overflow-hidden relative shadow-inner">
        <div className="p-4 bg-slate-50 border-b-2 border-slate-200 grid grid-cols-1 md:grid-cols-3 gap-3 no-print">
           {quickActions.map((action, i) => (
             <button 
              key={i} 
              onClick={() => { setAiMode('deep'); handleAsk(action.prompt); }}
              className="bg-white p-3 rounded-2xl border-2 border-slate-200 hover:border-orange-600 transition-all flex flex-col items-center gap-2 group shadow-sm"
             >
                <action.icon size={18} className={`${action.color} group-hover:scale-110 transition-transform`} />
                <span className="text-[8px] font-black text-slate-600 group-hover:text-[#001F3F]">{action.label}</span>
             </button>
           ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center opacity-30 space-y-4">
              <Bot size={80} className="text-[#001F3F]" />
              <div className="text-center max-w-sm">
                <p className="font-black text-sm mb-2">محلل فئة {selectedCategory} في وضع الانتظار</p>
                <p className="font-medium text-[11px] leading-relaxed">أهلاً بك مدرب الكرامة. استخدم وضع "التفكير العميق" للأسئلة الاستراتيجية والمصيرية للفريق.</p>
              </div>
            </div>
          )}
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[85%] p-5 rounded-[2.2rem] text-sm leading-relaxed shadow-sm ${msg.role === 'user' ? 'bg-slate-100 border-2 border-slate-200 text-slate-900 rounded-tr-none' : 'bg-[#001F3F] text-white border-b-4 border-orange-600 rounded-tl-none'}`}>
                <div className="flex items-center gap-2 mb-2 opacity-50">
                   {msg.role === 'user' ? <User size={14}/> : <Bot size={14}/>}
                   <span className="text-[9px] font-black uppercase">{msg.role === 'user' ? 'المدرب' : 'المحلل الفني (Pro)'}</span>
                </div>
                <div className="whitespace-pre-wrap font-medium">{msg.text}</div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end">
              <div className="bg-[#001F3F] text-white p-5 rounded-[2rem] rounded-tl-none flex items-center gap-4 shadow-xl border-b-4 border-orange-600">
                <Loader2 className="animate-spin text-orange-400" size={20} />
                <span className="text-[10px] font-black animate-pulse">
                  {aiMode === 'deep' ? 'الذكاء يقوم بعملية تفكير عميق (Deep Thinking)...' : 'جاري معالجة البيانات الفنية...'}
                </span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        <div className="p-4 bg-white border-t-2 border-slate-900 flex gap-3">
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            placeholder={aiMode === 'deep' ? "اسأل سؤالاً استراتيجياً معقداً (وضع التفكير)..." : "اسأل المحلل التكتيكي..."}
            className="flex-1 bg-slate-50 border-2 border-slate-200 rounded-2xl px-6 py-4 font-black outline-none focus:border-orange-600 transition-all"
          />
          <button onClick={() => handleAsk()} disabled={loading || !input.trim()} className="bg-[#001F3F] text-white p-4 rounded-2xl shadow-lg hover:bg-black transition-all">
            <Send size={24} />
          </button>
        </div>
      </div>
    </div>
  );
};

