    const userQuery = input;
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const systemInstruction = `
        أنت "مساعد الكرامة الاستراتيجي". 
        تستخدم نموذج Gemini 3 Pro مع التفكير العميق لحل المشكلات المعقدة.
        سياق البيانات: ${dataContext}
        هدفك: تقديم حلول إدارية وفنية ذكية، والربط بين المواعيد والبيانات البشرية للنادي.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: userQuery,
        config: {
          systemInstruction,
          // تفعيل وضع التفكير العميق بأقصى ميزانية
          thinkingConfig: { thinkingBudget: 32768 }
        }
      });

