            <button onClick={() => setIsOpen(false)} className="text-white hover:text-orange-400"><X size={20} /></button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-slate-50/50">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-[11px] font-bold leading-relaxed shadow-sm ${
                  msg.role === 'user' ? 'bg-white border-2 border-slate-200 text-slate-900 rounded-tr-none' : 'bg-[#001F3F] text-white rounded-tl-none'
                }`}>
                  {msg.text}
