import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Sparkles, Send, Bot, User, Loader2, BrainCircuit, Zap, X, Globe, ExternalLink, BarChart, TrendingUp, ShieldAlert, HeartPulse, History, Gavel, Filter, Trophy, Star, AlertCircle, Lightbulb } from 'lucide-react';
import { AppState } from '../types';

interface AIAssistantProps {
  state: AppState;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ state }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [aiMode, setAiMode] = useState<'fast' | 'deep'>('fast');
  const chatEndRef = useRef<HTMLDivElement>(null);

  const selectedCategory = state.globalCategoryFilter || 'الكل';

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // تجهيز سياق البيانات للنظام
  const clubContext = useMemo(() => {
    const categoryPlayers = state.people.filter(p => 
      p.role === 'لاعب' && (selectedCategory === 'الكل' ? true : p.category === selectedCategory)
    );
    const categoryMatches = state.matches.filter(m => 
      m.isCompleted && (selectedCategory === 'الكل' ? true : m.category === selectedCategory)
    );

    const playersStats = categoryPlayers.map(p => {
      const records = state.attendance.filter(a => a.personId === p.id);
      const attRate = records.length > 0 ? Math.round((records.filter(r => r.status === 'حاضر').length / records.length) * 100) : 0;
      return `${p.name} (عمر:${p.birthDate}, رقم:${p.number}, التزام:${attRate}%, إصابات:${p.injuries || 'لا يوجد'})`;
    }).join(' | ');

    const recentResults = categoryMatches.slice(-3).map(m => `ضد ${m.opponent}: (${m.ourScore}-${m.opponentScore})`).join(' | ');

    return `الفئة: ${selectedCategory}. اللاعبين المتاحين: ${playersStats}. النتائج الأخيرة: ${recentResults}.`;
  }, [state, selectedCategory]);

  const handleAsk = async (customPrompt?: string) => {
    const userQuery = customPrompt || input;
    if (!userQuery.trim() || loading) return;

    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setInput('');
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const systemInstruction = `
        أنت المحلل الاستراتيجي الذكي لنادي الكرامة الرياضي. 
        تستخدم التفكير العميق والمنطق الرياضي لتحليل البيانات.
        السياق الحالي: ${clubContext}
        في وضع "التفكير العميق"، يجب أن تقدم تحليلاً مفصلاً يربط بين الأرقام والحالة الفنية.
      `;

      // اختيار الموديل بناءً على الوضع
      const modelName = aiMode === 'deep' ? 'gemini-3-pro-preview' : 'gemini-3-flash-preview';

      const response = await ai.models.generateContent({
        model: modelName,
        contents: userQuery,
        config: {
          systemInstruction,
          // تفعيل ميزانية التفكير للبريميم فقط
          ...(aiMode === 'deep' && { thinkingConfig: { thinkingBudget: 32768 } })
        }
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "عذراً، أحتاج لتركيز أكثر للإجابة." }]);
    } catch (error: any) {
      setMessages(prev => [...prev, { role: 'ai', text: "حدث خطأ في الاتصال بالعقل الاصطناعي: " + error.message }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-180px)] space-y-4 font-['Tajawal']" dir="rtl">
      {/* Header with Mode Toggle */}
      <div className="bg-white p-5 rounded-[2.5rem] border-2 border-slate-900 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-3">
          <div className={`p-3 rounded-2xl ${aiMode === 'deep' ? 'bg-orange-600' : 'bg-[#001F3F]'} text-white transition-colors duration-500`}>
            {aiMode === 'deep' ? <BrainCircuit size={24} className="animate-pulse" /> : <Zap size={24} />}
          </div>
          <div>
            <h2 className="text-lg font-black text-slate-900">المحلل التكتيكي الذكي</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">فئة: {selectedCategory}</p>
          </div>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-2xl border-2 border-slate-200">
           <button 
            onClick={() => setAiMode('fast')} 
            className={`px-6 py-2 rounded-xl font-black text-[10px] transition-all ${aiMode === 'fast' ? 'bg-[#001F3F] text-white' : 'text-slate-500'}`}
           >
             وضع Flash (سريع)
           </button>
           <button 
            onClick={() => setAiMode('deep')} 
            className={`px-6 py-2 rounded-xl font-black text-[10px] transition-all flex items-center gap-2 ${aiMode === 'deep' ? 'bg-orange-600 text-white shadow-lg' : 'text-slate-500'}`}
           >
             <Sparkles size={14}/> وضع التفكير العميق (Pro)
           </button>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 bg-white rounded-[3rem] border-2 border-slate-900 flex flex-col overflow-hidden relative shadow-inner">
        <div className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center opacity-20 space-y-4 text-center">
              <Bot size={80} />
              <p className="font-black text-sm max-w-[200px]">مرحباً كوتش! اسألني عن أي تفصيل فني أو استراتيجي للفريق.</p>
            </div>
          )}
          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[85%] p-4 rounded-3xl text-sm leading-relaxed shadow-sm ${msg.role === 'user' ? 'bg-slate-100 border-2 border-slate-200 text-slate-900 rounded-tr-none' : 'bg-[#001F3F] text-white rounded-tl-none border-b-4 border-orange-600'}`}>
                <div className="flex items-center gap-2 mb-1 opacity-50">
                   {msg.role === 'user' ? <User size={12}/> : <Bot size={12}/>}
                   <span className="text-[8px] font-black">{msg.role === 'user' ? 'المدرب' : 'المحلل الفني'}</span>
                </div>
                <div className="whitespace-pre-wrap font-medium">{msg.text}</div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end">
              <div className="bg-[#001F3F] text-white p-4 rounded-3xl rounded-tl-none flex items-center gap-3 shadow-lg border-b-4 border-orange-600">
                <Loader2 className="animate-spin text-orange-400" size={18} />
                <span className="text-[10px] font-black animate-pulse">
                  {aiMode === 'deep' ? 'يتم التفكير بعمق في البيانات (Thinking Budget: 32K)...' : 'جاري التحليل السريع...'}
                </span>
              </div>
            </div>
          )}
          <div ref={chatEndRef} />
        </div>

        {/* Input Bar */}
        <div className="p-4 bg-white border-t-2 border-slate-900 flex gap-2">
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            placeholder={aiMode === 'deep' ? "اسأل سؤالاً تكتيكياً معقداً..." : "اسأل سؤالاً سريعاً..."}
            className="flex-1 bg-slate-50 border-2 border-slate-200 rounded-2xl px-6 py-3 font-bold outline-none focus:border-orange-600 transition-all"
          />
          <button onClick={() => handleAsk()} disabled={loading || !input.trim()} className={`${aiMode === 'deep' ? 'bg-orange-600' : 'bg-[#001F3F]'} text-white p-4 rounded-2xl shadow-lg hover:scale-105 transition-all`}>
            <Send size={24} />
          </button>
        </div>
      </div>

      {/* Suggestions */}
      <div className="flex gap-2 overflow-x-auto pb-2 no-print custom-scrollbar">
         {[
           "أفضل تشكيلة للمباراة القادمة؟",
           "من هم اللاعبون المعرضون للإصابة؟",
           "تحليل نقاط الضعف في الدفاع",
           "خطة تطوير للاعبين الأقل التزاماً"
         ].map((s, i) => (
           <button key={i} onClick={() => handleAsk(s)} className="bg-white border-2 border-slate-200 px-4 py-2 rounded-xl text-[10px] font-black text-slate-500 whitespace-nowrap hover:border-orange-600 hover:text-orange-600 transition-all">
             {s}
           </button>
         ))}
      </div>
    </div>
  );
};

export default AIAssistant;

import React, { useState, useMemo } from 'react';
import { Trophy, Clock, Plus, X, Trash2, Edit, Save, CheckCircle, Unlock, Users, ArrowRightLeft, Activity, FileText, Loader2, MapPin, Sparkles, MessageSquare } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';
import { GoogleGenAI } from "@google/genai";

interface MatchPlannerProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  defaultSelectedId?: string | null;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [isAiGenerating, setIsAiGenerating] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<string | null>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const restrictedCat = currentUser?.restrictedCategory;

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const generateAiSummary = async (match: Match) => {
    setIsAiGenerating(match.id);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const eventsStr = match.events.map(e => `${e.minute}' [${e.type}] - ${e.player}`).join(', ');

      const prompt = `
        اكتب ملخصاً فنياً واحترافياً لمباراة كرة قدم لفريق الكرامة (فئة ${match.category}) ضد فريق ${match.opponent}.
        النتيجة: الكرامة ${match.ourScore} - ${match.opponentScore} ${match.opponent}.
        الأحداث: ${eventsStr || 'لم يتم تسجيل أحداث محددة'}.
        الملعب: ${match.pitch}.
        اجعل الأسلوب حماسياً ومناسباً للنشر على صفحة النادي الرسمية.
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });

      setAiSummary(result.text || "لم يتمكن الذكاء من صياغة الملخص.");
    } catch (error) {
      alert("فشل في توليد الملخص الذكي.");
    } finally {
      setIsAiGenerating(null);
    }
  };

  const deleteMatch = async (id: string, opponent: string) => {
    if (!isManager && !isCatAdmin) return;
    if (confirm(`هل أنت متأكد من حذف مباراة ${opponent} نهائياً؟`)) {
      setIsDeleting(id);
      try {
        const { error } = await supabase.from('matches').delete().eq('id', id);
        if (error) throw error;
        setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      } finally {
        setIsDeleting(null);
      }
    }
  };

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || state.categories[0],
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'خصم مجهول',
      pitch: formData.pitch || 'ملعب النادي',
      date: formData.date || '',
      time: formData.time || '',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({playerId: '', name: '', number: ''}), subs: [], staff: [], captain: '' },
      advancePayment: '0'
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    setIsAddOpen(false);
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);

    if (player && getSuspension) {
      const susp = getSuspension(player.id, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 تنبيه: اللاعب ${player.name} موقوف إدارياً لهذه المباراة ولا يمكن إدراجه في التشكيلة.`);
        return;
      }
    }

    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-5 md:p-8 rounded-2xl border-2 border-slate-900 flex justify-between items-center shadow-md">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F]">إدارة المباريات</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase">Match Center</p>
        </div>
        {!currentUser?.role.includes('مشاهد') && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white p-3 md:px-6 md:py-3 rounded-xl font-black text-xs flex items-center gap-2">
            <Plus size={20}/> <span className="hidden md:inline">جدولة مباراة</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative shadow-sm transition-all hover:-translate-y-1 ${isDeleting === m.id ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date}</span>
             </div>
             <div className="text-center py-4">
                <p className="text-4xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-[#001F3F] mt-2">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-bold text-orange-600 mt-1 uppercase">{m.category}</p>
             </div>

             {m.isCompleted && (
               <button 
                onClick={() => generateAiSummary(m)} 
                disabled={isAiGenerating === m.id}
                className="mt-4 w-full bg-slate-50 border-2 border-dashed border-slate-300 py-3 rounded-xl flex items-center justify-center gap-2 text-[10px] font-black text-slate-500 hover:border-orange-600 hover:text-orange-600 transition-all"
               >
                 {isAiGenerating === m.id ? <Loader2 className="animate-spin" size={14}/> : <Sparkles size={14} className="text-orange-600" />}
                 تلخيص ذكي للمباراة
               </button>
             )}

             <div className="flex gap-2 mt-4 pt-4 border-t border-slate-50">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs uppercase">
                  {m.isCompleted ? 'التقرير الفني' : 'إدارة المباراة'}
                </button>
                {(isManager || (isCatAdmin && m.category === restrictedCat)) && (
                  <button onClick={() => deleteMatch(m.id, m.opponent)} className="p-3 bg-red-50 text-red-600 border-2 border-red-100 rounded-xl hover:bg-red-600 transition-all">
                    {isDeleting === m.id ? <Loader2 className="animate-spin" size={18}/> : <Trash2 size={18}/>}
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* AI Summary Modal */}
      {aiSummary && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in duration-300 text-right" dir="rtl">
            <div className="bg-orange-600 p-6 flex justify-between items-center text-white">
               <div className="flex items-center gap-3">
                 <Sparkles size={24} />
                 <h3 className="font-black text-lg">الملخص الفني الذكي</h3>
               </div>
               <button onClick={() => setAiSummary(null)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
            </div>
            <div className="p-8">
               <div className="bg-slate-50 p-6 rounded-2xl border-2 border-slate-100 font-bold text-sm leading-relaxed text-slate-700 whitespace-pre-wrap">
                 {aiSummary}
               </div>
               <div className="mt-6 flex gap-3">
                  <button onClick={() => { navigator.clipboard.writeText(aiSummary); alert('تم نسخ الملخص!'); }} className="flex-1 bg-[#001F3F] text-white py-4 rounded-xl font-black flex items-center justify-center gap-2">
                    <Save size={18}/> نسخ النص للنشر
                  </button>
                  <button onClick={() => setAiSummary(null)} className="flex-1 bg-slate-100 text-slate-500 py-4 rounded-xl font-black">إغلاق</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {activeMatch && (
        <div className="fixed inset-0 bg-white z-[300] overflow-y-auto p-4 md:p-10 text-right" dir="rtl">
           <div className="max-w-4xl mx-auto bg-white border-4 border-slate-900 rounded-[2rem] p-6 md:p-10 shadow-2xl mb-20">
              <div className="flex justify-between items-center mb-8 border-b-2 pb-4">
                 <h2 className="text-xl md:text-3xl font-black text-slate-900">الكرامة × {activeMatch.opponent}</h2>
                 <button onClick={() => setActiveMatch(null)} className="p-3 bg-slate-100 rounded-xl"><X/></button>
              </div>

              <div className="space-y-8">
                 <h3 className="font-black border-r-4 border-orange-600 pr-3">التشكيلة الأساسية</h3>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {activeMatch.lineup.starters.map((s, idx) => (
                      <div key={idx} className="flex gap-3 items-center">
                         <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black">#{idx+1}</span>
                         <select className="flex-1 bg-slate-50 border-2 border-slate-900 p-3 rounded-xl font-bold text-xs" value={s.playerId} onChange={e => updateStarter(idx, e.target.value)}>
                            <option value="">-- اختر لاعب --</option>
                            {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                              <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                            ))}
                         </select>
                      </div>
                    ))}
                 </div>

                 <div className="pt-8 border-t-2">
                    <button onClick={() => {
                       setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? {...activeMatch, isCompleted: true} : m)}));
                       setActiveMatch(null);
                    }} className="w-full bg-emerald-600 text-white py-4 rounded-2xl font-black shadow-lg">حفظ واعتماد المباراة</button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useMemo } from 'react';
import { Trophy, Clock, Plus, X, Trash2, Edit, Save, CheckCircle, Unlock, Users, ArrowRightLeft, Activity, FileText, Loader2, MapPin, Sparkles, MessageSquare, Timer, UserCheck, Shield } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';
import { GoogleGenAI } from "@google/genai";

interface MatchPlannerProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  defaultSelectedId?: string | null;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [isAiGenerating, setIsAiGenerating] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<string | null>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const restrictedCat = currentUser?.restrictedCategory;

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const generateAiSummary = async (match: Match) => {
    setIsAiGenerating(match.id);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const eventsStr = match.events.map(e => `${e.minute}' [${e.type}] - ${e.player}`).join(', ');

      const prompt = `
        اكتب ملخصاً فنياً واحترافياً لمباراة كرة قدم لفريق الكرامة (فئة ${match.category}) ضد فريق ${match.opponent}.
        النتيجة: الكرامة ${match.ourScore} - ${match.opponentScore} ${match.opponent}.
        الأحداث: ${eventsStr || 'لم يتم تسجيل أحداث محددة'}.
        الملعب: ${match.pitch}.
        اجعل الأسلوب حماسياً ومناسباً للنشر على صفحة النادي الرسمية.
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });

      setAiSummary(result.text || "لم يتمكن الذكاء من صياغة الملخص.");
    } catch (error) {
      alert("فشل في توليد الملخص الذكي.");
    } finally {
      setIsAiGenerating(null);
    }
  };

  const deleteMatch = async (id: string, opponent: string) => {
    if (!isManager && !isCatAdmin) return;
    if (confirm(`هل أنت متأكد من حذف مباراة ${opponent} نهائياً؟`)) {
      setIsDeleting(id);
      try {
        const { error } = await supabase.from('matches').delete().eq('id', id);
        if (error) throw error;
        setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      } finally {
        setIsDeleting(null);
      }
    }
  };

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || state.categories[0],
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'خصم مجهول',
      pitch: formData.pitch || 'ملعب النادي',
      date: formData.date || '',
      time: formData.time || '',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({playerId: '', name: '', number: ''}), subs: [], staff: [], captain: '' },
      advancePayment: '0'
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    setIsAddOpen(false);
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);

    if (player && getSuspension) {
      const susp = getSuspension(player.id, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 تنبيه: اللاعب ${player.name} موقوف إدارياً لهذه المباراة ولا يمكن إدراجه في التشكيلة.`);
        return;
      }
    }

    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const addSub = () => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs = [...newLineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0' }];
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.subs[index] = { ...newLineup.subs[index], playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const removeSub = (index: number) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.splice(index, 1);
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-5 md:p-8 rounded-2xl border-2 border-slate-900 flex justify-between items-center shadow-md">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F]">إدارة المباريات</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase">Match Center</p>
        </div>
        {!currentUser?.role.includes('مشاهد') && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white p-3 md:px-6 md:py-3 rounded-xl font-black text-xs flex items-center gap-2">
            <Plus size={20}/> <span className="hidden md:inline">جدولة مباراة</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative shadow-sm transition-all hover:-translate-y-1 ${isDeleting === m.id ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date}</span>
             </div>
             <div className="text-center py-4">
                <p className="text-4xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-[#001F3F] mt-2">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-bold text-orange-600 mt-1 uppercase">{m.category}</p>
             </div>

             {m.isCompleted && (
               <button 
                onClick={() => generateAiSummary(m)} 
                disabled={isAiGenerating === m.id}
                className="mt-4 w-full bg-slate-50 border-2 border-dashed border-slate-300 py-3 rounded-xl flex items-center justify-center gap-2 text-[10px] font-black text-slate-500 hover:border-orange-600 hover:text-orange-600 transition-all"
               >
                 {isAiGenerating === m.id ? <Loader2 className="animate-spin" size={14}/> : <Sparkles size={14} className="text-orange-600" />}
                 تلخيص ذكي للمباراة
               </button>
             )}

             <div className="flex gap-2 mt-4 pt-4 border-t border-slate-50">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs uppercase">
                  {m.isCompleted ? 'التقرير الفني' : 'إدارة المباراة'}
                </button>
                {(isManager || (isCatAdmin && m.category === restrictedCat)) && (
                  <button onClick={() => deleteMatch(m.id, m.opponent)} className="p-3 bg-red-50 text-red-600 border-2 border-red-100 rounded-xl hover:bg-red-600 transition-all">
                    {isDeleting === m.id ? <Loader2 className="animate-spin" size={18}/> : <Trash2 size={18}/>}
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* AI Summary Modal */}
      {aiSummary && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in duration-300 text-right" dir="rtl">
            <div className="bg-orange-600 p-6 flex justify-between items-center text-white">
               <div className="flex items-center gap-3">
                 <Sparkles size={24} />
                 <h3 className="font-black text-lg">الملخص الفني الذكي</h3>
               </div>
               <button onClick={() => setAiSummary(null)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
            </div>
            <div className="p-8">
               <div className="bg-slate-50 p-6 rounded-2xl border-2 border-slate-100 font-bold text-sm leading-relaxed text-slate-700 whitespace-pre-wrap">
                 {aiSummary}
               </div>
               <div className="mt-6 flex gap-3">
                  <button onClick={() => { navigator.clipboard.writeText(aiSummary); alert('تم نسخ الملخص!'); }} className="flex-1 bg-[#001F3F] text-white py-4 rounded-xl font-black flex items-center justify-center gap-2">
                    <Save size={18}/> نسخ النص للنشر
                  </button>
                  <button onClick={() => setAiSummary(null)} className="flex-1 bg-slate-100 text-slate-500 py-4 rounded-xl font-black">إغلاق</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Match Management Modal - RESTORED FULL VERSION */}
      {activeMatch && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[400] overflow-y-auto p-2 md:p-8 text-right font-['Tajawal']" dir="rtl">
           <div className="max-w-5xl mx-auto bg-white border-4 border-slate-900 rounded-[3rem] shadow-2xl overflow-hidden">
              <div className="bg-[#001F3F] p-6 md:p-10 flex justify-between items-center text-white border-b-8 border-orange-600">
                 <div className="flex items-center gap-6">
                    <div className="bg-white p-3 rounded-2xl">
                       <Trophy className="text-[#001F3F]" size={40} />
                    </div>
                    <div>
                       <h2 className="text-xl md:text-3xl font-black uppercase">الكرامة × {activeMatch.opponent}</h2>
                       <p className="text-orange-400 text-xs font-black uppercase mt-1 tracking-widest">{activeMatch.category} | {activeMatch.matchType}</p>
                    </div>
                 </div>
                 <button onClick={() => setActiveMatch(null)} className="bg-white/10 p-3 rounded-full hover:bg-white/20 transition-all">
                    <X size={32} />
                 </button>
              </div>

              <div className="p-6 md:p-12 space-y-12">
                 {/* 1. النتيجة والوقت */}
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-8 bg-slate-50 p-8 rounded-[2.5rem] border-2 border-slate-200">
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">النتيجة النهائية</label>
                       <div className="flex items-center gap-4">
                          <input type="number" className="w-20 h-20 bg-white border-4 border-[#001F3F] rounded-2xl text-center text-4xl font-black text-[#001F3F]" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                          <span className="text-2xl font-black text-slate-400">:</span>
                          <input type="number" className="w-20 h-20 bg-white border-4 border-slate-400 rounded-2xl text-center text-4xl font-black text-slate-500" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                       </div>
                    </div>
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">الوقت المضاف</label>
                       <div className="flex gap-2">
                          <input type="text" placeholder="ش1" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime1 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                          <input type="text" placeholder="ش2" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime2 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                       </div>
                    </div>
                    <div className="flex flex-col gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">مكان المباراة</label>
                       <div className="relative">
                          <MapPin className="absolute right-3 top-3 text-orange-600" size={18} />
                          <input type="text" className="w-full bg-white border-2 border-slate-200 rounded-xl py-2.5 pr-10 pl-4 font-black" value={activeMatch.pitch || ''} onChange={e => setActiveMatch({...activeMatch, pitch: e.target.value})} />
                       </div>
                    </div>
                 </div>

                 {/* 2. الأحداث (Events) */}
                 <div className="space-y-6">
                    <div className="flex justify-between items-center border-r-4 border-emerald-600 pr-4">
                       <h3 className="text-xl font-black text-slate-900 uppercase">أحداث المباراة (أهداف وكروت)</h3>
                       <div className="flex gap-2">
                          <button onClick={() => addEvent('goal')} className="bg-emerald-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">⚽ هدف</button>
                          <button onClick={() => addEvent('assist')} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🎯 أسيست</button>
                          <button onClick={() => addEvent('yellow')} className="bg-yellow-400 text-slate-900 px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🟨 إنذار</button>
                          <button onClick={() => addEvent('red')} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🟥 طرد</button>
                       </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       {activeMatch.events.map((event, idx) => (
                         <div key={event.id} className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center gap-4">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white ${event.type === 'goal' ? 'bg-emerald-600' : event.type === 'yellow' ? 'bg-yellow-400 text-slate-900' : event.type === 'red' ? 'bg-red-600' : 'bg-blue-600'}`}>
                               {event.type === 'goal' ? '⚽' : event.type === 'assist' ? '🎯' : '🎴'}
                            </div>
                            <select 
                              className="flex-1 bg-white border-2 border-slate-200 rounded-xl p-2 font-bold text-xs" 
                              value={event.player} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                newEvents[idx].player = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            >
                               <option value="">-- اختر اللاعب --</option>
                               {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                 <option key={p.id} value={p.id}>{p.name}</option>
                               ))}
                            </select>
                            <input 
                              type="number" 
                              placeholder="د" 
                              className="w-16 bg-white border-2 border-slate-200 rounded-xl p-2 font-black text-center" 
                              value={event.minute} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                newEvents[idx].minute = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            />
                            <button onClick={() => removeEvent(event.id)} className="text-red-600 p-2 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* 3. التشكيلة الأساسية والبدلاء */}
                 <div className="space-y-8">
                    <div className="flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                       <Users className="text-[#001F3F]" />
                       <h3 className="text-xl font-black text-slate-900 uppercase">التشكيلة الفنية (Lineup)</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                       {/* الأساسيون */}
                       <div className="space-y-4">
                          <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                             <UserCheck size={16} className="text-orange-600"/> اللاعبون الأساسيون (11)
                          </label>
                          <div className="space-y-2">
                             {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="flex gap-3 items-center">
                                  <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-[10px]">#{idx+1}</span>
                                  <select className="flex-1 bg-slate-50 border-2 border-slate-200 p-3 rounded-xl font-bold text-xs" value={s.playerId} onChange={e => updateStarter(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                       <option key={p.id} value={p.id}>{p.name}</option>
                                     ))}
                                  </select>
                                  <input type="number" placeholder="دق" className="w-16 bg-white border-2 border-slate-200 p-2 rounded-xl text-center font-black" value={s.minutesPlayed || '90'} onChange={e => {
                                     const newLineup = { ...activeMatch.lineup };
                                     newLineup.starters[idx].minutesPlayed = e.target.value;
                                     setActiveMatch({...activeMatch, lineup: newLineup});
                                  }} />
                               </div>
                             ))}
                          </div>
                       </div>

                       {/* البدلاء */}
                       <div className="space-y-4">
                          <div className="flex justify-between items-center">
                             <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <ArrowRightLeft size={16} className="text-blue-600"/> قائمة البدلاء
                             </label>
                             <button onClick={addSub} className="text-[10px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-lg border border-blue-200">+ إضافة بديل</button>
                          </div>
                          <div className="space-y-2">
                             {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="flex gap-3 items-center animate-in slide-in-from-right-2">
                                  <button onClick={() => removeSub(idx)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                                  <select className="flex-1 bg-slate-50 border-2 border-slate-200 p-3 rounded-xl font-bold text-xs" value={s.playerId} onChange={e => updateSub(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                       <option key={p.id} value={p.id}>{p.name}</option>
                                     ))}
                                  </select>
                                  <input type="number" placeholder="دق" className="w-16 bg-white border-2 border-slate-200 p-2 rounded-xl text-center font-black" value={s.minutesPlayed || '0'} onChange={e => {
                                     const newLineup = { ...activeMatch.lineup };
                                     newLineup.subs[idx].minutesPlayed = e.target.value;
                                     setActiveMatch({...activeMatch, lineup: newLineup});
                                  }} />
                               </div>
                             ))}
                          </div>

                          {/* الكادر الفني */}
                          <div className="pt-8 space-y-4">
                             <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <Shield size={16} className="text-slate-900"/> الكادر المتواجد
                             </label>
                             <div className="p-4 bg-slate-100 rounded-2xl border-2 border-slate-200">
                                <div className="grid grid-cols-2 gap-2">
                                   {state.people.filter(p => p.category === activeMatch.category && p.role !== 'لاعب').map(p => (
                                     <div key={p.id} className="flex items-center gap-2 bg-white p-2 rounded-lg border border-slate-200">
                                        <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                                        <span className="text-[10px] font-black">{p.name} ({p.role})</span>
                                     </div>
                                   ))}
                                </div>
                             </div>
                          </div>
                       </div>
                    </div>
                 </div>

                 {/* 4. الملاحظات والتقرير الفني */}
                 <div className="space-y-4">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <FileText size={16} className="text-orange-600"/> التقرير الفني والملاحظات
                    </label>
                    <textarea 
                      className="w-full bg-slate-50 border-4 border-slate-200 rounded-[2rem] p-8 font-bold text-slate-700 h-48 outline-none focus:border-[#001F3F] transition-all"
                      placeholder="اكتب التقرير الفني المفصل للمباراة هنا..."
                      value={activeMatch.notes || ''}
                      onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                    ></textarea>
                 </div>

                 <div className="pt-8 flex gap-4 no-print">
                    <button 
                      onClick={() => {
                        setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? {...activeMatch, isCompleted: true} : m)}));
                        setActiveMatch(null);
                      }} 
                      className="flex-1 bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl hover:bg-emerald-700 transition-all border-b-8 border-emerald-900"
                    >
                      حفظ وتثبيت التقرير النهائي
                    </button>
                    <button 
                      onClick={() => window.print()} 
                      className="bg-[#001F3F] text-white px-10 py-6 rounded-[2rem] font-black text-xl shadow-2xl flex items-center gap-3 border-b-8 border-black"
                    >
                      <Printer size={24}/> طباعة التقرير
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Modal Add Match (Keep as is) */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-black/80 z-[400] flex items-center justify-center p-4 text-right" dir="rtl">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-4 border-slate-900 shadow-2xl overflow-hidden animate-in zoom-in duration-300">
              <div className="bg-[#001F3F] p-6 flex justify-between items-center text-white">
                 <h3 className="font-black text-lg uppercase tracking-widest">جدولة مباراة جديدة</h3>
                 <button onClick={() => setIsAddOpen(false)} className="hover:rotate-90 transition-all"><X size={24}/></button>
              </div>
              <form onSubmit={handleCreate} className="p-8 space-y-6">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">الفئة</label>
                       <select required disabled={!!restrictedCat} className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">نوع المباراة</label>
                       <select className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                          <option value="دوري">مباراة دوري</option>
                          <option value="كأس">مباراة كأس</option>
                          <option value="ودية">مباراة ودية</option>
                          <option value="بطولة ودية">بطولة ودية</option>
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase">اسم الفريق الخصم</label>
                    <input required type="text" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التاريخ</label>
                       <input required type="date" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التوقيت</label>
                       <input required type="time" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all border-b-4 border-black">تثبيت الجدولة</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useMemo } from 'react';
import { Trophy, Clock, Plus, X, Trash2, Edit, Save, CheckCircle, Unlock, Users, ArrowRightLeft, Activity, FileText, Loader2, MapPin, Sparkles, MessageSquare, Timer, UserCheck, Shield, Printer } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';
import { GoogleGenAI } from "@google/genai";

interface MatchPlannerProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  defaultSelectedId?: string | null;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [isAiGenerating, setIsAiGenerating] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<string | null>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const restrictedCat = currentUser?.restrictedCategory;

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  // Use Gemini API to generate a match summary
  const generateAiSummary = async (match: Match) => {
    setIsAiGenerating(match.id);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const eventsStr = match.events.map(e => `${e.minute}' [${e.type}] - ${e.player}`).join(', ');

      const prompt = `
        اكتب ملخصاً فنياً واحترافياً لمباراة كرة قدم لفريق الكرامة (فئة ${match.category}) ضد فريق ${match.opponent}.
        النتيجة: الكرامة ${match.ourScore} - ${match.opponentScore} ${match.opponent}.
        الأحداث: ${eventsStr || 'لم يتم تسجيل أحداث محددة'}.
        الملعب: ${match.pitch}.
        اجعل الأسلوب حماسياً ومناسباً للنشر على صفحة النادي الرسمية.
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });

      setAiSummary(result.text || "لم يتمكن الذكاء من صياغة الملخص.");
    } catch (error) {
      alert("فشل في توليد الملخص الذكي.");
    } finally {
      setIsAiGenerating(null);
    }
  };

  const deleteMatch = async (id: string, opponent: string) => {
    if (!isManager && !isCatAdmin) return;
    if (confirm(`هل أنت متأكد من حذف مباراة ${opponent} نهائياً؟`)) {
      setIsDeleting(id);
      try {
        const { error } = await supabase.from('matches').delete().eq('id', id);
        if (error) throw error;
        setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      } finally {
        setIsDeleting(null);
      }
    }
  };

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || state.categories[0],
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'خصم مجهول',
      pitch: formData.pitch || 'ملعب النادي',
      date: formData.date || '',
      time: formData.time || '',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({playerId: '', name: '', number: ''}), subs: [], staff: [], captain: '' },
      advancePayment: '0'
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    setIsAddOpen(false);
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);

    if (player && getSuspension) {
      const susp = getSuspension(player.id, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 تنبيه: اللاعب ${player.name} موقوف إدارياً لهذه المباراة ولا يمكن إدراجه في التشكيلة.`);
        return;
      }
    }

    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const addSub = () => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs = [...newLineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0' }];
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSub = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.subs[index] = { ...newLineup.subs[index], playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const removeSub = (index: number) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.splice(index, 1);
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-5 md:p-8 rounded-2xl border-2 border-slate-900 flex justify-between items-center shadow-md">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F]">إدارة المباريات</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase">Match Center</p>
        </div>
        {!currentUser?.role.includes('مشاهد') && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white p-3 md:px-6 md:py-3 rounded-xl font-black text-xs flex items-center gap-2">
            <Plus size={20}/> <span className="hidden md:inline">جدولة مباراة</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative shadow-sm transition-all hover:-translate-y-1 ${isDeleting === m.id ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date}</span>
             </div>
             <div className="text-center py-4">
                <p className="text-4xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-[#001F3F] mt-2">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-bold text-orange-600 mt-1 uppercase">{m.category}</p>
             </div>

             {m.isCompleted && (
               <button 
                onClick={() => generateAiSummary(m)} 
                disabled={isAiGenerating === m.id}
                className="mt-4 w-full bg-slate-50 border-2 border-dashed border-slate-300 py-3 rounded-xl flex items-center justify-center gap-2 text-[10px] font-black text-slate-500 hover:border-orange-600 hover:text-orange-600 transition-all"
               >
                 {isAiGenerating === m.id ? <Loader2 className="animate-spin" size={14}/> : <Sparkles size={14} className="text-orange-600" />}
                 تلخيص ذكي للمباراة
               </button>
             )}

             <div className="flex gap-2 mt-4 pt-4 border-t border-slate-50">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs uppercase">
                  {m.isCompleted ? 'التقرير الفني' : 'إدارة المباراة'}
                </button>
                {(isManager || (isCatAdmin && m.category === restrictedCat)) && (
                  <button onClick={() => deleteMatch(m.id, m.opponent)} className="p-3 bg-red-50 text-red-600 border-2 border-red-100 rounded-xl hover:bg-red-600 transition-all">
                    {isDeleting === m.id ? <Loader2 className="animate-spin" size={18}/> : <Trash2 size={18}/>}
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* AI Summary Modal */}
      {aiSummary && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[600] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in duration-300 text-right" dir="rtl">
            <div className="bg-orange-600 p-6 flex justify-between items-center text-white">
               <div className="flex items-center gap-3">
                 <Sparkles size={24} />
                 <h3 className="font-black text-lg">الملخص الفني الذكي</h3>
               </div>
               <button onClick={() => setAiSummary(null)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
            </div>
            <div className="p-8">
               <div className="bg-slate-50 p-6 rounded-2xl border-2 border-slate-100 font-bold text-sm leading-relaxed text-slate-700 whitespace-pre-wrap">
                 {aiSummary}
               </div>
               <div className="mt-6 flex gap-3">
                  <button onClick={() => { navigator.clipboard.writeText(aiSummary); alert('تم نسخ الملخص!'); }} className="flex-1 bg-[#001F3F] text-white py-4 rounded-xl font-black flex items-center justify-center gap-2">
                    <Save size={18}/> نسخ النص للنشر
                  </button>
                  <button onClick={() => setAiSummary(null)} className="flex-1 bg-slate-100 text-slate-500 py-4 rounded-xl font-black">إغلاق</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Match Management Modal - RESTORED FULL VERSION */}
      {activeMatch && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[400] overflow-y-auto p-2 md:p-8 text-right font-['Tajawal']" dir="rtl">
           <div className="max-w-5xl mx-auto bg-white border-4 border-slate-900 rounded-[3rem] shadow-2xl overflow-hidden">
              <div className="bg-[#001F3F] p-6 md:p-10 flex justify-between items-center text-white border-b-8 border-orange-600">
                 <div className="flex items-center gap-6">
                    <div className="bg-white p-3 rounded-2xl">
                       <Trophy className="text-[#001F3F]" size={40} />
                    </div>
                    <div>
                       <h2 className="text-xl md:text-3xl font-black uppercase">الكرامة × {activeMatch.opponent}</h2>
                       <p className="text-orange-400 text-xs font-black uppercase mt-1 tracking-widest">{activeMatch.category} | {activeMatch.matchType}</p>
                    </div>
                 </div>
                 <button onClick={() => setActiveMatch(null)} className="bg-white/10 p-3 rounded-full hover:bg-white/20 transition-all">
                    <X size={32} />
                 </button>
              </div>

              <div className="p-6 md:p-12 space-y-12">
                 {/* 1. النتيجة والوقت */}
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-8 bg-slate-50 p-8 rounded-[2.5rem] border-2 border-slate-200">
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">النتيجة النهائية</label>
                       <div className="flex items-center gap-4">
                          <input type="number" className="w-20 h-20 bg-white border-4 border-[#001F3F] rounded-2xl text-center text-4xl font-black text-[#001F3F]" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                          <span className="text-2xl font-black text-slate-400">:</span>
                          <input type="number" className="w-20 h-20 bg-white border-4 border-slate-400 rounded-2xl text-center text-4xl font-black text-slate-500" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                       </div>
                    </div>
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">الوقت المضاف</label>
                       <div className="flex gap-2">
                          <input type="text" placeholder="ش1" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime1 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                          <input type="text" placeholder="ش2" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime2 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                       </div>
                    </div>
                    <div className="flex flex-col gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">مكان المباراة</label>
                       <div className="relative">
                          <MapPin className="absolute right-3 top-3 text-orange-600" size={18} />
                          <input type="text" className="w-full bg-white border-2 border-slate-200 rounded-xl py-2.5 pr-10 pl-4 font-black" value={activeMatch.pitch || ''} onChange={e => setActiveMatch({...activeMatch, pitch: e.target.value})} />
                       </div>
                    </div>
                 </div>

                 {/* 2. الأحداث (Events) */}
                 <div className="space-y-6">
                    <div className="flex justify-between items-center border-r-4 border-emerald-600 pr-4">
                       <h3 className="text-xl font-black text-slate-900 uppercase">أحداث المباراة (أهداف وكروت)</h3>
                       <div className="flex gap-2">
                          <button onClick={() => addEvent('goal')} className="bg-emerald-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">⚽ هدف</button>
                          <button onClick={() => addEvent('assist')} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🎯 أسيست</button>
                          <button onClick={() => addEvent('yellow')} className="bg-yellow-400 text-slate-900 px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🟨 إنذار</button>
                          <button onClick={() => addEvent('red')} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🟥 طرد</button>
                       </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       {activeMatch.events.map((event, idx) => (
                         <div key={event.id} className="bg-slate-50 p-4 rounded-2xl border border-slate-200 flex items-center gap-4">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white ${event.type === 'goal' ? 'bg-emerald-600' : event.type === 'yellow' ? 'bg-yellow-400 text-slate-900' : event.type === 'red' ? 'bg-red-600' : 'bg-blue-600'}`}>
                               {event.type === 'goal' ? '⚽' : event.type === 'assist' ? '🎯' : '🎴'}
                            </div>
                            <select 
                              className="flex-1 bg-white border-2 border-slate-200 rounded-xl p-2 font-bold text-xs" 
                              value={event.player} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                newEvents[idx].player = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            >
                               <option value="">-- اختر اللاعب --</option>
                               {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                 <option key={p.id} value={p.id}>{p.name}</option>
                               ))}
                            </select>
                            <input 
                              type="number" 
                              placeholder="د" 
                              className="w-16 bg-white border-2 border-slate-200 rounded-xl p-2 font-black text-center" 
                              value={event.minute} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                newEvents[idx].minute = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            />
                            <button onClick={() => removeEvent(event.id)} className="text-red-600 p-2 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button>
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* 3. التشكيلة الأساسية والبدلاء */}
                 <div className="space-y-8">
                    <div className="flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                       <Users className="text-[#001F3F]" />
                       <h3 className="text-xl font-black text-slate-900 uppercase">التشكيلة الفنية (Lineup)</h3>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                       {/* الأساسيون */}
                       <div className="space-y-4">
                          <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                             <UserCheck size={16} className="text-orange-600"/> اللاعبون الأساسيون (11)
                          </label>
                          <div className="space-y-2">
                             {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="flex gap-3 items-center">
                                  <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-[10px]">#{idx+1}</span>
                                  <select className="flex-1 bg-slate-50 border-2 border-slate-200 p-3 rounded-xl font-bold text-xs" value={s.playerId} onChange={e => updateStarter(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                       <option key={p.id} value={p.id}>{p.name}</option>
                                     ))}
                                  </select>
                                  <input type="number" placeholder="دق" className="w-16 bg-white border-2 border-slate-200 p-2 rounded-xl text-center font-black" value={s.minutesPlayed || '90'} onChange={e => {
                                     const newLineup = { ...activeMatch.lineup };
                                     newLineup.starters[idx].minutesPlayed = e.target.value;
                                     setActiveMatch({...activeMatch, lineup: newLineup});
                                  }} />
                               </div>
                             ))}
                          </div>
                       </div>

                       {/* البدلاء */}
                       <div className="space-y-4">
                          <div className="flex justify-between items-center">
                             <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <ArrowRightLeft size={16} className="text-blue-600"/> قائمة البدلاء
                             </label>
                             <button onClick={addSub} className="text-[10px] font-black bg-blue-50 text-blue-600 px-3 py-1 rounded-lg border border-blue-200">+ إضافة بديل</button>
                          </div>
                          <div className="space-y-2">
                             {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="flex gap-3 items-center animate-in slide-in-from-right-2">
                                  <button onClick={() => removeSub(idx)} className="text-red-400 hover:text-red-600"><Trash2 size={14}/></button>
                                  <select className="flex-1 bg-slate-50 border-2 border-slate-200 p-3 rounded-xl font-bold text-xs" value={s.playerId} onChange={e => updateSub(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                       <option key={p.id} value={p.id}>{p.name}</option>
                                     ))}
                                  </select>
                                  <input type="number" placeholder="دق" className="w-16 bg-white border-2 border-slate-200 p-2 rounded-xl text-center font-black" value={s.minutesPlayed || '0'} onChange={e => {
                                     const newLineup = { ...activeMatch.lineup };
                                     newLineup.subs[idx].minutesPlayed = e.target.value;
                                     setActiveMatch({...activeMatch, lineup: newLineup});
                                  }} />
                               </div>
                             ))}
                          </div>

                          {/* الكادر الفني */}
                          <div className="pt-8 space-y-4">
                             <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <Shield size={16} className="text-slate-900"/> الكادر المتواجد
                             </label>
                             <div className="p-4 bg-slate-100 rounded-2xl border-2 border-slate-200">
                                <div className="grid grid-cols-2 gap-2">
                                   {state.people.filter(p => p.category === activeMatch.category && p.role !== 'لاعب').map(p => (
                                     <div key={p.id} className="flex items-center gap-2 bg-white p-2 rounded-lg border border-slate-200">
                                        <div className="w-2 h-2 bg-emerald-500 rounded-full"></div>
                                        <span className="text-[10px] font-black">{p.name} ({p.role})</span>
                                     </div>
                                   ))}
                                </div>
                             </div>
                          </div>
                       </div>
                    </div>
                 </div>

                 {/* 4. الملاحظات والتقرير الفني */}
                 <div className="space-y-4">
                    <label className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       <FileText size={16} className="text-orange-600"/> التقرير الفني والملاحظات
                    </label>
                    <textarea 
                      className="w-full bg-slate-50 border-4 border-slate-200 rounded-[2rem] p-8 font-bold text-slate-700 h-48 outline-none focus:border-[#001F3F] transition-all"
                      placeholder="اكتب التقرير الفني المفصل للمباراة هنا..."
                      value={activeMatch.notes || ''}
                      onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                    ></textarea>
                 </div>

                 <div className="pt-8 flex gap-4 no-print">
                    <button 
                      onClick={() => {
                        setState(p => ({ ...p, matches: p.matches.map(m => m.id === activeMatch.id ? {...activeMatch, isCompleted: true} : m)}));
                        setActiveMatch(null);
                      }} 
                      className="flex-1 bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl hover:bg-emerald-700 transition-all border-b-8 border-emerald-900"
                    >
                      حفظ وتثبيت التقرير النهائي
                    </button>
                    <button 
                      onClick={() => window.print()} 
                      className="bg-[#001F3F] text-white px-10 py-6 rounded-[2rem] font-black text-xl shadow-2xl flex items-center gap-3 border-b-8 border-black"
                    >
                      <Printer size={24}/> طباعة التقرير
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Modal Add Match (Keep as is) */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-black/80 z-[400] flex items-center justify-center p-4 text-right" dir="rtl">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-4 border-slate-900 shadow-2xl overflow-hidden animate-in zoom-in duration-300">
              <div className="bg-[#001F3F] p-6 flex justify-between items-center text-white">
                 <h3 className="font-black text-lg uppercase tracking-widest">جدولة مباراة جديدة</h3>
                 <button onClick={() => setIsAddOpen(false)} className="hover:rotate-90 transition-all"><X size={24}/></button>
              </div>
              <form onSubmit={handleCreate} className="p-8 space-y-6">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">الفئة</label>
                       <select required disabled={!!restrictedCat} className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">نوع المباراة</label>
                       <select className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                          <option value="دوري">مباراة دوري</option>
                          <option value="كأس">مباراة كأس</option>
                          <option value="ودية">مباراة ودية</option>
                          <option value="بطولة ودية">بطولة ودية</option>
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase">اسم الفريق الخصم</label>
                    <input required type="text" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التاريخ</label>
                       <input required type="date" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التوقيت</label>
                       <input required type="time" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all border-b-4 border-black">تثبيت الجدولة</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface TechnicalReport {
  id: string;
  targetId: string; // ID of Match or Staff Member
  type: 'match_evaluation' | 'staff_review' | 'player_radar';
  category: Category;
  rating: number; // 1-5 stars
  content: string;
  author: string;
  date: string;
  radarData?: {
    technical: number;
    physical: number;
    tactical: number;
    mental: number;
    discipline: number;
  };
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
  monthlyReports?: { [key: string]: string };
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
  isLocked?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury' | 'substitution';
  player: string; 
  minute: string;
  note?: string;
  replacedPlayerId?: string; // خاص بالتبديلات
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  stoppageTime1?: string; 
  stoppageTime2?: string; 
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface WarehouseItem {
  id: string;
  name: string;
  category: Category | 'المخزن العام';
  quantity: number;
  unit: 'قطعة' | 'طقم' | 'كرة' | 'حذاء' | 'أخرى';
  condition: 'جديد' | 'مستعمل' | 'تالف';
  lastUpdated: string;
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  warehouse: WarehouseItem[];
  technicalReports: TechnicalReport[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useMemo, useEffect } from 'react';
import { Trophy, Clock, Plus, X, Trash2, Edit, Save, CheckCircle, Unlock, Users, ArrowRightLeft, Activity, FileText, Loader2, MapPin, Sparkles, MessageSquare, Timer, UserCheck, Shield, Printer } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';
import { GoogleGenAI } from "@google/genai";

interface MatchPlannerProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  defaultSelectedId?: string | null;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [isAiGenerating, setIsAiGenerating] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<string | null>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const restrictedCat = currentUser?.restrictedCategory;

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  // دالة ذكية لحساب دقائق اللعب بناءً على التبديلات والوقت الإضافي
  const calculateFinalMinutes = (match: Match) => {
    const stoppage2 = parseInt(match.stoppageTime2 || '0') || 0;
    const totalMatchTime = 90 + stoppage2;

    const starters = match.lineup.starters.map(s => {
      // البحث إذا كان قد تم تبديله
      const subEvent = match.events.find(e => e.type === 'substitution' && e.replacedPlayerId === s.playerId);
      const minutes = subEvent ? (parseInt(subEvent.minute) || 0) : totalMatchTime;
      return { ...s, minutesPlayed: minutes.toString() };
    });

    const subs = match.lineup.subs.map(s => {
      // البحث متى دخل
      const subEvent = match.events.find(e => e.type === 'substitution' && e.player === s.playerId);
      if (subEvent) {
        const entryMinute = parseInt(subEvent.minute) || 0;
        // هل تم تبديله مرة أخرى؟ (نادر ولكن ممكن)
        const exitEvent = match.events.find(e => e.type === 'substitution' && e.replacedPlayerId === s.playerId && parseInt(e.minute) > entryMinute);
        const exitMinute = exitEvent ? parseInt(exitEvent.minute) : totalMatchTime;
        const minutes = exitMinute - entryMinute;
        return { ...s, minutesPlayed: Math.max(0, minutes).toString(), substitutionMinute: entryMinute.toString() };
      }
      return { ...s, minutesPlayed: '0', substitutionMinute: '' };
    });

    return { ...match, lineup: { ...match.lineup, starters, subs } };
  };

  const handleSaveFinalReport = async () => {
    if (!activeMatch) return;
    const finalMatch = calculateFinalMinutes(activeMatch);

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === finalMatch.id ? { ...finalMatch, isCompleted: true } : m)
    }));

    try {
      const { error } = await supabase.from('matches').upsert(finalMatch);
      if (error) throw error;
      setActiveMatch(null);
      alert("تم حفظ التقرير الفني وحساب دقائق اللاعبين بنجاح.");
    } catch (err: any) {
      alert("فشل الحفظ: " + err.message);
    }
  };

  const generateAiSummary = async (match: Match) => {
    setIsAiGenerating(match.id);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const eventsStr = match.events.map(e => `${e.minute}' [${e.type}] - ${e.player}`).join(', ');

      const prompt = `
        اكتب ملخصاً فنياً واحترافياً لمباراة كرة قدم لفريق الكرامة (فئة ${match.category}) ضد فريق ${match.opponent}.
        النتيجة: الكرامة ${match.ourScore} - ${match.opponentScore} ${match.opponent}.
        الأحداث: ${eventsStr || 'لم يتم تسجيل أحداث محددة'}.
        الملعب: ${match.pitch}.
        اجعل الأسلوب حماسياً ومناسباً للنشر على صفحة النادي الرسمية.
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });

      setAiSummary(result.text || "لم يتمكن الذكاء من صياغة الملخص.");
    } catch (error) {
      alert("فشل في توليد الملخص الذكي.");
    } finally {
      setIsAiGenerating(null);
    }
  };

  const deleteMatch = async (id: string, opponent: string) => {
    if (!isManager && !isCatAdmin) return;
    if (confirm(`هل أنت متأكد من حذف مباراة ${opponent} نهائياً؟`)) {
      setIsDeleting(id);
      try {
        const { error } = await supabase.from('matches').delete().eq('id', id);
        if (error) throw error;
        setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      } finally {
        setIsDeleting(null);
      }
    }
  };

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || state.categories[0],
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'خصم مجهول',
      pitch: formData.pitch || 'ملعب النادي',
      date: formData.date || '',
      time: formData.time || '',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({playerId: '', name: '', number: ''}), subs: [], staff: [], captain: '' },
      advancePayment: '0'
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    setIsAddOpen(false);
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);

    if (player && getSuspension) {
      const susp = getSuspension(player.id, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 تنبيه: اللاعب ${player.name} موقوف إدارياً لهذه المباراة ولا يمكن إدراجه في التشكيلة.`);
        return;
      }
    }

    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
      replacedPlayerId: ''
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const addSubToBench = () => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs = [...newLineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0' }];
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSubInBench = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.subs[index] = { ...newLineup.subs[index], playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const removeSubFromBench = (index: number) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.splice(index, 1);
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  return (
    <div className="space-y-6 pb-20 font-['Tajawal']">
      <div className="bg-white p-5 md:p-8 rounded-2xl border-2 border-slate-900 flex justify-between items-center shadow-md">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F]">إدارة المباريات والتقارير</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase">Match & Technical Center</p>
        </div>
        {!currentUser?.role.includes('مشاهد') && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white p-3 md:px-6 md:py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg border-b-4 border-black">
            <Plus size={20}/> <span className="hidden md:inline">جدولة مباراة جديدة</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative shadow-sm transition-all hover:-translate-y-1 ${isDeleting === m.id ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date}</span>
             </div>
             <div className="text-center py-4">
                <p className="text-4xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-[#001F3F] mt-2">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-bold text-orange-600 mt-1 uppercase">{m.category}</p>
             </div>

             {m.isCompleted && (
               <button 
                onClick={() => generateAiSummary(m)} 
                disabled={isAiGenerating === m.id}
                className="mt-4 w-full bg-slate-50 border-2 border-dashed border-slate-300 py-3 rounded-xl flex items-center justify-center gap-2 text-[10px] font-black text-slate-500 hover:border-orange-600 hover:text-orange-600 transition-all"
               >
                 {isAiGenerating === m.id ? <Loader2 className="animate-spin" size={14}/> : <Sparkles size={14} className="text-orange-600" />}
                 تلخيص ذكي للمباراة
               </button>
             )}

             <div className="flex gap-2 mt-4 pt-4 border-t border-slate-50">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs uppercase shadow-md active:scale-95 transition-all">
                  {m.isCompleted ? 'التقرير الفني' : 'إدارة المباراة'}
                </button>
                {(isManager || (isCatAdmin && m.category === restrictedCat)) && (
                  <button onClick={() => deleteMatch(m.id, m.opponent)} className="p-3 bg-red-50 text-red-600 border-2 border-red-100 rounded-xl hover:bg-red-600 hover:text-white transition-all">
                    {isDeleting === m.id ? <Loader2 className="animate-spin" size={18}/> : <Trash2 size={18}/>}
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* AI Summary Modal */}
      {aiSummary && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[600] flex items-center justify-center p-4 text-right">
          <div className="bg-white rounded-[3rem] w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in duration-300">
            <div className="bg-orange-600 p-6 flex justify-between items-center text-white">
               <div className="flex items-center gap-3">
                 <Sparkles size={24} />
                 <h3 className="font-black text-lg">الملخص الفني الذكي</h3>
               </div>
               <button onClick={() => setAiSummary(null)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
            </div>
            <div className="p-8">
               <div className="bg-slate-50 p-6 rounded-2xl border-2 border-slate-100 font-bold text-sm leading-relaxed text-slate-700 whitespace-pre-wrap">
                 {aiSummary}
               </div>
               <div className="mt-6 flex gap-3">
                  <button onClick={() => { navigator.clipboard.writeText(aiSummary); alert('تم نسخ الملخص!'); }} className="flex-1 bg-[#001F3F] text-white py-4 rounded-xl font-black flex items-center justify-center gap-2 shadow-lg">
                    <Save size={18}/> نسخ النص للنشر
                  </button>
                  <button onClick={() => setAiSummary(null)} className="flex-1 bg-slate-100 text-slate-500 py-4 rounded-xl font-black">إغلاق</button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Match Management Modal - THE NEW POWERFUL REPORT */}
      {activeMatch && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[400] overflow-y-auto p-2 md:p-8 text-right font-['Tajawal']" dir="rtl">
           <div className="max-w-5xl mx-auto bg-white border-4 border-slate-900 rounded-[3rem] shadow-2xl overflow-hidden mb-20">
              <div className="bg-[#001F3F] p-6 md:p-10 flex justify-between items-center text-white border-b-8 border-orange-600">
                 <div className="flex items-center gap-6">
                    <div className="bg-white p-3 rounded-2xl">
                       <Trophy className="text-[#001F3F]" size={40} />
                    </div>
                    <div>
                       <h2 className="text-xl md:text-3xl font-black uppercase">الكرامة × {activeMatch.opponent}</h2>
                       <p className="text-orange-400 text-xs font-black uppercase mt-1 tracking-widest">{activeMatch.category} | {activeMatch.matchType}</p>
                    </div>
                 </div>
                 <button onClick={() => setActiveMatch(null)} className="bg-white/10 p-3 rounded-full hover:bg-white/20 transition-all">
                    <X size={32} />
                 </button>
              </div>

              <div className="p-6 md:p-12 space-y-12">
                 {/* 1. النتيجة والوقت المضاف */}
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-8 bg-slate-50 p-8 rounded-[2.5rem] border-2 border-slate-200">
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">النتيجة النهائية</label>
                       <div className="flex items-center gap-4">
                          <input type="number" className="w-20 h-20 bg-white border-4 border-[#001F3F] rounded-2xl text-center text-4xl font-black text-[#001F3F]" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                          <span className="text-2xl font-black text-slate-400">:</span>
                          <input type="number" className="w-20 h-20 bg-white border-4 border-slate-400 rounded-2xl text-center text-4xl font-black text-slate-500" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                       </div>
                    </div>
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">الوقت المضاف (دقائق)</label>
                       <div className="flex gap-2">
                          <input type="text" placeholder="ش1" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime1 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                          <input type="text" placeholder="ش2" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime2 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                       </div>
                       <p className="text-[8px] font-bold text-slate-400">سيتم استخدامه في حساب دقائق التبديلات</p>
                    </div>
                    <div className="flex flex-col gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">ملعب اللقاء</label>
                       <div className="relative">
                          <MapPin className="absolute right-3 top-3 text-orange-600" size={18} />
                          <input type="text" className="w-full bg-white border-2 border-slate-200 rounded-xl py-2.5 pr-10 pl-4 font-black" value={activeMatch.pitch || ''} onChange={e => setActiveMatch({...activeMatch, pitch: e.target.value})} />
                       </div>
                    </div>
                 </div>

                 {/* 2. التشكيلة الأساسية (مرتبطة بالفئة) */}
                 <div className="space-y-6">
                    <div className="flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                       <UserCheck className="text-[#001F3F]" />
                       <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter">التشكيلة الأساسية (11 لاعب)</h3>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       {activeMatch.lineup.starters.map((s, idx) => (
                         <div key={idx} className="flex gap-3 items-center bg-slate-50 p-2 rounded-2xl border border-slate-100">
                            <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-[10px]">#{idx+1}</span>
                            <select 
                              className="flex-1 bg-white border-2 border-slate-200 p-3 rounded-xl font-bold text-xs" 
                              value={s.playerId} 
                              onChange={e => updateStarter(idx, e.target.value)}
                            >
                               <option value="">-- اختر اللاعب --</option>
                               {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                 <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                               ))}
                            </select>
                            <div className="w-12 h-10 bg-slate-200 rounded-lg flex items-center justify-center text-[10px] font-black" title="رقم القميص">
                               {s.number || '--'}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* 3. قائمة البدلاء والتبديلات */}
                 <div className="space-y-8 bg-slate-50 p-8 rounded-[3rem] border-2 border-slate-200">
                    <div className="flex justify-between items-center border-r-4 border-blue-600 pr-4">
                       <h3 className="text-xl font-black text-slate-900 uppercase">مقاعد البدلاء والتبديلات الذكية</h3>
                       <button onClick={addSubToBench} className="bg-blue-600 text-white px-6 py-2 rounded-xl text-[10px] font-black shadow-md hover:bg-blue-700 transition-all">+ إضافة للاعب بديل</button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                       {/* عرض البدلاء */}
                       <div className="space-y-3">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قائمة الاحتياط المتاحة</label>
                          <div className="space-y-2">
                             {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="flex gap-3 items-center">
                                  <button onClick={() => removeSubFromBench(idx)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                                  <select className="flex-1 bg-white border-2 border-slate-200 p-3 rounded-xl font-bold text-xs shadow-sm" value={s.playerId} onChange={e => updateSubInBench(idx, e.target.value)}>
                                     <option value="">-- اختر البديل --</option>
                                     {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                       <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                     ))}
                                  </select>
                               </div>
                             ))}
                          </div>
                       </div>

                       {/* تسجيل التبديلات */}
                       <div className="space-y-3">
                          <div className="flex justify-between">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">سجل التبديلات المنفذة</label>
                            <button onClick={() => addEvent('substitution')} className="text-[9px] font-black bg-white border border-slate-200 px-3 py-1 rounded-lg">إضافة تبديل جديد</button>
                          </div>
                          <div className="space-y-2">
                             {activeMatch.events.filter(e => e.type === 'substitution').map((ev, idx) => (
                               <div key={ev.id} className="bg-white p-3 rounded-xl border border-slate-200 flex gap-2 items-center text-[10px] font-black animate-in slide-in-from-right-2">
                                  <select 
                                    className="flex-1 bg-red-50 p-1.5 rounded-lg text-red-700"
                                    value={ev.replacedPlayerId}
                                    onChange={e => {
                                       const newEvents = [...activeMatch.events];
                                       const target = newEvents.find(x => x.id === ev.id);
                                       if(target) target.replacedPlayerId = e.target.value;
                                       setActiveMatch({...activeMatch, events: newEvents});
                                    }}
                                  >
                                    <option value="">خروج الأساسي..</option>
                                    {activeMatch.lineup.starters.filter(s => s.playerId).map(s => <option key={s.playerId} value={s.playerId}>{s.name}</option>)}
                                  </select>
                                  <ArrowRightLeft size={14} className="text-blue-600" />
                                  <select 
                                    className="flex-1 bg-emerald-50 p-1.5 rounded-lg text-emerald-700"
                                    value={ev.player}
                                    onChange={e => {
                                       const newEvents = [...activeMatch.events];
                                       const target = newEvents.find(x => x.id === ev.id);
                                       if(target) target.player = e.target.value;
                                       setActiveMatch({...activeMatch, events: newEvents});
                                    }}
                                  >
                                    <option value="">دخول البديل..</option>
                                    {activeMatch.lineup.subs.filter(s => s.playerId).map(s => <option key={s.playerId} value={s.playerId}>{s.name}</option>)}
                                  </select>
                                  <input type="number" placeholder="د" className="w-12 bg-slate-100 p-1.5 rounded-lg text-center" value={ev.minute} onChange={e => {
                                      const newEvents = [...activeMatch.events];
                                      const target = newEvents.find(x => x.id === ev.id);
                                      if(target) target.minute = e.target.value;
                                      setActiveMatch({...activeMatch, events: newEvents});
                                  }} />
                                  <button onClick={() => removeEvent(ev.id)}><X size={14} className="text-red-400"/></button>
                               </div>
                             ))}
                          </div>
                       </div>
                    </div>
                 </div>

                 {/* 4. الأهداف، الأسيست، والبطاقات */}
                 <div className="space-y-6">
                    <div className="flex justify-between items-center border-r-4 border-emerald-600 pr-4">
                       <h3 className="text-xl font-black text-slate-900 uppercase">أحداث المباراة (الأهداف والبطاقات)</h3>
                       <div className="flex gap-2">
                          <button onClick={() => addEvent('goal')} className="bg-emerald-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md hover:scale-105 transition-all">⚽ هدف</button>
                          <button onClick={() => addEvent('assist')} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md hover:scale-105 transition-all">🎯 أسيست</button>
                          <button onClick={() => addEvent('yellow')} className="bg-yellow-400 text-slate-900 px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md hover:scale-105 transition-all">🟨 إنذار</button>
                          <button onClick={() => addEvent('red')} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md hover:scale-105 transition-all">🟥 طرد</button>
                       </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                       {activeMatch.events.filter(e => e.type !== 'substitution').map((event) => (
                         <div key={event.id} className="bg-white p-4 rounded-2xl border-2 border-slate-100 flex items-center gap-4 shadow-sm group">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white text-lg ${
                              event.type === 'goal' ? 'bg-emerald-600' : 
                              event.type === 'yellow' ? 'bg-yellow-400 text-slate-900' : 
                              event.type === 'red' ? 'bg-red-600' : 'bg-blue-600'
                            }`}>
                               {event.type === 'goal' ? '⚽' : event.type === 'assist' ? '🎯' : '🎴'}
                            </div>
                            <select 
                              className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-2 font-bold text-xs outline-none focus:border-orange-600" 
                              value={event.player} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                const target = newEvents.find(x => x.id === event.id);
                                if(target) target.player = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            >
                               <option value="">اختر اللاعب..</option>
                               {/* اختيار من كل المسجلين في التشكيلة والبدلاء */}
                               {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(p => p.playerId).map(p => (
                                 <option key={p.playerId} value={p.playerId}>{p.name}</option>
                               ))}
                            </select>
                            <input 
                              type="number" 
                              placeholder="د" 
                              className="w-16 bg-slate-50 border border-slate-200 rounded-xl p-2 font-black text-center" 
                              value={event.minute} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                const target = newEvents.find(x => x.id === event.id);
                                if(target) target.minute = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            />
                            <button onClick={() => removeEvent(event.id)} className="text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* 5. تقرير المباراة الفني */}
                 <div className="space-y-4">
                    <label className="text-sm font-black text-[#001F3F] border-r-4 border-orange-600 pr-3 uppercase">تقرير المباراة الفني والملاحظات العامة</label>
                    <textarea 
                      className="w-full bg-slate-50 border-4 border-slate-200 rounded-[2.5rem] p-8 font-bold text-slate-700 h-64 outline-none focus:border-[#001F3F] transition-all shadow-inner"
                      placeholder="صف أداء الفريق، التغييرات التكتيكية، وملاحظاتك الفنية الشاملة..."
                      value={activeMatch.notes || ''}
                      onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                    ></textarea>
                 </div>

                 {/* أزرار الحفظ والطباعة */}
                 <div className="pt-8 flex gap-4 no-print border-t-2 border-slate-100">
                    <button 
                      onClick={handleSaveFinalReport}
                      className="flex-1 bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl hover:bg-emerald-700 transition-all border-b-8 border-emerald-900 active:translate-y-2 active:border-b-0"
                    >
                      <Save size={28} className="inline-block mr-3" /> حفظ واعتماد التقرير الفني النهائي
                    </button>
                    <button 
                      onClick={() => window.print()} 
                      className="bg-[#001F3F] text-white px-10 py-6 rounded-[2rem] font-black text-xl shadow-2xl flex items-center gap-3 border-b-8 border-black hover:bg-black transition-all"
                    >
                      <Printer size={28}/> طباعة التقرير الشامل
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Modal Add Match (Simplified form for scheduling) */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-black/80 z-[400] flex items-center justify-center p-4 text-right">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-4 border-slate-900 shadow-2xl overflow-hidden animate-in zoom-in duration-300">
              <div className="bg-[#001F3F] p-6 flex justify-between items-center text-white">
                 <h3 className="font-black text-lg uppercase tracking-widest">جدولة مباراة جديدة</h3>
                 <button onClick={() => setIsAddOpen(false)} className="hover:rotate-90 transition-all"><X size={24}/></button>
              </div>
              <form onSubmit={handleCreate} className="p-8 space-y-6">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">الفئة</label>
                       <select required disabled={!!restrictedCat} className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">نوع المباراة</label>
                       <select className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                          <option value="دوري">دوري</option>
                          <option value="كأس">كأس</option>
                          <option value="ودية">ودية</option>
                          <option value="بطولة ودية">بطولة ودية</option>
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase">اسم الفريق الخصم</label>
                    <input required type="text" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التاريخ</label>
                       <input required type="date" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التوقيت</label>
                       <input required type="time" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all border-b-4 border-black">تثبيت الجدولة المركزية</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface TechnicalReport {
  id: string;
  targetId: string; // ID of Match or Staff Member
  type: 'match_evaluation' | 'staff_review' | 'player_radar';
  category: Category;
  rating: number; // 1-5 stars
  content: string;
  author: string;
  date: string;
  radarData?: {
    technical: number;
    physical: number;
    tactical: number;
    mental: number;
    discipline: number;
  };
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
  monthlyReports?: { [key: string]: string };
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
  isLocked?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury' | 'substitution';
  player: string; 
  minute: string;
  note?: string;
  replacedPlayerId?: string; // خاص بالتبديلات لربط الخارج بالداخل
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  stoppageTime1?: string; 
  stoppageTime2?: string; 
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface WarehouseItem {
  id: string;
  name: string;
  category: Category | 'المخزن العام';
  quantity: number;
  unit: 'قطعة' | 'طقم' | 'كرة' | 'حذاء' | 'أخرى';
  condition: 'جديد' | 'مستعمل' | 'تالف';
  lastUpdated: string;
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  warehouse: WarehouseItem[];
  technicalReports: TechnicalReport[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useMemo, useEffect } from 'react';
import { Trophy, Clock, Plus, X, Trash2, Edit, Save, CheckCircle, Unlock, Users, ArrowRightLeft, Activity, FileText, Loader2, MapPin, Sparkles, MessageSquare, Timer, UserCheck, Shield, Printer } from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';
import { GoogleGenAI } from "@google/genai";

interface MatchPlannerProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  defaultSelectedId?: string | null;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const [isAiGenerating, setIsAiGenerating] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<string | null>(null);

  const currentUser = state.currentUser;
  const isManager = currentUser?.role === 'مدير';
  const isCatAdmin = currentUser?.role === 'إداري فئة';
  const restrictedCat = currentUser?.restrictedCategory;

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  // دالة ذكية لحساب دقائق اللعب بناءً على التبديلات والوقت الإضافي
  const calculateFinalMinutes = (match: Match) => {
    const stoppage2 = parseInt(match.stoppageTime2 || '0') || 0;
    const totalMatchTime = 90 + stoppage2;

    const starters = match.lineup.starters.map(s => {
      // البحث إذا كان قد تم تبديله
      const subEvent = match.events.find(e => e.type === 'substitution' && e.replacedPlayerId === s.playerId);
      const minutes = subEvent ? (parseInt(subEvent.minute) || 0) : totalMatchTime;
      return { ...s, minutesPlayed: minutes.toString() };
    });

    const subs = match.lineup.subs.map(s => {
      // البحث متى دخل
      const subEvent = match.events.find(e => e.type === 'substitution' && e.player === s.playerId);
      if (subEvent) {
        const entryMinute = parseInt(subEvent.minute) || 0;
        // هل تم تبديله مرة أخرى؟ (نادر ولكن ممكن)
        const exitEvent = match.events.find(e => e.type === 'substitution' && e.replacedPlayerId === s.playerId && parseInt(e.minute) > entryMinute);
        const exitMinute = exitEvent ? parseInt(exitEvent.minute) : totalMatchTime;
        const minutes = exitMinute - entryMinute;
        return { ...s, minutesPlayed: Math.max(0, minutes).toString(), substitutionMinute: entryMinute.toString() };
      }
      return { ...s, minutesPlayed: '0', substitutionMinute: '' };
    });

    return { ...match, lineup: { ...match.lineup, starters, subs } };
  };

  const handleSaveFinalReport = async () => {
    if (!activeMatch) return;
    const finalMatch = calculateFinalMinutes(activeMatch);

    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === finalMatch.id ? { ...finalMatch, isCompleted: true } : m)
    }));

    try {
      const { error } = await supabase.from('matches').upsert(finalMatch);
      if (error) throw error;
      setActiveMatch(null);
      alert("تم حفظ التقرير الفني واعتماده بنجاح.");
    } catch (err: any) {
      alert("فشل الحفظ: " + err.message);
    }
  };

  const generateAiSummary = async (match: Match) => {
    setIsAiGenerating(match.id);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const eventsStr = match.events.map(e => `${e.minute}' [${e.type}] - ${e.player}`).join(', ');

      const prompt = `
        اكتب ملخصاً فنياً واحترافياً لمباراة كرة قدم لفريق الكرامة (فئة ${match.category}) ضد فريق ${match.opponent}.
        النتيجة: الكرامة ${match.ourScore} - ${match.opponentScore} ${match.opponent}.
        الأحداث: ${eventsStr || 'لم يتم تسجيل أحداث محددة'}.
        الملعب: ${match.pitch}.
        اجعل الأسلوب حماسياً ومناسباً للنشر على صفحة النادي الرسمية.
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });

      setAiSummary(result.text || "لم يتمكن الذكاء من صياغة الملخص.");
    } catch (error) {
      alert("فشل في توليد الملخص الذكي.");
    } finally {
      setIsAiGenerating(null);
    }
  };

  const deleteMatch = async (id: string, opponent: string) => {
    if (!isManager && !isCatAdmin) return;
    if (confirm(`هل أنت متأكد من حذف مباراة ${opponent} نهائياً؟`)) {
      setIsDeleting(id);
      try {
        const { error } = await supabase.from('matches').delete().eq('id', id);
        if (error) throw error;
        setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      } catch (err: any) {
        alert("فشل الحذف من السحابة: " + err.message);
      } finally {
        setIsDeleting(null);
      }
    }
  };

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || state.categories[0],
    date: new Date().toISOString().split('T')[0],
    time: '16:00'
  });

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: formData.matchType as MatchType,
      opponent: formData.opponent || 'خصم مجهول',
      pitch: formData.pitch || 'ملعب النادي',
      date: formData.date || '',
      time: formData.time || '',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      events: [],
      lineup: { starters: Array(11).fill({playerId: '', name: '', number: ''}), subs: [], staff: [], captain: '' },
      advancePayment: '0'
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    setIsAddOpen(false);
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);

    if (player && getSuspension) {
      const susp = getSuspension(player.id, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 تنبيه: اللاعب ${player.name} موقوف إدارياً لهذه المباراة ولا يمكن إدراجه في التشكيلة.`);
        return;
      }
    }

    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = {
      id: generateUUID(),
      type,
      player: '',
      minute: '',
      replacedPlayerId: ''
    };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const removeEvent = (id: string) => {
    if (!activeMatch) return;
    setActiveMatch({ ...activeMatch, events: activeMatch.events.filter(e => e.id !== id) });
  };

  const addSubToBench = () => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs = [...newLineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0' }];
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSubInBench = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (player) {
      newLineup.subs[index] = { ...newLineup.subs[index], playerId: player.id, name: player.name, number: player.number?.toString() || '0' };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const removeSubFromBench = (index: number) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.splice(index, 1);
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  return (
    <div className="space-y-6 pb-20 font-['Tajawal']">
      <div className="bg-white p-5 md:p-8 rounded-2xl border-2 border-slate-900 flex justify-between items-center shadow-md">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F]">سجل المباريات والتقارير</h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase">Match Administration & Technical Log</p>
        </div>
        {!currentUser?.role.includes('مشاهد') && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white p-3 md:px-6 md:py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg border-b-4 border-black">
            <Plus size={20}/> <span className="hidden md:inline">إضافة مباراة جديدة</span>
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative shadow-sm transition-all hover:-translate-y-1 ${isDeleting === m.id ? 'opacity-50 pointer-events-none' : ''}`}>
             <div className="flex justify-between items-center mb-4">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400">{m.date}</span>
             </div>
             <div className="text-center py-4">
                <p className="text-4xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-[#001F3F] mt-2">الكرامة × {m.opponent}</p>
                <p className="text-[10px] font-bold text-orange-600 mt-1 uppercase">{m.category}</p>
             </div>

             {m.isCompleted && (
               <button 
                onClick={() => generateAiSummary(m)} 
                disabled={isAiGenerating === m.id}
                className="mt-4 w-full bg-slate-50 border-2 border-dashed border-slate-300 py-3 rounded-xl flex items-center justify-center gap-2 text-[10px] font-black text-slate-500 hover:border-orange-600 hover:text-orange-600 transition-all"
               >
                 {isAiGenerating === m.id ? <Loader2 className="animate-spin" size={14}/> : <Sparkles size={14} className="text-orange-600" />}
                 ملخص فني بالذكاء الاصطناعي
               </button>
             )}

             <div className="flex gap-2 mt-4 pt-4 border-t border-slate-50">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3 rounded-xl font-black text-xs uppercase shadow-md active:scale-95 transition-all">
                  {m.isCompleted ? 'عرض التقرير' : 'إدارة التقرير الفني'}
                </button>
                {(isManager || (isCatAdmin && m.category === restrictedCat)) && (
                  <button onClick={() => deleteMatch(m.id, m.opponent)} className="p-3 bg-red-50 text-red-600 border-2 border-red-100 rounded-xl hover:bg-red-600 hover:text-white transition-all">
                    {isDeleting === m.id ? <Loader2 className="animate-spin" size={18}/> : <Trash2 size={18}/>}
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* التقرير الفني الشامل للمباراة */}
      {activeMatch && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-md z-[400] overflow-y-auto p-2 md:p-8 text-right font-['Tajawal']" dir="rtl">
           <div className="max-w-5xl mx-auto bg-white border-4 border-slate-900 rounded-[3rem] shadow-2xl overflow-hidden mb-20 animate-in slide-in-from-bottom-10">
              <div className="bg-[#001F3F] p-6 md:p-10 flex justify-between items-center text-white border-b-8 border-orange-600">
                 <div className="flex items-center gap-6">
                    <div className="bg-white p-3 rounded-2xl">
                       <Trophy className="text-[#001F3F]" size={40} />
                    </div>
                    <div>
                       <h2 className="text-xl md:text-3xl font-black uppercase tracking-tight">الكرامة × {activeMatch.opponent}</h2>
                       <p className="text-orange-400 text-xs font-black uppercase mt-1 tracking-widest">{activeMatch.category} | {activeMatch.matchType}</p>
                    </div>
                 </div>
                 <button onClick={() => setActiveMatch(null)} className="bg-white/10 p-3 rounded-full hover:bg-white/20 transition-all">
                    <X size={32} />
                 </button>
              </div>

              <div className="p-6 md:p-12 space-y-12">
                 {/* 1. لوحة النتائج والوقت */}
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-8 bg-slate-50 p-8 rounded-[2.5rem] border-2 border-slate-200">
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">النتيجة النهائية</label>
                       <div className="flex items-center gap-4">
                          <input type="number" className="w-20 h-20 bg-white border-4 border-[#001F3F] rounded-2xl text-center text-4xl font-black text-[#001F3F]" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                          <span className="text-2xl font-black text-slate-400">:</span>
                          <input type="number" className="w-20 h-20 bg-white border-4 border-slate-400 rounded-2xl text-center text-4xl font-black text-slate-500" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                       </div>
                    </div>
                    <div className="flex flex-col items-center gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">الوقت المضاف (ش1 / ش2)</label>
                       <div className="flex gap-2">
                          <input type="text" placeholder="ش1" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime1 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                          <input type="text" placeholder="ش2" className="w-16 h-12 bg-white border-2 border-slate-200 rounded-xl text-center font-black" value={activeMatch.stoppageTime2 || ''} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                       </div>
                       <p className="text-[8px] font-bold text-slate-400">ضروري لحساب دقائق اللعب بدقة</p>
                    </div>
                    <div className="flex flex-col gap-3">
                       <label className="text-[10px] font-black text-slate-500 uppercase">ملعب اللقاء</label>
                       <div className="relative">
                          <MapPin className="absolute right-3 top-3 text-orange-600" size={18} />
                          <input type="text" className="w-full bg-white border-2 border-slate-200 rounded-xl py-2.5 pr-10 pl-4 font-black" value={activeMatch.pitch || ''} onChange={e => setActiveMatch({...activeMatch, pitch: e.target.value})} />
                       </div>
                    </div>
                 </div>

                 {/* 2. التشكيلة الأساسية (مرتبطة بالفئة) */}
                 <div className="space-y-6">
                    <div className="flex items-center gap-3 border-r-4 border-orange-600 pr-4">
                       <UserCheck className="text-[#001F3F]" />
                       <h3 className="text-xl font-black text-slate-900 uppercase">التشكيلة الأساسية</h3>
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       {activeMatch.lineup.starters.map((s, idx) => (
                         <div key={idx} className="flex gap-3 items-center bg-slate-50 p-2 rounded-2xl border border-slate-100">
                            <span className="w-8 h-8 bg-slate-900 text-white rounded-lg flex items-center justify-center font-black text-[10px]">#{idx+1}</span>
                            <select 
                              className="flex-1 bg-white border-2 border-slate-200 p-3 rounded-xl font-bold text-xs" 
                              value={s.playerId} 
                              onChange={e => updateStarter(idx, e.target.value)}
                            >
                               <option value="">-- اختر اللاعب --</option>
                               {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                 <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                               ))}
                            </select>
                            <div className="w-12 h-10 bg-slate-200 rounded-lg flex items-center justify-center text-[10px] font-black" title="رقم القميص">
                               {s.number || '--'}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* 3. مقاعد البدلاء والتبديلات */}
                 <div className="space-y-8 bg-slate-50 p-8 rounded-[3rem] border-2 border-slate-200">
                    <div className="flex justify-between items-center border-r-4 border-blue-600 pr-4">
                       <h3 className="text-xl font-black text-slate-900 uppercase">مقاعد البدلاء والتبديلات</h3>
                       <button onClick={addSubToBench} className="bg-blue-600 text-white px-6 py-2 rounded-xl text-[10px] font-black shadow-md">+ إضافة لاعب للقائمة الاحتياطية</button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
                       {/* قائمة البدلاء */}
                       <div className="space-y-3">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">قائمة الاحتياط</label>
                          <div className="space-y-2">
                             {activeMatch.lineup.subs.map((s, idx) => (
                               <div key={idx} className="flex gap-3 items-center">
                                  <button onClick={() => removeSubFromBench(idx)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                                  <select className="flex-1 bg-white border-2 border-slate-200 p-3 rounded-xl font-bold text-xs" value={s.playerId} onChange={e => updateSubInBench(idx, e.target.value)}>
                                     <option value="">-- اختر اللاعب --</option>
                                     {state.people.filter(p => p.category === activeMatch.category && p.role === 'لاعب').map(p => (
                                       <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                     ))}
                                  </select>
                               </div>
                             ))}
                          </div>
                       </div>

                       {/* سجل التبديلات */}
                       <div className="space-y-3">
                          <div className="flex justify-between">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">سجل التبديلات</label>
                            <button onClick={() => addEvent('substitution')} className="text-[9px] font-black bg-white border border-slate-200 px-3 py-1 rounded-lg">إضافة تبديل</button>
                          </div>
                          <div className="space-y-2">
                             {activeMatch.events.filter(e => e.type === 'substitution').map((ev, idx) => (
                               <div key={ev.id} className="bg-white p-3 rounded-xl border border-slate-200 flex gap-2 items-center text-[10px] font-black">
                                  <select 
                                    className="flex-1 bg-red-50 p-1.5 rounded-lg text-red-700"
                                    value={ev.replacedPlayerId}
                                    onChange={e => {
                                       const newEvents = [...activeMatch.events];
                                       const target = newEvents.find(x => x.id === ev.id);
                                       if(target) target.replacedPlayerId = e.target.value;
                                       setActiveMatch({...activeMatch, events: newEvents});
                                    }}
                                  >
                                    <option value="">خروج..</option>
                                    {activeMatch.lineup.starters.filter(s => s.playerId).map(s => <option key={s.playerId} value={s.playerId}>{s.name}</option>)}
                                  </select>
                                  <ArrowRightLeft size={14} className="text-blue-600" />
                                  <select 
                                    className="flex-1 bg-emerald-50 p-1.5 rounded-lg text-emerald-700"
                                    value={ev.player}
                                    onChange={e => {
                                       const newEvents = [...activeMatch.events];
                                       const target = newEvents.find(x => x.id === ev.id);
                                       if(target) target.player = e.target.value;
                                       setActiveMatch({...activeMatch, events: newEvents});
                                    }}
                                  >
                                    <option value="">دخول..</option>
                                    {activeMatch.lineup.subs.filter(s => s.playerId).map(s => <option key={s.playerId} value={s.playerId}>{s.name}</option>)}
                                  </select>
                                  <input type="number" placeholder="د" className="w-12 bg-slate-100 p-1.5 rounded-lg text-center" value={ev.minute} onChange={e => {
                                      const newEvents = [...activeMatch.events];
                                      const target = newEvents.find(x => x.id === ev.id);
                                      if(target) target.minute = e.target.value;
                                      setActiveMatch({...activeMatch, events: newEvents});
                                  }} />
                                  <button onClick={() => removeEvent(ev.id)}><X size={14} className="text-red-400"/></button>
                               </div>
                             ))}
                          </div>
                       </div>
                    </div>
                 </div>

                 {/* 4. الأهداف والبطاقات */}
                 <div className="space-y-6">
                    <div className="flex justify-between items-center border-r-4 border-emerald-600 pr-4">
                       <h3 className="text-xl font-black text-slate-900 uppercase">الأهداف والبطاقات والأسيست</h3>
                       <div className="flex gap-2">
                          <button onClick={() => addEvent('goal')} className="bg-emerald-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">⚽ هدف</button>
                          <button onClick={() => addEvent('assist')} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🎯 أسيست</button>
                          <button onClick={() => addEvent('yellow')} className="bg-yellow-400 text-slate-900 px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🟨 إنذار</button>
                          <button onClick={() => addEvent('red')} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-md">🟥 طرد</button>
                       </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                       {activeMatch.events.filter(e => e.type !== 'substitution').map((event) => (
                         <div key={event.id} className="bg-white p-4 rounded-2xl border-2 border-slate-100 flex items-center gap-4 shadow-sm group">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white text-lg ${
                              event.type === 'goal' ? 'bg-emerald-600' : 
                              event.type === 'yellow' ? 'bg-yellow-400 text-slate-900' : 
                              event.type === 'red' ? 'bg-red-600' : 'bg-blue-600'
                            }`}>
                               {event.type === 'goal' ? '⚽' : event.type === 'assist' ? '🎯' : '🎴'}
                            </div>
                            <select 
                              className="flex-1 bg-slate-50 border border-slate-200 rounded-xl p-2 font-bold text-xs" 
                              value={event.player} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                const target = newEvents.find(x => x.id === event.id);
                                if(target) target.player = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            >
                               <option value="">اختر..</option>
                               {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(p => p.playerId).map(p => (
                                 <option key={p.playerId} value={p.playerId}>{p.name}</option>
                               ))}
                            </select>
                            <input 
                              type="number" 
                              placeholder="د" 
                              className="w-16 bg-slate-50 border border-slate-200 rounded-xl p-2 font-black text-center" 
                              value={event.minute} 
                              onChange={e => {
                                const newEvents = [...activeMatch.events];
                                const target = newEvents.find(x => x.id === event.id);
                                if(target) target.minute = e.target.value;
                                setActiveMatch({...activeMatch, events: newEvents});
                              }}
                            />
                            <button onClick={() => removeEvent(event.id)} className="text-red-400 opacity-0 group-hover:opacity-100"><Trash2 size={16}/></button>
                         </div>
                       ))}
                    </div>
                 </div>

                 {/* 5. تقرير المباراة */}
                 <div className="space-y-4">
                    <label className="text-sm font-black text-[#001F3F] border-r-4 border-orange-600 pr-3 uppercase">تقرير المباراة الفني (التحليل)</label>
                    <textarea 
                      className="w-full bg-slate-50 border-4 border-slate-200 rounded-[2.5rem] p-8 font-bold text-slate-700 h-64 outline-none focus:border-[#001F3F] transition-all"
                      placeholder="اكتب التقرير الفني للمباراة، الملاحظات على الأداء، والتوصيات..."
                      value={activeMatch.notes || ''}
                      onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                    ></textarea>
                 </div>

                 <div className="pt-8 flex gap-4 no-print border-t-2 border-slate-100">
                    <button 
                      onClick={handleSaveFinalReport}
                      className="flex-1 bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl hover:bg-emerald-700 transition-all border-b-8 border-emerald-900"
                    >
                      <Save size={28} className="inline-block mr-3" /> حفظ واعتماد التقرير الفني النهائي
                    </button>
                    <button 
                      onClick={() => window.print()} 
                      className="bg-[#001F3F] text-white px-10 py-6 rounded-[2rem] font-black text-xl shadow-2xl flex items-center gap-3 border-b-8 border-black hover:bg-black transition-all"
                    >
                      <Printer size={28}/> طباعة التقرير الشامل
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Modal Add Match (Simplified form for scheduling) */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-black/80 z-[400] flex items-center justify-center p-4 text-right">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-4 border-slate-900 shadow-2xl overflow-hidden animate-in zoom-in duration-300">
              <div className="bg-[#001F3F] p-6 flex justify-between items-center text-white">
                 <h3 className="font-black text-lg uppercase tracking-widest">إضافة لقاء جديد</h3>
                 <button onClick={() => setIsAddOpen(false)} className="hover:rotate-90 transition-all"><X size={24}/></button>
              </div>
              <form onSubmit={handleCreate} className="p-8 space-y-6">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">الفئة</label>
                       <select required disabled={!!restrictedCat} className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">نوع المباراة</label>
                       <select className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black text-sm" value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                          <option value="دوري">دوري</option>
                          <option value="كأس">كأس</option>
                          <option value="ودية">ودية</option>
                          <option value="بطولة ودية">بطولة ودية</option>
                       </select>
                    </div>
                 </div>
                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase">اسم الفريق الخصم</label>
                    <input required type="text" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التاريخ</label>
                       <input required type="date" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 uppercase">التوقيت</label>
                       <input required type="time" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl p-3 font-black" value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black shadow-xl hover:bg-black transition-all border-b-4 border-black">تأكيد الإضافة</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock,
  Gamepad2, UserCheck, TimerOff, ArrowRightLeft, Medal
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
    setFormData({ ...formData, opponent: '' });
  };

  const deleteMatch = async (id: string) => {
    if (!isManager) return;
    if (confirm('🚨 هل أنت متأكد من حذف هذه المباراة نهائياً؟')) {
      const { error } = await supabase.from('matches').delete().eq('id', id);
      if (error) {
        alert('حدث خطأ أثناء الحذف: ' + error.message);
        return;
      }
      setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      addLog?.('حذف مباراة', 'تمت إزالة سجل المباراة بالكامل من النظام السحابي', 'error');
    }
  };

  const addSubSlot = () => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.push({ playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' });
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const removeSubSlot = (index: number) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.splice(index, 1);
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = { id: generateUUID(), type, player: '', minute: '', note: '' };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const updateEvent = (eventId: string, field: keyof MatchEvent, value: string) => {
    if (!activeMatch) return;
    const newEvents = activeMatch.events.map(e => e.id === eventId ? { ...e, [field]: value } : e);
    setActiveMatch({ ...activeMatch, events: newEvents });
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (!player) {
      newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    } else {
      const susp = getSuspension(playerId, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 اللاعب ${player.name} موقوف!`);
        return;
      }
      const stopTime = (parseInt(activeMatch.stoppageTime1 || '0')) + (parseInt(activeMatch.stoppageTime2 || '0'));
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '', minutesPlayed: (90 + stopTime).toString() };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSub = (index: number, field: string, value: string) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    const sub = newLineup.subs[index];
    if (field === 'playerId') {
      const player = state.people.find(p => p.id === value);
      if (player) {
        sub.playerId = player.id;
        sub.name = player.name;
        sub.number = player.number?.toString() || '';
      } else {
        sub.playerId = ''; sub.name = ''; sub.number = '';
      }
    } else if (field === 'substitutionMinute' || field === 'replacedPlayerId') {
      // @ts-ignore
      sub[field] = value;
      if (sub.substitutionMinute && sub.replacedPlayerId) {
        const fullTime = 90 + (parseInt(activeMatch.stoppageTime1 || '0')) + (parseInt(activeMatch.stoppageTime2 || '0'));
        const subMin = parseInt(sub.substitutionMinute) || 0;
        sub.minutesPlayed = (fullTime - subMin).toString();
        const starterIdx = newLineup.starters.findIndex(s => s.playerId === sub.replacedPlayerId);
        if (starterIdx !== -1) {
          newLineup.starters[starterIdx].minutesPlayed = subMin.toString();
        }
      }
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatch = (complete: boolean = false) => {
    if (!activeMatch) return;
    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: complete } : m)
    }));
    setActiveMatch(null);
    addLog?.('تحديث مباراة', `تم حفظ بيانات مباراة ${activeMatch.opponent}`, 'info');
  };

  const inputStyle = "w-full bg-slate-100 border-4 border-slate-900 rounded-2xl py-4 px-6 font-black text-slate-900 shadow-inner focus:border-orange-600 outline-none drop-shadow-sm";
  const labelStyle = "text-xs font-black text-slate-900 mr-2 uppercase block mb-2 tracking-tighter drop-shadow-sm";

  return (
    <div className="space-y-6 md:space-y-10 pb-24 px-2 font-['Tajawal'] text-right" dir="rtl">
      {/* Header Panel */}
      <div className="bg-white p-8 rounded-[3rem] border-4 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print shadow-[10px_10px_0px_0px_rgba(0,31,63,1)] gap-6">
        <div>
          <h2 className="text-xl md:text-3xl font-black text-[#001F3F] flex items-center gap-4 uppercase tracking-tighter drop-shadow-md">
            <Trophy size={36} className="text-orange-600" /> إدارة مباريات وأنشطة نادي الكرامة
          </h2>
          <p className="text-[10px] font-black text-slate-400 mt-2 uppercase tracking-[0.3em]">Match Command & Analytics Center</p>
        </div>
        {!isViewer && (
          <button 
            onClick={() => setIsAddOpen(true)} 
            className="bg-[#001F3F] text-white px-12 py-4 rounded-[2rem] font-black text-lg shadow-[6px_6px_0px_0px_rgba(255,107,0,1)] hover:bg-black transition-all border-b-4 border-black active:translate-y-1 active:shadow-none flex items-center gap-3"
          >
            <Plus size={24}/> جدولة مواجهة جديدة
          </button>
        )}
      </div>

      {/* Match Cards List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-8 rounded-[3rem] border-4 border-slate-900 relative shadow-xl transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600 border-b-[16px]'}`}>
             <div className="flex justify-between items-start mb-8">
                <span className="bg-orange-600 text-white text-[11px] font-black px-5 py-2 rounded-2xl border-2 border-white shadow-lg uppercase">{m.matchType}</span>
                <span className="text-sm font-black text-slate-900 tabular-nums drop-shadow-sm">{m.date}</span>
             </div>
             <div className="text-center mb-10">
                <p className="text-6xl font-black text-slate-900 tabular-nums drop-shadow-[0_4px_4px_rgba(0,0,0,0.3)]">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-2xl text-slate-900 mt-6 uppercase drop-shadow-sm">الكرامة × {m.opponent}</p>
                <p className="text-xs font-black text-orange-600 mt-2 uppercase tracking-widest">{m.category} | {m.pitch}</p>
             </div>
             <div className="flex gap-4">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-5 rounded-[2rem] font-black text-sm uppercase shadow-2xl hover:bg-black transition-all border-b-4 border-black">
                  {m.isCompleted ? 'عرض التقرير النهائي' : 'إدارة أحداث المباراة'}
                </button>
                {isManager && (
                  <button onClick={() => deleteMatch(m.id)} className="p-4 bg-red-50 text-red-600 rounded-[1.5rem] border-2 border-red-900 hover:bg-red-600 hover:text-white transition-all shadow-md">
                    <Trash2 size={24}/>
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* Add Match Modal */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-xl z-[600] flex items-center justify-center p-4">
           <div className="bg-white rounded-[4rem] w-full max-w-xl border-[10px] border-slate-900 shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="p-10 bg-slate-100 border-b-8 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black text-slate-900 text-2xl uppercase tracking-tighter drop-shadow-sm">جدولة مواجهة رسمية مسبقة</h3>
                 <button onClick={() => setIsAddOpen(false)} className="bg-white p-4 rounded-3xl border-4 border-slate-900 hover:rotate-90 transition-all"><X size={28}/></button>
              </div>
              <form onSubmit={handleCreateMatch} className="p-12 space-y-8">
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <label className={labelStyle}>الفئة المستهدفة</label>
                       <select required className={inputStyle} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-2">
                       <label className={labelStyle}>نوع المنافسة</label>
                       <select className={inputStyle} value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as any})}>
                          <option value="دوري">دوري</option>
                          <option value="كأس">كأس</option>
                          <option value="ودية">ودية</option>
                       </select>
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className={labelStyle}>اسم النادي الخصم</label>
                    <input required type="text" className={inputStyle} value={formData.opponent} onChange={e => setFormData({...formData, opponent: e.target.value})} placeholder="مثال: نادي الاتحاد.." />
                 </div>
                 <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                       <label className={labelStyle}>تاريخ المباراة</label>
                       <input required type="date" className={inputStyle} value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-2">
                       <label className={labelStyle}>ساعة الركلة</label>
                       <input type="time" className={inputStyle} value={formData.time} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>
                 <button type="submit" className="w-full bg-[#001F3F] text-white py-6 rounded-[2.5rem] font-black text-2xl shadow-2xl hover:bg-black border-b-8 border-black transition-all uppercase">تثبيت الجدولة بالنظام</button>
              </form>
           </div>
        </div>
      )}

      {/* Active Match Editor Modal */}
      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-2xl z-[700] overflow-y-auto no-print text-right" dir="rtl">
           <div className="max-w-7xl mx-auto p-4 md:p-12 min-h-screen">
              <div className="bg-white rounded-[4rem] border-[12px] border-slate-900 p-8 md:p-16 shadow-2xl relative">

                {/* Modal Header */}
                <header className="flex flex-col md:flex-row justify-between items-center mb-16 border-b-[10px] border-slate-900 pb-12 gap-10">
                   <div className="text-center md:text-right">
                      <h2 className="text-3xl md:text-6xl font-black text-slate-900 tracking-tighter uppercase drop-shadow-md">الكرامة × {activeMatch.opponent}</h2>
                      <div className="flex gap-4 mt-6 justify-center md:justify-start">
                         <span className="bg-slate-900 text-white text-sm font-black px-6 py-3 rounded-2xl border-4 border-slate-900 shadow-xl tabular-nums">{activeMatch.date}</span>
                         <span className="bg-orange-600 text-white text-sm font-black px-6 py-3 rounded-2xl border-4 border-orange-900 shadow-xl uppercase">{activeMatch.category}</span>
                         {activeMatch.isCompleted && <span className="bg-emerald-600 text-white text-sm font-black px-6 py-3 rounded-2xl border-4 border-emerald-900 flex items-center gap-2 shadow-xl"><CheckCircle size={20}/> تقرير معتمد</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-5 justify-center">
                      {!activeMatch.isCompleted && (
                        <button onClick={() => saveMatch(true)} className="bg-emerald-600 text-white px-10 py-5 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center gap-3 border-b-8 border-black hover:bg-emerald-700 transition-all">
                          <CheckCircle size={24}/> اعتماد وإغلاق التقرير
                        </button>
                      )}
                      {activeMatch.isCompleted && isManager && (
                        <button onClick={() => saveMatch(false)} className="bg-red-600 text-white px-10 py-5 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center gap-3 border-b-8 border-black hover:bg-red-700 transition-all">
                           <Unlock size={24}/> فتح للتعديل
                        </button>
                      )}
                      <button onClick={() => saveMatch(false)} className="bg-blue-600 text-white px-10 py-5 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center gap-3 border-b-8 border-black hover:bg-blue-700 transition-all">
                        <Save size={24}/> حفظ المسودة
                      </button>
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-6 rounded-[2rem] border-4 border-slate-900 hover:bg-red-50 hover:text-red-600 transition-all"><X size={40}/></button>
                   </div>
                </header>

                <div className={`grid grid-cols-1 lg:grid-cols-12 gap-16 ${activeMatch.isCompleted ? 'opacity-80 pointer-events-none' : ''}`}>

                   {/* Left Column: Lineup & Score */}
                   <div className="lg:col-span-8 space-y-16">

                      {/* Score & Stoppage Section */}
                      <section className="bg-slate-900 text-white p-12 rounded-[4rem] border-8 border-orange-600 shadow-2xl">
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                            <div>
                               <h3 className="text-center text-xs font-black text-orange-400 mb-8 uppercase tracking-[0.3em]">النتيجة النهائية</h3>
                               <div className="flex justify-center items-center gap-8">
                                  <div className="space-y-4">
                                     <p className="text-[10px] font-black opacity-50 uppercase text-center">الكرامة</p>
                                     <input type="number" className="w-24 h-24 bg-white/10 border-4 border-white/20 text-white rounded-[2rem] text-center font-black text-5xl outline-none focus:border-orange-600" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                                  </div>
                                  <span className="text-6xl font-black text-orange-600">:</span>
                                  <div className="space-y-4">
                                     <p className="text-[10px] font-black opacity-50 uppercase text-center">{activeMatch.opponent}</p>
                                     <input type="number" className="w-24 h-24 bg-white/10 border-4 border-white/20 text-white rounded-[2rem] text-center font-black text-5xl outline-none focus:border-white" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                                  </div>
                               </div>
                            </div>
                            <div>
                               <h3 className="text-center text-xs font-black text-blue-400 mb-8 uppercase tracking-[0.3em]">الوقت بدل الضائع</h3>
                               <div className="grid grid-cols-2 gap-6">
                                  <div className="space-y-4">
                                     <p className="text-[10px] font-black opacity-50 uppercase text-center">الشوط الأول (د)</p>
                                     <input type="number" className="w-full bg-white/10 border-4 border-white/20 text-white rounded-2xl py-4 text-center font-black text-2xl outline-none" value={activeMatch.stoppageTime1} onChange={e => setActiveMatch({...activeMatch, stoppageTime1: e.target.value})} />
                                  </div>
                                  <div className="space-y-4">
                                     <p className="text-[10px] font-black opacity-50 uppercase text-center">الشوط الثاني (د)</p>
                                     <input type="number" className="w-full bg-white/10 border-4 border-white/20 text-white rounded-2xl py-4 text-center font-black text-2xl outline-none" value={activeMatch.stoppageTime2} onChange={e => setActiveMatch({...activeMatch, stoppageTime2: e.target.value})} />
                                  </div>
                               </div>
                            </div>
                         </div>
                      </section>

                      {/* Starters Section */}
                      <section>
                         <h3 className="text-2xl font-black text-slate-900 mb-10 border-r-8 border-orange-600 pr-5 uppercase flex items-center gap-4 drop-shadow-sm"><Users size={32}/> التشكيلة الأساسية (11 لاعب)</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-6 rounded-[2.5rem] border-4 border-slate-200 shadow-sm flex flex-col gap-4 group hover:border-orange-600 transition-all">
                                  <div className="flex justify-between items-center">
                                     <span className="w-14 h-14 bg-slate-900 text-white rounded-2xl flex items-center justify-center font-black text-2xl shadow-xl border-2 border-white">#{s.number || (idx+1)}</span>
                                     <div className="flex items-center gap-3 bg-emerald-100 text-emerald-800 px-5 py-2 rounded-2xl border-2 border-emerald-200 font-black text-sm">
                                        <Timer size={20}/> {s.minutesPlayed || '0'} دقيقة
                                     </div>
                                  </div>
                                  <select className={inputStyle} value={s.playerId} onChange={e => updateStarter(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب أساسي --</option>
                                     {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => (
                                       <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                     ))}
                                  </select>
                               </div>
                            ))}
                         </div>
                      </section>

                      {/* Bench Section - NEWLY ADDED AS REQUESTED */}
                      <section className="bg-blue-50/50 p-10 rounded-[4rem] border-4 border-blue-900 shadow-xl">
                         <div className="flex justify-between items-center mb-10">
                            <h3 className="text-2xl font-black text-blue-900 uppercase flex items-center gap-4 drop-shadow-sm"><ArrowRightLeft size={32}/> دكة البدلاء</h3>
                            <button onClick={addSubSlot} className="bg-blue-900 text-white px-8 py-3 rounded-2xl font-black text-sm flex items-center gap-2 border-b-4 border-black shadow-lg">
                               <Plus size={20}/> إضافة لاعب احتياطي
                            </button>
                         </div>
                         <div className="space-y-4">
                            {activeMatch.lineup.subs.map((sub, idx) => (
                               <div key={idx} className="bg-white p-6 rounded-[2rem] border-4 border-blue-200 shadow-sm flex items-center gap-6">
                                  <div className="flex-1 space-y-2">
                                     <label className={labelStyle}>اللاعب الاحتياطي</label>
                                     <select className={inputStyle} value={sub.playerId} onChange={e => updateSub(idx, 'playerId', e.target.value)}>
                                        <option value="">-- اختر لاعب من الاحتياط --</option>
                                        {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => (
                                          <option key={p.id} value={p.id}>{p.name} (#{p.number})</option>
                                        ))}
                                     </select>
                                  </div>
                                  <div className="w-40 space-y-2">
                                     <label className={labelStyle}>دقيقة الدخول (اختياري)</label>
                                     <input type="number" className={inputStyle} value={sub.substitutionMinute} onChange={e => updateSub(idx, 'substitutionMinute', e.target.value)} placeholder="مثال: 70" />
                                  </div>
                                  <button onClick={() => removeSubSlot(idx)} className="mt-6 p-4 bg-red-50 text-red-600 rounded-2xl border-2 border-red-200 hover:bg-red-600 hover:text-white transition-all">
                                    <Trash2 size={24}/>
                                  </button>
                               </div>
                            ))}
                            {activeMatch.lineup.subs.length === 0 && <p className="text-center py-10 font-black text-slate-300 italic">دكة البدلاء فارغة حالياً.</p>}
                         </div>
                      </section>
                   </div>

                   {/* Right Column: Events & Technical Report */}
                   <div className="lg:col-span-4 space-y-16">

                      {/* Events Tracker */}
                      <section className="bg-slate-50 p-10 rounded-[4rem] border-4 border-slate-900 shadow-xl">
                         <h3 className="text-xl font-black text-slate-900 mb-8 border-r-8 border-emerald-600 pr-4 uppercase flex items-center gap-3 drop-shadow-sm"><Activity size={28}/> سجل أحداث المباراة</h3>
                         <div className="grid grid-cols-2 gap-3 mb-8">
                            <button onClick={() => addEvent('goal')} className="bg-emerald-600 text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">⚽ هدف</button>
                            <button onClick={() => addEvent('assist')} className="bg-blue-600 text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">👟 أسيست</button>
                            <button onClick={() => addEvent('yellow')} className="bg-yellow-400 text-slate-900 py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">🟨 إنذار</button>
                            <button onClick={() => addEvent('red')} className="bg-red-600 text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">🟥 طرد</button>
                         </div>
                         <div className="space-y-4 max-h-[600px] overflow-y-auto custom-scrollbar pr-2">
                            {activeMatch.events.map(ev => (
                               <div key={ev.id} className="bg-white p-6 rounded-[2rem] border-2 border-slate-200 shadow-sm relative group">
                                  <div className="flex justify-between items-center mb-4">
                                     <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase border-2 ${
                                       ev.type === 'goal' ? 'bg-emerald-600 text-white border-emerald-700' : 
                                       ev.type === 'assist' ? 'bg-blue-600 text-white border-blue-700' : 
                                       ev.type === 'yellow' ? 'bg-yellow-400 text-slate-900 border-yellow-500' : 'bg-red-600 text-white border-red-700'
                                     }`}>{ev.type === 'goal' ? 'هدف' : ev.type === 'assist' ? 'أسيست' : ev.type === 'yellow' ? 'إنذار' : 'طرد'}</span>
                                     <button onClick={() => setActiveMatch({...activeMatch, events: activeMatch.events.filter(x => x.id !== ev.id)})} className="text-red-600 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                                  </div>
                                  <div className="space-y-3">
                                     <select className={inputStyle} value={ev.player} onChange={e => updateEvent(ev.id, 'player', e.target.value)}>
                                        <option value="">-- اختر اللاعب --</option>
                                        {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(x => x.playerId).map(x => (
                                          <option key={x.playerId} value={x.playerId}>{x.name} (#{x.number})</option>
                                        ))}
                                     </select>
                                     <input type="number" className={inputStyle} placeholder="الدقيقة" value={ev.minute} onChange={e => updateEvent(ev.id, 'minute', e.target.value)} />
                                  </div>
                               </div>
                            ))}
                         </div>
                      </section>

                      {/* Technical Report Section */}
                      <section className="bg-white p-10 rounded-[4rem] border-4 border-[#001F3F] shadow-xl">
                         <h3 className="text-xl font-black text-[#001F3F] mb-8 border-r-8 border-[#FF6B00] pr-4 uppercase flex items-center gap-3 drop-shadow-sm"><FileText size={28}/> التقرير الفني للمكتب</h3>
                         <textarea 
                            className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2.5rem] p-8 text-sm font-black text-slate-900 h-80 resize-none outline-none focus:border-orange-600 shadow-inner drop-shadow-sm"
                            placeholder="اكتب التقرير الفني الشامل للمباراة، الملاحظات على الأداء، التكتيك المتبع، والأخطاء المرصودة..."
                            value={activeMatch.notes}
                            onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                         ></textarea>
                         <div className="mt-8 bg-[#001F3F] p-6 rounded-[2rem] text-white">
                            <p className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Sparkles size={14}/> تذكير المحلل</p>
                            <p className="text-[11px] font-black leading-relaxed opacity-80">سيتم استخدام هذا التقرير في تغذية نظام الذكاء الاصطناعي الخاص بالنادي لتحليل مسار تطور الفريق.</p>
                         </div>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock,
  Gamepad2, UserCheck, TimerOff, ArrowRightLeft, Medal
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
    setFormData({ ...formData, opponent: '' });
  };

  const deleteMatch = async (id: string) => {
    if (!isManager) return;
    if (confirm('🚨 هل أنت متأكد من حذف هذه المباراة نهائياً؟')) {
      const { error } = await supabase.from('matches').delete().eq('id', id);
      if (error) {
        alert('حدث خطأ أثناء الحذف: ' + error.message);
        return;
      }
      setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      addLog?.('حذف مباراة', 'تمت إزالة سجل المباراة بالكامل من النظام السحابي', 'error');
    }
  };

  const addSubSlot = () => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.push({ playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' });
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const removeSubSlot = (index: number) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    newLineup.subs.splice(index, 1);
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const addEvent = (type: MatchEvent['type']) => {
    if (!activeMatch) return;
    const newEvent: MatchEvent = { id: generateUUID(), type, player: '', minute: '', note: '' };
    setActiveMatch({ ...activeMatch, events: [...activeMatch.events, newEvent] });
  };

  const updateEvent = (eventId: string, field: keyof MatchEvent, value: string) => {
    if (!activeMatch) return;
    const newEvents = activeMatch.events.map(e => e.id === eventId ? { ...e, [field]: value } : e);
    setActiveMatch({ ...activeMatch, events: newEvents });
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };
    if (!player) {
      newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    } else {
      const susp = getSuspension(playerId, activeMatch.category);
      if (susp.isSuspended) {
        alert(`🚨 اللاعب ${player.name} موقوف!`);
        return;
      }
      const stopTime2 = (parseInt(activeMatch.stoppageTime2 || '0'));
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '', minutesPlayed: (90 + stopTime2).toString() };
    }
    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const updateSub = (index: number, field: string, value: string) => {
    if (!activeMatch) return;
    const newLineup = { ...activeMatch.lineup };
    const sub = newLineup.subs[index];

    if (field === 'playerId') {
      const player = state.people.find(p => p.id === value);
      if (player) {
        sub.playerId = player.id;
        sub.name = player.name;
        sub.number = player.number?.toString() || '';
      } else {
        sub.playerId = ''; sub.name = ''; sub.number = '';
      }
    } else if (field === 'substitutionMinute' || field === 'replacedPlayerId') {
      // @ts-ignore
      sub[field] = value;
    }

    // منطق حساب الوقت التلقائي للتبديلات
    if (sub.substitutionMinute && sub.replacedPlayerId) {
      const stoppage2 = parseInt(activeMatch.stoppageTime2 || '0');
      const fullTime = 90 + stoppage2;
      const subMin = parseInt(sub.substitutionMinute) || 0;

      // حساب دقائق البديل (الداخل)
      sub.minutesPlayed = (fullTime - subMin).toString();

      // حساب دقائق الأساسي (الخارج)
      const starterIdx = newLineup.starters.findIndex(s => s.playerId === sub.replacedPlayerId);
      if (starterIdx !== -1) {
        newLineup.starters[starterIdx].minutesPlayed = subMin.toString();
      }
    }

    setActiveMatch({ ...activeMatch, lineup: newLineup });
  };

  const saveMatch = (complete: boolean = false) => {
    if (!activeMatch) return;
    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: complete } : m)
    }));
    setActiveMatch(null);
    addLog?.('تحديث مباراة', `تم حفظ بيانات مباراة ${activeMatch.opponent}`, 'info');
  };

  const inputStyle = "w-full bg-slate-100 border-4 border-slate-900 rounded-2xl py-4 px-6 font-black text-slate-900 shadow-inner focus:border-orange-600 outline-none drop-shadow-sm";
  const labelStyle = "text-xs font-black text-slate-900 mr-2 uppercase block mb-2 tracking-tighter drop-shadow-sm";

  return (
    <div className="space-y-6 md:space-y-10 pb-24 px-2 font-['Tajawal'] text-right" dir="rtl">
      {/* Header Panel */}
      <div className="bg-white p-8 rounded-[3rem] border-4 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print shadow-[10px_10px_0px_0px_rgba(0,31,63,1)] gap-6">
        <div>
          <h2 className="text-xl md:text-3xl font-black text-[#001F3F] flex items-center gap-4 uppercase tracking-tighter drop-shadow-md">
            <Trophy size={36} className="text-orange-600" /> إدارة مباريات وأنشطة نادي الكرامة
          </h2>
          <p className="text-[10px] font-black text-slate-400 mt-2 uppercase tracking-[0.3em]">Match Command & Analytics Center</p>
        </div>
        {!isViewer && (
          <button 
            onClick={() => setIsAddOpen(true)} 
            className="bg-[#001F3F] text-white px-12 py-4 rounded-[2rem] font-black text-lg shadow-[6px_6px_0px_0px_rgba(255,107,0,1)] hover:bg-black transition-all border-b-4 border-black active:translate-y-1 active:shadow-none flex items-center gap-3"
          >
            <Plus size={24}/> جدولة مواجهة جديدة
          </button>
        )}
      </div>

      {/* Match Cards List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-8 rounded-[3rem] border-4 border-slate-900 relative shadow-xl transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600 border-b-[16px]'}`}>
             <div className="flex justify-between items-start mb-8">
                <span className="bg-orange-600 text-white text-[11px] font-black px-5 py-2 rounded-2xl border-2 border-white shadow-lg uppercase">{m.matchType}</span>
                <span className="text-sm font-black text-slate-900 tabular-nums drop-shadow-sm">{m.date}</span>
             </div>
             <div className="text-center mb-10">
                <p className="text-6xl font-black text-slate-900 tabular-nums drop-shadow-[0_4px_4px_rgba(0,0,0,0.3)]">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-2xl text-slate-900 mt-6 uppercase drop-shadow-sm">الكرامة × {m.opponent}</p>
