  const getPlayerSuspensionStatus = useCallback((personId: string, category: string) => {
    const completedMatches = state.matches
      .filter(m => m.category === category && m.isCompleted)
      .sort((a, b) => b.date.localeCompare(a.date));

    let yellowCount = 0;
    let hasRecentRed = false;
    let isSuspended = false;

    if (completedMatches.length > 0) {
      const lastMatch = completedMatches[0];
      hasRecentRed = lastMatch.events.some(e => e.type === 'red' && (e.player === personId || e.player === state.people.find(p => p.id === personId)?.name));
    }

    state.matches
      .filter(m => m.category === category && m.isCompleted)
      .forEach(m => {
        yellowCount += m.events.filter(e => e.type === 'yellow' && (e.player === personId || e.player === state.people.find(p => p.id === personId)?.name)).length;
      });

    if (hasRecentRed || yellowCount >= 3) {
      isSuspended = true;
    }

    return { isSuspended, currentYellows: yellowCount, hasActiveRed: hasRecentRed };
  }, [state.matches, state.people]);

  useEffect(() => {
    localStorage.setItem('alkarama_secure_v10', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;
    setIsSyncing(true);
    setSyncStatus('syncing');

    try {
      const pplQuery = supabase.from('people').select('*');
      const sessQuery = supabase.from('sessions').select('*');
      const mtchQuery = supabase.from('matches').select('*');
      const techQuery = supabase.from('technical_reports').select('*');
      const wrhsQuery = supabase.from('warehouse').select('*');
      const attnQuery = supabase.from('attendance').select('*');
      const catQuery = supabase.from('categories').select('*');
      const usrQuery = supabase.from('app_users').select('*');

      if (state.currentUser.restrictedCategory) {
        const cat = state.currentUser.restrictedCategory;
        pplQuery.eq('category', cat);
        sessQuery.eq('category', cat);
        mtchQuery.eq('category', cat);
        wrhsQuery.or(`category.eq.${cat},category.eq.المخزن العام`);
      }

      const [cats, ppl, sess, mtch, attn, wrhs, tech, usrs] = await Promise.all([
        catQuery, pplQuery, sessQuery, mtchQuery, attnQuery, wrhsQuery, techQuery, usrQuery
      ]);

      // CRITICAL FIX: Overwriting local cache with pure DB data to avoid returning deleted items
      setState(prev => ({
        ...prev,
        categories: (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories,
        people: ppl.data || [],
        sessions: sess.data || [],
        matches: mtch.data || [],
        technicalReports: tech.data || [],
        warehouse: wrhs.data || [],
        attendance: attn.data || [],
        users: usrs.data || []
      }));
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  const updateStateAndSync = useCallback(async (updater: (prev: AppState) => AppState) => {
    if (!state.currentUser) return;

    let nextState: AppState | null = null;
    setState(prev => {
        nextState = updater(prev);
        return nextState;
    });

    if (!nextState) return;

    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    try {
      const syncTasks = [
        supabase.from('people').upsert(sanitize((nextState as AppState).people)),
        supabase.from('sessions').upsert(sanitize((nextState as AppState).sessions)),
        supabase.from('matches').upsert(sanitize((nextState as AppState).matches)),
        supabase.from('attendance').upsert(sanitize((nextState as AppState).attendance)),
        supabase.from('technical_reports').upsert(sanitize((nextState as AppState).technicalReports)),
        supabase.from('warehouse').upsert(sanitize((nextState as AppState).warehouse)),
        supabase.from('categories').upsert((nextState as AppState).categories.map(c => ({ name: c })))
      ];

      if (state.currentUser.role === 'مدير') {
        syncTasks.push(supabase.from('app_users').upsert(sanitize((nextState as AppState).users)));
      }

      const results = await Promise.all(syncTasks);
      const error = results.find(r => r.error);
      if (error) throw new Error(error.error.message);

      setSyncStatus('synced');
    } catch (err: any) {
      setSyncStatus('error');
      addLog('خطأ في المزامنة السحابية', err.message, 'error');
    } finally {
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state.currentUser, addLog]);

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();
    const handleRealtimeChange = () => {
        if (isInternalUpdate.current) return;
        fetchData();
    };
    const channels = [
        supabase.channel('matches-db').on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, handleRealtimeChange).subscribe(),
        supabase.channel('users-db').on('postgres_changes', { event: '*', schema: 'public', table: 'app_users' }, handleRealtimeChange).subscribe(),
        supabase.channel('people-db').on('postgres_changes', { event: '*', schema: 'public', table: 'people' }, handleRealtimeChange).subscribe(),
        supabase.channel('categories-db').on('postgres_changes', { event: '*', schema: 'public', table: 'categories' }, handleRealtimeChange).subscribe()
    ];
    return () => { channels.forEach(ch => supabase.removeChannel(ch)); };
  }, [state.currentUser, fetchData]);

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('alkarama_secure_v10');
  };

  const handleCloudLogin = async (usernameInput: string, passwordInput: string): Promise<AppUser | null> => {
    try {
      const trimmedUser = usernameInput.trim();
      const trimmedPass = passwordInput.trim();
      if ((trimmedUser.toUpperCase() === 'IZZAT' || trimmedUser === 'عزت') && trimmedPass === '123') {
        const rootUser: AppUser = { id: 'root-izzat', username: 'عزت عامر الشيخة', role: 'مدير' };
        setState(prev => ({ ...prev, currentUser: rootUser }));
        return rootUser;
      }
      const { data, error } = await supabase.from('app_users').select('*').ilike('username', trimmedUser).maybeSingle(); 
      if (error || !data) throw new Error("المستخدم غير موجود");
      if (data.password === trimmedPass) {
        const loggedUser: AppUser = { id: data.id, username: data.username, role: data.role as any, restrictedCategory: data.restrictedCategory };
        setState(prev => ({ ...prev, currentUser: loggedUser }));
        return loggedUser;
      } else { throw new Error("كلمة المرور غير صحيحة"); }
    } catch (err: any) { throw err; }
  };

  if (!state.currentUser) return <Login onLoginAttempt={handleCloudLogin} />;

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'tech_reports', label: 'التقارير الفنية', icon: FilePieChart },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'stats', label: 'الإحصائيات', icon: BarChart3 },
    { id: 'archive', label: 'الأرشيف', icon: Archive },
    { id: 'ai', label: 'الذكاء الفني', icon: Sparkles },
    { id: 'logistics', label: 'اللوجستيك', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  return (
    <div className="min-h-screen bg-[#000F21] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 transition-all duration-500 lg:translate-x-0 lg:static lg:p-4 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print`}>
        <div className="h-full bg-[#001F3F] rounded-[2rem] flex flex-col border-2 border-[#FF6B00]">
          <div className="p-8 flex items-center justify-between border-b border-white/5">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-2xl"><ClubLogo size={35} /></div>
              <div className="flex flex-col text-white">
                <span className="font-black text-sm leading-tight">نادي الكرامة</span>
                <span className="text-[9px] font-bold text-[#FF6B00] uppercase tracking-tighter">مكتب كرة القدم</span>
              </div>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 text-white hover:text-[#FF6B00]"><X size={20} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-2 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 group ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg scale-[1.02]' : 'text-white/60 hover:text-white hover:bg-white/5'}`}>
                <item.icon size={18} className={`${activeTab === item.id ? 'text-white' : 'group-hover:text-[#FF6B00]'} transition-colors`} />
                <span className="font-bold text-xs">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-6 border-t border-white/5">
            <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-red-400 hover:bg-red-500/10 font-bold transition-all">
              <LogOut size={18} /> <span className="text-xs">تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-[#001F3F] z-40 px-6 lg:px-12 py-5 flex items-center justify-between no-print border-b border-[#FF6B00]">
