            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-3 bg-white/5 rounded-2xl text-white shadow-lg"><Menu size={20} /></button>
            <div>
               <h1 className="text-xl font-black text-white tracking-tight">{navItems.find(i => i.id === activeTab)?.label}</h1>
               <p className="text-[9px] font-bold text-[#FF6B00] uppercase tracking-widest mt-0.5">Football Intelligence OS v10.0</p>
            </div>
