const ActivityCountdown: React.FC<{ date: string; time: string }> = ({ date, time }) => {
  const [timeLeft, setTimeLeft] = useState<{ d: number; h: number; m: number; s: number } | null>(null);

  useEffect(() => {
    const calculateTime = () => {
      const target = new Date(`${date}T${time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();

      if (diff <= 0) {
        setTimeLeft(null);
        return;
      }

      setTimeLeft({
        d: Math.floor(diff / (1000 * 60 * 60 * 24)),
        h: Math.floor((diff / (1000 * 60 * 60)) % 24),
        m: Math.floor((diff / (1000 * 60)) % 60),
        s: Math.floor((diff / 1000) % 60)
      });
    };

    calculateTime();
    const timer = setInterval(calculateTime, 1000);
    return () => clearInterval(timer);
  }, [date, time]);

  if (!timeLeft) {
    return (
      <div className="flex items-center gap-2 px-3 py-1 bg-emerald-100 text-emerald-700 rounded-full animate-pulse border border-emerald-200">
        <Zap size={12} />
        <span className="text-[9px] font-black uppercase">جارٍ الآن</span>
      </div>
    );
  }

  return (
    <div className="flex gap-1.5 items-center text-[#001F3F] bg-slate-50 px-2.5 py-1 rounded-xl border border-slate-100 shadow-inner">
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums">{timeLeft.d}</span>
        <span className="text-[6px] font-bold opacity-50 uppercase">يوم</span>
      </div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums">{String(timeLeft.h).padStart(2, '0')}</span>
        <span className="text-[6px] font-bold opacity-50 uppercase">سا</span>
      </div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums">{String(timeLeft.m).padStart(2, '0')}</span>
        <span className="text-[6px] font-bold opacity-50 uppercase">د</span>
      </div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center">
        <span className="text-xs font-black tabular-nums text-orange-600">{String(timeLeft.s).padStart(2, '0')}</span>
        <span className="text-[6px] font-bold opacity-50 uppercase">ث</span>
      </div>
    </div>
  );
};

const Dashboard: React.FC<DashboardProps> = ({ state, setState, onMatchClick, onSessionClick, onPlayerClick }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [quickEditMatch, setQuickEditMatch] = useState<Match | null>(null);
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  const now = new Date();
  const todayStr = now.toLocaleDateString('en-CA');
  const currentTime = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowStr = tomorrow.toLocaleDateString('en-CA');

  const globalFilter = state.globalCategoryFilter;
  const isManager = state.currentUser?.role === 'مدير';

  const upcomingMatches = useMemo(() => {
    return state.matches
      .filter(m => {
        const matchCat = (globalFilter === 'الكل' || m.category === globalFilter);
        if (!matchCat || m.isCompleted) return false;
        if (m.date < todayStr) return false;
        if (m.date === todayStr && m.time < currentTime) return false;
        return true;
      })
      .sort((a, b) => a.date.localeCompare(a.date) || a.time.localeCompare(b.time));
  }, [state.matches, globalFilter, todayStr, currentTime]);

  const upcomingSessions = useMemo(() => {
    return state.sessions
      .filter(s => {
        const sessCat = (globalFilter === 'الكل' || s.category === globalFilter);
