import React, { useState, useMemo } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Shield, Award, Calendar, 
  ChevronLeft, Trash2, Target, AlertTriangle, UserPlus, 
  Printer, FileText, Users, Save, ShieldAlert, BookOpen, Info, Timer, LogOut, LogIn, Crown, Map, ChevronRight, CheckCircle, Zap, TrendingUp, Activity, UserCircle, Sparkles, Loader2, BrainCircuit, Lock, Unlock,
  Gamepad2, UserCheck, TimerOff, ArrowRightLeft, Medal, ClipboardList
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent, Person } from '../types';
import { generateUUID, supabase } from '../App';
import ClubLogo from './ClubLogo';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Match>>({ 
    matchType: 'دوري', 
    category: restrictedCat || (state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter),
    pitch: 'ملعب الكرامة',
    date: new Date().toISOString().split('T')[0],
    time: '16:00',
    opponent: '',
    ourScore: '0',
    opponentScore: '0',
    stoppageTime1: '0',
    stoppageTime2: '0'
  });

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.opponent || !formData.date) return;
    const newMatch: Match = {
      id: generateUUID(),
      category: formData.category || state.categories[0],
      matchType: (formData.matchType as MatchType) || 'دوري',
      opponent: formData.opponent,
      pitch: formData.pitch || 'ملعب الكرامة',
      date: formData.date,
      time: formData.time || '16:00',
      advancePayment: '0',
      isCompleted: false,
      ourScore: '0',
      opponentScore: '0',
      stoppageTime1: '0',
      stoppageTime2: '0',
      events: [],
      lineup: {
        starters: Array(11).fill(null).map(() => ({ playerId: '', name: '', number: '', minutesPlayed: '0' })),
        subs: [],
        staff: [],
        captain: ''
      },
      notes: ''
    };
    setState(prev => ({ ...prev, matches: [newMatch, ...prev.matches] }));
    addLog?.('جدولة مباراة', `تمت جدولة مواجهة ضد ${newMatch.opponent}`, 'success');
    setIsAddOpen(false);
    setFormData({ ...formData, opponent: '' });
  };

  const deleteMatch = async (id: string) => {
    if (!isManager) return;
    if (confirm('🚨 هل أنت متأكد من حذف هذه المباراة نهائياً؟')) {
      const { error } = await supabase.from('matches').delete().eq('id', id);
      if (error) {
        alert('فشل الحذف من السحابة: ' + error.message);
        return;
      }
      setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      addLog?.('حذف مباراة', 'تمت إزالة سجل المباراة بالكامل من النظام السحابي', 'error');
    }
  };

  const saveMatch = (complete: boolean = false) => {
    if (!activeMatch) return;
    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === activeMatch.id ? { ...activeMatch, isCompleted: complete } : m)
    }));
    setActiveMatch(null);
    addLog?.('تحديث مباراة', `تم حفظ بيانات مباراة ${activeMatch.opponent}`, 'info');
  };

  return (
    <div className="space-y-6 md:space-y-8 pb-24 px-2 font-['Tajawal'] text-right" dir="rtl">
      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print shadow-sm gap-6">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F] flex items-center gap-3 uppercase tracking-tighter drop-shadow-md">
            <Trophy size={20} className="text-orange-600" /> إدارة مباريات وأنشطة النادي
          </h2>
          <p className="text-[9px] font-black text-slate-400 mt-1 uppercase tracking-widest">Match Command Center</p>
        </div>
        {!isViewer && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-3 rounded-2xl font-black text-sm shadow-lg hover:bg-black transition-all border-b-4 border-black flex items-center gap-2">
            <Plus size={18}/> جدولة مواجهة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative shadow-xl transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600 border-b-[10px]'}`}>
             <div className="flex justify-between items-start mb-6">
                <span className="bg-orange-600 text-white text-[9px] font-black px-3 py-1 rounded-lg border-2 border-white shadow-lg uppercase">{m.matchType}</span>
                <span className="text-[10px] font-black text-slate-400 tabular-nums">{m.date}</span>
             </div>
             <div className="text-center mb-8">
                <p className="text-5xl font-black text-slate-900 tabular-nums">{m.ourScore} - {m.opponentScore}</p>
                <p className="font-black text-lg text-slate-900 mt-4 uppercase">الكرامة × {m.opponent}</p>
                <p className="text-[9px] font-black text-orange-600 mt-1 uppercase tracking-widest">{m.category} | {m.pitch}</p>
             </div>
             <div className="flex gap-2">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-4 rounded-xl font-black text-[10px] uppercase shadow-md hover:bg-black transition-all border-b-4 border-black">
                  {m.isCompleted ? 'عرض التقرير' : 'إدارة الأحداث'}
                </button>
                {isManager && (
                  <button onClick={() => deleteMatch(m.id)} className="p-3 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 hover:bg-red-600 hover:text-white transition-all shadow-md">
                    <Trash2 size={18}/>
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {/* Modal for Adding New Match */}
      {isAddOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-md flex items-center justify-center z-[800] p-4 text-right" dir="rtl">
           <div className="bg-white rounded-[3rem] w-full max-w-xl shadow-2xl border-[6px] border-slate-900 overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black text-slate-900 uppercase">جدولة مواجهة رسمية/ودية</h3>
                 <button onClick={() => setIsAddOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900 hover:rotate-90 transition-all"><X size={20}/></button>
              </div>
              <form onSubmit={handleCreateMatch} className="p-8 space-y-6">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5">الفئة العمرية</label>
                       <select required disabled={!!restrictedCat} className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.filter(c => !restrictedCat || c === restrictedCat).map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5">نوع المباراة</label>
                       <select className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-sm" value={formData.matchType} onChange={e => setFormData({...formData, matchType: e.target.value as MatchType})}>
                          <option value="دوري">دوري رسمي</option>
                          <option value="كأس">مباراة كأس</option>
                          <option value="ودية">مباراة ودية</option>
                          <option value="بطولة ودية">بطولة ودية</option>
                       </select>
                    </div>
                 </div>

                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5">اسم المنافس / الخصم</label>
                    <input required type="text" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-sm" value={formData.opponent || ''} onChange={e => setFormData({...formData, opponent: e.target.value})} placeholder="أدخل اسم النادي المنافس..." />
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5">التاريخ</label>
                       <input required type="date" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-sm" value={formData.date || ''} onChange={e => setFormData({...formData, date: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5">التوقيت</label>
                       <input required type="time" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-sm" value={formData.time || ''} onChange={e => setFormData({...formData, time: e.target.value})} />
                    </div>
                 </div>

                 <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5">الملعب / الموقع</label>
                    <input type="text" className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-sm" value={formData.pitch || ''} onChange={e => setFormData({...formData, pitch: e.target.value})} placeholder="ملعب الكرامة، ملعب تشرين..." />
                 </div>

                 <button type="submit" className="w-full bg-[#001F3F] text-white py-5 rounded-2xl font-black text-lg shadow-xl hover:bg-black transition-all uppercase border-b-4 border-black">
                    تثبيت الموعد في الأجندة
                 </button>
              </form>
           </div>
        </div>
      )}

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-2xl z-[700] overflow-y-auto no-print text-right" dir="rtl">
           <div className="max-w-6xl mx-auto p-4 md:p-10 min-h-screen">
              <div className="bg-white rounded-[3rem] border-[8px] border-slate-900 p-8 md:p-12 shadow-2xl relative">
                <header className="flex flex-col md:flex-row justify-between items-center mb-10 border-b-4 border-slate-900 pb-8 gap-6">
                   <div className="text-center md:text-right">
                      <h2 className="text-2xl md:text-4xl font-black text-slate-900 tracking-tighter uppercase">الكرامة × {activeMatch.opponent}</h2>
                      <div className="flex gap-3 mt-4 justify-center md:justify-start">
                         <span className="bg-slate-900 text-white text-[9px] font-black px-4 py-2 rounded-xl tabular-nums">{activeMatch.date}</span>
                         {activeMatch.isCompleted && <span className="bg-emerald-600 text-white text-[9px] font-black px-4 py-2 rounded-xl flex items-center gap-1 shadow-xl"><CheckCircle size={14}/> تقرير معتمد</span>}
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-3 justify-center">
                      <button onClick={() => saveMatch(false)} className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg flex items-center gap-2 border-b-4 border-black hover:bg-blue-700 transition-all">
                        <Save size={18}/> حفظ المسودة
                      </button>
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-4 rounded-xl border-2 border-slate-900 hover:bg-red-50 hover:text-red-600 transition-all"><X size={24}/></button>
                   </div>
                </header>
                {/* Simplified Body Content for management... */}
                <div className="text-center p-20 opacity-30 italic font-black">جاري تحميل واجهة إدارة الأحداث الفنية...</div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

