import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  MapPin, Hash, UserCheck, ChevronLeft, Filter, BookOpen, Globe, CreditCard,
  Briefcase, Printer, FileText, HeartPulse, Gavel, StickyNote, Edit2, Save, BadgeCheck, Phone, Fingerprint
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';
import { generateUUID, supabase } from '../App';

interface SquadManagementProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog, getSuspension }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');
  const [activeSubTab, setActiveSubTab] = useState<'players' | 'staff'>('players');

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: restrictedCat || state.categories[0],
    joinDate: new Date().toISOString().split('T')[0]
  });

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-[11px] shadow-inner";
  const labelClass = "text-[9px] font-black text-slate-900 mr-1 uppercase block mb-1";

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isViewer) return;
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => person.id === editingId ? { ...person, ...formData } as Person : person)
      }));
      addLog?.('تحديث عضو', `تم تعديل بيانات: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: generateUUID(),
        name: formData.name!,
        fatherName: formData.fatherName || '',
        motherName: formData.motherName || '',
        birthDate: formData.birthDate || '',
        birthPlace: formData.birthPlace || '',
        khana: formData.khana || '',
        nationalId: formData.nationalId || '',
        federalNumber: formData.federalNumber || '',
        internationalId: formData.internationalId || '',
        address: formData.address || '',
        category: formData.category as Category,
        role: formData.role as Role,
        number: formData.number,
        phone: formData.phone,
        joinDate: formData.joinDate!,
        contractStart: formData.contractStart,
        contractEnd: formData.contractEnd,
        contractValue: formData.contractValue,
        medicalHistory: formData.medicalHistory,
        injuries: formData.injuries,
        penalties: formData.penalties,
        notes: formData.notes,
        coachingCertificate: formData.coachingCertificate,
        academicDegree: formData.academicDegree
      };
      setState(p => ({ ...p, people: [newPerson, ...p.people] }));
      addLog?.('إضافة عضو', `تم تسجيل عضو جديد: ${newPerson.name}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const deletePerson = async (id: string, name: string) => {
    if (isViewer) return;
    if (confirm(`هل أنت متأكد من حذف ملف ${name} نهائياً؟`)) {
        const { error } = await supabase.from('people').delete().eq('id', id);
        if (error) {
            alert('فشل الحذف من السحابة: ' + error.message);
            return;
        }
        setState(p => ({ ...p, people: p.people.filter(x => x.id !== id) }));
        addLog?.('حذف عضو', `تم مسح ملف: ${name}`, 'error');
    }
  };

  const displayList = state.people.filter(p => {
    const matchCat = restrictedCat ? p.category === restrictedCat : (localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter);
    const matchSearch = p.name.includes(searchTerm) || p.number?.toString() === searchTerm;
    const matchType = activeSubTab === 'players' ? p.role === 'لاعب' : p.role !== 'لاعب';
    return matchCat && matchSearch && matchType;
  });

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 no-print space-y-5">
        <div className="flex flex-col lg:flex-row gap-4 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input type="text" placeholder="البحث بالاسم أو الرقم..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className={`${fieldClass} pr-10 h-10`} />
          </div>

          <div className="flex items-center gap-2 w-full lg:w-auto">
            {!restrictedCat && (
              <select value={localCategoryFilter} onChange={e => setLocalCategoryFilter(e.target.value)} className="bg-slate-50 border-2 border-slate-900 rounded-xl py-2 px-3 font-black text-[10px] outline-none h-10 min-w-[120px]">
                <option value="الكل">كل الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            )}
            {!isViewer && (
              <button onClick={() => { setEditingId(null); setFormData({ role: 'لاعب', category: restrictedCat || state.categories[0], joinDate: new Date().toISOString().split('T')[0] }); setIsModalOpen(true); }} className="bg-[#001F3F] text-white px-6 h-10 rounded-xl font-black text-[10px] flex items-center gap-2 shadow-md border-b-4 border-black">
                <UserPlus size={16} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        <div className="flex p-1 bg-slate-100 border border-slate-200 rounded-xl w-fit">
          <button onClick={() => setActiveSubTab('players')} className={`px-6 py-1.5 rounded-lg font-black text-[10px] transition-all ${activeSubTab === 'players' ? 'bg-[#001F3F] text-white shadow-sm' : 'text-slate-500'}`}>اللاعبين</button>
          <button onClick={() => setActiveSubTab('staff')} className={`px-6 py-1.5 rounded-lg font-black text-[10px] transition-all ${activeSubTab === 'staff' ? 'bg-[#001F3F] text-white shadow-sm' : 'text-slate-500'}`}>الكوادر</button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 no-print">
        {displayList.map(person => (
          <div key={person.id} className="bg-white p-5 rounded-[2rem] shadow-sm border-2 border-slate-900 group transition-all hover:shadow-lg border-b-[6px] hover:border-orange-600">
             <div className="flex justify-between items-start mb-4">
