  const isInternalUpdate = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_secure_v10');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      warehouse: [],
      technicalReports: [],
      attendance: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // CORE TASK 2: DISCIPLINARY LOGIC
  const getPlayerSuspensionStatus = useCallback((personId: string, category: string) => {
    // نعتمد فقط على المباريات المكتملة
    const relevantMatches = state.matches.filter(m => m.category === category && m.isCompleted);

    let yellowCount = 0;
    let hasRedInLastMatch = false;

    // ترتيب المباريات تنازلياً للحصول على آخر مباراة
    const sortedMatches = [...relevantMatches].sort((a, b) => b.date.localeCompare(a.date));

    if (sortedMatches.length > 0) {
      const lastMatch = sortedMatches[0];
      hasRedInLastMatch = lastMatch.events.some(e => e.type === 'red' && e.player === personId);
    }

    // حساب الإنذارات التراكمية
    relevantMatches.forEach(m => {
      yellowCount += m.events.filter(e => e.type === 'yellow' && e.player === personId).length;
    });

    // الإيقاف يكون إذا كان هناك طرد في المباراة السابقة أو مجموع الإنذارات 3 (أو مضاعفاتها ولم تخدم بعد)
    // للتبسيط: 3 إنذارات أو طرد مباشر يؤدي للإيقاف في "المباراة التالية غير المكتملة"
    const isSuspended = hasRedInLastMatch || (yellowCount > 0 && yellowCount % 3 === 0);

    return { 
      isSuspended, 
      currentYellows: yellowCount, 
      hasActiveRed: hasRedInLastMatch 
    };
  }, [state.matches]);

  useEffect(() => {
    localStorage.setItem('alkarama_secure_v10', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  // CORE TASK 4: RELIABLE FETCHING (Single Source of Truth)
  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;
    setIsSyncing(true);
    setSyncStatus('syncing');

    try {
      const [ppl, sess, mtch, attn, wrhs, tech, cats, usrs] = await Promise.all([
