import React, { useState, useMemo } from 'react';
import { 
  Trophy, MapPin, Clock, Plus, X, Trash2, CheckCircle, Save, Timer, Users, ArrowRightLeft, Activity, FileText, Sparkles, Unlock, AlertTriangle
} from 'lucide-react';
import { AppState, Match, MatchType, MatchEvent } from '../types';
import { generateUUID, supabase } from '../App';

interface MatchPlannerProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  defaultSelectedId?: string | null;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const MatchPlanner: React.FC<MatchPlannerProps> = ({ state, setState, defaultSelectedId, addLog, getSuspension }) => {
  const [isAddOpen, setIsAddOpen] = useState(false);
  const [activeMatch, setActiveMatch] = useState<Match | null>(null);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isManager = currentUser?.role === 'مدير';
  const isViewer = currentUser?.role === 'مشاهد';

  const filteredMatches = useMemo(() => {
    return state.matches.filter(m => {
      if (restrictedCat) return m.category === restrictedCat;
      return (state.globalCategoryFilter === 'الكل' || m.category === state.globalCategoryFilter);
    }).sort((a,b) => b.date.localeCompare(a.date));
  }, [state.matches, state.globalCategoryFilter, restrictedCat]);

  // CORE TASK 1: FIX PERSISTENT DELETION
  const deleteMatch = async (id: string) => {
    if (!isManager) return;
    if (confirm('🚨 هل أنت متأكد من حذف هذه المباراة نهائياً من السحابة؟')) {
      const { error } = await supabase.from('matches').delete().eq('id', id);
      if (error) {
        alert('فشل الحذف من السحابة: ' + error.message);
        return;
      }
      setState(prev => ({ ...prev, matches: prev.matches.filter(m => m.id !== id) }));
      addLog?.('حذف مباراة', 'تمت إزالة سجل المباراة بالكامل من النظام', 'error');
    }
  };

  const handleCreateMatch = (e: React.FormEvent) => {
    e.preventDefault();
    // (Existing form handling logic...)
    setIsAddOpen(false);
  };

  // CORE TASK 3: AUTOMATED MATCH MINUTES
  const calculateAutoMinutes = (match: Match) => {
    const stoppage2 = parseInt(match.stoppageTime2 || '0');
    const totalTime = 90 + stoppage2;
    const newLineup = { ...match.lineup };

    // إعادة تعيين دقائق الأساسيين
    newLineup.starters = newLineup.starters.map(s => ({ ...s, minutesPlayed: totalTime.toString() }));

    // معالجة التبديلات
    newLineup.subs.forEach(sub => {
      if (sub.substitutionMinute && sub.replacedPlayerId) {
        const subMin = parseInt(sub.substitutionMinute) || 0;
        // اللاعب الداخل يلعب الوقت المتبقي
        sub.minutesPlayed = (totalTime - subMin).toString();
        // اللاعب الخارج يلعب حتى دقيقة التبديل فقط
        const starterIdx = newLineup.starters.findIndex(s => s.playerId === sub.replacedPlayerId);
        if (starterIdx !== -1) {
          newLineup.starters[starterIdx].minutesPlayed = subMin.toString();
        }
      }
    });
    return newLineup;
  };

  const updateStarter = (index: number, playerId: string) => {
    if (!activeMatch) return;
    const player = state.people.find(p => p.id === playerId);
    const newLineup = { ...activeMatch.lineup };

    if (player) {
      // CORE TASK 2: UI HARD BLOCK
      const susp = getSuspension(playerId, activeMatch.category);
      if (susp.isSuspended) {
        alert("🚨 تنبيه انضباطي: هذا اللاعب موقوف حالياً ولا يمكن إدراجه في التشكيلة.");
        return;
      }
      newLineup.starters[index] = { playerId: player.id, name: player.name, number: player.number?.toString() || '', minutesPlayed: '90' };
    } else {
      newLineup.starters[index] = { playerId: '', name: '', number: '', minutesPlayed: '0' };
    }
    setActiveMatch({ ...activeMatch, lineup: calculateAutoMinutes({ ...activeMatch, lineup: newLineup }) });
  };

  const saveMatch = (complete: boolean = false) => {
    if (!activeMatch) return;
    const finalMatch = { ...activeMatch, isCompleted: complete, lineup: calculateAutoMinutes(activeMatch) };
    setState(prev => ({
      ...prev,
      matches: prev.matches.map(m => m.id === activeMatch.id ? finalMatch : m)
    }));
    setActiveMatch(null);
    addLog?.('تحديث مباراة', `تم حفظ بيانات مباراة ${activeMatch.opponent}`, 'info');
  };

  return (
    <div className="space-y-6 md:space-y-8 pb-24 px-2 font-['Tajawal'] text-right" dir="rtl">
      <div className="bg-white p-6 rounded-[2rem] border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center no-print shadow-sm gap-6">
        <div>
          <h2 className="text-lg md:text-2xl font-black text-[#001F3F] flex items-center gap-3 uppercase tracking-tighter drop-shadow-md">
            <Trophy size={22} className="text-orange-600" /> إدارة مباريات الكرامة
          </h2>
        </div>
        {!isViewer && (
          <button onClick={() => setIsAddOpen(true)} className="bg-[#001F3F] text-white px-8 py-2.5 rounded-xl font-black text-xs shadow-lg hover:bg-black transition-all border-b-4 border-black flex items-center gap-2">
            <Plus size={18}/> جدولة مواجهة جديدة
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 no-print">
        {filteredMatches.map(m => (
          <div key={m.id} className={`bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 relative shadow-xl transition-all ${m.isCompleted ? 'border-emerald-600' : 'hover:border-orange-600 border-b-[10px]'}`}>
             {/* ... (Existing Match Card UI) */}
             <div className="flex gap-2 mt-6">
                <button onClick={() => setActiveMatch(m)} className="flex-1 bg-[#001F3F] text-white py-3.5 rounded-xl font-black text-[10px] uppercase shadow-md hover:bg-black transition-all border-b-4 border-black">
                  {m.isCompleted ? 'عرض التقرير' : 'إدارة الأحداث'}
                </button>
                {isManager && (
                  <button onClick={() => deleteMatch(m.id)} className="p-3 bg-red-50 text-red-600 rounded-xl border-2 border-red-900 hover:bg-red-600 hover:text-white transition-all shadow-md">
                    <Trash2 size={18}/>
                  </button>
                )}
             </div>
          </div>
        ))}
      </div>

      {activeMatch && (
        <div className="fixed inset-0 bg-slate-950/95 backdrop-blur-2xl z-[700] overflow-y-auto no-print text-right" dir="rtl">
           <div className="max-w-6xl mx-auto p-4 md:p-10 min-h-screen">
              <div className="bg-white rounded-[3rem] border-[8px] border-slate-900 p-8 md:p-12 shadow-2xl relative">
                {/* Header Section */}
                <header className="flex flex-col md:flex-row justify-between items-center mb-10 border-b-4 border-slate-900 pb-8 gap-6">
                   <div className="text-center md:text-right">
                      <h2 className="text-2xl md:text-4xl font-black text-slate-900 tracking-tighter uppercase">الكرامة × {activeMatch.opponent}</h2>
                   </div>
                   <div className="flex flex-wrap gap-3 justify-center">
                      <button onClick={() => saveMatch(true)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg flex items-center gap-2 border-b-4 border-black">
                        <CheckCircle size={18}/> اعتماد وإغلاق
                      </button>
                      <button onClick={() => saveMatch(false)} className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg flex items-center gap-2 border-b-4 border-black">
                        <Save size={18}/> حفظ مؤقت
                      </button>
                      <button onClick={() => setActiveMatch(null)} className="bg-slate-100 p-4 rounded-xl border-2 border-slate-900 hover:bg-red-50 hover:text-red-600 transition-all"><X size={24}/></button>
                   </div>
                </header>

                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                   {/* Lineup & Events Management */}
                   <div className="lg:col-span-8 space-y-10">
                      <section className="bg-slate-900 text-white p-8 rounded-[3rem] border-4 border-orange-600 shadow-xl">
                         <div className="grid grid-cols-2 gap-8">
                            <div className="text-center border-l border-white/10">
                               <p className="text-[10px] font-black text-orange-400 mb-4 uppercase">النتيجة النهائية</p>
                               <div className="flex items-center justify-center gap-4">
                                  <input type="number" className="w-16 h-16 bg-white/10 rounded-xl text-center text-3xl font-black" value={activeMatch.ourScore} onChange={e => setActiveMatch({...activeMatch, ourScore: e.target.value})} />
                                  <span className="text-2xl">:</span>
                                  <input type="number" className="w-16 h-16 bg-white/10 rounded-xl text-center text-3xl font-black" value={activeMatch.opponentScore} onChange={e => setActiveMatch({...activeMatch, opponentScore: e.target.value})} />
                               </div>
                            </div>
                            <div className="text-center">
                               <p className="text-[10px] font-black text-blue-400 mb-4 uppercase">الوقت الضائع (د)</p>
                               <div className="flex items-center justify-center gap-4">
                                  <input type="number" className="w-full bg-white/10 rounded-xl py-3 text-center font-black" value={activeMatch.stoppageTime2} onChange={e => { const val = e.target.value; setActiveMatch(m => calculateAutoMinutes({ ...m!, stoppageTime2: val }) as Match); }} placeholder="الشوط 2" />
                               </div>
                            </div>
                         </div>
                      </section>

                      <section>
                         <h3 className="text-lg font-black text-slate-900 mb-6 border-r-4 border-orange-600 pr-3 uppercase flex items-center gap-2"><Users size={20}/> التشكيلة الأساسية</h3>
                         <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {activeMatch.lineup.starters.map((s, idx) => (
                               <div key={idx} className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-200 flex flex-col gap-3 relative">
                                  <select className="w-full bg-white border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-xs" value={s.playerId} onChange={e => updateStarter(idx, e.target.value)}>
                                     <option value="">-- اختر لاعب --</option>
                                     {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => {
                                        const susp = getSuspension(p.id, activeMatch.category);
                                        return (
                                          <option key={p.id} value={p.id} disabled={susp.isSuspended} className={susp.isSuspended ? "text-red-600 font-bold" : ""}>
                                            {p.name} {susp.isSuspended ? "(موقوف انضباطياً 🛑)" : ""}
                                          </option>
                                        );
                                     })}
                                  </select>
                                  <div className="flex justify-between items-center px-2">
                                     <span className="text-[10px] font-black text-slate-400 uppercase">دقائق اللعب</span>
                                     <span className="text-sm font-black text-emerald-600">{s.minutesPlayed} د</span>
                                  </div>
                               </div>
                            ))}
                         </div>
                      </section>
                   </div>

                   <div className="lg:col-span-4 space-y-8">
                      <div className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 shadow-md">
                         <h3 className="text-md font-black mb-4 flex items-center gap-2 border-r-4 border-blue-600 pr-2 uppercase"><Activity size={18}/> التبديلات</h3>
                         {/* (Substitutions management UI here with auto-calculated minutes) */}
                         <button onClick={() => {
                            const newSubs = [...activeMatch.lineup.subs, { playerId: '', name: '', number: '', minutesPlayed: '0', substitutionMinute: '', replacedPlayerId: '' }];
                            setActiveMatch({...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs }});
                         }} className="w-full bg-blue-50 text-blue-900 border-2 border-blue-900 py-3 rounded-xl font-black text-[10px] uppercase mb-4">+ إضافة تبديل</button>

                         <div className="space-y-4">
                            {activeMatch.lineup.subs.map((sub, i) => (
                               <div key={i} className="p-4 bg-slate-50 rounded-2xl border-2 border-slate-200 space-y-3 relative">
                                  <select className="w-full bg-white border-2 border-slate-300 rounded-lg py-1.5 px-3 text-[10px] font-black" value={sub.playerId} onChange={e => {
                                      const newSubs = [...activeMatch.lineup.subs];
                                      const p = state.people.find(x => x.id === e.target.value);
                                      newSubs[i] = { ...newSubs[i], playerId: e.target.value, name: p?.name || '', number: p?.number?.toString() || '' };
                                      setActiveMatch({...activeMatch, lineup: calculateAutoMinutes({...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs }}) });
                                  }}>
                                     <option value="">-- اللاعب البديل --</option>
                                     {state.people.filter(p => p.role === 'لاعب' && p.category === activeMatch.category).map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                  </select>
                                  <div className="grid grid-cols-2 gap-2">
                                     <select className="w-full bg-white border-2 border-slate-300 rounded-lg py-1.5 px-3 text-[10px] font-black" value={sub.replacedPlayerId} onChange={e => {
                                        const newSubs = [...activeMatch.lineup.subs];
                                        newSubs[i].replacedPlayerId = e.target.value;
                                        setActiveMatch({...activeMatch, lineup: calculateAutoMinutes({...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs }}) });
                                     }}>
                                        <option value="">-- اللاعب الخارج --</option>
                                        {activeMatch.lineup.starters.map(s => <option key={s.playerId} value={s.playerId}>{s.name}</option>)}
                                     </select>
                                     <input type="number" placeholder="دقيقة" className="w-full bg-white border-2 border-slate-300 rounded-lg py-1.5 px-3 text-[10px] font-black" value={sub.substitutionMinute} onChange={e => {
                                        const newSubs = [...activeMatch.lineup.subs];
                                        newSubs[i].substitutionMinute = e.target.value;
                                        setActiveMatch({...activeMatch, lineup: calculateAutoMinutes({...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs }}) });
                                     }} />
                                  </div>
                                  <button onClick={() => {
                                    const newSubs = activeMatch.lineup.subs.filter((_, idx) => idx !== i);
                                    setActiveMatch({...activeMatch, lineup: calculateAutoMinutes({...activeMatch, lineup: { ...activeMatch.lineup, subs: newSubs }}) });
                                  }} className="absolute -top-2 -left-2 bg-red-600 text-white rounded-full p-1"><X size={12}/></button>
                               </div>
                            ))}
                         </div>
                      </div>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

