import React, { useState } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  MapPin, Hash, UserCheck, ChevronLeft, Filter, BookOpen, Globe, CreditCard,
  Briefcase, Printer, FileText, HeartPulse, Gavel, StickyNote, Edit2, Save, BadgeCheck, Phone, Fingerprint
} from 'lucide-react';
