                            <div className="text-center">
                               <p className="text-[10px] font-black text-blue-400 mb-4 uppercase">الوقت الضائع (د)</p>
                               <div className="flex items-center justify-center gap-4">
                                  {/* Fix: removed incorrect 'as Match' cast and ensured calculateAutoMinutes correctly returns the lineup for match state update */}
                                  <input type="number" className="w-full bg-white/10 rounded-xl py-3 text-center font-black" value={activeMatch.stoppageTime2} onChange={e => { const val = e.target.value; setActiveMatch(m => m ? ({ ...m, stoppageTime2: val, lineup: calculateAutoMinutes({ ...m, stoppageTime2: val } as Match) }) : null); }} placeholder="الشوط 2" />
