                         <h3 className="text-xl font-black text-slate-900 mb-8 border-r-8 border-emerald-600 pr-4 uppercase flex items-center gap-3 drop-shadow-sm"><Activity size={28}/> سجل أحداث المباراة</h3>
                         <div className="grid grid-cols-2 gap-3 mb-8">
                            <button onClick={() => addEvent('goal')} className="bg-emerald-600 text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">⚽ هدف</button>
                            <button onClick={() => addEvent('assist')} className="bg-blue-600 text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">👟 أسيست</button>
                            <button onClick={() => addEvent('yellow')} className="bg-yellow-400 text-slate-900 py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">🟨 إنذار</button>
                            <button onClick={() => addEvent('red')} className="bg-red-600 text-white py-3 rounded-xl font-black text-xs flex items-center justify-center gap-2 shadow-md">🟥 طرد</button>
                         </div>
                         <div className="space-y-4 max-h-[600px] overflow-y-auto custom-scrollbar pr-2">
                            {activeMatch.events.map(ev => (
                               <div key={ev.id} className="bg-white p-6 rounded-[2rem] border-2 border-slate-200 shadow-sm relative group">
                                  <div className="flex justify-between items-center mb-4">
                                     <span className={`text-[10px] font-black px-3 py-1 rounded-lg uppercase border-2 ${
                                       ev.type === 'goal' ? 'bg-emerald-600 text-white border-emerald-700' : 
                                       ev.type === 'assist' ? 'bg-blue-600 text-white border-blue-700' : 
                                       ev.type === 'yellow' ? 'bg-yellow-400 text-slate-900 border-yellow-500' : 'bg-red-600 text-white border-red-700'
                                     }`}>{ev.type === 'goal' ? 'هدف' : ev.type === 'assist' ? 'أسيست' : ev.type === 'yellow' ? 'إنذار' : 'طرد'}</span>
                                     <button onClick={() => setActiveMatch({...activeMatch, events: activeMatch.events.filter(x => x.id !== ev.id)})} className="text-red-600 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={16}/></button>
                                  </div>
                                  <div className="space-y-3">
                                     <select className={inputStyle} value={ev.player} onChange={e => updateEvent(ev.id, 'player', e.target.value)}>
                                        <option value="">-- اختر اللاعب --</option>
                                        {[...activeMatch.lineup.starters, ...activeMatch.lineup.subs].filter(x => x.playerId).map(x => (
                                          <option key={x.playerId} value={x.playerId}>{x.name} (#{x.number})</option>
                                        ))}
                                     </select>
                                     <input type="number" className={inputStyle} placeholder="الدقيقة" value={ev.minute} onChange={e => updateEvent(ev.id, 'minute', e.target.value)} />
                                  </div>
                               </div>
                            ))}
                         </div>
                      </section>

                      <section className="bg-white p-10 rounded-[4rem] border-4 border-[#001F3F] shadow-xl">
                         <h3 className="text-xl font-black text-[#001F3F] mb-8 border-r-8 border-[#FF6B00] pr-4 uppercase flex items-center gap-3 drop-shadow-sm"><FileText size={28}/> التقرير الفني للمكتب</h3>
                         <textarea 
                            className="w-full bg-slate-50 border-4 border-slate-100 rounded-[2.5rem] p-8 text-sm font-black text-slate-900 h-80 resize-none outline-none focus:border-orange-600 shadow-inner drop-shadow-sm"
                            placeholder="اكتب التقرير الفني الشامل للمباراة، الملاحظات على الأداء، التكتيك المتبع، والأخطاء المرصودة..."
                            value={activeMatch.notes}
                            onChange={e => setActiveMatch({...activeMatch, notes: e.target.value})}
                         ></textarea>
                         <div className="mt-8 bg-[#001F3F] p-6 rounded-[2rem] text-white">
                            <p className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Sparkles size={14}/> تذكير المحلل</p>
                            <p className="text-[11px] font-black leading-relaxed opacity-80">سيتم استخدام هذا التقرير في تغذية نظام الذكاء الاصطناعي الخاص بالنادي لتحليل مسار تطور الفريق.</p>
                         </div>
                      </section>
                   </div>
                </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default MatchPlanner;

export type Category = string;
export type Role = 'لاعب' | 'مدرب' | 'مساعد مدرب' | 'مدرب حراس' | 'مدرب لياقة' | 'إداري' | 'طبيب' | 'معالج' | 'منسق إعلامي' | 'مرافق';
export type AttendanceStatus = 'حاضر' | 'متأخر' | 'غائب' | 'غياب بعذر';
export type UserRole = 'مدير' | 'إداري فئة' | 'مشاهد';
export type MatchType = 'دوري' | 'كأس' | 'ودية' | 'بطولة ودية' | 'مباراة دولية';

export interface AppNotification {
  id: string;
  message: string;
  details?: string;
  type: 'info' | 'success' | 'warning' | 'error';
  timestamp: number;
  isRead?: boolean;
}

export interface TechnicalReport {
  id: string;
  targetId: string; // ID of Match or Staff Member
  type: 'match_evaluation' | 'staff_review' | 'player_radar';
  category: Category;
  rating: number; // 1-5 stars
  content: string;
  author: string;
  date: string;
  radarData?: {
    technical: number;
    physical: number;
    tactical: number;
    mental: number;
    discipline: number;
  };
}

export interface Person {
  id: string;
  name: string;
  fatherName: string;
  motherName: string;
  birthDate: string;
  birthPlace: string;
  khana: string;
  nationalId: string;
  federalNumber: string;
  internationalId: string;
  address: string;
  category: Category;
  role: Role;
  number?: number;
  phone?: string;
  joinDate: string;
  height?: string;
  weight?: string;
  position?: string;
  contractStart?: string;
  contractEnd?: string;
  contractValue?: string;
  medicalHistory?: string;
  injuries?: string;
  penalties?: string;
  notes?: string;
  coachingCertificate?: string;
  academicDegree?: string;
  monthlyReports?: { [key: string]: string };
}

export interface AttendanceRecord {
  id: string;
  personId: string;
  sessionId: string;
  date: string;
  time: string;
  status: AttendanceStatus;
  excuse?: string;
  fine?: string;
  isLocked?: boolean;
}

export interface TrainingSession {
  id: string;
  category: Category;
  date: string;
  time: string;
  pitch?: string;
  objective: string;
  isCompleted?: boolean;
  isLocked?: boolean;
}

export interface MatchEvent {
  id: string;
  type: 'goal' | 'assist' | 'yellow' | 'red' | 'injury' | 'substitution';
  player: string; 
  minute: string;
  note?: string;
}

export interface Match {
  id: string;
  category: Category;
  matchType: MatchType;
  opponent: string;
  pitch?: string;
  date: string;
  time: string;
  advancePayment: string;
  isCompleted: boolean;
  ourScore: string;
  opponentScore: string;
  stoppageTime1?: string; 
  stoppageTime2?: string; 
  events: MatchEvent[];
  lineup: {
    starters: { playerId: string; name: string; number: string; minutesPlayed?: string }[];
    subs: { 
      playerId: string; 
      name: string; 
      number: string; 
      minutesPlayed?: string;
      substitutionMinute?: string;
      replacedPlayerId?: string;
    }[];
    staff: { role: string; name: string }[];
    captain: string;
  };
  notes?: string;
}

export interface WarehouseItem {
  id: string;
  name: string;
  category: Category | 'المخزن العام';
  quantity: number;
  unit: 'قطعة' | 'طقم' | 'كرة' | 'حذاء' | 'أخرى';
  condition: 'جديد' | 'مستعمل' | 'تالف';
  lastUpdated: string;
  notes?: string;
}

export interface AppUser {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  restrictedCategory?: Category;
}

export interface AppState {
  people: Person[];
  attendance: AttendanceRecord[];
  sessions: TrainingSession[];
  matches: Match[];
  warehouse: WarehouseItem[];
  technicalReports: TechnicalReport[];
  users: AppUser[];
  categories: Category[];
  currentUser: AppUser | null;
  notifications: AppNotification[];
  globalCategoryFilter: Category | 'الكل';
}

import React, { useState, useEffect } from 'react';
import { 
  UserPlus, Trash2, Search, X, Shield, Award, Layers, Home, Plus, AlertCircle, Calendar,
  MapPin, Hash, UserCheck, ChevronLeft, FolderPlus, Filter, Settings2, BookOpen, Globe, CreditCard, Map,
  Briefcase, Printer, FileSpreadsheet, Eye, FileText, Users, ChevronRight, HeartPulse, Gavel, StickyNote,
  Edit2, Ruler, Weight, Target
} from 'lucide-react';
import { AppState, Person, Role, Category } from '../types';
import ClubLogo from './ClubLogo';
import { generateUUID, supabase } from '../App';

interface SquadManagementProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  onOpenReport?: (player: Person) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
  getSuspension?: (id: string, cat: string) => { isSuspended: boolean, currentYellows: number, hasActiveRed: boolean };
}

const SquadManagement: React.FC<SquadManagementProps> = ({ state, setState, onOpenReport, addLog, getSuspension }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');
  const [activeSubTab, setActiveSubTab] = useState<'players' | 'staff'>('players');
  const [showFullReportView, setShowFullReportView] = useState(false);

  const currentUser = state.currentUser;
  const restrictedCat = currentUser?.restrictedCategory;
  const isViewer = currentUser?.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<Person>>({
    role: 'لاعب',
    category: restrictedCat || state.categories[0] || '',
    joinDate: new Date().toISOString().split('T')[0],
    position: 'غير محدد',
    height: '',
    weight: ''
  });

  const roles: Role[] = ['لاعب', 'مدرب', 'مساعد مدرب', 'مدرب حراس', 'مدرب لياقة', 'إداري', 'طبيب', 'معالج', 'منسق إعلامي', 'مرافق'];

  const calculateAge = (date?: string) => {
    if (!date) return null;
    const b = new Date(date);
    const today = new Date();
    let age = today.getFullYear() - b.getFullYear();
    if (today.getMonth() < b.getMonth() || (today.getMonth() === b.getMonth() && today.getDate() < b.getDate())) age--;
    return age >= 0 ? age : 0;
  };

  const handleSave = (e: React.FormEvent) => {
    if (isViewer) return;
    e.preventDefault();
    if (!formData.name) return;

    if (editingId) {
      setState(p => ({
        ...p,
        people: p.people.map(person => {
          if (person.id === editingId) {
             const updated = { ...person, ...formData };
             return updated as Person;
          }
          return person;
        })
      }));
      addLog?.('تعديل عضو', `تم تحديث ملف العضو: ${formData.name}`, 'info');
    } else {
      const newPerson: Person = {
        id: generateUUID(),
        name: formData.name || '',
        fatherName: formData.fatherName || '',
        motherName: formData.motherName || '',
        birthDate: formData.birthDate || '',
        birthPlace: formData.birthPlace || '',
        khana: formData.khana || '',
        nationalId: formData.nationalId || '',
        federalNumber: formData.federalNumber || '',
        internationalId: formData.internationalId || '',
        address: formData.address || '',
        category: formData.category || restrictedCat || state.categories[0],
        role: formData.role || 'لاعب',
        number: formData.number || 0,
        phone: formData.phone || '',
        joinDate: formData.joinDate || new Date().toISOString().split('T')[0],
        height: formData.height || '',
        weight: formData.weight || '',
        position: formData.position || 'غير محدد',
        contractStart: formData.contractStart || undefined,
        contractEnd: formData.contractEnd || undefined,
        contractValue: formData.contractValue || undefined,
        coachingCertificate: formData.coachingCertificate || undefined,
        academicDegree: formData.academicDegree || undefined,
        medicalHistory: formData.medicalHistory || undefined,
        injuries: formData.injuries || undefined,
        penalties: formData.penalties || undefined,
        notes: formData.notes || undefined,
        monthlyReports: {}
      };

      setState(p => ({ ...p, people: [...p.people, newPerson] }));
      addLog?.('تسجيل عضو جديد', `تم تسجيل ${newPerson.role}: ${newPerson.name}`, 'success');
    }
    setIsModalOpen(false);
    setEditingId(null);
  };

  const deletePerson = async (id: string, name: string) => {
    if (isViewer) return;
    if (confirm(`هل أنت متأكد من حذف ملف ${name} نهائياً؟`)) {
        const { error } = await supabase.from('people').delete().eq('id', id);
        if (error) {
            alert('فشل الحذف من السحابة: ' + error.message);
            return;
        }
        setState(p => ({ ...p, people: p.people.filter(x => x.id !== id) }));
        addLog?.('حذف عضو', `تم مسح ملف: ${name}`, 'error');
    }
  };

  const baseFiltered = state.people.filter(p => {
    const matchCat = restrictedCat ? p.category === restrictedCat : (localCategoryFilter === 'الكل' ? true : p.category === localCategoryFilter);
    const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                      (p.number?.toString().includes(searchTerm));
    return matchCat && matchSearch;
  });

  const filteredPlayers = baseFiltered.filter(p => p.role === 'لاعب');
  const filteredStaff = baseFiltered.filter(p => p.role !== 'لاعب');
  const displayList = activeSubTab === 'players' ? filteredPlayers : filteredStaff;

  const fieldClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2.5 px-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-orange-600/10 focus:border-orange-600 transition-all placeholder:text-slate-500 text-sm";
  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";
  const textAreaClass = "w-full bg-white border-2 border-slate-900 rounded-xl py-2.5 px-4 font-black text-slate-900 outline-none focus:ring-4 focus:ring-orange-600/10 focus:border-orange-600 transition-all placeholder:text-slate-400 text-xs min-h-[80px] resize-none";

  if (showFullReportView) {
    const activeCategory = restrictedCat || localCategoryFilter;
    const reportList = baseFiltered.sort((a,b) => (a.number || 0) - (b.number || 0));
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <div className="flex justify-between items-center no-print">
           <button onClick={() => setShowFullReportView(false)} className="flex items-center gap-2 text-slate-500 font-black hover:text-[#001F3F] transition-all">
             <ChevronRight size={20}/> العودة للإدارة
           </button>
           <button onClick={() => window.print()} className="bg-[#001F3F] text-white px-8 py-3 rounded-xl font-black text-sm flex items-center gap-2 shadow-xl hover:bg-black transition-all border-b-4 border-black">
             <Printer size={18}/> طباعة الكشف PDF
           </button>
        </div>

        <div className="bg-white p-10 rounded-[2.5rem] border-4 border-slate-900 shadow-xl print:border-2 print:rounded-none print:shadow-none print:p-4">
           <div className="flex justify-between items-center border-b-4 border-slate-900 pb-6 mb-8 print:mb-4">
              <div className="flex items-center gap-4">
                 <ClubLogo size={80} />
                 <div>
                    <h2 className="text-2xl font-black text-[#001F3F]">نادي الكرامة الرياضي</h2>
                    <p className="text-sm font-black text-orange-600">مكتب كرة القدم المركزي</p>
                 </div>
              </div>
              <div className="text-left font-black">
                 <p className="text-xl">كشف الفئة الشامل</p>
                 <p className="text-sm text-slate-400">فئة: {activeCategory}</p>
                 <p className="text-[10px] mt-1">تاريخ الاستخراج: {new Date().toLocaleDateString('ar-SY')}</p>
              </div>
           </div>

           <div className="overflow-x-auto">
              <table className="w-full text-right border-collapse">
                 <thead>
                    <tr className="bg-slate-100 border-y-2 border-slate-900">
                       <th className="p-3 text-[10px] font-black border-l border-slate-200">الاسم الكامل</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">الرقم</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">الصفة</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">تاريخ الميلاد</th>
                       <th className="p-3 text-[10px] font-black border-l border-slate-200 text-center">الرقم الوطني</th>
                       <th className="p-3 text-[10px] font-black text-center">رقم القيد</th>
                    </tr>
                 </thead>
                 <tbody>
                    {reportList.map((p, idx) => (
                       <tr key={p.id} className="border-b border-slate-100 hover:bg-slate-50">
                          <td className="p-3 text-xs font-black border-l border-slate-200">{p.name}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.number || '--'}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.role}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.birthDate}</td>
                          <td className="p-3 text-xs font-black border-l border-slate-200 text-center">{p.nationalId || '--'}</td>
                          <td className="p-3 text-xs font-black text-center">{p.khana || '--'}</td>
                       </tr>
                    ))}
                 </tbody>
              </table>
           </div>

           <div className="mt-16 flex justify-around items-start opacity-0 print:opacity-100">
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع مدرب الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">توقيع إداري الفئة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
              <div className="text-center space-y-12">
                 <p className="font-black text-sm">مدير مكتب كرة القدم</p>
                 <p className="font-black text-xs text-blue-900">عزت عامر الشيخة</p>
                 <p className="text-[10px]">..........................</p>
              </div>
           </div>
           <div className="mt-10 pt-4 border-t border-slate-200 text-center hidden print:block">
              <p className="text-[8px] font-black text-slate-400">وثيقة رسمية صادرة عن النظام الإلكتروني لنادي الكرامة الرياضي - مكتب كرة القدم</p>
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 animate-in fade-in duration-500">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 no-print space-y-6">
        <div className="flex flex-col lg:flex-row gap-4 items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
            <input 
              type="text" 
              placeholder="البحث بالاسم أو رقم القميص..." 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
              className={`${fieldClass} pr-12 h-12 text-lg`} 
            />
          </div>

          <div className="flex items-center gap-3 w-full lg:w-auto">
            {!restrictedCat && (
              <select 
                value={localCategoryFilter}
                onChange={e => setLocalCategoryFilter(e.target.value)}
                className="bg-slate-100 border-2 border-slate-900 rounded-xl py-2 pr-4 pl-10 font-black text-sm text-slate-900 outline-none h-12 appearance-none cursor-pointer hover:bg-white transition-colors min-w-[140px]"
              >
                <option value="الكل">جميع الفئات</option>
                {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            )}

            <button 
              onClick={() => {
                if (!restrictedCat && localCategoryFilter === 'الكل') { alert("يرجى اختيار فئة محددة أولاً لاستخراج الكشف الشامل."); return; }
                setShowFullReportView(true);
              }}
              className="bg-emerald-600 text-white px-6 h-12 rounded-xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-lg shrink-0 border-b-4 border-black group"
            >
              <FileText size={20} className="group-hover:scale-110" /> كشف الفئة الشامل
            </button>

            {!isViewer && (
              <button 
                onClick={() => { 
                  setEditingId(null); 
                  setFormData({ role: 'لاعب', category: restrictedCat || (localCategoryFilter !== 'الكل' ? localCategoryFilter : (state.categories[0] || '')), joinDate: new Date().toISOString().split('T')[0], position: 'غير محدد', height: '', weight: '' }); 
                  setIsModalOpen(true); 
                }} 
                className="bg-[#001F3F] text-white px-8 h-12 rounded-xl font-black text-sm flex items-center gap-3 hover:bg-black transition-all shadow-lg shrink-0 border-b-4 border-black"
              >
                <UserPlus size={20} /> إضافة عضو
              </button>
            )}
          </div>
        </div>

        <div className="flex p-1.5 bg-slate-100 border-2 border-slate-900 rounded-2xl w-fit mx-auto md:mx-0">
          <button 
            onClick={() => setActiveSubTab('players')}
            className={`flex items-center gap-2 px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'players' ? 'bg-[#001F3F] text-white shadow-md scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
          >
            اللاعبين
            <span className={`px-2 py-0.5 rounded-md text-[10px] ${activeSubTab === 'players' ? 'bg-orange-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
              {filteredPlayers.length}
            </span>
          </button>
          <button 
            onClick={() => setActiveSubTab('staff')}
            className={`flex items-center gap-2 px-8 py-2.5 rounded-xl font-black text-sm transition-all ${activeSubTab === 'staff' ? 'bg-[#001F3F] text-white shadow-md scale-105' : 'text-slate-500 hover:bg-slate-100'}`}
          >
            الكوادر الفنية والإدارية
            <span className={`px-2 py-0.5 rounded-md text-[10px] ${activeSubTab === 'staff' ? 'bg-orange-500 text-white' : 'bg-slate-200 text-slate-600'}`}>
              {filteredStaff.length}
            </span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 no-print">
        {displayList.map(person => {
