const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');

  const isInternalUpdate = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_secure_v10');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      warehouse: [],
      technicalReports: [],
      attendance: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  // توجيه أمين المستودع للتبويب المناسب عند تسجيل الدخول
  useEffect(() => {
    if (state.currentUser?.role === 'أمين مستودع') {
      setActiveTab('warehouse');
    }
  }, [state.currentUser]);

  const getPlayerSuspensionStatus = useCallback((personId: string, category: string) => {
    const completedMatches = state.matches
      .filter(m => m.category === category && m.isCompleted)
      .sort((a, b) => b.date.localeCompare(a.date));

    let yellowCount = 0;
    let hasRecentRed = false;
    let isSuspended = false;

    if (completedMatches.length > 0) {
      const lastMatch = completedMatches[0];
      hasRecentRed = lastMatch.events.some(e => e.type === 'red' && (e.player === personId || e.player === state.people.find(p => p.id === personId)?.name));
    }

    state.matches
      .filter(m => m.category === category && m.isCompleted)
      .forEach(m => {
        yellowCount += m.events.filter(e => e.type === 'yellow' && (e.player === personId || e.player === state.people.find(p => p.id === personId)?.name)).length;
      });

    if (hasRecentRed || yellowCount >= 3) {
      isSuspended = true;
    }

    return { isSuspended, currentYellows: yellowCount, hasActiveRed: hasRecentRed };
  }, [state.matches, state.people]);

  useEffect(() => {
    localStorage.setItem('alkarama_secure_v10', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = {
      id: generateUUID(),
      message, details, type, timestamp: Date.now(), isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  }, []);

  const sanitize = (data: any[]) => {
    return data.map(item => {
      const cleanItem = JSON.parse(JSON.stringify(item));
      Object.keys(cleanItem).forEach(key => {
        if (cleanItem[key] === undefined) cleanItem[key] = null;
      });
      return cleanItem;
    });
  };

  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;
    setIsSyncing(true);
    setSyncStatus('syncing');
    try {
      const pplQuery = supabase.from('people').select('*');
      const sessQuery = supabase.from('sessions').select('*');
      const mtchQuery = supabase.from('matches').select('*');
      const techQuery = supabase.from('technical_reports').select('*');
      const wrhsQuery = supabase.from('warehouse').select('*');
      const attnQuery = supabase.from('attendance').select('*');
      const catQuery = supabase.from('categories').select('*');
      const usrQuery = supabase.from('app_users').select('*');

      if (state.currentUser.restrictedCategory && state.currentUser.role !== 'أمين مستودع') {
        const cat = state.currentUser.restrictedCategory;
        pplQuery.eq('category', cat);
        sessQuery.eq('category', cat);
        mtchQuery.eq('category', cat);
        wrhsQuery.or(`category.eq.${cat},category.eq.المخزن العام`);
      }

      const [cats, ppl, sess, mtch, attn, wrhs, tech, usrs] = await Promise.all([
        catQuery, pplQuery, sessQuery, mtchQuery, attnQuery, wrhsQuery, techQuery, usrQuery
      ]);

      setState(prev => {
        const rawCats = (cats.data && cats.data.length > 0) ? cats.data.map(c => c.name) : prev.categories;
        const uniqueCats = Array.from(new Set(rawCats));

        return {
          ...prev,
          categories: uniqueCats,
          people: ppl.data || [],
          sessions: sess.data || [],
          matches: mtch.data || [],
          technicalReports: tech.data || [],
          warehouse: wrhs.data || [],
          attendance: attn.data || [],
          users: usrs.data || []
        };
      });
      setSyncStatus('synced');
    } catch (error: any) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  }, [state.currentUser]);

  const updateStateAndSync = useCallback(async (updater: (prev: AppState) => AppState) => {
    if (!state.currentUser) return;

    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    let nextState: AppState;
    setState(prev => {
      nextState = updater(prev);
      return nextState;
    });

    try {
      const currentNextState = updater(state); 

      const syncTasks = [
        supabase.from('people').upsert(sanitize(currentNextState.people)),
        supabase.from('sessions').upsert(sanitize(currentNextState.sessions)),
        supabase.from('matches').upsert(sanitize(currentNextState.matches)),
        supabase.from('attendance').upsert(sanitize(currentNextState.attendance)),
        supabase.from('technical_reports').upsert(sanitize(currentNextState.technicalReports)),
        supabase.from('warehouse').upsert(sanitize(currentNextState.warehouse)),
        supabase.from('categories').upsert(currentNextState.categories.map(c => ({ name: c })))
      ];

      if (state.currentUser.role === 'مدير') {
        syncTasks.push(supabase.from('app_users').upsert(sanitize(currentNextState.users)));
      }

      const results = await Promise.all(syncTasks);
      const error = results.find(r => r.error);
      if (error) throw new Error(error.error.message);

      setSyncStatus('synced');
    } catch (err: any) {
      setSyncStatus('error');
      addLog('خطأ في المزامنة السحابية', err.message, 'error');
    } finally {
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state, fetchData, addLog]);

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();
    const handleRealtimeChange = () => {
        if (isInternalUpdate.current) return;
        fetchData();
    };
    const channels = [
        supabase.channel('matches-db').on('postgres_changes', { event: '*', schema: 'public', table: 'matches' }, handleRealtimeChange).subscribe(),
        supabase.channel('users-db').on('postgres_changes', { event: '*', schema: 'public', table: 'app_users' }, handleRealtimeChange).subscribe(),
        supabase.channel('people-db').on('postgres_changes', { event: '*', schema: 'public', table: 'people' }, handleRealtimeChange).subscribe(),
        supabase.channel('categories-db').on('postgres_changes', { event: '*', schema: 'public', table: 'categories' }, handleRealtimeChange).subscribe()
    ];
    return () => { channels.forEach(ch => supabase.removeChannel(ch)); };
  }, [state.currentUser, fetchData]);

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    localStorage.removeItem('alkarama_secure_v10');
  };

  const handleCloudLogin = async (usernameInput: string, passwordInput: string): Promise<AppUser | null> => {
    try {
      const trimmedUser = usernameInput.trim();
      const trimmedPass = passwordInput.trim();
      if ((trimmedUser.toUpperCase() === 'IZZAT' || trimmedUser === 'عزت') && trimmedPass === '123') {
        const rootUser: AppUser = { id: 'root-izzat', username: 'عزت عامر الشيخة', role: 'مدير' };
        setState(prev => ({ ...prev, currentUser: rootUser }));
        return rootUser;
      }
      const { data, error } = await supabase.from('app_users').select('*').ilike('username', trimmedUser).maybeSingle(); 
      if (error || !data) throw new Error("المستخدم غير موجود");
      if (data.password === trimmedPass) {
        const loggedUser: AppUser = { id: data.id, username: data.username, role: data.role as any, restrictedCategory: data.restrictedCategory };
        setState(prev => ({ ...prev, currentUser: loggedUser }));
        return loggedUser;
      } else { throw new Error("كلمة المرور غير صحيحة"); }
    } catch (err: any) { throw err; }
  };

  if (!state.currentUser) return <Login onLoginAttempt={handleCloudLogin} />;

  // فلترة العناصر بناءً على الرتبة
  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'tech_reports', label: 'التقارير الفنية', icon: FilePieChart },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'ai', label: 'الذكاء الفني', icon: Sparkles },
    { id: 'logistics', label: 'اللوجستيك', icon: Map },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ].filter(item => {
      if (state.currentUser?.role === 'أمين مستودع') {
          return item.id === 'warehouse' || item.id === 'dashboard';
      }
      return true;
  });

  return (
    <div className="min-h-screen bg-[#000F21] flex text-right font-['Tajawal'] overflow-hidden" dir="rtl">
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 transition-all duration-500 lg:translate-x-0 lg:static lg:p-4 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print`}>
        <div className="h-full bg-[#001F3F] rounded-[2rem] flex flex-col border-2 border-[#FF6B00]">
          <div className="p-8 flex items-center justify-between border-b border-white/5">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-2xl"><ClubLogo size={45} /></div>
              <div className="flex flex-col text-white">
                <span className="font-black text-lg leading-tight">نادي الكرامة</span>
                <span className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-tighter">مكتب كرة القدم</span>
              </div>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-2 text-white hover:text-[#FF6B00]"><X size={24} /></button>
          </div>
          <nav className="flex-1 overflow-y-auto py-6 px-4 space-y-2 custom-scrollbar">
            {navItems.map((item) => (
              <button key={item.id} onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all duration-300 group ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg scale-[1.02]' : 'text-white/60 hover:text-white hover:bg-white/5'}`}>
                <item.icon size={22} className={`${activeTab === item.id ? 'text-white' : 'group-hover:text-[#FF6B00]'} transition-colors`} />
                <span className="font-bold text-sm">{item.label}</span>
              </button>
            ))}
          </nav>
          <div className="p-6 border-t border-white/5">
            <button onClick={handleLogout} className="w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-red-400 hover:bg-red-500/10 font-bold transition-all">
              <LogOut size={22} /> <span className="text-sm">تسجيل الخروج</span>
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-[#001F3F] z-40 px-6 lg:px-12 py-5 flex items-center justify-between no-print border-b border-[#FF6B00]">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-3 bg-white/5 rounded-2xl text-white shadow-lg"><Menu size={24} /></button>
            <div>
               <h1 className="text-2xl font-black text-white tracking-tight">{navItems.find(i => i.id === activeTab)?.label}</h1>
               <p className="text-[10px] font-bold text-[#FF6B00] uppercase tracking-widest mt-0.5">Football Intelligence OS v10.0 Stable</p>
            </div>
          </div>
          <div className="flex items-center gap-4 lg:gap-8">
            <div className="flex items-center gap-4 bg-black/20 border border-white/10 px-5 py-2 rounded-2xl">
                 <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-white/60 hover:text-[#FF6B00] relative">
                    <Bell size={24} />
                    {state.notifications.filter(n => !n.isRead).length > 0 && (
                      <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-[#FF6B00] rounded-full border-2 border-[#001F3F]"></span>
                    )}
                 </button>
                 <div className="flex items-center gap-4 border-r pr-5 border-white/10">
                    <div className="hidden sm:flex flex-col text-left">
                       <span className="text-xs font-black text-white leading-none">{state.currentUser?.username}</span>
                       <span className="text-[10px] font-black text-[#FF6B00] uppercase mt-1">{state.currentUser?.role}</span>
                    </div>
                    <div className="w-10 h-10 bg-[#FF6B00] text-white border border-white/20 rounded-2xl flex items-center justify-center font-black text-lg">
                       {state.currentUser?.username.charAt(0)}
                    </div>
                 </div>
              </div>
            <div className="flex items-center gap-3">
              <div className={`hidden md:flex items-center gap-3 px-5 py-3 rounded-2xl border transition-all ${syncStatus === 'synced' ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-orange-500/10 border-[#FF6B00]/30 text-[#FF6B00]'}`}>
                 {syncStatus === 'synced' ? <CloudCheck size={18} /> : <Cloud size={18} />}
                 <span className="text-[10px] font-black uppercase tracking-tighter">{syncStatus === 'synced' ? 'مؤمن سحابياً' : 'جاري المزامنة...'}</span>
              </div>
              <button onClick={() => fetchData()} disabled={isSyncing} className="p-3.5 rounded-2xl bg-white/5 border border-white/10 text-white/60 hover:text-white hover:bg-[#FF6B00] transition-all">
                <RefreshCw size={20} className={isSyncing ? 'animate-spin' : ''} />
              </button>
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-6 lg:p-12 custom-scrollbar bg-[#000F21]">
          <div className="max-w-[1400px] mx-auto pb-24">
            {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={m => { setActiveTab('matches'); setSelectedMatchId(m); }} onSessionClick={s => { setActiveTab('attendance'); setSelectedSessionId(s); }} />}
            {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={addLog} getSuspension={getPlayerSuspensionStatus} />}
            {activeTab === 'tech_reports' && <TechnicalReports state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'ai' && <AIAssistant state={state} />}
            {activeTab === 'logistics' && <LocationAssistant />}
            {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={addLog} />}
            {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}

            <footer className="mt-20 py-20 text-center border-t-2 border-white/5 no-print relative overflow-hidden">
              <div className="absolute inset-0 bg-gradient-to-b from-transparent via-orange-500/5 to-transparent opacity-40"></div>
              <div className="relative z-10 space-y-8">
                <div className="flex flex-col items-center gap-4">
                    <p className="text-4xl md:text-7xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-[#FFD700] via-[#FFA500] to-[#FF8C00] drop-shadow-[0_8px_20px_rgba(0,0,0,0.8)] transition-all hover:scale-110 duration-700 select-none">
                      Powered by: Izzat Amer Alshikha
                    </p>
                    <div className="flex items-center gap-6 w-full max-w-2xl">
                       <div className="h-[3px] flex-1 bg-gradient-to-l from-transparent via-orange-500 to-transparent"></div>
                       <p className="text-white/80 font-black text-lg md:text-3xl uppercase tracking-[0.6em] drop-shadow-[0_4px_8px_rgba(0,0,0,0.9)] whitespace-nowrap">
                         نادي الكرامة الرياضي - مكتب كرة القدم
                       </p>
                       <div className="h-[3px] flex-1 bg-gradient-to-r from-transparent via-orange-500 to-transparent"></div>
                    </div>
                </div>
                <div className="flex justify-center gap-4">
                   <div className="w-3 h-3 bg-[#FFD700] rounded-full animate-pulse shadow-[0_0_15px_#FFD700]"></div>
                   <div className="w-3 h-3 bg-orange-600 rounded-full animate-pulse [animation-delay:200ms] shadow-[0_0_15px_#FF6B00]"></div>
                   <div className="w-3 h-3 bg-[#FFD700] rounded-full animate-pulse [animation-delay:400ms] shadow-[0_0_15px_#FFD700]"></div>
                </div>
              </div>
            </footer>
          </div>
        </section>

        <nav className="lg:hidden fixed bottom-0 inset-x-0 bg-[#001F3F] border-t border-[#FF6B00]/30 p-3 flex justify-around items-center z-[100] rounded-t-[2rem]">
           {navItems.slice(0, 5).map(item => (
             <button key={item.id} onClick={() => setActiveTab(item.id)} className={`p-4 rounded-2xl transition-all ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'text-white/40'}`}>
                <item.icon size={24} />
             </button>
           ))}
        </nav>
        <ChatBot state={state} />
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ShieldCheck, CloudUpload, Trash2, Key, Info, UserPlus, X, Edit2, ShieldAlert, Layers, Plus, Database, Lock, Eye, EyeOff } from 'lucide-react';
import { AppState, AppUser, UserRole, Category } from '../types';
import { generateUUID, supabase } from '../App';

interface SettingsProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const SettingsView: React.FC<SettingsProps> = ({ state, setState, addLog }) => {
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [newCatName, setNewCatName] = useState('');
  const [showPassInForm, setShowPassInForm] = useState(false);

  const currentUser = state.currentUser;
  const isGlobalManager = currentUser?.role === 'مدير';

  const [userFormData, setUserFormData] = useState<Partial<AppUser>>({
    username: '',
    role: 'إداري فئة',
    password: '',
    restrictedCategory: ''
  });

  const roles: UserRole[] = ['مدير', 'إداري فئة', 'مشاهد', 'أمين مستودع'];

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.username || !userFormData.password) return alert('يرجى إكمال كافة البيانات المطلوبة');

    if (editingUserId) {
      setState(prev => ({
        ...prev,
        users: prev.users.map(u => u.id === editingUserId ? { ...u, ...userFormData } as AppUser : u)
      }));
      addLog?.('تعديل صلاحية مستخدم', `تم تحديث بيانات المستخدم: ${userFormData.username}`, 'info');
    } else {
      const newUser: AppUser = {
        id: generateUUID(),
        username: userFormData.username!.trim(),
        role: userFormData.role as UserRole,
        password: userFormData.password!,
        restrictedCategory: (userFormData.role === 'إداري فئة' || userFormData.role === 'مشاهد') ? userFormData.restrictedCategory : undefined
      };
      setState(prev => ({ ...prev, users: [...prev.users, newUser] }));
      addLog?.('إنشاء حساب مستخدم', `تم إنشاء مستخدم جديد بنجاح: ${newUser.username}`, 'success');
    }

    setIsUserModalOpen(false);
    setEditingUserId(null);
    setUserFormData({ username: '', role: 'إداري فئة', password: '', restrictedCategory: '' });
  };

  const handleAddCategory = () => {
    if (!newCatName.trim()) return;
    if (state.categories.includes(newCatName.trim())) return alert('هذه الفئة موجودة مسبقاً.');
    setState(prev => ({ ...prev, categories: [...prev.categories, newCatName.trim()] }));
    addLog?.('إضافة فئة', `تمت إضافة فئة: ${newCatName}`, 'success');
    setNewCatName('');
  };

  const removeCategory = (cat: string) => {
    if (confirm(`حذف فئة ${cat}؟`)) {
      setState(prev => ({ ...prev, categories: prev.categories.filter(c => c !== cat) }));
    }
  };

  const deleteUser = async (id: string, name: string) => {
    if (name.toUpperCase() === 'IZZAT' || name === 'عزت عامر الشيخة') return alert('لا يمكن حذف الحساب الجذري.');
    if (confirm(`هل أنت متأكد من حذف حساب ${name}؟`)) {
      await supabase.from('app_users').delete().eq('id', id);
      setState(p => ({ ...p, users: p.users.filter(u => u.id !== id) }));
      addLog?.('حذف مستخدم', `تم حذف حساب: ${name}`, 'error');
    }
  };

  const labelClass = "text-[11px] font-black text-slate-900 mr-2 uppercase block mb-1.5 drop-shadow-sm";
  const fieldClass = "w-full bg-slate-50 border-4 border-slate-900 rounded-2xl py-4 px-6 font-black text-slate-900 outline-none focus:border-orange-600 shadow-inner";

  return (
    <div className="max-w-6xl mx-auto space-y-12 pb-24 font-['Tajawal'] text-right" dir="rtl">
      {isGlobalManager && (
        <div className="bg-white p-10 rounded-[3rem] shadow-sm border-[6px] border-slate-900">
           <div className="flex justify-between items-center mb-10 border-b-4 border-slate-900 pb-8">
              <div>
                <h3 className="text-2xl md:text-4xl font-black text-slate-900 flex items-center gap-4 drop-shadow-md">
                  <ShieldCheck size={40} className="text-[#001F3F]" /> إدارة حسابات وصلاحيات النظام
                </h3>
                <p className="text-xs font-black text-orange-600 mt-2 uppercase tracking-widest drop-shadow-sm">التحكم المركزي الكامل بكافة المستخدمين والوصول</p>
              </div>
              <button onClick={() => { setEditingUserId(null); setIsUserModalOpen(true); }} className="bg-[#001F3F] text-white px-8 py-4 rounded-2xl font-black text-sm flex items-center gap-3 shadow-xl border-b-4 border-black hover:bg-black transition-all">
                <UserPlus size={24}/> إنشاء حساب جديد
              </button>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {state.users.map(user => (
                <div key={user.id} className="bg-slate-100 p-8 rounded-[3rem] border-4 border-slate-900 relative overflow-hidden group shadow-md hover:border-orange-600 transition-all">
                   <div className="flex justify-between items-start mb-6">
                      <div className="w-14 h-14 bg-white border-4 border-slate-900 rounded-2xl flex items-center justify-center shadow-lg">
                         <Key size={28} className="text-orange-600"/>
                      </div>
                      <span className={`text-[10px] font-black px-4 py-2 rounded-xl uppercase border-2 shadow-sm ${user.role === 'مدير' ? 'bg-orange-600 text-white border-orange-900' : 'bg-[#001F3F] text-white border-black'}`}>
                        {user.role}
                      </span>
                   </div>
                   <h4 className="font-black text-2xl text-slate-900 drop-shadow-sm">{user.username}</h4>
                   <p className="text-[11px] font-black text-slate-500 mt-2 uppercase tracking-tighter">
                      {user.restrictedCategory ? `الوصول محصور بـ: ${user.restrictedCategory}` : 'صلاحيات وصول شاملة للنظام'}
                   </p>
                   <div className="mt-8 pt-6 border-t-2 border-slate-200 flex justify-between items-center">
                      <div className="flex flex-col">
                         <p className="text-[9px] font-black text-slate-400 uppercase">كلمة السر</p>
                         <p className="text-xs font-black text-slate-900 tracking-widest">••••••••</p>
                      </div>
                      <div className="flex gap-2">
                         <button onClick={() => { setEditingUserId(user.id); setUserFormData(user); setIsUserModalOpen(true); }} className="p-3 bg-white border-2 border-slate-900 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all shadow-sm"><Edit2 size={20}/></button>
                         {(user.username.toUpperCase() !== 'IZZAT' && user.username !== 'عزت عامر الشيخة') && (
                           <button onClick={() => deleteUser(user.id, user.username)} className="p-3 bg-white border-2 border-slate-900 text-red-600 hover:bg-red-600 hover:text-white transition-all shadow-sm"><Trash2 size={20}/></button>
                         )}
                      </div>
                   </div>
                </div>
              ))}
              {state.users.length === 0 && (
                <div className="col-span-full py-20 text-center border-4 border-dashed border-slate-300 rounded-[3rem]">
                   <p className="text-xl font-black text-slate-400 italic">لا توجد حسابات فرعية منشأة حالياً.</p>
                </div>
              )}
           </div>
        </div>
      )}

      {/* باقي الأقسام تتبع نفس النمط الصارم للرؤية */}
      <div className="bg-white p-12 rounded-[4rem] shadow-sm border-[6px] border-slate-900">
        <h3 className="text-2xl md:text-4xl font-black text-slate-900 mb-10 drop-shadow-sm">إدارة فئات النادي الرياضية</h3>
        <div className="flex flex-col md:flex-row gap-6 mb-12">
          <input 
            type="text" 
            value={newCatName} 
            onChange={e => setNewCatName(e.target.value)}
            placeholder="أدخل اسم الفئة الجديدة.."
            className="flex-1 bg-slate-100 border-4 border-slate-900 rounded-[2rem] p-6 font-black text-2xl outline-none focus:border-orange-600 transition-all shadow-inner"
          />
          <button 
            onClick={handleAddCategory}
            disabled={!isGlobalManager}
            className="bg-[#001F3F] text-white px-12 py-6 rounded-[2rem] font-black text-xl shadow-2xl border-b-8 border-black hover:bg-black transition-all disabled:opacity-30"
          >
            تثبيت الفئة
          </button>
        </div>
        <div className="flex flex-wrap gap-4">
           {state.categories.map(cat => (
             <div key={cat} className="bg-slate-50 border-4 border-slate-900 px-8 py-4 rounded-[2rem] flex items-center gap-5 shadow-md">
                <span className="font-black text-xl text-slate-900 drop-shadow-sm">{cat}</span>
                {isGlobalManager && (
                  <button onClick={() => removeCategory(cat)} className="text-red-600 hover:bg-red-50 p-2 rounded-full transition-all"><X size={20}/></button>
                )}
             </div>
           ))}
        </div>
      </div>

      {isUserModalOpen && (
        <div className="fixed inset-0 bg-[#001F3F]/95 backdrop-blur-3xl flex items-center justify-center z-[800] p-6 no-print overflow-y-auto text-right" dir="rtl">
          <div className="bg-white rounded-[4rem] w-full max-w-2xl shadow-2xl border-[10px] border-white p-12">
            <div className="flex justify-between items-center mb-10 border-b-4 border-slate-900 pb-6">
               <h3 className="text-2xl md:text-3xl font-black text-[#001F3F] uppercase tracking-tighter drop-shadow-sm">برمجة حساب مستخدم</h3>
               <button onClick={() => setIsUserModalOpen(false)} className="bg-slate-100 p-4 rounded-full hover:rotate-90 transition-all border-2 border-slate-900"><X/></button>
            </div>
            <form onSubmit={handleSaveUser} className="space-y-8">
              <div className="space-y-2">
                <label className={labelClass}>اسم الدخول (المعرف)</label>
                <input required type="text" value={userFormData.username || ''} onChange={e => setUserFormData({ ...userFormData, username: e.target.value })}
                  className={fieldClass} placeholder="مثال: Ahmed_Staff" />
              </div>

              <div className="space-y-2">
                <label className={labelClass}>كلمة المرور (Secret Code)</label>
                <div className="relative">
                   <input required type={showPassInForm ? "text" : "password"} value={userFormData.password || ''} onChange={e => setUserFormData({ ...userFormData, password: e.target.value })}
                    className={fieldClass} placeholder="••••••••" />
                   <button type="button" onClick={() => setShowPassInForm(!showPassInForm)} className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-900">
                      {showPassInForm ? <EyeOff size={24}/> : <Eye size={24}/>}
                   </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-8">
                 <div className="space-y-2">
                    <label className={labelClass}>الرتبة / الصلاحية</label>
                    <select className={fieldClass}
                      value={userFormData.role} onChange={e => setUserFormData({ ...userFormData, role: e.target.value as UserRole, restrictedCategory: '' })}>
                      {roles.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                 </div>
                 {(userFormData.role === 'إداري فئة' || userFormData.role === 'مشاهد') && (
                    <div className="space-y-2">
                      <label className={labelClass}>الفئة المحصورة</label>
                      <select className={fieldClass}
                        value={userFormData.restrictedCategory} onChange={e => setUserFormData({ ...userFormData, restrictedCategory: e.target.value })}>
                        <option value="">-- فئة مخصصة --</option>
                        {state.categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                      </select>
                    </div>
                 )}
              </div>

              <div className="bg-blue-50 p-6 rounded-[2rem] border-4 border-blue-900 flex items-start gap-4">
                 <ShieldAlert className="text-blue-900 shrink-0" size={32}/>
                 <p className="text-[11px] font-black text-blue-900 leading-relaxed uppercase drop-shadow-sm">
                    تنبيه أمني: تأكد من تزويد المستخدم ببياناته يدوياً. النظام يشفر كلمات المرور سحابياً لحماية أمن معلومات نادي الكرامة.
                 </p>
              </div>

              <button type="submit" className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] shadow-2xl text-2xl hover:bg-black transition-all border-b-8 border-black">
                {editingUserId ? 'تثبيت التحديثات' : 'تفعيل الحساب الجديد'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useMemo } from 'react';
import { Package, Plus, Trash2, Edit3, Search, Filter, Box, Archive, ClipboardList, ShieldAlert, X, Save, TrendingUp, AlertTriangle, CheckCircle } from 'lucide-react';
import { AppState, WarehouseItem, Category } from '../types';
import { generateUUID, supabase } from '../App';

interface WarehouseManagementProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const WarehouseManagement: React.FC<WarehouseManagementProps> = ({ state, setState, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [localCategoryFilter, setLocalCategoryFilter] = useState<string>('الكل');

  const currentUser = state.currentUser!;
  const restrictedCat = currentUser.restrictedCategory;
  const isManager = currentUser.role === 'مدير';
  const isWarehouseKeeper = currentUser.role === 'أمين مستودع';
  const isViewer = currentUser.role === 'مشاهد';

  const [formData, setFormData] = useState<Partial<WarehouseItem>>({
    category: restrictedCat || 'المخزن العام',
    condition: 'جديد',
    unit: 'قطعة',
    quantity: 0
  });

  const filteredItems = useMemo(() => {
    return state.warehouse.filter(item => {
      // السماح للمدير وأمين المستودع برؤية كل شيء
      const canAccess = isManager || isWarehouseKeeper || item.category === restrictedCat || item.category === 'المخزن العام';
      if (!canAccess) return false;

      const matchCat = localCategoryFilter === 'الكل' ? true : item.category === localCategoryFilter;
      const matchSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());

      return matchCat && matchSearch;
    }).sort((a, b) => a.category.localeCompare(b.category));
  }, [state.warehouse, localCategoryFilter, searchTerm, restrictedCat, isManager, isWarehouseKeeper]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (isViewer) return;
    if (!formData.name || formData.quantity === undefined) return;

    if (editingId) {
      setState(p => ({
        ...p,
        warehouse: p.warehouse.map(item => item.id === editingId ? { ...item, ...formData, lastUpdated: new Date().toISOString() } as WarehouseItem : item)
      }));
      addLog?.('تحديث مستودع', `تم تعديل بيانات: ${formData.name}`, 'info');
    } else {
      const newItem: WarehouseItem = {
        id: generateUUID(),
        name: formData.name!,
        category: formData.category as any || 'المخزن العام',
        quantity: formData.quantity!,
        unit: formData.unit as any || 'قطعة',
        condition: formData.condition as any || 'جديد',
        lastUpdated: new Date().toISOString(),
        notes: formData.notes
      };
      setState(p => ({ ...p, warehouse: [newItem, ...p.warehouse] }));
      addLog?.('إضافة للمستودع', `تم تسجيل صنف جديد: ${newItem.name}`, 'success');
    }

    setIsModalOpen(false);
    setEditingId(null);
  };

  const labelClass = "text-[10px] font-black text-slate-900 mr-2 uppercase block mb-1.5";
  const fieldClass = "w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-3 px-4 font-black text-slate-900 outline-none focus:border-orange-600 transition-all text-sm";

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      {/* رأس الصفحة */}
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border-2 border-slate-900 flex flex-col md:flex-row justify-between items-center gap-4 no-print">
        <div className="flex items-center gap-4">
           <div className="bg-[#001F3F] p-3 rounded-2xl text-white">
             <Package size={28} />
           </div>
           <div>
             <h2 className="text-xl font-black text-slate-900">المستودع المركزي والمخازن</h2>
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">إدارة العتاد، اللباس، والمعدات الرياضية</p>
           </div>
        </div>

        <div className="flex items-center gap-3 w-full md:w-auto">
           <div className="relative flex-1 md:w-64">
              <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="بحث في المستودع..." 
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full bg-slate-50 border-2 border-slate-900 rounded-xl py-2 pr-10 pl-4 font-black text-xs outline-none focus:border-orange-600"
              />
           </div>

           {/* السماح لأمين المستودع والمدير بالفلترة عبر جميع الفئات */}
           {(isManager || isWarehouseKeeper) && (
             <select 
               value={localCategoryFilter}
               onChange={e => setLocalCategoryFilter(e.target.value)}
               className="bg-white border-2 border-slate-900 rounded-xl py-2 px-4 font-black text-xs outline-none cursor-pointer"
             >
               <option value="الكل">جميع الأقسام</option>
               <option value="المخزن العام">المخزن العام</option>
               {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
             </select>
           )}

           {!isViewer && (
             <button onClick={() => { setEditingId(null); setFormData({ category: restrictedCat || 'المخزن العام', condition: 'جديد', unit: 'قطعة', quantity: 0 }); setIsModalOpen(true); }} className="bg-[#001F3F] text-white px-6 py-2 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg border-b-4 border-black">
               <Plus size={18}/> إضافة صنف
             </button>
           )}
        </div>
      </div>

      {/* عرض البطاقات */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
         {filteredItems.map(item => (
           <div key={item.id} className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-900 shadow-sm relative group hover:shadow-xl transition-all border-b-8 hover:border-orange-600">
              <div className="flex justify-between items-start mb-4">
                 <span className={`text-[9px] font-black px-3 py-1 rounded-lg uppercase border ${item.category === 'المخزن العام' ? 'bg-orange-600 text-white border-orange-700' : 'bg-[#001F3F] text-white border-black'}`}>
                   {item.category}
                 </span>
                 <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    {!isViewer && (isManager || isWarehouseKeeper || item.category === restrictedCat) && (
                      <>
                        <button onClick={() => { setEditingId(item.id); setFormData(item); setIsModalOpen(true); }} className="p-1.5 bg-slate-100 text-blue-600 rounded-lg"><Edit3 size={14}/></button>
                        <button onClick={async () => { if(confirm('هل تريد حذف هذا الصنف؟')) { setState(p => ({...p, warehouse: p.warehouse.filter(x => x.id !== item.id)})); addLog?.('حذف من المستودع', `تم مسح: ${item.name}`, 'error'); } }} className="p-1.5 bg-red-50 text-red-600 rounded-lg"><Trash2 size={14}/></button>
                      </>
                    )}
                 </div>
              </div>

              <div className="mb-6">
                 <h4 className="text-lg font-black text-slate-900 mb-1">{item.name}</h4>
                 <div className="flex items-center gap-2">
                    <span className={`w-2 h-2 rounded-full ${item.condition === 'جديد' ? 'bg-emerald-500' : item.condition === 'تالف' ? 'bg-red-500' : 'bg-yellow-500'}`}></span>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.condition}</span>
                 </div>
              </div>

              <div className="bg-slate-50 p-4 rounded-2xl border-2 border-slate-100 flex justify-between items-center">
                 <div>
                    <p className="text-[9px] font-black text-slate-400 uppercase">الكمية المتوفرة</p>
                    <p className="text-2xl font-black text-slate-900">{item.quantity} <span className="text-[10px] text-slate-400 font-bold">{item.unit}</span></p>
                 </div>
                 <Box size={32} className="text-slate-200" />
              </div>

              {item.notes && (
                <div className="mt-4 p-3 bg-orange-50 rounded-xl border border-orange-100">
                   <p className="text-[9px] font-black text-orange-600 leading-relaxed italic">{item.notes}</p>
                </div>
              )}
           </div>
         ))}

         {filteredItems.length === 0 && (
           <div className="col-span-full py-20 text-center bg-white rounded-[3rem] border-2 border-dashed border-slate-200">
              <Archive className="mx-auto text-slate-200 mb-4" size={48} />
              <p className="text-slate-900 font-black italic">لا توجد أصناف في هذا القسم من المستودع</p>
           </div>
         )}
      </div>

      {/* نافذة الإضافة والتعديل */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md flex items-center justify-center z-[500] p-4">
           <div className="bg-white rounded-[2.5rem] w-full max-w-lg border-[6px] border-slate-900 shadow-2xl overflow-hidden">
              <div className="p-6 bg-slate-100 border-b-2 border-slate-900 flex justify-between items-center">
                 <h3 className="font-black text-slate-900 uppercase">{editingId ? 'تعديل بيانات الصنف' : 'إضافة صنف جديد للمستودع'}</h3>
                 <button onClick={() => setIsModalOpen(false)} className="bg-white p-2 rounded-lg border-2 border-slate-900"><X size={20}/></button>
              </div>
              <form onSubmit={handleSave} className="p-8 space-y-5 text-right" dir="rtl">
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>القسم / الفئة</label>
                       <select 
                        disabled={!!restrictedCat && !isWarehouseKeeper}
                        className={fieldClass} 
                        value={formData.category} 
                        onChange={e => setFormData({...formData, category: e.target.value as any})}
                       >
                          <option value="المخزن العام">المخزن العام (مركزي)</option>
                          {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>حالة الصنف</label>
                       <select className={fieldClass} value={formData.condition} onChange={e => setFormData({...formData, condition: e.target.value as any})}>
                          <option value="جديد">جديد (بكر)</option>
                          <option value="مستعمل">مستعمل (جيد)</option>
                          <option value="تالف">تالف (للإتلاف)</option>
                       </select>
                    </div>
                 </div>

                 <div className="space-y-1">
                    <label className={labelClass}>اسم الصنف (كرات، طقم تدريب، أقماع...)</label>
                    <input required type="text" className={fieldClass} value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} />
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className={labelClass}>الكمية</label>
                       <input required type="number" className={fieldClass} value={formData.quantity || 0} onChange={e => setFormData({...formData, quantity: parseInt(e.target.value)})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>وحدة القياس</label>
                       <select className={fieldClass} value={formData.unit} onChange={e => setFormData({...formData, unit: e.target.value as any})}>
                          <option value="قطعة">قطعة</option>
                          <option value="طقم">طقم (كامل)</option>
                          <option value="كرة">كرة</option>
                          <option value="حذاء">حذاء</option>
                          <option value="أخرى">أخرى</option>
                       </select>
                    </div>
                 </div>

                 <div className="space-y-1">
                    <label className={labelClass}>ملاحظات المستودع (اختياري)</label>
                    <textarea className={fieldClass + " h-24 resize-none"} value={formData.notes || ''} onChange={e => setFormData({...formData, notes: e.target.value})}></textarea>
                 </div>

                 <button type="submit" className="w-full bg-[#001F3F] text-white py-4 rounded-xl font-black text-lg flex items-center justify-center gap-3 border-b-4 border-black active:translate-y-1 active:border-b-0 transition-all">
                    <Save size={20}/> حفظ في السجلات
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default WarehouseManagement;
